-- Sepulchria
-- Phase 8.9 — Initial database schema baseline
--
-- Generated from the live Supabase PostgreSQL catalog on 2026-10-07.
-- Source project: ykxrkajqolnrsxiellnm
--
-- IMPORTANT:
--   * This is a SCHEMA baseline. It intentionally does not contain production row data.
--   * Supabase-managed schemas (auth, storage, realtime, etc.) are supplied by a fresh
--     Supabase project. Application schemas public/private and custom storage RLS
--     policies are reconstructed here.
--   * Do NOT run this baseline against the existing production database; it represents
--     the schema already present there. Mark it as applied in migration history instead.
--
-- Objects captured from live database:
--   201 tables
--   367 functions/procedures
--   195 non-internal triggers
--   268 RLS policies
--   331 standalone indexes
--   3 custom enums
--   4 sequences
--   1 view/materialized view
--   grants and comments
--
-- Phase 8.9 baseline.

begin;

-- ============================================================================
-- SCHEMAS
-- ============================================================================

create schema if not exists private;

-- ============================================================================
-- EXTENSIONS
-- ============================================================================

create extension if not exists pg_cron with schema pg_catalog;

create extension if not exists pg_stat_statements with schema extensions;

create extension if not exists pg_trgm with schema public;

create extension if not exists pgcrypto with schema extensions;

create extension if not exists supabase_vault with schema vault;

create extension if not exists "uuid-ossp" with schema extensions;

-- ============================================================================
-- CUSTOM ENUM TYPES
-- ============================================================================

create type public.codex_entry_status as enum ('draft', 'published');

create type public.codex_visibility as enum ('public', 'staff');

create type public.rule_status as enum ('draft', 'published');

-- ============================================================================
-- SEQUENCES
-- ============================================================================

create sequence public.account_legal_acceptances_id_seq;

create sequence public.character_expertise_ledger_id_seq;

create sequence public.ticket_number_seq;

create sequence public.world_state_history_id_seq;

