-- ============================================================================
-- PRIMARY / UNIQUE / CHECK / EXCLUSION CONSTRAINTS
-- ============================================================================

alter table public.account_legal_acceptances add constraint account_legal_acceptances_pkey PRIMARY KEY (id);

alter table public.account_legal_acceptances add constraint account_legal_acceptances_user_id_terms_version_privacy_ver_key UNIQUE (user_id, terms_version, privacy_version);

alter table public.active_shape_effects add constraint active_shape_effects_effect_nature_check CHECK (effect_nature = ANY (ARRAY['beneficial'::text, 'harmful'::text, 'mixed'::text]));

alter table public.active_shape_effects add constraint active_shape_effects_pkey PRIMARY KEY (id);

alter table public.active_shape_effects add constraint active_shape_effects_profile_check CHECK (profile = ANY (ARRAY['self'::text, 'other'::text]));

alter table public.active_shape_effects add constraint active_shape_effects_source_shape_level_check CHECK (source_shape_level >= 1 AND source_shape_level <= 9);

alter table public.areas add constraint areas_pkey PRIMARY KEY (id);

alter table public.areas add constraint areas_slug_key UNIQUE (slug);

alter table public.associations add constraint associations_colour_format CHECK (colour IS NULL OR colour ~ '^#[0-9A-Fa-f]{6}$'::text);

alter table public.associations add constraint associations_name_not_blank CHECK (length(TRIM(BOTH FROM name)) > 0);

alter table public.associations add constraint associations_name_unique UNIQUE (name);

alter table public.associations add constraint associations_pkey PRIMARY KEY (id);

alter table public.associations add constraint associations_slug_not_blank CHECK (length(TRIM(BOTH FROM slug)) > 0);

alter table public.associations add constraint associations_slug_unique UNIQUE (slug);

alter table public.breeze_lodging_guests add constraint breeze_lodging_guests_pkey PRIMARY KEY (rental_id, character_id);

alter table public.breeze_lodging_guests add constraint breeze_lodging_guests_status_check CHECK (status = ANY (ARRAY['active'::text, 'revoked'::text]));

alter table public.breeze_lodging_invitations add constraint breeze_lodging_invitations_delivery_method_check CHECK (delivery_method = ANY (ARRAY['popup'::text, 'message'::text]));

alter table public.breeze_lodging_invitations add constraint breeze_lodging_invitations_pkey PRIMARY KEY (id);

alter table public.breeze_lodging_invitations add constraint breeze_lodging_invitations_status_check CHECK (status = ANY (ARRAY['pending'::text, 'accepted'::text, 'refused'::text, 'cancelled'::text]));

alter table public.breeze_lodging_rentals add constraint breeze_lodging_rentals_daily_rate_check CHECK (daily_rate > 0);

alter table public.breeze_lodging_rentals add constraint breeze_lodging_rentals_days_check CHECK (days >= 1 AND days <= 7);

alter table public.breeze_lodging_rentals add constraint breeze_lodging_rentals_pkey PRIMARY KEY (id);

alter table public.breeze_lodging_rentals add constraint breeze_lodging_rentals_status_check CHECK (status = ANY (ARRAY['active'::text, 'expired'::text]));

alter table public.breeze_lodging_rentals add constraint breeze_lodging_rentals_total_paid_check CHECK (total_paid > 0);

alter table public.breeze_lodging_rooms add constraint breeze_lodging_rooms_daily_rate_check CHECK (daily_rate > 0);

alter table public.breeze_lodging_rooms add constraint breeze_lodging_rooms_pkey PRIMARY KEY (room_id);

alter table public.breeze_lodging_rooms add constraint breeze_lodging_rooms_room_number_check CHECK (room_number >= 1 AND room_number <= 20);

alter table public.breeze_lodging_rooms add constraint breeze_lodging_rooms_room_number_key UNIQUE (room_number);

alter table public.breeze_lodging_rooms add constraint breeze_lodging_rooms_tier_check CHECK (tier = ANY (ARRAY['gilded'::text, 'wayfarer'::text, 'hearth'::text]));

alter table public.calendar_event_reads add constraint calendar_event_reads_pkey PRIMARY KEY (character_id, event_id);

alter table public.calendar_events add constraint calendar_events_pkey PRIMARY KEY (id);

alter table public.calendar_events add constraint calendar_events_recurrence_type_check CHECK (recurrence_type = ANY (ARRAY['once'::text, 'daily'::text, 'weekly'::text, 'monthly'::text, 'yearly'::text]));

alter table public.calendar_events add constraint calendar_events_time_order_check CHECK (start_time IS NULL OR end_time IS NULL OR end_time >= start_time);

alter table public.calendar_events add constraint calendar_events_title_check CHECK (char_length(title) >= 1 AND char_length(title) <= 160);

alter table public.character_active_item_effects add constraint active_item_effects_warp_affinity_check CHECK (warping_affinity_modifier >= 0 AND warping_affinity_modifier <= 8);

alter table public.character_active_item_effects add constraint active_item_effects_warps_day_check CHECK (warps_per_day_modifier >= 0 AND warps_per_day_modifier <= 10);

alter table public.character_active_item_effects add constraint character_active_item_effects_expiry_check CHECK (expires_at > activated_at);

alter table public.character_active_item_effects add constraint character_active_item_effects_pkey PRIMARY KEY (id);

alter table public.character_audit_log add constraint character_audit_log_actor_type_check CHECK (actor_type = ANY (ARRAY['player'::text, 'staff'::text, 'system'::text]));

alter table public.character_audit_log add constraint character_audit_log_operation_check CHECK (operation = ANY (ARRAY['insert'::text, 'update'::text, 'delete'::text, 'event'::text]));

alter table public.character_audit_log add constraint character_audit_log_pkey PRIMARY KEY (id);

alter table public.character_blocks add constraint character_blocks_check CHECK (blocker_character_id <> blocked_character_id);

alter table public.character_blocks add constraint character_blocks_pkey PRIMARY KEY (blocker_character_id, blocked_character_id);

alter table public.character_conditions add constraint character_conditions_created_by_role CHECK (created_by_role = ANY (ARRAY['player'::text, 'master'::text, 'admin'::text, 'owner'::text]));

alter table public.character_conditions add constraint character_conditions_label_length CHECK (char_length(TRIM(BOTH FROM label)) >= 1 AND char_length(TRIM(BOTH FROM label)) <= 40);

alter table public.character_conditions add constraint character_conditions_pkey PRIMARY KEY (id);

alter table public.character_cosmetic_entitlements add constraint character_cosmetic_entitlements_pkey PRIMARY KEY (character_id, cosmetic_item_id);

alter table public.character_cosmetic_entitlements add constraint character_cosmetic_entitlements_source_check CHECK (source = ANY (ARRAY['paid'::text, 'staff'::text, 'reward'::text, 'promotion'::text, 'gift'::text, 'event'::text]));

alter table public.character_cosmetic_preferences add constraint character_cosmetic_preferences_pkey PRIMARY KEY (character_id);

alter table public.character_death_events add constraint character_death_events_pkey PRIMARY KEY (id);

alter table public.character_death_events add constraint character_death_events_status_check CHECK (status = ANY (ARRAY['pending'::text, 'rescued'::text, 'dead'::text, 'revived'::text]));

alter table public.character_death_rules add constraint character_death_rules_death_duration_hours_check CHECK (death_duration_hours >= 1 AND death_duration_hours <= 8760);

