-- ============================================================================
-- VIEWS / MATERIALIZED VIEWS
-- ============================================================================

create or replace view public.store_catalogue as  SELECT p.id,
    p.slug,
    p.name,
    p.description,
    p.image_url,
    p.product_type,
    p.category,
    p.is_featured,
    p.sort_order,
    p.available_from,
    p.available_until,
    pr.id AS price_id,
    pr.currency,
    pr.money_amount_minor,
    pr.remnants_amount
   FROM store_products p
     JOIN store_product_prices pr ON pr.product_id = p.id AND pr.is_active = true
  WHERE p.is_active = true AND (p.available_from IS NULL OR p.available_from <= now()) AND (p.available_until IS NULL OR p.available_until > now());;

