-- FUNCTIONS / PROCEDURES
-- ============================================================================

CREATE OR REPLACE FUNCTION private.phase8_character_history_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 SELECT c.id,coalesce(nullif(btrim(c.display_name),''),nullif(btrim(coalesce(c.first_name,'')||' '||coalesce(c.surname,'')),''),c.id::text)
 INTO NEW.character_id_snapshot,NEW.character_name_snapshot FROM public.characters c WHERE c.id=NEW.character_id;
 IF NEW.character_id_snapshot IS NULL THEN RAISE EXCEPTION 'A live character is required for new financial history.'; END IF;
 RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.phase8_delete_character(p_character_id uuid, p_delete_entire_conversations boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  deleted_count integer;
begin
  if p_character_id is null then raise exception 'Character ID is required.'; end if;

  perform 1 from public.characters where id=p_character_id for update;
  if not found then return false; end if;

  if exists(select 1 from public.npcs n where n.character_id=p_character_id) then
    raise exception 'NPC Characters must be deleted from NPC Administration.';
  end if;

  perform private.phase8_snapshot_character_history(p_character_id);

  delete from public.character_presence where character_id=p_character_id;
  delete from public.direct_conversation_participants where character_id=p_character_id;
  delete from public.character_blocks where blocker_character_id=p_character_id or blocked_character_id=p_character_id;

  delete from public.characters where id=p_character_id;
  get diagnostics deleted_count=row_count;
  return deleted_count=1;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.phase8_item_history_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 SELECT ii.id,jsonb_build_object('instance',to_jsonb(ii),'item_name',(SELECT i.name FROM public.items i WHERE i.id=ii.item_id))
 INTO NEW.item_instance_id_snapshot,NEW.item_snapshot FROM public.character_item_instances ii WHERE ii.id=NEW.item_instance_id;
 IF NEW.item_instance_id_snapshot IS NULL THEN RAISE EXCEPTION 'A live item instance is required for new item history.'; END IF;
 RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.phase8_return_unique_items_before_character_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE moved_id uuid; owner_label text;
BEGIN
 -- Lock the affected instances in a stable order before changing inventory.
 PERFORM 1 FROM public.character_item_instances WHERE owner_character_id=OLD.id ORDER BY id FOR UPDATE;
 -- Invalid cross-owner container contents must not be transferred or detached silently.
 IF EXISTS(SELECT 1 FROM public.character_items child JOIN public.character_item_instances parent ON parent.id=child.container_instance_id
   WHERE parent.owner_character_id=OLD.id AND child.character_id IS DISTINCT FROM OLD.id)
 OR EXISTS(SELECT 1 FROM public.character_item_instances child JOIN public.character_item_instances parent ON parent.id=child.container_instance_id
   WHERE parent.owner_character_id=OLD.id AND child.owner_character_id IS DISTINCT FROM OLD.id) THEN
   RAISE EXCEPTION 'Cannot delete character: a container has items belonging to another owner.';
 END IF;
 -- Standard contents still follow their existing character ON DELETE CASCADE rule.
 -- Detach them first so recovered containers are empty in the Admin Vault.
 UPDATE public.character_items SET container_instance_id=NULL
 WHERE character_id=OLD.id AND container_instance_id IS NOT NULL;
 owner_label:=coalesce(nullif(btrim(OLD.display_name),''),nullif(btrim(coalesce(OLD.first_name,'')||' '||coalesce(OLD.surname,'')),''),OLD.id::text);
 -- Update owner and vault state together. Existing equipment/container triggers remain enabled.
 FOR moved_id IN
  UPDATE public.character_item_instances SET owner_character_id=NULL,container_instance_id=NULL,
    vault_status='admin_vault',updated_at=now()
  WHERE owner_character_id=OLD.id RETURNING id
 LOOP
  INSERT INTO public.item_instance_history(item_instance_id,from_character_id,actor_user_id,event_type,details)
  VALUES(moved_id,OLD.id,auth.uid(),'moved_to_admin_vault',
    'Returned to the Admin Vault when character '||owner_label||' ('||OLD.id::text||') was deleted.');
 END LOOP;
 RETURN OLD;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.phase8_snapshot_character_history(p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
begin
  select coalesce(nullif(btrim(c.display_name), ''), btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.surname,'')))
  into v_name
  from public.characters c
  where c.id = p_character_id;

  if not found then return; end if;

  update public.character_status_history set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.character_death_events set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.daily_mission_events set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.gathering_attempts set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.house_of_chances_plays set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.item_trades set character_one_id_snapshot=coalesce(character_one_id_snapshot,p_character_id), character_one_name_snapshot=coalesce(character_one_name_snapshot,v_name) where character_one_id=p_character_id;
  update public.item_trades set character_two_id_snapshot=coalesce(character_two_id_snapshot,p_character_id), character_two_name_snapshot=coalesce(character_two_name_snapshot,v_name) where character_two_id=p_character_id;
  update public.item_trade_offers set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.odd_job_claims set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.opposed_actions set attacker_character_id_snapshot=coalesce(attacker_character_id_snapshot,p_character_id), attacker_name_snapshot=coalesce(attacker_name_snapshot,v_name) where attacker_character_id=p_character_id;
  update public.opposed_actions set target_character_id_snapshot=coalesce(target_character_id_snapshot,p_character_id), target_name_snapshot=coalesce(target_name_snapshot,v_name) where target_character_id=p_character_id;
  update public.order_payroll_runs set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.order_submissions set submitted_by_character_id_snapshot=coalesce(submitted_by_character_id_snapshot,p_character_id), submitted_by_name_snapshot=coalesce(submitted_by_name_snapshot,v_name) where submitted_by_character_id=p_character_id;
  update public.pioneer_reward_claims set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.poll_ballots set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.portal_presence_events set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.room_messages set character_id_snapshot=coalesce(character_id_snapshot,p_character_id), character_name_snapshot=coalesce(character_name_snapshot,v_name) where character_id=p_character_id;
  update public.room_messages set whisper_recipient_character_id_snapshot=coalesce(whisper_recipient_character_id_snapshot,p_character_id), whisper_recipient_name_snapshot=coalesce(whisper_recipient_name_snapshot,v_name) where whisper_recipient_character_id=p_character_id;
  update public.direct_messages set sender_character_id_snapshot=coalesce(sender_character_id_snapshot,p_character_id), sender_name_snapshot=coalesce(sender_name_snapshot,v_name) where sender_character_id=p_character_id;
  update public.shape_casts set caster_character_id_snapshot=coalesce(caster_character_id_snapshot,p_character_id), caster_name_snapshot=coalesce(caster_name_snapshot,v_name) where caster_character_id=p_character_id;
  update public.shape_cast_targets set target_character_id_snapshot=coalesce(target_character_id_snapshot,p_character_id), target_name_snapshot=coalesce(target_name_snapshot,v_name) where target_character_id=p_character_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.phase8_user_history_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF (to_jsonb(NEW)->>TG_ARGV[0]) IS NULL THEN RAISE EXCEPTION 'A live account is required for new history.'; END IF;
 NEW := jsonb_populate_record(NEW,jsonb_build_object(TG_ARGV[0]||'_snapshot',to_jsonb(NEW)->TG_ARGV[0]));
 RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.use_character_inventory_record_targeted_internal(p_source_character_id uuid, p_record_kind text, p_record_id uuid, p_target_character_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source_room_id uuid;
  v_item_id uuid;
  v_item_instance_id uuid;
  v_item_name text;
  v_is_usable boolean;
  v_use_behaviour text;
  v_target_mode text;
  v_cooldown_minutes integer;
  v_max_charges integer;
  v_charges_remaining integer;
  v_quantity integer;
  v_target_character_id uuid;
  v_target_name text;
  v_target_room_id uuid;
  v_target_health integer;
  v_target_max_health integer;
  v_source_key text;
  v_ready_at timestamptz;
  v_has_use_effect boolean:=false;
  v_has_temporary boolean:=false;
  v_has_applicable_instant boolean:=false;
  v_has_positive_heal boolean:=false;
  v_health_delta integer:=0;
  v_temporary_count integer:=0;
  v_effect record;
begin
  if not exists (
    select 1
    from public.characters c
    join public.npcs n on n.character_id=c.id
    where c.id=p_source_character_id
      and c.is_system=true
      and c.status='approved'
      and n.is_active=true
  ) then
    raise exception 'NPC Character not found.';
  end if;

  if p_record_kind='standard' then
    select c.current_room_id,ci.item_id,null::uuid,i.name,i.is_usable,
           i.use_behaviour,i.target_mode,i.cooldown_minutes,i.max_charges,
           null::integer,ci.quantity
    into v_source_room_id,v_item_id,v_item_instance_id,v_item_name,
         v_is_usable,v_use_behaviour,v_target_mode,v_cooldown_minutes,
         v_max_charges,v_charges_remaining,v_quantity
    from public.character_items ci
    join public.items i on i.id=ci.item_id
    join public.characters c on c.id=ci.character_id
    where ci.id=p_record_id and ci.character_id=p_source_character_id;

  elsif p_record_kind='unique' then
    select c.current_room_id,inst.item_id,inst.id,coalesce(inst.custom_name,i.name),
           i.is_usable,i.use_behaviour,i.target_mode,i.cooldown_minutes,i.max_charges,
           coalesce(inst.charges_remaining,i.max_charges),1
    into v_source_room_id,v_item_id,v_item_instance_id,v_item_name,
         v_is_usable,v_use_behaviour,v_target_mode,v_cooldown_minutes,
         v_max_charges,v_charges_remaining,v_quantity
    from public.character_item_instances inst
    join public.items i on i.id=inst.item_id
    join public.characters c on c.id=inst.owner_character_id
    where inst.id=p_record_id
      and inst.owner_character_id=p_source_character_id
      and inst.vault_status='owned';

  else
    raise exception 'Invalid inventory record type.';
  end if;

  if v_item_id is null then
    raise exception 'NPC does not own this Item.';
  end if;

  if coalesce(v_is_usable,false)=false then
    raise exception 'This Item cannot be used.';
  end if;

  if coalesce(v_target_mode,'self')='self' then
    v_target_character_id:=p_source_character_id;
  elsif v_target_mode='other' then
    if p_target_character_id is null then
      raise exception 'Choose a target.';
    end if;
    if p_target_character_id=p_source_character_id then
      raise exception 'This Item must target another character.';
    end if;
    v_target_character_id:=p_target_character_id;
  elsif v_target_mode='either' then
    v_target_character_id:=coalesce(p_target_character_id,p_source_character_id);
  else
    raise exception 'Invalid Item target mode.';
  end if;

  select c.display_name,c.current_room_id,c.current_health
  into v_target_name,v_target_room_id,v_target_health
  from public.characters c
  where c.id=v_target_character_id and c.status='approved';

  if v_target_room_id is null then
    raise exception 'Target character is not available.';
  end if;

  if v_target_character_id<>p_source_character_id
     and v_source_room_id<>v_target_room_id then
    raise exception 'Target character must be in the same location.';
  end if;

  v_source_key:=case
    when p_record_kind='standard' then 'standard:'||v_item_id::text
    else 'unique:'||v_item_instance_id::text
  end;

  select ready_at into v_ready_at
  from public.character_item_use_cooldowns
  where character_id=p_source_character_id and source_key=v_source_key;

  if v_ready_at is not null and v_ready_at>now() then
    raise exception 'This Item is still on cooldown.';
  end if;

  v_target_max_health:=public.get_character_current_max_health(v_target_character_id);
  v_target_health:=greatest(
    0,
    least(coalesce(v_target_health,v_target_max_health),v_target_max_health)
  );

  select
    exists(select 1 from public.item_effects e
           where e.item_id=v_item_id and e.trigger_type='use'),
    exists(select 1 from public.item_effects e
           where e.item_id=v_item_id and e.trigger_type='use'
             and e.effect_mode='temporary'),
    exists(select 1 from public.item_effects e
           where e.item_id=v_item_id and e.trigger_type='use'
             and e.effect_mode='instant' and e.health_delta>0),
    exists(select 1 from public.item_effects e
           where e.item_id=v_item_id and e.trigger_type='use'
             and e.effect_mode='instant'
             and (
               (e.health_delta>0 and v_target_health<v_target_max_health)
               or
               (e.health_delta<0 and v_target_health>0)
             ))
  into v_has_use_effect,v_has_temporary,v_has_positive_heal,v_has_applicable_instant;

  if not v_has_use_effect then
    return jsonb_build_object(
      'ok',false,'blocked',true,
      'block_reason','This Item has no configured Use effect.'
    );
  end if;

  if not v_has_temporary and not v_has_applicable_instant then
    if v_has_positive_heal and v_target_health>=v_target_max_health then
      return jsonb_build_object(
        'ok',false,'blocked',true,
        'block_reason','Target is already at full Health.'
      );
    end if;

    return jsonb_build_object(
      'ok',false,'blocked',true,
      'block_reason','This Item would have no effect on that target right now.'
    );
  end if;

  for v_effect in
    select e.*
    from public.item_effects e
    where e.item_id=v_item_id and e.trigger_type='use'
    order by e.sort_order,e.id
  loop
    if v_effect.effect_mode='instant' then
      v_health_delta:=v_health_delta+coalesce(v_effect.health_delta,0);

    elsif v_effect.effect_mode='temporary' then
      if coalesce(v_effect.allow_duplicate_stacking,false)=false then
        delete from public.character_active_item_effects
        where character_id=v_target_character_id
          and source_effect_id=v_effect.id;
      end if;

      insert into public.character_active_item_effects(
        character_id,item_id,item_instance_id,source_effect_id,source_name,
        muscles_modifier,reflexes_modifier,vigour_modifier,shrewd_modifier,
        brains_modifier,presence_modifier,max_health_modifier,
        warping_affinity_modifier,warps_per_day_modifier,
        activated_at,expires_at
      )
      values(
        v_target_character_id,v_item_id,v_item_instance_id,v_effect.id,v_item_name,
        coalesce(v_effect.muscles_modifier,0),
        coalesce(v_effect.reflexes_modifier,0),
        coalesce(v_effect.vigour_modifier,0),
        coalesce(v_effect.shrewd_modifier,0),
        coalesce(v_effect.brains_modifier,0),
        coalesce(v_effect.presence_modifier,0),
        coalesce(v_effect.max_health_modifier,0),
        coalesce(v_effect.warping_affinity_modifier,0),
        coalesce(v_effect.warps_per_day_modifier,0),
        now(),
        now()+make_interval(mins=>v_effect.duration_minutes)
      );

      v_temporary_count:=v_temporary_count+1;
    end if;
  end loop;

  if v_health_delta<>0 then
    v_target_max_health:=public.get_character_current_max_health(v_target_character_id);

    update public.characters
    set current_health=greatest(
          0,
          least(
            coalesce(current_health,v_target_max_health)+v_health_delta,
            v_target_max_health
          )
        ),
        updated_at=now()
    where id=v_target_character_id;
  end if;

  if p_record_kind='standard' and v_use_behaviour='consumable' then
    if v_quantity<=1 then
      delete from public.character_items where id=p_record_id;
    else
      update public.character_items
      set quantity=quantity-1,updated_at=now()
      where id=p_record_id;
    end if;

  elsif p_record_kind='unique' and v_max_charges is not null then
    update public.character_item_instances
    set charges_remaining=greatest(
          0,
          coalesce(charges_remaining,v_max_charges)-1
        ),
        updated_at=now()
    where id=p_record_id;

    v_charges_remaining:=greatest(
      0,
      coalesce(v_charges_remaining,v_max_charges)-1
    );
  end if;

  if coalesce(v_cooldown_minutes,0)>0 then
    v_ready_at:=now()+make_interval(mins=>v_cooldown_minutes);

    insert into public.character_item_use_cooldowns(
      character_id,source_key,item_id,item_instance_id,ready_at,updated_at
    )
    values(
      p_source_character_id,v_source_key,v_item_id,v_item_instance_id,
      v_ready_at,now()
    )
    on conflict(character_id,source_key)
    do update set
      ready_at=excluded.ready_at,
      updated_at=now();
  end if;

  return jsonb_build_object(
    'ok',true,
    'item_name',v_item_name,
    'target_character_id',v_target_character_id,
    'target_name',v_target_name,
    'health_delta',v_health_delta,
    'temporary_effects',v_temporary_count,
    'charges_remaining',v_charges_remaining,
    'cooldown_ready_at',v_ready_at
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public._ensure_odd_job_rates(p_work_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.odd_job_daily_rates(
    work_date,
    job_id,
    pay,
    starting_pay,
    claims_used,
    max_claims
  )
  select
    p_work_date,
    j.id,
    generated_pay,
    generated_pay,
    0,
    50
  from (
    select
      oj.id,
      floor(random() * 41 + 10)::integer as generated_pay
    from public.odd_jobs oj
    where oj.is_active = true
  ) as j
  on conflict(work_date, job_id) do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._grant_expertise(p_character_id uuid, p_amount numeric, p_source text, p_source_units numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text, p_awarded_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_amount = 0 then return; end if;

  update public.characters
  set expertise = greatest(0, expertise + p_amount),
      updated_at = now()
  where id = p_character_id;

  if not found then
    raise exception 'Character not found';
  end if;

  insert into public.character_expertise_ledger(
    character_id, amount, source, source_units, note, awarded_by_user_id
  ) values (
    p_character_id, p_amount, p_source, p_source_units, p_note, p_awarded_by
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public._normalize_character_inventory_stacks(p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  g record;
  r record;
  v_remaining integer;
  v_target integer;
  v_first_source text;
  v_first_assigned_by uuid;
begin
  if p_character_id is null then
    return;
  end if;

  for g in
    select
      ci.item_id,
      ci.container_instance_id,
      sum(ci.quantity)::integer as total_quantity,
      i.max_stack
    from public.character_items ci
    join public.items i
      on i.id = ci.item_id
    where ci.character_id = p_character_id
      and i.stackable = true
    group by
      ci.item_id,
      ci.container_instance_id,
      i.max_stack
    having count(*) > 1
  loop
    v_remaining := g.total_quantity;
    v_first_source := null;
    v_first_assigned_by := null;

    for r in
      select
        ci.id,
        ci.quantity,
        ci.acquisition_source,
        ci.assigned_by
      from public.character_items ci
      where ci.character_id = p_character_id
        and ci.item_id = g.item_id
        and ci.container_instance_id is not distinct from g.container_instance_id
      order by ci.acquired_at asc, ci.id asc
      for update
    loop
      if v_first_source is null then
        v_first_source := r.acquisition_source;
        v_first_assigned_by := r.assigned_by;
      end if;

      if v_remaining <= 0 then
        delete from public.character_items
        where id = r.id;
        continue;
      end if;

      v_target :=
        case
          when g.max_stack is null then v_remaining
          else least(g.max_stack, v_remaining)
        end;

      update public.character_items
      set quantity = v_target
      where id = r.id;

      v_remaining := v_remaining - v_target;
    end loop;

    while v_remaining > 0 loop
      v_target :=
        case
          when g.max_stack is null then v_remaining
          else least(g.max_stack, v_remaining)
        end;

      insert into public.character_items (
        character_id,
        item_id,
        quantity,
        container_instance_id,
        acquisition_source,
        assigned_by
      )
      values (
        p_character_id,
        g.item_id,
        v_target,
        g.container_instance_id,
        coalesce(v_first_source, 'system'),
        v_first_assigned_by
      );

      v_remaining := v_remaining - v_target;
    end loop;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._odd_job_current_pay(p_starting_pay integer, p_claims_used integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select greatest(
    1,
    ceil(
      p_starting_pay::numeric *
      greatest(
        0,
        1 - (floor(p_claims_used / 5.0) * 0.10)
      )
    )::integer
  );
$function$
;

CREATE OR REPLACE FUNCTION public._post_remnant_transaction(p_character_id uuid, p_amount bigint, p_transaction_type text, p_source_type text, p_source_id text, p_reason text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(ledger_id uuid, new_balance bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_balance bigint;
  v_new_balance bigint;
  v_ledger_id uuid;
begin
  if p_amount = 0 then raise exception 'Remnant transaction amount cannot be zero.'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'A transaction reason is required.'; end if;

  insert into public.character_wallets(character_id, balance)
  values (p_character_id, 100)
  on conflict (character_id) do nothing;

  select balance into v_balance
  from public.character_wallets
  where character_id = p_character_id
  for update;

  v_new_balance := v_balance + p_amount;
  if v_new_balance < 0 then raise exception 'Insufficient Remnants.'; end if;

  update public.character_wallets
  set balance = v_new_balance, updated_at = now()
  where character_id = p_character_id;

  insert into public.remnant_ledger(
    character_id, amount, balance_after, transaction_type,
    source_type, source_id, reason, actor_user_id
  )
  values (
    p_character_id, p_amount, v_new_balance, p_transaction_type,
    p_source_type, p_source_id, p_reason, p_actor_user_id
  )
  returning id into v_ledger_id;

  return query select v_ledger_id, v_new_balance;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.add_item_trade_offer(tid uuid, k text, r uuid, q integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid:=public.my_character_id(); have int; pol text; quest bool; inst public.character_item_instances%rowtype;
begin
  perform public.enforce_db_user_rate_limit('db_item_trade_mutation_user', auth.uid(), 60, 60);
 if not exists(select 1 from item_trades where id=tid and status='open' and me in(character_one_id,character_two_id)) then raise exception 'Open exchange not found.'; end if;
 if q<1 then raise exception 'Quantity must be at least 1.'; end if;
 if public.item_record_is_equipped(k,r,me) then raise exception 'Unequip this Item first.'; end if;
 if k='standard' then
  select ci.quantity,i.transfer_policy,i.is_quest_item into have,pol,quest from character_items ci join items i on i.id=ci.item_id where ci.id=r and ci.character_id=me and ci.container_instance_id is null;
  if not found or q>have then raise exception 'Item or quantity is no longer available.'; end if;
 elsif k='unique' then
  if q<>1 then raise exception 'Unique Items have quantity 1.'; end if;
  select * into inst from character_item_instances where id=r and owner_character_id=me and container_instance_id is null and vault_status='owned';
  if not found then raise exception 'Unique Item is no longer available.'; end if;
  select coalesce(inst.transfer_policy_override,i.transfer_policy),coalesce(inst.is_quest_item_override,i.is_quest_item) into pol,quest from items i where i.id=inst.item_id;
 else raise exception 'Invalid Item type.'; end if;
 if pol<>'free' or quest then raise exception 'This Item cannot be exchanged.'; end if;
 insert into item_trade_offers(trade_id,character_id,record_kind,record_id,quantity) values(tid,me,k,r,q)
 on conflict(trade_id,record_kind,record_id) do update set quantity=excluded.quantity,character_id=excluded.character_id;
 update item_trades set character_one_confirmed=false,character_two_confirmed=false,updated_at=now() where id=tid;
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_vault_assign_unique_item(p_instance_id uuid, p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid(); v_status text; v_owner uuid; v_action_id uuid; v_item_id uuid; v_item_name text;
begin
  perform public.assert_character_economy_staff();
 if v_actor is null or not exists(select 1 from staff_members where user_id=v_actor) then raise exception 'Staff access required.'; end if;
 perform 1 from characters where id=p_character_id for update;
 if not found then raise exception 'Character not found.'; end if;
 select cii.vault_status,cii.owner_character_id,cii.item_id,coalesce(cii.custom_name,i.name)
 into v_status,v_owner,v_item_id,v_item_name
 from character_item_instances cii join items i on i.id=cii.item_id
 where cii.id=p_instance_id for update;
 if not found or v_status<>'admin_vault' or v_owner is not null then raise exception 'That Item is not currently in the Admin Vault.'; end if;
 v_action_id := public.character_audit_begin_action('staff_item_grant','staff_inventory');
 update character_item_instances set owner_character_id=p_character_id,vault_status='owned',container_instance_id=null,updated_at=now() where id=p_instance_id;
 insert into item_instance_history(item_instance_id,to_character_id,actor_user_id,event_type,details)
 values(p_instance_id,p_character_id,v_actor,'assigned_from_admin_vault','Assigned from the Admin Vault to a character.');
 perform public.character_audit_write_event(
   p_character_id,'staff_item_grant','staff_inventory',v_action_id,
   jsonb_build_object('item_id',v_item_id,'item_name',v_item_name,'quantity',1,'record_kind','unique','via','admin_vault'),
   'staff_item_grant',p_instance_id::text
 );
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_vault_create_unique_item(p_item_id uuid, p_custom_name text DEFAULT NULL::text, p_custom_description text DEFAULT NULL::text, p_custom_image_url text DEFAULT NULL::text, p_quality_override text DEFAULT NULL::text, p_transfer_policy_override text DEFAULT NULL::text, p_is_quest_item_override boolean DEFAULT NULL::boolean, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid(); v_id uuid; v_behaviour text; v_charges integer;
begin
  perform public.assert_character_economy_staff();
 if v_actor is null or not exists(select 1 from staff_members where user_id=v_actor) then raise exception 'Staff access required.'; end if;
 if p_quality_override is not null and p_quality_override not in ('poor','average','fine','superior','flawless','peerless') then raise exception 'Invalid quality override.'; end if;
 if p_transfer_policy_override is not null and p_transfer_policy_override not in ('free','restricted','bound') then raise exception 'Invalid transfer-policy override.'; end if;
 select use_behaviour,max_charges into v_behaviour,v_charges from items where id=p_item_id;
 if not found then raise exception 'Item not found.'; end if;
 insert into character_item_instances(item_id,owner_character_id,custom_name,custom_description,custom_image_url,quality_override,transfer_policy_override,is_quest_item_override,notes,charges_remaining,container_instance_id,vault_status,acquisition_source,assigned_by)
 values(p_item_id,null,nullif(btrim(p_custom_name),''),nullif(btrim(p_custom_description),''),nullif(btrim(p_custom_image_url),''),nullif(btrim(p_quality_override),''),nullif(btrim(p_transfer_policy_override),''),p_is_quest_item_override,nullif(btrim(p_notes),''),case when v_behaviour='limited_charges' then v_charges else null end,null,'admin_vault','staff',v_actor)
 returning id into v_id;
 insert into item_instance_history(item_instance_id,actor_user_id,event_type,details)
 values(v_id,v_actor,'created_in_admin_vault','Created as an individual Item instance in the Admin Vault.');
 return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_vault_destroy_unique_item(p_instance_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_reason text := nullif(btrim(p_reason), '');
  v_instance public.character_item_instances%rowtype;
  v_master jsonb;
  v_master_name text;
  v_master_quality text;
  v_master_image text;
  v_history jsonb;
  v_archive_id uuid;
  v_standard_children bigint;
  v_unique_children bigint;
begin
  perform public.assert_character_economy_staff();
  if v_actor is null then
    raise exception 'You must be signed in.';
  end if;

  if not exists (
    select 1
    from public.staff_members
    where user_id = v_actor
  ) then
    raise exception 'Staff access required.';
  end if;

  if v_reason is null then
    raise exception 'A destruction reason is required.';
  end if;

  if char_length(v_reason) > 1000 then
    raise exception 'Destruction reason must be 1000 characters or fewer.';
  end if;

  select *
  into v_instance
  from public.character_item_instances
  where id = p_instance_id
  for update;

  if not found
     or v_instance.vault_status <> 'admin_vault'
     or v_instance.owner_character_id is not null then
    raise exception 'Only ownerless Admin Vault Items can be destroyed here.';
  end if;

  select count(*)
  into v_standard_children
  from public.character_items
  where container_instance_id = p_instance_id;

  select count(*)
  into v_unique_children
  from public.character_item_instances
  where container_instance_id = p_instance_id;

  if coalesce(v_standard_children, 0) + coalesce(v_unique_children, 0) > 0 then
    raise exception 'Empty this container before moving or destroying it.';
  end if;

  select to_jsonb(i), i.name, i.quality, i.image_url
  into v_master, v_master_name, v_master_quality, v_master_image
  from public.items i
  where i.id = v_instance.item_id;

  select coalesce(
    jsonb_agg(to_jsonb(h) order by h.created_at asc),
    '[]'::jsonb
  )
  into v_history
  from public.item_instance_history h
  where h.item_instance_id = p_instance_id;

  insert into public.destroyed_item_instances (
    original_instance_id,
    item_id,
    item_name,
    display_name,
    description,
    image_url,
    quality,
    destruction_reason,
    destroyed_by,
    instance_snapshot,
    master_item_snapshot,
    provenance_snapshot
  )
  values (
    v_instance.id,
    v_instance.item_id,
    coalesce(v_master_name, 'Unknown Item'),
    coalesce(nullif(btrim(v_instance.custom_name), ''), v_master_name, 'Unknown Item'),
    coalesce(nullif(btrim(v_instance.custom_description), ''), v_master ->> 'description'),
    coalesce(nullif(btrim(v_instance.custom_image_url), ''), v_master_image),
    coalesce(v_instance.quality_override, v_master_quality),
    v_reason,
    v_actor,
    to_jsonb(v_instance),
    v_master,
    v_history
  )
  returning id into v_archive_id;

  delete from public.item_instance_history
  where item_instance_id = p_instance_id;

  delete from public.character_item_instances
  where id = p_instance_id;

  if not found then
    raise exception 'Vault Item could not be destroyed.';
  end if;

  return v_archive_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.admin_vault_send_unique_item(p_instance_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid(); v_character_id uuid; v_status text; a bigint; b bigint; v_action_id uuid; v_item_id uuid; v_item_name text;
begin
  perform public.assert_character_economy_staff();
 if v_actor is null or not exists(select 1 from staff_members where user_id=v_actor) then raise exception 'Staff access required.'; end if;
 select cii.owner_character_id,cii.vault_status,cii.item_id,coalesce(cii.custom_name,i.name)
 into v_character_id,v_status,v_item_id,v_item_name
 from character_item_instances cii join items i on i.id=cii.item_id
 where cii.id=p_instance_id for update;
 if not found or v_character_id is null or v_status<>'owned' then raise exception 'Owned Unique Item not found.'; end if;
 select count(*) into a from character_items where container_instance_id=p_instance_id;
 select count(*) into b from character_item_instances where container_instance_id=p_instance_id;
 if coalesce(a,0)+coalesce(b,0)>0 then raise exception 'Empty this container before moving or destroying it.'; end if;
 v_action_id := public.character_audit_begin_action('staff_item_removal','staff_inventory');
 update character_item_instances set owner_character_id=null,container_instance_id=null,vault_status='admin_vault',updated_at=now() where id=p_instance_id;
 insert into item_instance_history(item_instance_id,from_character_id,actor_user_id,event_type,details)
 values(p_instance_id,v_character_id,v_actor,'moved_to_admin_vault','Removed from the character and placed in the Admin Vault.');
 perform public.character_audit_write_event(
   v_character_id,'staff_item_removal','staff_inventory',v_action_id,
   jsonb_build_object('item_id',v_item_id,'item_name',v_item_name,'quantity',1,'record_kind','unique','via','admin_vault'),
   'staff_item_removal',p_instance_id::text
 );
 return v_character_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_vault_update_unique_item(p_instance_id uuid, p_custom_name text DEFAULT NULL::text, p_custom_description text DEFAULT NULL::text, p_custom_image_url text DEFAULT NULL::text, p_quality_override text DEFAULT NULL::text, p_transfer_policy_override text DEFAULT NULL::text, p_is_quest_item_override boolean DEFAULT NULL::boolean, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_status text;
  v_owner uuid;
begin
  perform public.assert_character_economy_staff();
  if v_actor is null then
    raise exception 'You must be signed in.';
  end if;

  if not exists (
    select 1
    from public.staff_members
    where user_id = v_actor
  ) then
    raise exception 'Staff access required.';
  end if;

  if p_quality_override is not null
     and p_quality_override not in (
       'poor', 'average', 'fine', 'superior', 'flawless', 'peerless'
     ) then
    raise exception 'Invalid quality override.';
  end if;

  if p_transfer_policy_override is not null
     and p_transfer_policy_override not in (
       'free', 'restricted', 'bound'
     ) then
    raise exception 'Invalid transfer-policy override.';
  end if;

  select vault_status, owner_character_id
  into v_status, v_owner
  from public.character_item_instances
  where id = p_instance_id
  for update;

  if not found
     or v_status <> 'admin_vault'
     or v_owner is not null then
    raise exception 'That Item is no longer in the Admin Vault.';
  end if;

  update public.character_item_instances
  set
    custom_name = nullif(btrim(p_custom_name), ''),
    custom_description = nullif(btrim(p_custom_description), ''),
    custom_image_url = nullif(btrim(p_custom_image_url), ''),
    quality_override = nullif(btrim(p_quality_override), ''),
    transfer_policy_override = nullif(btrim(p_transfer_policy_override), ''),
    is_quest_item_override = p_is_quest_item_override,
    notes = nullif(btrim(p_notes), ''),
    updated_at = now()
  where id = p_instance_id;

  insert into public.item_instance_history (
    item_instance_id,
    actor_user_id,
    event_type,
    details
  )
  values (
    p_instance_id,
    v_actor,
    'admin_updated_in_vault',
    'Individual Item details were updated while stored in the Admin Vault.'
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.advance_sep_weather()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ws public.world_state%rowtype;

  effective_game_time timestamptz;
  game_month integer;
  game_hour integer;
  season text;

  roll double precision;
  stay_roll double precision;

  next_weather text;
  next_intensity text;

  base_temp integer;
  time_modifier integer;
  weather_modifier integer;
  random_modifier integer;
  next_temp integer;

  duration_hours double precision;
  previous_json jsonb;
begin
  select *
  into ws
  from public.world_state
  where id = 'aureth'
  for update;

  if not found then
    return;
  end if;

  if not ws.automatic_weather then
    return;
  end if;

  -- Work out the actual current in-game time from the clock anchor.
  if ws.automatic_time then
    effective_game_time :=
      ws.game_datetime
      + (
          extract(
            epoch from (
              clock_timestamp() - ws.updated_at
            )
          )
          * greatest(ws.time_scale, 0)
        ) * interval '1 second';
  else
    effective_game_time :=
      ws.game_datetime;
  end if;

  -- A staff override is expressed in GAME time.
  if
    ws.weather_override_until_game is not null
    and effective_game_time <
      ws.weather_override_until_game
  then
    return;
  end if;

  if
    ws.next_weather_change_game is not null
    and effective_game_time <
      ws.next_weather_change_game
  then
    return;
  end if;

  game_month :=
    extract(
      month from effective_game_time
    )::integer;

  game_hour :=
    extract(
      hour from effective_game_time
    )::integer;

  season :=
    case
      when game_month between 3 and 5
        then 'spring'
      when game_month between 6 and 8
        then 'summer'
      when game_month between 9 and 11
        then 'autumn'
      else 'winter'
    end;

  previous_json :=
    to_jsonb(ws);

  roll := random();
  stay_roll := random();

  next_weather := ws.weather;

  -- Roughly 30% of checks continue the same spell.
  -- This prevents weather from changing every scheduled evaluation.
  if stay_roll >= 0.30 then
    case ws.weather
      when 'clear' then
        if roll < 0.62 then
          next_weather := 'partly_cloudy';
        elsif roll < 0.88 then
          next_weather := 'cloudy';
        else
          next_weather := 'fog';
        end if;

      when 'partly_cloudy' then
        if roll < 0.34 then
          next_weather := 'clear';
        elsif roll < 0.78 then
          next_weather := 'cloudy';
        else
          next_weather := 'overcast';
        end if;

      when 'cloudy' then
        if roll < 0.27 then
          next_weather := 'partly_cloudy';
        elsif roll < 0.61 then
          next_weather := 'overcast';
        elsif roll < 0.84 then
          next_weather := 'drizzle';
        else
          next_weather := 'fog';
        end if;

      when 'overcast' then
        if roll < 0.23 then
          next_weather := 'cloudy';
        elsif roll < 0.49 then
          next_weather := 'drizzle';
        elsif roll < 0.81 then
          next_weather := 'rain';
        elsif roll < 0.94 then
          next_weather := 'heavy_rain';
        else
          next_weather := 'storm';
        end if;

      when 'fog' then
        if roll < 0.38 then
          next_weather := 'cloudy';
        elsif roll < 0.68 then
          next_weather := 'partly_cloudy';
        elsif roll < 0.86 then
          next_weather := 'drizzle';
        else
          next_weather := 'clear';
        end if;

      when 'drizzle' then
        if roll < 0.30 then
          next_weather := 'cloudy';
        elsif roll < 0.56 then
          next_weather := 'overcast';
        elsif roll < 0.90 then
          next_weather := 'rain';
        else
          next_weather := 'partly_cloudy';
        end if;

      when 'rain' then
        if roll < 0.27 then
          next_weather := 'drizzle';
        elsif roll < 0.51 then
          next_weather := 'overcast';
        elsif roll < 0.79 then
          next_weather := 'heavy_rain';
        elsif roll < 0.91 then
          next_weather := 'storm';
        else
          next_weather := 'cloudy';
        end if;

      when 'heavy_rain' then
        if roll < 0.46 then
          next_weather := 'rain';
        elsif roll < 0.69 then
          next_weather := 'storm';
        else
          next_weather := 'overcast';
        end if;

      when 'storm' then
        if roll < 0.40 then
          next_weather := 'heavy_rain';
        elsif roll < 0.73 then
          next_weather := 'rain';
        else
          next_weather := 'overcast';
        end if;

      when 'snow' then
        if roll < 0.36 then
          next_weather := 'cloudy';
        elsif roll < 0.66 then
          next_weather := 'overcast';
        elsif roll < 0.86 then
          next_weather := 'heavy_snow';
        else
          next_weather := 'partly_cloudy';
        end if;

      when 'heavy_snow' then
        if roll < 0.56 then
          next_weather := 'snow';
        elsif roll < 0.82 then
          next_weather := 'overcast';
        else
          next_weather := 'cloudy';
        end if;
    end case;
  end if;

  -- SEASONAL BIAS.
  -- These are nudges, not complete rerolls, so transitions remain coherent.
  if season = 'spring' then
    if next_weather = 'clear' and random() < 0.22 then
      next_weather := 'partly_cloudy';
    end if;

    if next_weather = 'cloudy' and random() < 0.22 then
      next_weather := 'drizzle';
    end if;

  elsif season = 'summer' then
    -- Summer suppresses snow and prolonged fog.
    if next_weather in ('snow', 'heavy_snow') then
      next_weather := 'rain';
    end if;

    if next_weather = 'fog' and game_hour between 9 and 18 then
      next_weather := 'partly_cloudy';
    end if;

    -- Warm afternoon convection can turn heavy rain into a storm.
    if
      game_hour between 14 and 19
      and next_weather in ('rain', 'heavy_rain')
      and random() < 0.22
    then
      next_weather := 'storm';
    end if;

    if next_weather = 'cloudy' and random() < 0.18 then
      next_weather := 'partly_cloudy';
    end if;

  elsif season = 'autumn' then
    if next_weather = 'clear' and random() < 0.30 then
      next_weather := 'partly_cloudy';
    end if;

    if next_weather = 'cloudy' and random() < 0.26 then
      next_weather := 'overcast';
    end if;

    if
      game_hour <= 8
      and next_weather in ('clear', 'partly_cloudy')
      and random() < 0.22
    then
      next_weather := 'fog';
    end if;

  else
    -- Winter suppresses implausibly warm clear spells a little.
    if next_weather = 'clear' and random() < 0.18 then
      next_weather := 'partly_cloudy';
    end if;
  end if;

  -- Baseline seasonal temperatures.
  base_temp :=
    case season
      when 'spring' then 12
      when 'summer' then 22
      when 'autumn' then 13
      else 4
    end;

  -- TIME-OF-DAY temperature cycle.
  time_modifier :=
    case
      when game_hour between 0 and 4
        then -4
      when game_hour between 5 and 7
        then -2
      when game_hour between 8 and 11
        then 0
      when game_hour between 12 and 16
        then 3
      when game_hour between 17 and 19
        then 1
      else -2
    end;

  weather_modifier :=
    case next_weather
      when 'clear' then 2
      when 'partly_cloudy' then 1
      when 'cloudy' then 0
      when 'overcast' then -1
      when 'fog' then -2
      when 'drizzle' then -2
      when 'rain' then -3
      when 'heavy_rain' then -4
      when 'storm' then -5
      when 'snow' then -5
      when 'heavy_snow' then -7
      else 0
    end;

  random_modifier :=
    floor(random() * 5)::integer - 2;

  next_temp :=
    base_temp
    + time_modifier
    + weather_modifier
    + random_modifier;

  -- WINTER PRECIPITATION becomes snow when cold enough.
  if
    season = 'winter'
    and next_temp <= 2
  then
    if next_weather in ('drizzle', 'rain') then
      next_weather := 'snow';
    elsif next_weather = 'heavy_rain' then
      next_weather := 'heavy_snow';
    end if;
  end if;

  -- Snow cannot survive clearly above freezing.
  if
    next_temp >= 5
    and next_weather in ('snow', 'heavy_snow')
  then
    next_weather :=
      case
        when next_weather = 'heavy_snow'
          then 'heavy_rain'
        else 'rain'
      end;
  end if;

  -- Fog is most natural at night/dawn.
  if
    game_hour between 5 and 8
    and next_weather in ('clear', 'partly_cloudy', 'cloudy')
    and random() < (
      case season
        when 'autumn' then 0.22
        when 'spring' then 0.16
        when 'winter' then 0.14
        else 0.07
      end
    )
  then
    next_weather := 'fog';
  end if;

  next_intensity :=
    case
      when next_weather in ('heavy_rain', 'heavy_snow', 'storm')
        then 'heavy'
      when next_weather in ('drizzle', 'fog')
        then 'light'
      when random() < 0.25
        then 'light'
      when random() < 0.28
        then 'heavy'
      else 'moderate'
    end;

  -- Weather spells normally last 2-5 GAME hours.
  -- Severe conditions are somewhat shorter.
  duration_hours :=
    case
      when next_weather = 'storm'
        then 1.0 + random() * 2.0
      when next_weather in ('heavy_rain', 'heavy_snow')
        then 1.5 + random() * 2.5
      when next_weather = 'fog'
        then 1.0 + random() * 3.0
      else
        2.0 + random() * 3.0
    end;

  -- Re-anchor the automatic clock at the effective game time.
  -- This is crucial because updated_at is also the clock's real-time anchor.
  update public.world_state
  set
    game_datetime = effective_game_time,
    weather = next_weather,
    weather_intensity = next_intensity,
    temperature_c = next_temp,
    weather_last_changed_game = effective_game_time,
    weather_override_until_game = null,
    next_weather_change_game =
      effective_game_time
      + duration_hours * interval '1 hour',
    updated_at = clock_timestamp()
  where id = 'aureth';

  insert into public.world_state_history (
    changed_by,
    previous_state,
    new_state
  )
  values (
    null,
    previous_json,
    jsonb_build_object(
      'source', 'automatic_weather',
      'season', season,
      'game_hour', game_hour,
      'weather', next_weather,
      'weather_intensity', next_intensity,
      'temperature_c', next_temp,
      'game_datetime', effective_game_time,
      'next_weather_change_game',
        effective_game_time
        + duration_hours * interval '1 hour'
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.assert_character_economy_staff()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null
     or not public.can_manage_character_economy()
  then
    raise exception 'Owner or Admin access required.';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.assert_container_capacity(p_container_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  configured_capacity integer;
  used_slots integer;
begin
  if p_container_id is null then
    return;
  end if;

  select i.container_capacity
    into configured_capacity
  from public.character_item_instances ci
  join public.items i
    on i.id = ci.item_id
  where ci.id = p_container_id;

  if configured_capacity is null then
    raise exception
      'This container has no configured slot capacity.';
  end if;

  select
    (
      select count(*)
      from public.character_items c
      where c.container_instance_id = p_container_id
    )
    +
    (
      select count(*)
      from public.character_item_instances ci
      where ci.container_instance_id = p_container_id
    )
  into used_slots;

  if used_slots > configured_capacity then
    raise exception
      'Container capacity exceeded (%/% slots).',
      used_slots,
      configured_capacity;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_account_registration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
