      'terms_version', new.raw_user_meta_data->'terms_version',
      'privacy_version', new.raw_user_meta_data->'privacy_version'
    )
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_character_table_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  oldj jsonb :=
    case
      when tg_op = 'INSERT' then '{}'::jsonb
      else to_jsonb(old)
    end;

  newj jsonb :=
    case
      when tg_op = 'DELETE' then '{}'::jsonb
      else to_jsonb(new)
    end;

  effective jsonb :=
    case
      when tg_op = 'DELETE' then oldj
      else newj
    end;

  character_key text :=
    coalesce(tg_argv[0], 'character_id');

  character_uuid uuid;
  audit_character_uuid uuid;
  entity_id_value text;
  fields text[];
  old_changed jsonb;
  new_changed jsonb;
  event_name text;
  name_snapshot text;
  actor record;
  fallback_source text;

  context_action_id text :=
    nullif(
      current_setting(
        'sepulchria.audit_action_id',
        true
      ),
      ''
    );

  context_action_type text :=
    nullif(
      current_setting(
        'sepulchria.audit_action_type',
        true
      ),
      ''
    );

  context_action_source text :=
    nullif(
      current_setting(
        'sepulchria.audit_action_source',
        true
      ),
      ''
    );

  audit_metadata jsonb;
begin
  begin
    character_uuid :=
      nullif(
        effective ->> character_key,
        ''
      )::uuid;
  exception
    when others then
      character_uuid := null;
  end;

  if character_uuid is null
     and tg_table_name = 'characters'
  then
    begin
      character_uuid :=
        nullif(
          effective ->> 'id',
          ''
        )::uuid;
    exception
      when others then
        character_uuid := null;
    end;
  end if;

  fields :=
    public.character_audit_diff_keys(
      oldj,
      newj
    );

  if tg_op = 'UPDATE'
     and coalesce(
       array_length(fields, 1),
       0
     ) = 0
  then
    return new;
  end if;

  old_changed :=
    public.character_audit_pick(
      oldj,
      fields
    );

  new_changed :=
    public.character_audit_pick(
      newj,
      fields
    );

  event_name :=
    public.character_audit_event_type(
      tg_table_name,
      tg_op,
      oldj,
      newj,
      fields
    );

  entity_id_value :=
    coalesce(
      effective ->> 'id',
      effective ->> 'gift_id',
      effective ->> 'shape_id',
      effective ->> 'item_id',
      effective ->> 'order_id',
      effective ->> 'expertise_id',
      effective ->> 'feature_key'
    );

  if character_uuid is not null then
    select coalesce(
      nullif(c.display_name, ''),
      nullif(
        btrim(
          coalesce(c.first_name, '') ||
          ' ' ||
          coalesce(c.surname, '')
        ),
        ''
      ),
      character_uuid::text
    )
    into name_snapshot
    from public.characters c
    where c.id = character_uuid;

    if name_snapshot is null
       and tg_table_name = 'characters'
    then
      name_snapshot :=
        coalesce(
          nullif(
            effective ->> 'display_name',
            ''
          ),
          nullif(
            btrim(
              coalesce(
                effective ->> 'first_name',
                ''
              ) ||
              ' ' ||
              coalesce(
                effective ->> 'surname',
                ''
              )
            ),
            ''
          ),
          character_uuid::text
        );
    end if;
  end if;

  /*
   * Keep the live FK only while the character still exists.
   *
   * During permanent character deletion, cascading deletes on
   * character-owned tables can fire this audit trigger after the
   * parent character has ceased to be a valid FK target.
   *
   * The audit event must survive, so in that case character_id
   * becomes NULL while entity_id / snapshots retain the history.
   */
  if character_uuid is not null
     and exists (
       select 1
       from public.characters c
       where c.id = character_uuid
     )
  then
    audit_character_uuid := character_uuid;
  else
    audit_character_uuid := null;
  end if;

  select *
  into actor
  from public.character_audit_actor();

  fallback_source :=
    case tg_table_name
      when 'characters'
        then 'character'
      when 'order_memberships'
        then 'orders'
      when 'character_gifts'
        then 'feats'
      when 'character_shapes'
        then 'warping'
      when 'character_items'
        then 'inventory'
      when 'character_item_instances'
        then 'inventory'
      when 'character_feature_entitlements'
        then 'features'
      else tg_table_name
    end;

  audit_metadata :=
    jsonb_build_object(
      'table',
      tg_table_name,
      'schema',
      tg_table_schema,
      'trigger',
      'database'
    );

  if context_action_id is not null then
    audit_metadata :=
      audit_metadata ||
      jsonb_build_object(
        'semantic_event',
        false,
        'raw_mutation',
        true,
        'action_id',
        context_action_id,
        'action_type',
        context_action_type,
        'action_source',
        context_action_source
      );
  end if;

  insert into public.character_audit_log (
    character_id,
    character_name_snapshot,
    event_type,
    entity_type,
    entity_id,
    operation,
    actor_user_id,
    actor_type,
    actor_staff_role,
    actor_label,
    source,
    changed_fields,
    old_values,
    new_values,
    metadata
  )
  values (
    audit_character_uuid,
    name_snapshot,
    event_name,
    tg_table_name,
    entity_id_value,
    lower(tg_op),
    actor.actor_user_id,
    actor.actor_type,
    actor.actor_staff_role,
    actor.actor_label,
    coalesce(
      context_action_source,
      case
        when actor.audit_source = 'database'
          then fallback_source
        else actor.audit_source
      end
    ),
    fields,
    case
      when tg_op = 'INSERT'
        then null
      else old_changed
    end,
    case
      when tg_op = 'DELETE'
        then null
      else new_changed
    end,
    audit_metadata
  );

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_characters_without_expertise()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  oldj jsonb :=
    case
      when tg_op = 'INSERT' then '{}'::jsonb
      else to_jsonb(old) - 'expertise' - 'current_room_id'
    end;

  newj jsonb :=
    case
      when tg_op = 'DELETE' then '{}'::jsonb
      else to_jsonb(new) - 'expertise' - 'current_room_id'
    end;

  effective jsonb :=
    case
      when tg_op = 'DELETE' then oldj
      else newj
    end;

  character_uuid uuid;
  entity_id_value text;
  fields text[];
  old_changed jsonb;
  new_changed jsonb;
  event_name text;
  name_snapshot text;
  actor record;
begin
  begin
    character_uuid := nullif(effective->>'id', '')::uuid;
  exception when others then
    character_uuid := null;
  end;

  fields := public.character_audit_diff_keys(oldj, newj);

  if (
    tg_op = 'UPDATE'
    and coalesce(array_length(fields, 1), 0) = 0
  ) then
    return new;
  end if;

  old_changed := public.character_audit_pick(oldj, fields);
  new_changed := public.character_audit_pick(newj, fields);

  event_name := public.character_audit_event_type(
    'characters',
    tg_op,
    oldj,
    newj,
    fields
  );

  entity_id_value := effective->>'id';

  name_snapshot :=
    coalesce(
      nullif(effective->>'display_name', ''),
      nullif(
        btrim(
          coalesce(effective->>'first_name', '')
          || ' '
          || coalesce(effective->>'surname', '')
        ),
        ''
      ),
      character_uuid::text
    );

  select *
  into actor
  from public.character_audit_actor();

  insert into public.character_audit_log (
    character_id,
    character_name_snapshot,
    event_type,
    entity_type,
    entity_id,
    operation,
    actor_user_id,
    actor_type,
    actor_staff_role,
    actor_label,
    source,
    changed_fields,
    old_values,
    new_values,
    metadata
  )
  values (
    case
      when tg_op = 'DELETE' then null
      else character_uuid
    end,
    name_snapshot,
    event_name,
    'characters',
    entity_id_value,
    lower(tg_op),
    actor.actor_user_id,
    actor.actor_type,
    actor.actor_staff_role,
    actor.actor_label,
    case
      when actor.audit_source = 'database'
        then 'character'
      else actor.audit_source
    end,
    fields,
    case
      when tg_op = 'INSERT' then null
      else old_changed
    end,
    case
      when tg_op = 'DELETE' then null
      else new_changed
    end,
    jsonb_build_object(
      'table', 'characters',
      'schema', tg_table_schema,
      'trigger', 'database'
    )
  );

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$
;

