CREATE OR REPLACE FUNCTION public.calendar_event_expiry_datetime(p_event_date date, p_start_time time without time zone, p_end_time time without time zone)
 RETURNS timestamp with time zone
 LANGUAGE sql
 IMMUTABLE
AS $function$
