CREATE OR REPLACE FUNCTION public.cancel_item_trade(tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid:=public.my_character_id();
begin
  perform public.enforce_db_user_rate_limit('db_item_trade_mutation_user', auth.uid(), 60, 60);
 update item_trades set status='cancelled',cancelled_at=now(),updated_at=now() where id=tid and status='open' and me in(character_one_id,character_two_id);
 if not found then raise exception 'Open exchange not found.'; end if;
end $function$
;

CREATE OR REPLACE FUNCTION public.character_audit_actor()
 RETURNS TABLE(actor_user_id uuid, actor_type text, actor_staff_role text, actor_label text, audit_source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  headers jsonb := public.character_audit_request_headers();
  header_user text;
  header_role text;
  header_source text;
  resolved_user uuid;
  resolved_role text;
  resolved_email text;
begin
  header_user := nullif(headers->>'x-sepulchria-actor-user-id', '');
  header_role := nullif(headers->>'x-sepulchria-actor-role', '');
  header_source := nullif(headers->>'x-sepulchria-audit-source', '');

  if header_user is not null then
    begin
      resolved_user := header_user::uuid;
    exception when others then
      resolved_user := null;
    end;
  else
    resolved_user := auth.uid();
  end if;

  if header_role in ('owner','admin','moderator','master') then
    resolved_role := header_role;
  elsif resolved_user is not null then
    select sm.role::text
      into resolved_role
      from public.staff_members sm
      where sm.user_id = resolved_user
      limit 1;
  end if;

  if resolved_user is not null then
    select u.email
      into resolved_email
      from auth.users u
      where u.id = resolved_user;
  end if;

  actor_user_id := resolved_user;
  actor_staff_role := resolved_role;
  actor_type :=
    case
      when resolved_role is not null then 'staff'
      when resolved_user is not null then 'player'
      else 'system'
    end;
  actor_label :=
    case
      when resolved_role is not null and resolved_email is not null
        then resolved_role || ' · ' || resolved_email
      when resolved_role is not null then resolved_role
      when resolved_email is not null then resolved_email
      else actor_type
    end;
  audit_source := coalesce(header_source, 'database');

  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.character_audit_begin_action(p_action_type text, p_source text, p_action_id uuid DEFAULT gen_random_uuid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_action_id is null then
    raise exception 'Audit action id is required.';
  end if;

  if nullif(btrim(p_action_type), '') is null then
    raise exception 'Audit action type is required.';
  end if;

  if nullif(btrim(p_source), '') is null then
    raise exception 'Audit action source is required.';
  end if;

  perform set_config(
    'sepulchria.audit_action_id',
    p_action_id::text,
    true
  );

  perform set_config(
    'sepulchria.audit_action_type',
    btrim(p_action_type),
    true
  );

  perform set_config(
    'sepulchria.audit_action_source',
    btrim(p_source),
    true
  );

  return p_action_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.character_audit_diff_keys(old_row jsonb, new_row jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(array_agg(k order by k), '{}'::text[])
  from (
    select key as k from jsonb_each(coalesce(old_row, '{}'::jsonb))
    union
    select key as k from jsonb_each(coalesce(new_row, '{}'::jsonb))
  ) keys
  where
    k <> 'updated_at'
    and k <> 'expertise'
    and coalesce(old_row, '{}'::jsonb)->k
        is distinct from
        coalesce(new_row, '{}'::jsonb)->k;
$function$
;

CREATE OR REPLACE FUNCTION public.character_audit_event_type(table_name text, operation_name text, old_row jsonb, new_row jsonb, changed text[])
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  acquisition_source text := lower(coalesce(new_row->>'acquisition_source', ''));
begin
  if table_name = 'characters' then
    if operation_name = 'INSERT' then return 'character_created'; end if;
    if operation_name = 'DELETE' then return 'character_deleted'; end if;

    if 'status' = any(changed) then
      if new_row->>'status' = 'submitted' then return 'character_submitted'; end if;
      if new_row->>'status' = 'approved' then return 'character_approved'; end if;
      if new_row->>'status' = 'rejected' then return 'character_rejected'; end if;
      return 'character_status_changed';
    end if;

    if 'ancestry_id' = any(changed) or 'race_id' = any(changed) then
      return 'ancestry_changed';
    end if;

    if 'association_id' = any(changed) then
      return 'association_changed';
    end if;

    return 'character_updated';
  end if;

  if table_name = 'order_memberships' then
    if operation_name = 'INSERT' then return 'order_joined'; end if;
    if operation_name = 'DELETE' then return 'order_left'; end if;
    if 'order_level_id' = any(changed) or 'level_id' = any(changed)
       or 'rank' = any(changed) or 'level' = any(changed) then
      return 'order_rank_changed';
    end if;
    return 'order_membership_changed';
  end if;

  if table_name = 'character_gifts' then
    if operation_name = 'INSERT' then return 'feat_acquired'; end if;
    if operation_name = 'DELETE' then return 'feat_removed'; end if;
    return 'feat_changed';
  end if;

  if table_name = 'character_shapes' then
    if operation_name = 'INSERT' then return 'shape_acquired'; end if;
    if operation_name = 'DELETE' then return 'shape_removed'; end if;
    return 'shape_changed';
  end if;

  if table_name in ('character_items','character_item_instances') then
    if operation_name = 'INSERT' then
      if acquisition_source in ('market','purchase','shop') then
        return 'item_purchased';
      end if;
      return 'item_acquired';
    end if;
    if operation_name = 'DELETE' then return 'item_removed'; end if;
    return 'inventory_changed';
  end if;

  if table_name = 'character_feature_entitlements' then
    if operation_name = 'INSERT' then return 'feature_entitlement_added'; end if;
    if operation_name = 'DELETE' then return 'feature_entitlement_removed'; end if;
    return 'feature_entitlement_changed';
  end if;

  if table_name like '%expertise%' then
    if operation_name = 'INSERT' then return 'expertise_added'; end if;
    if operation_name = 'DELETE' then return 'expertise_removed'; end if;
    return 'expertise_changed';
  end if;

  if table_name like '%remnant%' or table_name like '%currency%'
     or table_name like '%wallet%' or table_name like '%ledger%' then
    return 'currency_changed';
  end if;

  if table_name like '%market%' then
    return 'market_transaction';
  end if;

  if table_name like '%job%' then
    return 'job_changed';
  end if;

  if table_name like '%mission%' then
    return 'mission_changed';
  end if;

  if operation_name = 'INSERT' then return table_name || '_added'; end if;
  if operation_name = 'DELETE' then return table_name || '_removed'; end if;
  return table_name || '_changed';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.character_audit_pick(row_data jsonb, keys text[])
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(
    jsonb_object_agg(k, row_data->k),
    '{}'::jsonb
  )
  from unnest(coalesce(keys, '{}'::text[])) as k;
$function$
;

CREATE OR REPLACE FUNCTION public.character_audit_request_headers()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  raw text;
begin
  raw := current_setting('request.headers', true);
  if raw is null or btrim(raw) = '' then
    return '{}'::jsonb;
  end if;

  begin
    return raw::jsonb;
  exception when others then
    return '{}'::jsonb;
  end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.character_audit_write_event(p_character_id uuid, p_event_type text, p_source text, p_action_id uuid, p_details jsonb DEFAULT '{}'::jsonb, p_entity_type text DEFAULT 'item_action'::text, p_entity_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_id uuid;
  v_name text;
  v_actor record;
  v_details jsonb := coalesce(p_details, '{}'::jsonb);
begin
  if p_character_id is null then
    raise exception 'Character id is required.';
  end if;

  if nullif(btrim(p_event_type), '') is null then
    raise exception 'Audit event type is required.';
  end if;

  if nullif(btrim(p_source), '') is null then
    raise exception 'Audit source is required.';
  end if;

  if p_action_id is null then
    raise exception 'Audit action id is required.';
  end if;

  select coalesce(
    nullif(c.display_name, ''),
    nullif(
      btrim(
        coalesce(c.first_name, '') || ' ' ||
        coalesce(c.surname, '')
      ),
      ''
    ),
    p_character_id::text
  )
  into v_name
  from public.characters c
  where c.id = p_character_id;

  if v_name is null then
    raise exception 'Character not found.';
  end if;

  select *
  into v_actor
  from public.character_audit_actor();

  insert into public.character_audit_log (
    character_id,
    character_name_snapshot,
    event_type,
    entity_type,
    entity_id,
    operation,
    actor_user_id,
    actor_type,
    actor_staff_role,
    actor_label,
    source,
    changed_fields,
    old_values,
    new_values,
    metadata
  )
  values (
    p_character_id,
    v_name,
    btrim(p_event_type),
    coalesce(nullif(btrim(p_entity_type), ''), 'item_action'),
    coalesce(p_entity_id, p_action_id::text),
    'event',
    v_actor.actor_user_id,
    v_actor.actor_type,
    v_actor.actor_staff_role,
    v_actor.actor_label,
    btrim(p_source),
    '{}'::text[],
    null,
    v_details,
    jsonb_build_object(
      'semantic_event', true,
      'action_id', p_action_id,
      'action_type', btrim(p_event_type),
      'action_source', btrim(p_source)
    )
  )
  returning id into v_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.character_can_equip_item(p_character_id uuid, p_item_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.characters%rowtype;
  i public.items%rowtype;
  membership_job_id uuid;
  membership_level integer;
  membership_order_id uuid;
begin
  select * into c
  from public.characters
  where id = p_character_id;

  if not found then
    return false;
  end if;

  select * into i
  from public.items
  where id = p_item_id;

  if not found
     or i.is_active = false
     or i.is_equippable = false then
    return false;
  end if;

  -- Base Attribute requirements deliberately use permanent character columns.
  if coalesce(c.muscles, 0) < coalesce(i.min_muscles, 0)
     or coalesce(c.reflexes, 0) < coalesce(i.min_reflexes, 0)
     or coalesce(c.vigor, 0) < coalesce(i.min_vigour, 0)
     or coalesce(c.shrewd, 0) < coalesce(i.min_shrewd, 0)
     or coalesce(c.brains, 0) < coalesce(i.min_brains, 0)
     or coalesce(c.presence_score, 0) < coalesce(i.min_presence, 0) then
    return false;
  end if;

  -- If at least one race is configured, the character's race must match one.
  if exists (
    select 1
    from public.item_equipment_races r
    where r.item_id = p_item_id
  )
  and not exists (
    select 1
    from public.item_equipment_races r
    where r.item_id = p_item_id
      and r.race_id = c.race_id
  ) then
    return false;
  end if;

  select
    om.order_job_id,
    ol.level,
    ol.order_id
  into
    membership_job_id,
    membership_level,
    membership_order_id
  from public.order_memberships om
  join public.order_jobs oj
    on oj.id = om.order_job_id
  join public.order_levels ol
    on ol.id = oj.order_level_id
  where om.character_id = p_character_id
  limit 1;

  if exists (
    select 1
    from public.item_equipment_orders o
    where o.item_id = p_item_id
  )
  and (
    membership_order_id is null
    or not exists (
      select 1
      from public.item_equipment_orders o
      where o.item_id = p_item_id
        and o.order_id = membership_order_id
    )
  ) then
    return false;
  end if;

  if exists (
    select 1
    from public.item_equipment_jobs j
    where j.item_id = p_item_id
  )
  and (
    membership_job_id is null
    or not exists (
      select 1
      from public.item_equipment_jobs j
      where j.item_id = p_item_id
        and j.order_job_id = membership_job_id
    )
  ) then
    return false;
  end if;

  if i.min_order_level is not null
     and coalesce(membership_level, -1) < i.min_order_level then
    return false;
  end if;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.characters_have_global_block(a uuid, b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.character_blocks cb
    where (cb.blocker_character_id=a and cb.blocked_character_id=b)
       or (cb.blocker_character_id=b and cb.blocked_character_id=a)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.check_container_capacity_after_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform public.assert_container_capacity(
      old.container_instance_id
    );
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    perform public.assert_container_capacity(
      new.container_instance_id
    );
  end if;

  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.check_signup_age(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  dob_text text;
  dob date;
  confirmed boolean;
begin
  dob_text :=
    event->'user'->'user_metadata'->>'date_of_birth';

  confirmed :=
    coalesce(
      (event->'user'->'user_metadata'->>'age_18_confirmed')::boolean,
      false
    );

  if dob_text is null or dob_text = '' then
    return jsonb_build_object(
      'error',
      jsonb_build_object(
        'http_code', 400,
        'message', 'Date of birth is required.'
      )
    );
  end if;

  begin
    dob := dob_text::date;
  exception
    when others then
      return jsonb_build_object(
        'error',
        jsonb_build_object(
          'http_code', 400,
          'message', 'Invalid date of birth.'
        )
      );
  end;

  if not confirmed then
    return jsonb_build_object(
      'error',
      jsonb_build_object(
        'http_code', 403,
        'message', 'You must confirm that you are at least 18 years old.'
      )
    );
  end if;

  if dob > current_date - interval '18 years' then
    return jsonb_build_object(
      'error',
      jsonb_build_object(
        'http_code', 403,
        'message', 'Sepulchria is only available to users aged 18 or older.'
      )
    );
  end if;

  return '{}'::jsonb;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.claim_my_daily_mission(p_assignment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
  v_assignment public.daily_mission_assignments%rowtype;
  v_day public.daily_mission_days%rowtype;
  v_ledger_id uuid;
  v_new_balance bigint;
begin
  perform public.refresh_my_daily_mission_progress();

  select a.*
  into v_assignment
  from public.daily_mission_assignments a
  where a.id = p_assignment_id
  for update;

  if v_assignment.id is null then
    raise exception 'Daily Mission not found.';
  end if;

  select d.*
  into v_day
  from public.daily_mission_days d
  where d.id = v_assignment.day_id;

  select c.id
  into v_character_id
  from public.characters c
  where c.user_id = auth.uid()
    and c.id = v_day.character_id
    and c.status = 'approved'
    and coalesce(c.is_system, false) = false
  limit 1;

  if v_character_id is null then
    raise exception 'This Daily Mission does not belong to your character.';
  end if;

  if v_day.mission_date <> (now() at time zone 'UTC')::date then
    raise exception 'That Daily Mission has expired.';
  end if;

  if v_assignment.completed_at is null then
    raise exception 'That Daily Mission is not complete yet.';
  end if;

  if v_assignment.claimed_at is not null then
    raise exception 'That Daily Mission reward has already been claimed.';
  end if;

  if v_assignment.reward_remnants_snapshot > 0 then
    select t.ledger_id, t.new_balance
    into v_ledger_id, v_new_balance
    from public._post_remnant_transaction(
      v_character_id,
      v_assignment.reward_remnants_snapshot::bigint,
      'daily_mission_reward',
      'daily_mission_reward',
      v_assignment.id::text,
      'Daily Mission reward: ' || v_assignment.name_snapshot,
      null
    ) t;
  end if;

  perform public.daily_mission_grant_item(
    v_character_id,
    v_assignment.reward_item_id_snapshot,
    v_assignment.reward_item_quantity_snapshot
  );

  update public.daily_mission_assignments
  set claimed_at = now()
  where id = v_assignment.id;

  perform public.daily_mission_audit_event(
    v_character_id,
    'daily_mission_reward_claimed',
    'daily_mission_assignment',
    v_assignment.id,
    jsonb_build_object(
      'mission_date', v_day.mission_date,
      'mission_code', v_assignment.code_snapshot,
      'mission_name', v_assignment.name_snapshot,
      'reward_remnants', v_assignment.reward_remnants_snapshot,
      'reward_item_name', v_assignment.reward_item_name_snapshot,
      'reward_item_quantity', v_assignment.reward_item_quantity_snapshot
    ),
    jsonb_build_object(
      'reward_random_kind', v_assignment.reward_random_kind_snapshot
    )
  );

  return jsonb_build_object(
    'ok', true,
    'mission', v_assignment.name_snapshot
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.claim_my_daily_mission_milestone(p_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
  v_claim public.daily_mission_milestone_claims%rowtype;
  v_day public.daily_mission_days%rowtype;
  v_completed integer;
  v_total integer;
  v_required integer;
  v_ledger_id uuid;
  v_new_balance bigint;
begin
  perform public.refresh_my_daily_mission_progress();

  select mc.*
  into v_claim
  from public.daily_mission_milestone_claims mc
  where mc.id = p_claim_id
  for update;

  if v_claim.id is null then
    raise exception 'Daily Milestone not found.';
  end if;

  select d.*
  into v_day
  from public.daily_mission_days d
  where d.id = v_claim.day_id;

  select c.id
  into v_character_id
  from public.characters c
  where c.user_id = auth.uid()
    and c.id = v_day.character_id
    and c.status = 'approved'
    and coalesce(c.is_system, false) = false
  limit 1;

  if v_character_id is null then
    raise exception 'This Daily Milestone does not belong to your character.';
  end if;

  if v_day.mission_date <> (now() at time zone 'UTC')::date then
    raise exception 'That Daily Milestone has expired.';
  end if;

  if v_claim.claimed_at is not null then
    raise exception 'That Daily Milestone reward has already been claimed.';
  end if;

  select
    count(*) filter (
      where a.completed_at is not null
    )::integer,
    count(*)::integer
  into v_completed, v_total
  from public.daily_mission_assignments a
  where a.day_id = v_day.id
    and a.counts_toward_milestones = true;

  v_required :=
    case
      when v_claim.is_all_snapshot
        then v_total
      else coalesce(v_claim.target_count_snapshot, 0)
    end;

  if v_required <= 0
     or v_completed < v_required
  then
    raise exception 'That Daily Milestone is not complete yet.';
  end if;

  if v_claim.reward_remnants_snapshot > 0 then
    select t.ledger_id, t.new_balance
    into v_ledger_id, v_new_balance
    from public._post_remnant_transaction(
      v_character_id,
      v_claim.reward_remnants_snapshot::bigint,
      'daily_mission_milestone_reward',
      'daily_mission_milestone_reward',
      v_claim.id::text,
      'Daily Milestone reward: ' || v_claim.name_snapshot,
      null
    ) t;
  end if;

  perform public.daily_mission_grant_item(
    v_character_id,
    v_claim.reward_item_id_snapshot,
    v_claim.reward_item_quantity_snapshot
  );

  update public.daily_mission_milestone_claims
  set
    claimed_at = now(),
    completed_at = coalesce(completed_at, now())
  where id = v_claim.id;

  perform public.daily_mission_audit_event(
    v_character_id,
    'daily_milestone_reward_claimed',
    'daily_mission_milestone',
    v_claim.id,
    jsonb_build_object(
      'mission_date', v_day.mission_date,
      'milestone_key', v_claim.milestone_key,
      'milestone_name', v_claim.name_snapshot,
      'completed_missions', v_completed,
      'required_missions', v_required,
      'reward_remnants', v_claim.reward_remnants_snapshot,
      'reward_item_name', v_claim.reward_item_name_snapshot,
      'reward_item_quantity', v_claim.reward_item_quantity_snapshot
    ),
    jsonb_build_object(
      'reward_random_kind', v_claim.reward_random_kind_snapshot,
      'countable_missions', v_total
    )
  );

  return jsonb_build_object(
    'ok', true,
    'milestone', v_claim.name_snapshot
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.claim_odd_job(p_job_id uuid)
 RETURNS TABLE(job_name text, paid integer, new_balance bigint, work_date date, claims_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_room_id uuid;
  v_status text;
  v_work_date date := (now() at time zone 'Europe/London')::date;

  v_job_name text;
  v_starting_pay integer;
  v_claims_used integer;
  v_max_claims integer;
  v_pay integer;

  v_claim_id uuid;
  v_ledger_id uuid;
  v_balance bigint;
begin
  if v_user_id is null then
    raise exception 'Authentication required.';
  end if;

  select
    c.id,
    c.current_room_id,
    c.status::text
  into
    v_character_id,
    v_room_id,
    v_status
  from public.characters as c
  where c.user_id = v_user_id
  limit 1;

  if v_character_id is null then
    raise exception 'Character not found.';
  end if;

  if v_status <> 'approved' then
    raise exception 'Only approved characters can work at the Odd Jobs Bureau.';
  end if;

  if not exists (
    select 1
    from public.rooms as r
    where r.id = v_room_id
      and r.slug = 'odd-jobs-bureau'
      and r.is_active = true
  ) then
    raise exception 'You must be at the Odd Jobs Bureau to work.';
  end if;

  if exists (
    select 1
    from public.odd_job_claims as c
    where c.character_id = v_character_id
      and c.work_date = v_work_date
  ) then
    raise exception 'You have already worked today. Return tomorrow.';
  end if;

  select j.name
  into v_job_name
  from public.odd_jobs as j
  where j.id = p_job_id
    and j.is_active = true;

  if v_job_name is null then
    raise exception 'This job is not currently available.';
  end if;

  perform public._ensure_odd_job_rates(v_work_date);

  -- Critical concurrency lock: one job/day row is processed serially.
  select
    r.starting_pay,
    r.claims_used,
    r.max_claims
  into
    v_starting_pay,
    v_claims_used,
    v_max_claims
  from public.odd_job_daily_rates as r
  where r.work_date = v_work_date
    and r.job_id = p_job_id
  for update;

  if v_starting_pay is null then
    raise exception 'Today''s pay could not be loaded.';
  end if;

  if v_claims_used >= v_max_claims then
    raise exception 'This job has no work slots remaining today.';
  end if;

  -- The character receives the tier displayed BEFORE this click.
  -- The 5th successful click therefore receives the original rate;
  -- clicks 6-10 receive the first 10% reduction.
  v_pay := public._odd_job_current_pay(
    v_starting_pay,
    v_claims_used
  );

  insert into public.odd_job_claims(
    character_id,
    work_date,
    job_id,
    pay
  )
  values(
    v_character_id,
    v_work_date,
    p_job_id,
    v_pay
  )
  returning id into v_claim_id;

  update public.odd_job_daily_rates as r
  set
    claims_used = r.claims_used + 1,
    pay = public._odd_job_current_pay(
      r.starting_pay,
      r.claims_used + 1
    )
  where r.work_date = v_work_date
    and r.job_id = p_job_id;

  select t.ledger_id, t.new_balance
  into v_ledger_id, v_balance
  from public._post_remnant_transaction(
    v_character_id,
    v_pay,
    'income',
    'odd_job',
    v_claim_id::text,
    'Odd Jobs Bureau — ' || v_job_name,
    v_user_id
  ) as t;

  update public.odd_job_claims as c
  set ledger_id = v_ledger_id
  where c.id = v_claim_id;

  return query
  select
    v_job_name,
    v_pay,
    v_balance,
    v_work_date,
    greatest(v_max_claims - (v_claims_used + 1), 0);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.claim_presence_expertise_tick()
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller uuid := auth.uid();
  character_uuid uuid;
  checkpoint timestamptz;
  elapsed numeric;
  elapsed_seconds bigint;
  total_seconds numeric;
  completed_hours integer;
  remainder numeric;
  awarded numeric := 0;
begin
  if caller is null then
    raise exception 'Not authenticated';
  end if;

  select c.id
  into character_uuid
  from public.characters c
  where c.user_id = caller
    and c.status = 'approved'
    and coalesce(c.is_system, false) = false
  limit 1;

  if character_uuid is null then
    return 0;
  end if;

  insert into public.character_expertise_progress(
    character_id,
    presence_checkpoint_at
  )
  values (
    character_uuid,
    now()
  )
  on conflict (character_id) do nothing;

  select p.presence_checkpoint_at
  into checkpoint
  from public.character_expertise_progress p
  where p.character_id = character_uuid
  for update;

  if checkpoint is null then
    update public.character_expertise_progress
    set
      presence_checkpoint_at = now(),
      updated_at = now()
    where character_id = character_uuid;

    return 0;
  end if;

  elapsed :=
    extract(epoch from (now() - checkpoint));

  if elapsed < 540 then
    return 0;
  end if;

  if elapsed > 720 then
    update public.character_expertise_progress
    set
      presence_checkpoint_at = now(),
      updated_at = now()
    where character_id = character_uuid;

    return 0;
  end if;

  elapsed_seconds :=
    floor(elapsed)::bigint;

  -- Existing Expertise portal-time progress.
  update public.character_expertise_progress
  set
    online_seconds =
      coalesce(online_seconds, 0) + elapsed,
    presence_checkpoint_at = now(),
    updated_at = now()
  where character_id = character_uuid
  returning online_seconds into total_seconds;

  -- Permanent lifetime portal-time counter for Trophies.
  insert into public.character_lifetime_stats (
    character_id,
    active_portal_seconds
  )
  values (
    character_uuid,
    elapsed_seconds
  )
  on conflict (character_id)
  do update
  set
    active_portal_seconds =
      public.character_lifetime_stats.active_portal_seconds
      + excluded.active_portal_seconds,
    updated_at = now();

  completed_hours :=
    floor(total_seconds / 3600);

  if completed_hours > 0 then
    remainder :=
      total_seconds -
      (completed_hours * 3600);

    update public.character_expertise_progress
    set
      online_seconds = remainder,
      updated_at = now()
    where character_id = character_uuid;

    awarded :=
      completed_hours * 0.3;

    perform public._grant_expertise(
      character_uuid,
      awarded,
      'portal_time',
      completed_hours,
      completed_hours || ' portal hour(s)',
      null
    );
  end if;

  return awarded;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_security_rate_limits()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted integer;
begin
  delete from public.security_rate_limits
  where window_start < now() - interval '2 days';

  get diagnostics
    v_deleted = row_count;

  return v_deleted;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.confirm_item_trade(tid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := public.my_character_id();
  t public.item_trades%rowtype;
  o record;
  receiver uuid;
  have int;
  pol text;
  quest bool;
  iid uuid;
  inst public.character_item_instances%rowtype;
  v_action_id uuid;
  v_item_name text;
  v_one_name text;
  v_two_name text;
  v_one_gave jsonb := '[]'::jsonb;
  v_two_gave jsonb := '[]'::jsonb;
begin
  perform public.enforce_db_user_rate_limit('db_item_trade_confirm_user', auth.uid(), 20, 60);
  select *
  into t
  from public.item_trades
  where id = tid
    and status = 'open'
    and me in (character_one_id, character_two_id)
  for update;

  if not found then
    raise exception 'Open exchange not found.';
  end if;

  if (
    select current_room_id
    from public.characters
    where id = t.character_one_id
  ) is null
  or (
    select current_room_id
    from public.characters
    where id = t.character_one_id
  ) is distinct from (
    select current_room_id
    from public.characters
    where id = t.character_two_id
  ) then
    raise exception 'Both characters must remain in the same Location.';
  end if;

  if me = t.character_one_id then
    update public.item_trades
    set character_one_confirmed = true, updated_at = now()
    where id = tid;
  else
    update public.item_trades
    set character_two_confirmed = true, updated_at = now()
    where id = tid;
  end if;

  select * into t
  from public.item_trades
  where id = tid
  for update;

  if not (t.character_one_confirmed and t.character_two_confirmed) then
    return false;
  end if;

  if not exists (
    select 1
    from public.item_trade_offers
    where trade_id = tid
  )
  and coalesce(t.character_one_remnants, 0) = 0
  and coalesce(t.character_two_remnants, 0) = 0 then
    raise exception 'The exchange contains no Items or Remnants.';
  end if;

  for o in
    select *
    from public.item_trade_offers
    where trade_id = tid
    order by id
  loop
    if o.character_id <> t.character_one_id
       and o.character_id <> t.character_two_id then
      raise exception 'An offered Item does not belong to an exchange participant.';
    end if;

    if public.item_record_is_equipped(o.record_kind, o.record_id, o.character_id) then
      raise exception 'An offered Item is now equipped.';
    end if;

    if o.record_kind = 'standard' then
      select ci.quantity, ci.item_id, i.name, i.transfer_policy, i.is_quest_item
      into have, iid, v_item_name, pol, quest
      from public.character_items ci
      join public.items i on i.id = ci.item_id
      where ci.id = o.record_id
        and ci.character_id = o.character_id
        and ci.container_instance_id is null
      for update of ci;

      if not found or have < o.quantity or pol <> 'free' or quest then
        raise exception 'An offered Item is no longer transferable.';
      end if;
    else
      select *
      into inst
      from public.character_item_instances
      where id = o.record_id
        and owner_character_id = o.character_id
        and container_instance_id is null
        and vault_status = 'owned'
      for update;

      if not found then
        raise exception 'An offered Unique Item is no longer available.';
      end if;

      select
        coalesce(inst.transfer_policy_override, i.transfer_policy),
        coalesce(inst.is_quest_item_override, i.is_quest_item),
        i.name
      into pol, quest, v_item_name
      from public.items i
      where i.id = inst.item_id;

      if pol <> 'free' or quest then
        raise exception 'An offered Unique Item is no longer transferable.';
      end if;

      iid := inst.item_id;
    end if;

    if o.character_id = t.character_one_id then
      v_one_gave :=
        v_one_gave ||
        jsonb_build_array(
          jsonb_build_object(
            'item_id', iid,
            'item_name', v_item_name,
            'quantity', o.quantity
          )
        );
    else
      v_two_gave :=
        v_two_gave ||
        jsonb_build_array(
          jsonb_build_object(
            'item_id', iid,
            'item_name', v_item_name,
            'quantity', o.quantity
          )
        );
    end if;
  end loop;

  select
    coalesce(nullif(c1.display_name,''), btrim(coalesce(c1.first_name,'')||' '||coalesce(c1.surname,'')), c1.id::text),
    coalesce(nullif(c2.display_name,''), btrim(coalesce(c2.first_name,'')||' '||coalesce(c2.surname,'')), c2.id::text)
  into v_one_name, v_two_name
  from public.characters c1
  cross join public.characters c2
  where c1.id = t.character_one_id
    and c2.id = t.character_two_id;

  v_action_id :=
    public.character_audit_begin_action(
      'item_exchange',
      'item_exchange'
    );

  for o in
    select *
    from public.item_trade_offers
    where trade_id = tid
    order by id
  loop
    receiver :=
      case
        when o.character_id = t.character_one_id then t.character_two_id
        else t.character_one_id
      end;

    if o.record_kind = 'standard' then
      select quantity, item_id
      into have, iid
      from public.character_items
      where id = o.record_id;

      if have = o.quantity then
        update public.character_items
        set
          character_id = receiver,
          acquisition_source = 'trade',
          assigned_by = null,
          updated_at = now()
        where id = o.record_id;
      else
        update public.character_items
        set quantity = quantity - o.quantity, updated_at = now()
        where id = o.record_id;

        insert into public.character_items(
          character_id, item_id, quantity, acquisition_source, acquired_at
        )
        values(receiver, iid, o.quantity, 'trade', now());
      end if;
    else
      update public.character_item_instances
      set
        owner_character_id = receiver,
        acquisition_source = 'trade',
        acquired_at = now(),
        updated_at = now()
      where id = o.record_id;

      insert into public.item_instance_history(
        item_instance_id,
        event_type,
        from_character_id,
        to_character_id,
        actor_user_id,
        details
      )
      values(
        o.record_id,
        'trade',
        o.character_id,
        receiver,
        auth.uid(),
        'Transferred through confirmed Item Exchange.'
      );
    end if;
  end loop;

  perform public.character_audit_write_event(
    t.character_one_id,
    'item_exchange',
    'item_exchange',
    v_action_id,
    jsonb_build_object(
      'other_character_id', t.character_two_id,
      'other_character_name', v_two_name,
      'gave_items', v_one_gave,
      'received_items', v_two_gave,
      'gave_remnants', coalesce(t.character_one_remnants, 0),
      'received_remnants', coalesce(t.character_two_remnants, 0)
    ),
    'item_trade',
    tid::text
  );

  perform public.character_audit_write_event(
    t.character_two_id,
    'item_exchange',
    'item_exchange',
    v_action_id,
    jsonb_build_object(
      'other_character_id', t.character_one_id,
      'other_character_name', v_one_name,
      'gave_items', v_two_gave,
      'received_items', v_one_gave,
      'gave_remnants', coalesce(t.character_two_remnants, 0),
      'received_remnants', coalesce(t.character_one_remnants, 0)
    ),
    'item_trade',
    tid::text
  );

  update public.item_trades
  set status = 'completed', completed_at = now(), updated_at = now()
  where id = tid;

  return true;

exception
  when others then
    update public.item_trades
    set
      character_one_confirmed = false,
      character_two_confirmed = false,
      updated_at = now()
    where id = tid and status = 'open';
    raise;
end
$function$
;

CREATE OR REPLACE FUNCTION public.confirm_item_trade_with_remnants(tid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid;
  v_trade public.item_trades%rowtype;
  v_one_name text;
  v_two_name text;
  v_one_room uuid;
  v_two_room uuid;
  v_one_balance bigint;
  v_two_balance bigint;
  v_one_after bigint;
  v_two_after bigint;
  v_completed boolean;
begin
  if auth.uid() is null then raise exception 'You must be signed in.'; end if;

  select c.id into v_me
  from public.characters c
  where c.user_id = auth.uid()
  limit 1;

  if v_me is null then raise exception 'Unable to identify your character.'; end if;

  select * into v_trade
  from public.item_trades
  where id = tid
  for update;

  if not found then raise exception 'Exchange not found.'; end if;
  if v_trade.status <> 'open' then raise exception 'This exchange is no longer open.'; end if;

  if v_me <> v_trade.character_one_id and v_me <> v_trade.character_two_id then
    raise exception 'You are not part of this exchange.';
  end if;

  select display_name, current_room_id
  into v_one_name, v_one_room
  from public.characters
  where id = v_trade.character_one_id and status = 'approved';

  select display_name, current_room_id
  into v_two_name, v_two_room
  from public.characters
  where id = v_trade.character_two_id and status = 'approved';

  if v_one_room is null or v_two_room is null or v_one_room <> v_two_room then
    raise exception 'Both characters must still be in the same location to complete the exchange.';
  end if;

  insert into public.character_wallets(character_id, balance)
  values
    (v_trade.character_one_id, 0),
    (v_trade.character_two_id, 0)
  on conflict(character_id) do nothing;

  perform 1
  from public.character_wallets
  where character_id in (v_trade.character_one_id, v_trade.character_two_id)
  order by character_id
  for update;

  select balance into v_one_balance
  from public.character_wallets
  where character_id = v_trade.character_one_id;

  select balance into v_two_balance
  from public.character_wallets
  where character_id = v_trade.character_two_id;

  if coalesce(v_one_balance, 0) < v_trade.character_one_remnants then
    raise exception '% no longer has enough Remnants for the promised offer.',
      coalesce(v_one_name, 'Character one');
  end if;

  if coalesce(v_two_balance, 0) < v_trade.character_two_remnants then
    raise exception '% no longer has enough Remnants for the promised offer.',
      coalesce(v_two_name, 'Character two');
  end if;

  select public.confirm_item_trade(tid)
  into v_completed;

  if not coalesce(v_completed, false) then
    return false;
  end if;

  if v_trade.character_one_remnants > 0 then
    update public.character_wallets
    set balance = balance - v_trade.character_one_remnants
    where character_id = v_trade.character_one_id
    returning balance into v_one_after;

    update public.character_wallets
    set balance = balance + v_trade.character_one_remnants
    where character_id = v_trade.character_two_id
    returning balance into v_two_after;

    insert into public.remnant_ledger(
      character_id, amount, balance_after, transaction_type,
      source_type, source_id, reason, actor_user_id
    )
    values
      (
        v_trade.character_one_id,
        -v_trade.character_one_remnants,
        v_one_after,
        'transfer_out',
        'item_trade',
        tid::text,
        'Exchange payment to ' || coalesce(v_two_name, 'other character'),
        auth.uid()
      ),
      (
        v_trade.character_two_id,
        v_trade.character_one_remnants,
        v_two_after,
        'transfer_in',
        'item_trade',
        tid::text,
        'Exchange payment from ' || coalesce(v_one_name, 'other character'),
        auth.uid()
      );
  end if;

  if v_trade.character_two_remnants > 0 then
    update public.character_wallets
    set balance = balance - v_trade.character_two_remnants
    where character_id = v_trade.character_two_id
    returning balance into v_two_after;

    update public.character_wallets
    set balance = balance + v_trade.character_two_remnants
    where character_id = v_trade.character_one_id
    returning balance into v_one_after;

    insert into public.remnant_ledger(
      character_id, amount, balance_after, transaction_type,
      source_type, source_id, reason, actor_user_id
    )
    values
      (
        v_trade.character_two_id,
        -v_trade.character_two_remnants,
        v_two_after,
        'transfer_out',
        'item_trade',
        tid::text,
        'Exchange payment to ' || coalesce(v_one_name, 'other character'),
        auth.uid()
      ),
      (
        v_trade.character_one_id,
        v_trade.character_two_remnants,
        v_one_after,
        'transfer_in',
        'item_trade',
        tid::text,
        'Exchange payment from ' || coalesce(v_two_name, 'other character'),
        auth.uid()
      );
  end if;

  perform public._normalize_character_inventory_stacks(v_trade.character_one_id);
  perform public._normalize_character_inventory_stacks(v_trade.character_two_id);

  return true;
end
$function$
;

CREATE OR REPLACE FUNCTION public.consume_security_rate_limit(p_scope text, p_identifier_hash text, p_limit integer, p_window_seconds integer)
 RETURNS TABLE(allowed boolean, remaining integer, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_window_start timestamptz;
  v_count integer;
  v_retry integer;
begin
  if p_scope is null
     or length(btrim(p_scope)) = 0
     or length(p_scope) > 100
  then
    raise exception 'Invalid rate-limit scope.';
  end if;

  if p_identifier_hash is null
     or length(p_identifier_hash) < 32
     or length(p_identifier_hash) > 128
  then
    raise exception 'Invalid rate-limit identifier.';
  end if;

  if p_limit < 1
     or p_limit > 10000
  then
    raise exception 'Invalid rate-limit maximum.';
  end if;

  if p_window_seconds < 1
     or p_window_seconds > 86400
  then
    raise exception 'Invalid rate-limit window.';
  end if;

  /*
   * Calculate a deterministic fixed-window boundary.
   */
  v_window_start :=
    to_timestamp(
      floor(
        extract(epoch from v_now)
        / p_window_seconds
      ) * p_window_seconds
    );

  insert into public.security_rate_limits (
    scope,
    identifier_hash,
    window_start,
    request_count,
    updated_at
  )
  values (
    p_scope,
    p_identifier_hash,
    v_window_start,
    1,
    v_now
  )
  on conflict (
    scope,
    identifier_hash,
    window_start
  )
  do update set
    request_count =
      public.security_rate_limits.request_count + 1,
    updated_at = v_now
  returning request_count
  into v_count;

  v_retry :=
    greatest(
      1,
      ceil(
        extract(
          epoch from (
            v_window_start
            + make_interval(
                secs => p_window_seconds
              )
            - v_now
          )
        )
      )::integer
    );

  return query
  select
    v_count <= p_limit,
    greatest(
      p_limit - v_count,
      0
    ),
    case
      when v_count > p_limit
        then v_retry
      else 0
    end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.craft_recipe(p_character_id uuid, p_recipe_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_recipe public.crafting_recipes%rowtype;
    v_result_item public.items%rowtype;
    v_requirement record;
    v_stack record;
    v_owned_quantity integer;
    v_inventory_row_id uuid;
    v_instance_id uuid;
    v_result_remaining integer;
    v_add integer;
    v_action_id uuid;
    v_ingredients jsonb := '[]'::jsonb;
begin
    perform pg_advisory_xact_lock(
        hashtextextended(p_character_id::text, 0)
    );

    if not exists (
        select 1
        from public.characters c
        where c.id = p_character_id
          and c.user_id = auth.uid()
    ) then
        raise exception 'You cannot craft for this character.';
    end if;

    select *
    into v_recipe
    from public.crafting_recipes
    where id = p_recipe_id
      and is_active = true;

    if not found then
        raise exception 'Recipe does not exist or is not active.';
    end if;

    if not exists (
        select 1
        from public.character_recipes cr
        where cr.character_id = p_character_id
          and cr.recipe_id = p_recipe_id
    ) then
        raise exception 'This character does not know this recipe.';
    end if;

    for v_requirement in
        select
            cri.ingredient_item_id,
            cri.quantity,
            i.name
        from public.crafting_recipe_ingredients cri
        join public.items i
          on i.id = cri.ingredient_item_id
        where cri.recipe_id = p_recipe_id
        order by cri.sort_order
    loop
        select coalesce(sum(ci.quantity), 0)::integer
        into v_owned_quantity
        from public.character_items ci
        where ci.character_id = p_character_id
          and ci.item_id = v_requirement.ingredient_item_id
          and ci.container_instance_id is null;

        if v_owned_quantity < v_requirement.quantity then
            raise exception
                'Not enough %. Required: %, owned: %.',
                v_requirement.name,
                v_requirement.quantity,
                v_owned_quantity;
        end if;
    end loop;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'item_id', cri.ingredient_item_id,
                'item_name', i.name,
                'quantity', cri.quantity
            )
            order by cri.sort_order
        ),
        '[]'::jsonb
    )
    into v_ingredients
    from public.crafting_recipe_ingredients cri
    join public.items i on i.id = cri.ingredient_item_id
    where cri.recipe_id = p_recipe_id;

    v_action_id :=
        public.character_audit_begin_action(
            'crafting',
            'crafting'
        );

    for v_requirement in
        select
            cri.ingredient_item_id,
            cri.quantity
        from public.crafting_recipe_ingredients cri
        where cri.recipe_id = p_recipe_id
        order by cri.sort_order
    loop
        v_owned_quantity := v_requirement.quantity;

        while v_owned_quantity > 0 loop
            select ci.id
            into v_inventory_row_id
            from public.character_items ci
            where ci.character_id = p_character_id
              and ci.item_id = v_requirement.ingredient_item_id
              and ci.container_instance_id is null
              and ci.quantity > 0
            order by ci.acquired_at, ci.created_at
            limit 1
            for update;

            if not found then
                raise exception
                    'Ingredient inventory changed during crafting.';
            end if;

            declare
                v_stack_quantity integer;
                v_consume integer;
            begin
                select quantity
                into v_stack_quantity
                from public.character_items
                where id = v_inventory_row_id
                for update;

                v_consume := least(v_stack_quantity, v_owned_quantity);

                if v_stack_quantity = v_consume then
                    delete from public.character_items
                    where id = v_inventory_row_id;
                else
                    update public.character_items
                    set
                        quantity = quantity - v_consume,
                        updated_at = now()
                    where id = v_inventory_row_id;
                end if;

                v_owned_quantity := v_owned_quantity - v_consume;
            end;
        end loop;
    end loop;

    select *
    into v_result_item
    from public.items
    where id = v_recipe.result_item_id
      and is_active = true;

    if not found then
        raise exception
            'The item produced by this recipe does not exist or is inactive.';
    end if;

    if v_result_item.stackable then
        v_result_remaining := v_recipe.result_quantity;

        if v_result_item.max_stack is null then
            select ci.id
            into v_inventory_row_id
            from public.character_items ci
            where ci.character_id = p_character_id
              and ci.item_id = v_result_item.id
              and ci.container_instance_id is null
            order by ci.acquired_at, ci.created_at
            limit 1
            for update;

            if found then
                update public.character_items
                set
                    quantity = quantity + v_result_remaining,
                    acquisition_source = 'crafting',
                    updated_at = now()
                where id = v_inventory_row_id;
            else
                insert into public.character_items (
                    character_id,
                    item_id,
                    quantity,
                    container_instance_id,
                    acquisition_source
                )
                values (
                    p_character_id,
                    v_result_item.id,
                    v_result_remaining,
                    null,
                    'crafting'
                );
            end if;

            v_result_remaining := 0;
        else
            for v_stack in
                select
                    ci.id,
                    ci.quantity
                from public.character_items ci
                where ci.character_id = p_character_id
                  and ci.item_id = v_result_item.id
                  and ci.container_instance_id is null
                  and ci.quantity < v_result_item.max_stack
                order by ci.acquired_at, ci.created_at
                for update
            loop
                exit when v_result_remaining <= 0;

                v_add := least(
                    v_result_item.max_stack - v_stack.quantity,
                    v_result_remaining
                );

                if v_add > 0 then
                    update public.character_items
                    set
                        quantity = quantity + v_add,
                        acquisition_source = 'crafting',
                        updated_at = now()
                    where id = v_stack.id;

                    v_result_remaining := v_result_remaining - v_add;
                end if;
            end loop;

            while v_result_remaining > 0 loop
                v_add := least(
                    v_result_item.max_stack,
                    v_result_remaining
                );

                insert into public.character_items (
                    character_id,
                    item_id,
                    quantity,
                    container_instance_id,
                    acquisition_source
                )
                values (
                    p_character_id,
                    v_result_item.id,
                    v_add,
                    null,
                    'crafting'
                );

                v_result_remaining := v_result_remaining - v_add;
            end loop;
        end if;
    else
        for i in 1..v_recipe.result_quantity loop
            insert into public.character_item_instances (
                item_id,
                owner_character_id,
                vault_status,
                acquisition_source
            )
            values (
                v_result_item.id,
                p_character_id,
                'owned',
                'crafting'
            )
            returning id into v_instance_id;
        end loop;
    end if;

    -- --------------------------------------------------------
    -- TROPHY / LIFETIME STAT:
    -- Count the actual number of Items produced.
    -- --------------------------------------------------------

    insert into public.character_lifetime_stats (
        character_id,
        items_crafted_total
    )
    values (
        p_character_id,
        v_recipe.result_quantity
    )
    on conflict (character_id)
    do update
    set
        items_crafted_total =
            public.character_lifetime_stats.items_crafted_total
            + excluded.items_crafted_total,
        updated_at = now();

    perform public.character_audit_write_event(
        p_character_id,
        'crafting',
        'crafting',
        v_action_id,
        jsonb_build_object(
            'recipe_id', v_recipe.id,
            'recipe_name', v_recipe.name,
            'crafted_items', jsonb_build_array(
                jsonb_build_object(
                    'item_id', v_result_item.id,
                    'item_name', v_result_item.name,
                    'quantity', v_recipe.result_quantity
                )
            ),
            'ingredients_used', v_ingredients
        ),
        'crafting',
        p_recipe_id::text
    );

    return jsonb_build_object(
        'success', true,
        'recipe_id', v_recipe.id,
        'recipe_name', v_recipe.name,
        'item_id', v_result_item.id,
        'item_name', v_result_item.name,
        'quantity', v_recipe.result_quantity,
        'message',
            'Crafted ' ||
            v_recipe.result_quantity::text ||
            ' × ' ||
            v_result_item.name ||
            '.'
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_automatic_notification(p_type text, p_title text, p_body text, p_href text, p_target_type text, p_target_id uuid, p_source_type text, p_source_id text, p_source_trigger text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if p_target_type not in ('global', 'staff', 'user', 'character') then
    raise exception 'Invalid notification target type.';
  end if;

  if exists (
    select 1
    from public.notification_suppressions s
    where s.source_type = p_source_type
      and s.source_id = p_source_id
      and s.source_trigger = p_source_trigger
  ) then
    return null;
  end if;

  insert into public.notifications (
    type,
    title,
    body,
    href,
    starts_at,
    expires_at,
    expires_game_at,
    source_type,
    source_id,
    source_trigger,
    is_automatic,
    is_active
  )
  values (
    p_type,
    p_title,
    p_body,
    p_href,
    now(),
    coalesce(p_expires_at, now() + interval '30 days'),
    null,
    p_source_type,
    p_source_id,
    p_source_trigger,
    true,
    true
  )
  on conflict (
    source_type,
    source_id,
    source_trigger
  ) where is_automatic = true
  do nothing
  returning id into v_id;

  if v_id is null then
    select n.id
    into v_id
    from public.notifications n
    where n.is_automatic = true
      and n.source_type = p_source_type
      and n.source_id = p_source_id
      and n.source_trigger = p_source_trigger
    limit 1;
  end if;

  if v_id is not null then
    insert into public.notification_targets (
      notification_id,
      target_type,
      target_id
    )
    values (
      v_id,
      p_target_type,
      case
        when p_target_type in ('global', 'staff') then null
        else p_target_id
      end
    )
    on conflict do nothing;
  end if;

  return v_id;
end;
$function$
;

