CREATE OR REPLACE FUNCTION public.create_forum_topic(requested_section_id uuid, requested_character_id uuid, requested_title text, requested_slug text, requested_body text, requested_quoted_post_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  created_topic_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if trim(coalesce(requested_title, '')) = '' then
    raise exception 'The discussion title is required.';
  end if;

  if trim(coalesce(requested_slug, '')) = '' then
    raise exception 'The discussion slug is required.';
  end if;

  if trim(coalesce(requested_body, '')) = '' then
    raise exception 'The discussion text is required.';
  end if;

  if not public.current_user_can_view_forum_section(
    requested_section_id
  ) then
    raise exception 'You cannot publish in this section.';
  end if;

  if requested_character_id is not null
     and not exists (
       select 1
       from public.characters
       where id = requested_character_id
         and user_id = auth.uid()
     )
  then
    raise exception 'The selected character does not belong to you.';
  end if;

  insert into public.forum_topics (
    section_id,
    author_user_id,
    author_character_id,
    title,
    slug
  )
  values (
    requested_section_id,
    auth.uid(),
    requested_character_id,
    trim(requested_title),
    trim(requested_slug)
  )
  returning id into created_topic_id;

  insert into public.forum_posts (
    topic_id,
    author_user_id,
    author_character_id,
    body,
    quoted_post_id,
    is_initial
  )
  values (
    created_topic_id,
    auth.uid(),
    requested_character_id,
    trim(requested_body),
    requested_quoted_post_id,
    true
  );

  return created_topic_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_forum_topic(requested_section_id uuid, requested_character_id uuid, requested_title text, requested_slug text, requested_body text, requested_quoted_post_id uuid DEFAULT NULL::uuid, requested_is_anonymous boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  created_topic_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if trim(coalesce(requested_title, '')) = '' then
