CREATE OR REPLACE FUNCTION public.create_item_shape_cast(p_shape_id uuid, p_room_id uuid, p_written_target text DEFAULT NULL::text, p_item_shape_id uuid DEFAULT NULL::uuid, p_record_kind text DEFAULT NULL::text, p_record_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
  v_item_id uuid;
  v_shape_id uuid;
  v_charges integer;
  v_used integer;
  v_remaining integer;
  v_reset_date date;
  v_equipped boolean;
  v_cast_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if p_record_kind not in ('standard','unique') then
    raise exception 'Invalid Item record.';
  end if;

  select c.id
    into v_character_id
  from public.characters c
  where c.user_id = auth.uid()
  limit 1;

  if v_character_id is null then
    raise exception 'Character not found.';
  end if;

  if not exists (
    select 1
    from public.characters c
    where c.id = v_character_id
      and c.current_room_id = p_room_id
  ) then
    raise exception 'Your Character is no longer in this room.';
  end if;

  select
    ish.item_id,
    ish.shape_id,
    ish.charges_per_day
  into
    v_item_id,
    v_shape_id,
    v_charges
  from public.item_shapes ish
  join public.items i
    on i.id = ish.item_id
   and i.is_active = true
  join public.shapes s
    on s.id = ish.shape_id
   and s.is_active = true
   and coalesce(s.is_feat_backing, false) = false
  where ish.id = p_item_shape_id
    and ish.shape_id = p_shape_id;

  if v_item_id is null then
    raise exception 'This Item no longer grants that Shape.';
  end if;

  select exists (
    select 1
    from public.get_public_character_inventory(v_character_id) inv
    where inv.record_kind = p_record_kind
      and inv.record_id = p_record_id
      and inv.item_id = v_item_id
      and inv.is_equipped = true
  )
  into v_equipped;

  if not v_equipped then
    raise exception 'The Item granting this Shape must be equipped.';
  end if;

  v_reset_date :=
    (now() at time zone 'utc')::date;

  insert into public.character_item_shape_usage (
    character_id,
    item_shape_id,
    item_record_kind,
    item_record_id,
    reset_date,
    charges_used,
    updated_at
  )
  values (
    v_character_id,
    p_item_shape_id,
    p_record_kind,
    p_record_id,
    v_reset_date,
    1,
    now()
  )
  on conflict (
    character_id,
    item_shape_id,
    item_record_kind,
    item_record_id,
    reset_date
  )
  do update
    set charges_used =
          public.character_item_shape_usage.charges_used + 1,
        updated_at = now()
  where public.character_item_shape_usage.charges_used < v_charges
  returning charges_used
  into v_used;

  if v_used is null or v_used > v_charges then
    raise exception 'No Item Shape charges remaining.';
  end if;

  insert into public.shape_casts (
    caster_character_id,
    shape_id,
    room_id,
    written_target,
    resource_type,
    item_shape_id,
    item_record_kind,
    item_record_id
  )
  values (
    v_character_id,
    p_shape_id,
    p_room_id,
    nullif(btrim(p_written_target), ''),
    'item',
    p_item_shape_id,
    p_record_kind,
    p_record_id
  )
  returning id
  into v_cast_id;

  v_remaining :=
    greatest(
      0,
      v_charges - v_used
    );

  return jsonb_build_object(
    'cast_id', v_cast_id,
    'remaining', v_remaining,
    'charges_per_day', v_charges,
    'reset_date', v_reset_date
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.create_item_trade(other uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := public.my_character_id();
  a uuid;
  b uuid;
  tid uuid;
begin
  perform public.enforce_db_user_rate_limit('db_item_trade_start_user', auth.uid(), 10, 600);
  if me is null or other = me then
    raise exception 'Invalid exchange.';
  end if;

  if exists (
    select 1
    from public.npcs n
    where n.character_id = other
  ) then
    raise exception 'NPCs cannot take part in Item Exchanges. Use Give Item instead.';
  end if;

  perform 1
  from public.characters
  where id in (me, other)
  order by id
  for update;

  select current_room_id into a
  from public.characters
  where id = me and status = 'approved';

  select current_room_id into b
  from public.characters
  where id = other and status = 'approved';

  if a is null or b is distinct from a then
    raise exception 'Both characters must be in the same Location.';
  end if;

  if exists (
    select 1
    from public.item_trades
    where status = 'open'
      and (
        me in (character_one_id, character_two_id)
        or other in (character_one_id, character_two_id)
      )
  ) then
    raise exception 'One character already has an open Item Exchange.';
  end if;

  insert into public.item_trades(character_one_id, character_two_id)
  values(me, other)
  returning id into tid;

  return tid;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_moderation_report(p_reporter_user_id uuid, p_reporter_character_id uuid, p_reporter_name_snapshot text, p_reported_user_id uuid, p_reported_character_id uuid, p_reported_name_snapshot text, p_reason_code text, p_explanation text, p_source_type text, p_source_id uuid, p_source_context jsonb, p_author_user_id uuid, p_author_character_id uuid, p_author_name_snapshot text, p_content_snapshot text, p_original_created_at timestamp with time zone, p_context_snapshot jsonb)
 RETURNS TABLE(ticket_id uuid, public_reference text, report_id uuid)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_ticket_id uuid;
  v_reference text;
  v_report_id uuid;
  v_duplicate_reference text;
  v_recent_count integer;
  v_player_message text;
begin
  if p_reporter_user_id is null then
    raise exception 'A reporter account is required.';
  end if;

  if p_source_type not in (
    'forum_topic',
    'forum_post',
    'direct_message',
    'room_message',
    'instant_chat_message',
    'character'
  ) then
    raise exception 'Unsupported report source.';
  end if;

  if p_reason_code not in (
    'child_sexual_content',
    'child_grooming',
    'suicide_self_harm',
    'eating_disorder',
    'pornographic_media',
    'immediate_safety',
    'harassment',
    'offensive_inappropriate',
    'metagaming_rule_breach',
    'spam',
    'impersonation',
    'sexual_inappropriate',
    'other'
  ) then
    raise exception 'Invalid report reason.';
  end if;

  select t.public_reference
    into v_duplicate_reference
  from public.reports r
  join public.tickets t
    on t.id = r.ticket_id
  where r.reporter_user_id = p_reporter_user_id
    and r.source_type = p_source_type
    and r.source_id = p_source_id
    and t.status not in ('resolved', 'closed')
  order by r.created_at desc
  limit 1;

  if v_duplicate_reference is not null then
    raise exception
      'You already have an open report for this content (%).',
      v_duplicate_reference;
  end if;

  select count(*)
    into v_recent_count
  from public.reports
  where reporter_user_id = p_reporter_user_id
    and created_at >= now() - interval '10 minutes';

  if v_recent_count >= 5 then
    raise exception
      'Too many reports were submitted recently. Please wait before submitting another.';
  end if;

  insert into public.tickets (
    category,
    status,
    priority,
    subject,
    opened_by_user_id,
    opened_by_character_id,
    subject_user_id,
    subject_character_id
  )
  values (
    'report',
    'open',
    'normal',
    case p_source_type
      when 'forum_topic' then 'Report: Forum topic'
      when 'forum_post' then 'Report: Forum post'
      when 'direct_message' then 'Report: Private message'
      when 'room_message' then 'Report: Location message'
      when 'instant_chat_message' then 'Report: Instant Chat message'
      when 'character' then 'Report: Character profile'
      else 'Report'
    end,
    p_reporter_user_id,
    p_reporter_character_id,
    p_reported_user_id,
    p_reported_character_id
  )
  returning id, tickets.public_reference
  into v_ticket_id, v_reference;

  insert into public.reports (
    ticket_id,
    reporter_user_id,
    reporter_character_id,
    reported_user_id,
    reported_character_id,
    reporter_name_snapshot,
    reported_name_snapshot,
    reason_code,
    explanation,
    source_type,
    source_id,
    source_context
  )
  values (
    v_ticket_id,
    p_reporter_user_id,
    p_reporter_character_id,
    p_reported_user_id,
    p_reported_character_id,
    p_reporter_name_snapshot,
    p_reported_name_snapshot,
    p_reason_code,
    nullif(trim(p_explanation), ''),
    p_source_type,
    p_source_id,
    coalesce(p_source_context, '{}'::jsonb)
  )
  returning id into v_report_id;

  v_player_message :=
    'A moderation report was submitted.' || E'\n\n' ||
    'Reason: ' || initcap(replace(p_reason_code, '_', ' ')) ||
    case
      when nullif(trim(p_explanation), '') is not null
      then E'\n\nDetails:\n' || trim(p_explanation)
      else ''
    end;

  insert into public.ticket_messages (
    ticket_id,
    author_user_id,
    author_character_id,
    visibility,
    body
  )
  values (
    v_ticket_id,
    p_reporter_user_id,
    p_reporter_character_id,
    'player',
    v_player_message
  );

  insert into public.ticket_events (
    ticket_id,
    actor_user_id,
    actor_character_id,
    event_type,
    details
  )
  values (
    v_ticket_id,
    p_reporter_user_id,
    p_reporter_character_id,
    'ticket_created',
    jsonb_build_object(
      'category', 'report',
      'source', 'player_report',
      'source_type', p_source_type,
      'source_id', p_source_id
    )
  );

  insert into public.ticket_events (
    ticket_id,
    actor_user_id,
    actor_character_id,
    event_type,
    details
  )
  values (
    v_ticket_id,
    p_reporter_user_id,
    p_reporter_character_id,
    'report_submitted',
    jsonb_build_object(
      'report_id', v_report_id,
      'reason_code', p_reason_code,
      'source_type', p_source_type,
      'source_id', p_source_id
    )
  );

  insert into public.report_evidence (
    ticket_id,
    report_id,
    evidence_type,
    source_type,
    source_id,
    author_user_id,
    author_character_id,
    author_name_snapshot,
    content_snapshot,
    original_created_at,
    context_snapshot,
    captured_by_user_id
  )
  values (
    v_ticket_id,
    v_report_id,
    'content_snapshot',
    p_source_type,
    p_source_id,
    p_author_user_id,
    p_author_character_id,
    p_author_name_snapshot,
    p_content_snapshot,
    p_original_created_at,
    coalesce(p_context_snapshot, '{}'::jsonb),
    p_reporter_user_id
  );

  return query
  select
    v_ticket_id,
    v_reference,
    v_report_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_order_levels_1_to_6()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.order_levels (order_id, level)
  select new.id, gs.level
  from generate_series(1, 6) as gs(level)
  on conflict (order_id, level) do nothing;

  return new;
