$function$
;

CREATE OR REPLACE FUNCTION public.create_price_for_shape_cast(p_cast_id uuid, p_shape_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caster uuid;
  v_owner uuid;
  v_key text;
  v_stage integer;
  v_days integer;
  v_existing_effect_id uuid;
begin
  select caster_character_id
  into v_caster
  from public.shape_casts
  where id=p_cast_id;

  select id
  into v_owner
  from public.characters
  where user_id=auth.uid();

  if v_caster is null
     or v_owner is null
     or v_caster<>v_owner then
    raise exception 'Invalid Shape cast';
  end if;

  select s.price_key,p.stage,p.duration_days
  into v_key,v_stage,v_days
  from public.shapes s
  left join public.warping_prices p
    on p.key=s.price_key
  where s.id=p_shape_id;

  if v_key is null then
    return;
  end if;

  if v_stage is null or v_days is null then
    raise exception 'Shape Price % is not configured.',v_key;
  end if;

  select id
  into v_existing_effect_id
  from public.character_price_effects
  where character_id=v_caster
    and price_key=v_key
    and expires_at>now()
  order by expires_at desc
  limit 1
  for update;

  if v_existing_effect_id is not null then
    update public.character_price_effects
    set expires_at=expires_at+make_interval(days=>v_days),
        cast_id=p_cast_id
    where id=v_existing_effect_id;
  else
    insert into public.character_price_effects
      (cast_id,character_id,price_key,stage,expires_at)
    values
      (p_cast_id,v_caster,v_key,v_stage,now()+make_interval(days=>v_days));
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_price_for_shape_cast_for_staff(p_cast_id uuid, p_shape_id uuid, p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key text; v_stage integer; v_days integer; v_existing uuid;
begin
  if not exists(select 1 from public.shape_casts where id=p_cast_id and caster_character_id=p_character_id) then raise exception 'Invalid Shape cast'; end if;
  select s.price_key,p.stage,p.duration_days into v_key,v_stage,v_days from public.shapes s left join public.warping_prices p on p.key=s.price_key where s.id=p_shape_id;
  if v_key is null then return; end if;
  if v_stage is null or v_days is null then raise exception 'Shape Price % is not configured.',v_key; end if;
  select id into v_existing from public.character_price_effects where character_id=p_character_id and price_key=v_key and expires_at>now() order by expires_at desc limit 1 for update;
  if v_existing is not null then update public.character_price_effects set expires_at=expires_at+make_interval(days=>v_days),cast_id=p_cast_id where id=v_existing;
  else insert into public.character_price_effects(cast_id,character_id,price_key,stage,expires_at) values(p_cast_id,p_character_id,v_key,v_stage,now()+make_interval(days=>v_days)); end if;
end $function$
;

CREATE OR REPLACE FUNCTION public.create_starting_character_wallet()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.character_wallets(character_id, balance)
  values (new.id, 100)
  on conflict (character_id) do nothing;

  if not exists (
    select 1 from public.remnant_ledger
    where character_id = new.id and transaction_type = 'opening_balance'
  ) then
    insert into public.remnant_ledger(
      character_id, amount, balance_after, transaction_type,
      source_type, source_id, reason, actor_user_id
    )
    values (
      new.id, 100, 100, 'opening_balance', 'character_creation',
      new.id::text, 'Starting balance', new.user_id
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.current_aureth_game_datetime()
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    case
      when ws.automatic_time then
        ws.game_datetime
        + make_interval(
            secs => (
              extract(epoch from (now() - ws.updated_at))
              * greatest(coalesce(ws.time_scale, 0), 0)
            )::double precision
          )
      else ws.game_datetime
    end
  from public.world_state ws
  where ws.id = 'aureth'
  limit 1;
$function$
;

