CREATE OR REPLACE FUNCTION public.daily_mission_audit_event(p_character_id uuid, p_event_type text, p_entity_type text, p_entity_id uuid, p_new_values jsonb, p_metadata jsonb DEFAULT '{}'::jsonb, p_created_at timestamp with time zone DEFAULT now())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.character_audit_log (
    character_id,
    event_type,
    entity_type,
    entity_id,
    operation,
    actor_user_id,
    actor_type,
    actor_staff_role,
    actor_label,
    source,
    changed_fields,
    old_values,
    new_values,
    metadata,
    created_at
  )
  values (
    p_character_id,
    p_event_type,
    p_entity_type,
    p_entity_id,
    'event',
    null,
    'system',
    null,
    'Daily Missions',
    'daily_missions',
    array[]::text[],
    null,
    coalesce(p_new_values, '{}'::jsonb),
    coalesce(p_metadata, '{}'::jsonb),
    coalesce(p_created_at, now())
  );
end;
$function$
;

