      'mission_date', new.mission_date,
      'evidence_type', new.event_type,
      'value', new.event_value,
      'subject_id', new.subject_id,
      'source_kind', new.source_kind,
      'source_id', new.source_id
    ),
    jsonb_build_object(
      'daily_mission_event_id', new.id,
      'source_kind', new.source_kind,
      'source_id', new.source_id,
      'evidence_metadata', new.metadata
    ),
    new.created_at
  );

