end;
$function$
;

CREATE OR REPLACE FUNCTION public.daily_mission_from_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.operation <> 'event' or new.character_id is null then
    return new;
  end if;

  if new.event_type = 'crafting' then
    perform public.daily_mission_record_event(
      new.character_id, 'craft_item', 1, null,
      'character_audit_log', new.id::text, new.created_at, '{}'::jsonb
    );
  elsif new.event_type = 'market_purchase' then
    perform public.daily_mission_record_event(
      new.character_id, 'market_buy', 1, null,
      'character_audit_log', new.id::text, new.created_at, '{}'::jsonb
    );
  elsif new.event_type = 'market_sale' then
    perform public.daily_mission_record_event(
      new.character_id, 'market_sell', 1, null,
      'character_audit_log', new.id::text, new.created_at, '{}'::jsonb
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.daily_mission_from_gathering_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item_teaches_recipe uuid;
begin
  perform public.daily_mission_record_event(
    new.character_id, 'gather_attempt', 1, new.gathering_location_id::text,
    'gathering_attempt', new.id::text, new.created_at,
    jsonb_build_object(
      'location_id', new.gathering_location_id,
      'room_id', new.room_id,
      'outcome_type', new.outcome_type
    )
  );

  if new.outcome_type = 'item' and new.item_id is not null then
    select i.teaches_recipe_id
    into v_item_teaches_recipe
    from public.items i
    where i.id = new.item_id;

    if v_item_teaches_recipe is null then
      perform public.daily_mission_record_event(
        new.character_id, 'gather_ingredient',
        greatest(coalesce(new.quantity, 1), 1),
        new.item_id::text, 'gathering_attempt', new.id::text, new.created_at,
        jsonb_build_object(
          'location_id', new.gathering_location_id,
          'item_id', new.item_id
        )
      );
    end if;
  end if;

  return new;
end;
$function$
;

