CREATE OR REPLACE FUNCTION public.daily_mission_from_location_chat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_other record;
begin
  if new.message_type <> 'action' or new.character_id is null then
    return new;
  end if;

  if char_length(coalesce(new.message, '')) >= 800
     and exists (
       select 1
       from public.room_messages rm
       where rm.room_id = new.room_id
         and rm.character_id <> new.character_id
         and rm.message_type = 'action'
         and rm.created_at >= new.created_at - interval '30 minutes'
         and rm.created_at <= new.created_at
     )
  then
    perform public.daily_mission_record_event(
      new.character_id, 'location_chat_action', 1, new.room_id::text,
      'room_message', new.id::text, new.created_at,
      jsonb_build_object(
        'room_id', new.room_id,
        'minimum_characters', 800,
        'interaction_window_minutes', 30
      )
    );
  end if;

  for v_other in
    select rm.id, rm.character_id, rm.created_at
    from public.room_messages rm
    where rm.room_id = new.room_id
      and rm.character_id <> new.character_id
      and rm.message_type = 'action'
      and char_length(coalesce(rm.message, '')) >= 800
      and rm.created_at >= new.created_at - interval '30 minutes'
      and rm.created_at <= new.created_at
  loop
    perform public.daily_mission_record_event(
      v_other.character_id, 'location_chat_action', 1, new.room_id::text,
      'room_message', v_other.id::text, v_other.created_at,
      jsonb_build_object(
        'room_id', new.room_id,
        'minimum_characters', 800,
        'interaction_window_minutes', 30
      )
    );
  end loop;

  return new;
end;
$function$
;

