CREATE OR REPLACE FUNCTION public.daily_mission_from_remnant_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source_type text := coalesce(new.source_type, '');
  v_amount bigint := coalesce(new.amount, 0);
begin
  -- Absolute rule: mission rewards NEVER generate mission progress.
  if v_source_type in ('daily_mission_reward', 'daily_mission_milestone_reward') then
    return new;
  end if;

  if v_amount > 0 then
    perform public.daily_mission_record_event(
      new.character_id, 'remnants_earned',
      least(v_amount, 2147483647)::integer, null,
      'remnant_ledger', new.id::text, new.created_at,
      jsonb_build_object('source_type', v_source_type)
    );
  elsif v_amount < 0 then
    perform public.daily_mission_record_event(
      new.character_id, 'remnants_spent',
      least(abs(v_amount), 2147483647)::integer, null,
      'remnant_ledger', new.id::text, new.created_at,
      jsonb_build_object('source_type', v_source_type)
    );
  end if;

  if v_source_type = 'house_of_chances' then
    if v_amount < 0 then
      perform public.daily_mission_record_event(
        new.character_id, 'chance_play', 1, new.source_id,
        'house_of_chances_ledger', new.id::text, new.created_at, '{}'::jsonb
      );
    elsif v_amount > 0 then
      perform public.daily_mission_record_event(
        new.character_id, 'chance_win', 1, new.source_id,
        'house_of_chances_ledger', new.id::text, new.created_at, '{}'::jsonb
      );
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.daily_mission_grant_item(p_character_id uuid, p_item_id uuid, p_quantity integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stackable boolean;
begin
  if p_item_id is null or coalesce(p_quantity, 0) <= 0 then
    return;
  end if;

  select coalesce(i.stackable, false)
  into v_stackable
  from public.items i
  where i.id = p_item_id
    and i.is_active = true;

  if not found then
    raise exception 'The configured Daily Mission reward Item is unavailable.';
  end if;

  if v_stackable then
    insert into public.character_items (
      character_id, item_id, quantity, container_instance_id,
      acquisition_source, assigned_by
    )
    values (
      p_character_id, p_item_id, p_quantity, null, 'system', null
    );

    perform public._normalize_character_inventory_stacks(p_character_id);
  else
    insert into public.character_items (
      character_id, item_id, quantity, container_instance_id,
      acquisition_source, assigned_by
    )
    select p_character_id, p_item_id, 1, null, 'system', null
    from generate_series(1, p_quantity);
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.daily_mission_pick_reward_item(p_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item_id uuid;
begin
  if p_kind = 'ingredient_common' then
    select i.id
    into v_item_id
    from public.items i
    join public.item_categories c
      on c.id = i.category_id
    where c.slug = 'ingredient'
      and i.is_active = true
      and coalesce(i.is_quest_item, false) = false
      and i.teaches_recipe_id is null
      and i.quality in ('poor', 'average', 'fine')
    order by random()
    limit 1;

    -- Safe fallback if the current catalogue has no common-quality Ingredients.
    if v_item_id is null then
      select i.id
      into v_item_id
      from public.items i
      join public.item_categories c
        on c.id = i.category_id
      where c.slug = 'ingredient'
        and i.is_active = true
        and coalesce(i.is_quest_item, false) = false
        and i.teaches_recipe_id is null
      order by random()
      limit 1;
    end if;

  elsif p_kind = 'ingredient_rare' then
    select i.id
    into v_item_id
    from public.items i
    join public.item_categories c
      on c.id = i.category_id
    where c.slug = 'ingredient'
      and i.is_active = true
      and coalesce(i.is_quest_item, false) = false
      and i.teaches_recipe_id is null
      and i.quality in ('superior', 'flawless', 'peerless')
    order by random()
    limit 1;

    -- Fallback keeps the reward claimable if rare Ingredients are not populated yet.
    if v_item_id is null then
      select i.id
      into v_item_id
      from public.items i
      join public.item_categories c
        on c.id = i.category_id
      where c.slug = 'ingredient'
        and i.is_active = true
        and coalesce(i.is_quest_item, false) = false
        and i.teaches_recipe_id is null
      order by random()
      limit 1;
    end if;

  elsif p_kind = 'random_item' then
    select i.id
    into v_item_id
    from public.items i
    join public.item_categories c
      on c.id = i.category_id
    where c.slug <> 'ingredient'
      and i.is_active = true
      and coalesce(i.is_quest_item, false) = false
      and i.transfer_policy = 'free'
      and i.teaches_recipe_id is null
      and i.container_capacity is null
      and coalesce(i.use_behaviour::text, '') <> 'limited_charges'
    order by random()
    limit 1;
  end if;

  return v_item_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.daily_mission_record_event(p_character_id uuid, p_event_type text, p_event_value integer, p_subject_id text, p_source_kind text, p_source_id text, p_created_at timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_character_id is null or p_event_type is null or p_source_id is null then
    return;
  end if;

  insert into public.daily_mission_events (
    character_id, mission_date, event_type, event_value, subject_id,
    source_kind, source_id, metadata, created_at
  )
  values (
    p_character_id,
    (coalesce(p_created_at, now()) at time zone 'UTC')::date,
    p_event_type,
    greatest(coalesce(p_event_value, 1), 0),
    p_subject_id,
    p_source_kind,
    p_source_id,
    coalesce(p_metadata, '{}'::jsonb),
    coalesce(p_created_at, now())
  )
  on conflict (character_id, event_type, source_kind, source_id)
  do nothing;
end;
$function$
;

