CREATE OR REPLACE FUNCTION public.delete_account_characters(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c record; removed integer:=0;
BEGIN
 IF p_user_id IS NULL THEN RAISE EXCEPTION 'Account ID is required.'; END IF;
 PERFORM 1 FROM auth.users WHERE id=p_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Account not found.'; END IF;
 FOR c IN SELECT id FROM public.characters WHERE user_id=p_user_id ORDER BY id FOR UPDATE LOOP
   IF private.phase8_delete_character(c.id,false) THEN removed:=removed+1; END IF;
 END LOOP;
 RETURN removed;
END;
$function$
;

