 SET search_path TO ''
AS $function$
BEGIN
 RETURN private.phase8_delete_character(p_character_id,true);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_crafting_recipe_bundle(p_recipe_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_recipe_item_ids uuid[];
begin
  if auth.uid() is null or not exists (
    select 1
    from public.staff_members sm
    where sm.user_id = auth.uid()
      and sm.role = 'owner'
  ) then
    raise exception 'Not authorised to delete crafting recipes.';
  end if;

  if not exists (
    select 1
    from public.crafting_recipes cr
    where cr.id = p_recipe_id
  ) then
    raise exception 'Crafting recipe not found.';
  end if;

  select array_agg(i.id)
  into v_recipe_item_ids
  from public.items i
  where i.teaches_recipe_id = p_recipe_id;

  if coalesce(array_length(v_recipe_item_ids, 1), 0) > 0 then
    delete from public.character_items
    where item_id = any(v_recipe_item_ids);

    delete from public.character_item_instances
    where item_id = any(v_recipe_item_ids);

    delete from public.items
    where id = any(v_recipe_item_ids);
  end if;

  delete from public.character_recipes
  where recipe_id = p_recipe_id;

  delete from public.crafting_recipes
  where id = p_recipe_id;

  if not found then
    raise exception 'Crafting recipe could not be deleted.';
  end if;
end
$function$
;

CREATE OR REPLACE FUNCTION public.delete_direct_conversation_for_me(target_conversation_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  viewer_character_id uuid;
  visible_message_ids uuid[];
  affected_count integer := 0;
begin
  select c.id into viewer_character_id
  from public.characters c
  where c.user_id = auth.uid()
  limit 1;

  if viewer_character_id is null then
    raise exception 'Character not found.';
  end if;

  if not exists (
    select 1 from public.direct_conversation_participants p
    where p.conversation_id = target_conversation_id
      and p.character_id = viewer_character_id
  ) then
    raise exception 'Conversation not found.';
  end if;

  select coalesce(array_agg(m.id), array[]::uuid[])
  into visible_message_ids
  from public.direct_messages m
  where m.conversation_id = target_conversation_id
    and not exists (
      select 1 from public.direct_message_deletions d
      where d.message_id = m.id and d.character_id = viewer_character_id
    );

  if cardinality(visible_message_ids) > 0 then
    affected_count := public.delete_direct_messages_for_me(
      target_conversation_id,
      visible_message_ids,
      'conversation'
    );
  end if;

  update public.direct_conversation_participants
  set deleted_at = now(), archived_at = null
  where conversation_id = target_conversation_id
    and character_id = viewer_character_id;

  return affected_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_direct_messages_for_me(target_conversation_id uuid, target_message_ids uuid[], target_deletion_kind text DEFAULT 'bulk'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  viewer_character_id uuid;
  affected_count integer := 0;
begin
  if target_deletion_kind not in ('single','bulk','conversation') then
    raise exception 'Invalid deletion kind.';
  end if;

  select c.id into viewer_character_id
  from public.characters c
  where c.user_id = auth.uid()
  limit 1;

  if viewer_character_id is null then
    raise exception 'Character not found.';
  end if;

  if not exists (
    select 1 from public.direct_conversation_participants p
    where p.conversation_id = target_conversation_id
      and p.character_id = viewer_character_id
  ) then
    raise exception 'Conversation not found.';
  end if;

  insert into public.private_message_deletion_log (
    original_message_id, conversation_id, sender_character_id,
    deleting_character_id, original_body, original_message_mode,
    original_created_at, deletion_kind, deleted_at
  )
  select
    m.id, m.conversation_id, m.sender_character_id,
    viewer_character_id, m.body, m.message_mode::text,
    m.created_at, target_deletion_kind, now()
  from public.direct_messages m
  where m.conversation_id = target_conversation_id
    and m.id = any(target_message_ids)
    and not exists (
      select 1 from public.direct_message_deletions d
      where d.message_id = m.id and d.character_id = viewer_character_id
    );

  insert into public.direct_message_deletions (message_id, character_id, deleted_at)
  select m.id, viewer_character_id, now()
  from public.direct_messages m
  where m.conversation_id = target_conversation_id
    and m.id = any(target_message_ids)
  on conflict (message_id, character_id) do nothing;

  get diagnostics affected_count = row_count;
  return affected_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_item_with_crafting_bundle(p_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owned_count integer := 0;
  v_recipe record;
  v_recipe_item_ids uuid[];
begin
  if auth.uid() is null or not exists (
    select 1
    from public.staff_members sm
    where sm.user_id = auth.uid()
      and sm.role = 'owner'
  ) then
    raise exception 'Not authorised to delete Items.';
  end if;

  if not exists (
    select 1
    from public.items i
    where i.id = p_item_id
  ) then
    raise exception 'Item not found.';
  end if;

  select
    (
      select count(*)
      from public.character_items ci
      where ci.item_id = p_item_id
    )
    +
    (
      select count(*)
      from public.character_item_instances cii
      where cii.item_id = p_item_id
    )
  into v_owned_count;

  if v_owned_count > 0 then
    raise exception
      'This Item still has % inventory record%. Remove or destroy those physical copies before deleting the Item.',
      v_owned_count,
      case when v_owned_count = 1 then '' else 's' end;
  end if;

  for v_recipe in
    select cr.id
    from public.crafting_recipes cr
    where cr.result_item_id = p_item_id
  loop
    select array_agg(i.id)
    into v_recipe_item_ids
    from public.items i
    where i.teaches_recipe_id = v_recipe.id;

    if coalesce(array_length(v_recipe_item_ids, 1), 0) > 0 then
      delete from public.character_items
      where item_id = any(v_recipe_item_ids);

      delete from public.character_item_instances
      where item_id = any(v_recipe_item_ids);

      delete from public.items
      where id = any(v_recipe_item_ids);
    end if;

    delete from public.character_recipes
    where recipe_id = v_recipe.id;

    delete from public.crafting_recipes
    where id = v_recipe.id;
  end loop;

  delete from public.items
  where id = p_item_id;

  if not found then
    raise exception 'Item could not be deleted.';
  end if;
end
$function$
;

CREATE OR REPLACE FUNCTION public.delete_npc_completely(p_npc_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_character_id uuid;
  v_is_system boolean;
  v_deleted boolean;
begin
  if p_npc_id is null then raise exception 'NPC ID is required.'; end if;

  select n.character_id into v_character_id
  from public.npcs n
  where n.id=p_npc_id
  for update;

  if not found then return false; end if;
  if v_character_id is null then raise exception 'NPC mechanics Character is missing.'; end if;

  select c.is_system into v_is_system
  from public.characters c
  where c.id=v_character_id
  for update;

  if not found or v_is_system is distinct from true then
    raise exception 'NPC mechanics Character is invalid.';
  end if;

  perform private.phase8_snapshot_character_history(v_character_id);

  delete from public.npcs where id=p_npc_id;
  v_deleted := private.phase8_delete_character(v_character_id,true);

  if not v_deleted then raise exception 'NPC Character could not be deleted.'; end if;
  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_room_completely(p_room_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_deleted integer;
begin
  if p_room_id is null then raise exception 'Room ID is required.'; end if;

  select r.name into v_name
  from public.rooms r
  where r.id=p_room_id
  for update;

  if not found then return false; end if;

  if exists(select 1 from public.order_headquarters h where h.room_id=p_room_id) then
    raise exception 'This room is assigned as an Order Headquarters. Remove or change the Headquarters first.';
  end if;

  update public.room_messages set room_id_snapshot=coalesce(room_id_snapshot,p_room_id), room_name_snapshot=coalesce(room_name_snapshot,v_name) where room_id=p_room_id;
  update public.gathering_attempts set room_id_snapshot=coalesce(room_id_snapshot,p_room_id), room_name_snapshot=coalesce(room_name_snapshot,v_name) where room_id=p_room_id;
  update public.opposed_actions set room_id_snapshot=coalesce(room_id_snapshot,p_room_id), room_name_snapshot=coalesce(room_name_snapshot,v_name) where room_id=p_room_id;
  update public.room_system_events set room_id_snapshot=coalesce(room_id_snapshot,p_room_id), room_name_snapshot=coalesce(room_name_snapshot,v_name) where room_id=p_room_id;
  update public.shape_casts set room_id_snapshot=coalesce(room_id_snapshot,p_room_id), room_name_snapshot=coalesce(room_name_snapshot,v_name) where room_id=p_room_id;

  delete from public.rooms where id=p_room_id;
  get diagnostics v_deleted=row_count;
  return v_deleted=1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_shape_completely(p_shape_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_level integer;
  v_deleted integer;
begin
  if p_shape_id is null then raise exception 'Shape ID is required.'; end if;

  select s.name,s.level into v_name,v_level
  from public.shapes s
  where s.id=p_shape_id
  for update;

  if not found then return false; end if;

  update public.shape_casts
  set shape_id_snapshot=coalesce(shape_id_snapshot,p_shape_id),
      shape_name_snapshot=coalesce(shape_name_snapshot,v_name),
      shape_level_snapshot=coalesce(shape_level_snapshot,v_level)
  where shape_id=p_shape_id;

  update public.character_shape_effects
  set shape_id_snapshot=coalesce(shape_id_snapshot,p_shape_id),
      shape_name_snapshot=coalesce(shape_name_snapshot,v_name)
  where shape_id=p_shape_id;

  delete from public.shapes where id=p_shape_id;
  get diagnostics v_deleted=row_count;
  return v_deleted=1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.discard_own_inventory_record(k text, r uuid, q integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := public.my_character_id();
  have int;
  quest bool;
  inst public.character_item_instances%rowtype;
  v_action_id uuid;
  v_item_id uuid;
  v_item_name text;
begin
  if me is null or q < 1 then
    raise exception 'Invalid discard.';
  end if;

  if public.item_record_is_equipped(k, r, me) then
    raise exception 'Unequip this Item first.';
  end if;

  if k = 'standard' then
    select ci.quantity, ci.item_id, i.name, i.is_quest_item
    into have, v_item_id, v_item_name, quest
    from character_items ci
    join items i on i.id = ci.item_id
    where ci.id = r
      and ci.character_id = me
      and ci.container_instance_id is null
    for update of ci;

    if not found then
      raise exception 'Item not found in Loose Inventory.';
    end if;

    if quest then
      raise exception 'Quest Items cannot be discarded.';
    end if;

    if q > have then
      raise exception 'Not enough quantity.';
    end if;

    v_action_id := public.character_audit_begin_action('item_discarded','discard');

    if q = have then
      delete from character_items
      where id = r;
    else
      update character_items
      set
        quantity = quantity - q,
        updated_at = now()
      where id = r;
    end if;

  elsif k = 'unique' then
    select *
    into inst
    from character_item_instances
    where id = r
      and owner_character_id = me
      and container_instance_id is null
      and vault_status = 'owned'
    for update;

    if not found then
      raise exception 'Unique Item not found in Loose Inventory.';
    end if;

    select coalesce(
      inst.is_quest_item_override,
      i.is_quest_item
    )
    into quest
    from items i
    where i.id = inst.item_id;

    if quest then
      raise exception 'Quest Items cannot be discarded.';
    end if;

    v_item_id := inst.item_id;
    select name into v_item_name from public.items where id=v_item_id;
    v_action_id := public.character_audit_begin_action('item_discarded','discard');

    update character_item_instances
    set
      owner_character_id = null,
      container_instance_id = null,
      vault_status = 'admin_vault',
      updated_at = now()
    where id = r;

    insert into item_instance_history(
      item_instance_id,
      event_type,
      from_character_id,
      actor_user_id,
      details
    )
    values(
      r,
      'discarded',
      me,
      auth.uid(),
      'Discarded by owner; returned to Admin Vault.'
    );

  else
    raise exception 'Invalid Item type.';
  end if;

  perform public.character_audit_write_event(
    me,'item_discarded','discard',v_action_id,
    jsonb_build_object('item_id',v_item_id,'item_name',v_item_name,'quantity',q,'record_kind',k),
    'item_discard',r::text
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.email_is_registered(check_email text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select exists (
    select 1
    from auth.users
    where lower(email) = lower(trim(check_email))
  );
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_automatic_notification_expiry()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.is_automatic = true
     and new.expires_at is null
     and new.expires_game_at is null
  then
    new.expires_at :=
      coalesce(new.starts_at, now())
      + interval '30 days';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_block_direct_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare other_id uuid;
begin
  for other_id in
    select p.character_id
    from public.direct_conversation_participants p
    where p.conversation_id=new.conversation_id
      and p.character_id<>new.sender_character_id
      and p.deleted_at is null
  loop
    if public.characters_have_global_block(new.sender_character_id,other_id) then
      raise exception 'This conversation is unavailable.';
    end if;
  end loop;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.enforce_block_friend()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.characters_have_global_block(new.owner_character_id,new.target_character_id) then
    raise exception 'This character cannot be added to a Friend List.';
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.enforce_block_instant_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      declare a uuid; b uuid;
      begin
        select character_one_id, character_two_id into a,b
        from public.instant_chat_conversations where id=new.conversation_id;
        if public.characters_have_global_block(a,b) then
          raise exception 'This character is not available for Instant Chat.';
        end if;
        return new;
      end $function$
;

CREATE OR REPLACE FUNCTION public.enforce_block_whisper()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.message_type='whisper'
     and new.whisper_recipient_character_id is not null
     and public.characters_have_global_block(new.character_id,new.whisper_recipient_character_id)
  then
    raise exception 'That character is not available for whispers.';
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.enforce_character_ancestry_gift_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare c integer;
begin
  if new.acquisition_source <> 'ancestry' then return new; end if;

  select count(*) into c
  from public.character_gifts cg
  where cg.character_id=new.character_id
    and cg.acquisition_source='ancestry'
    and (tg_op <> 'UPDATE' or cg.id <> new.id);

  if c >= 2 then
    raise exception 'A character may have at most 2 Ancestry-selected Gifts.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_db_user_rate_limit(p_scope text, p_user_id uuid, p_limit integer, p_window_seconds integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allowed boolean;
  v_remaining integer;
  v_retry integer;
begin
  if p_user_id is null then
    return;
  end if;

  select
    allowed,
    remaining,
    retry_after_seconds
  into
    v_allowed,
    v_remaining,
    v_retry
  from public.consume_security_rate_limit(
    p_scope,
    md5(p_user_id::text),
    p_limit,
    p_window_seconds
  );

  if not coalesce(v_allowed, false) then
    raise exception
      'You are doing this too quickly. Please wait % second(s) before trying again.',
      greatest(coalesce(v_retry, 1), 1);
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_dead_forum_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_state text;
  v_section_type text;
begin
  if new.author_character_id is null then
    return new;
  end if;

  select life_state::text
  into v_state
  from public.characters
  where id = new.author_character_id;

  if v_state <> 'dead' then
    return new;
  end if;

  select fs.section_type::text
  into v_section_type
  from public.forum_topics ft
  join public.forum_sections fs
    on fs.id = ft.section_id
  where ft.id = new.topic_id;

  if coalesce(v_section_type, '') <> 'offgame' then
    raise exception
      'Dead Characters may only use Offgame forum sections.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_dead_private_message_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_state text;
begin
  select life_state::text
  into v_state
  from public.characters
  where id = new.sender_character_id;

  if v_state = 'dead'
     and coalesce(new.message_mode::text, 'ongame') <> 'offgame' then
    raise exception
      'Dead Characters may only send Off-game private messages.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_dead_room_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_state text;
  v_room_allowed boolean;
  v_ghost_chat boolean;
begin
  if new.character_id is null
     or coalesce(new.speaker_type::text, '') = 'system' then
    return new;
  end if;

  select life_state::text
  into v_state
  from public.characters
  where id = new.character_id;

  if v_state <> 'dead' then
    return new;
  end if;

  select allow_dead_ghosts
  into v_room_allowed
  from public.rooms
  where id = new.room_id;

  select ghost_chat_enabled
  into v_ghost_chat
  from public.character_death_rules
  where singleton = true;

  if coalesce(v_ghost_chat, true) is not true
     or coalesce(v_room_allowed, false) is not true then
    raise exception
      'Ghosts cannot speak in this Location.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_dead_shape_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_state text;
  v_died_at timestamptz;
  v_zero_hp_at timestamptz;
  v_window integer;
  v_level integer;
  v_choice text;
  v_heal_dice text;
  v_heal_attribute text;
  v_healing boolean;
begin
  if new.target_character_id is null then
    return new;
  end if;

  select life_state::text, died_at, zero_hp_at
  into v_state, v_died_at, v_zero_hp_at
  from public.characters
  where id = new.target_character_id;

  if v_state <> 'dead' then
    return new;
  end if;

  select
    s.level,
    coalesce(new.other_effect_choice, 'beneficial'),
    case
      when coalesce(new.other_effect_choice, 'beneficial') = 'harmful'
        then s.other_alt_heal_dice
      else s.other_heal_dice
    end,
    case
      when coalesce(new.other_effect_choice, 'beneficial') = 'harmful'
        then s.other_alt_heal_attribute
      else s.other_heal_attribute
    end
  into
    v_level,
    v_choice,
    v_heal_dice,
    v_heal_attribute
  from public.shape_casts sc
  join public.shapes s on s.id = sc.shape_id
  where sc.id = new.cast_id;

  v_healing :=
    (
      nullif(trim(coalesce(v_heal_dice, '')), '') is not null
      and left(trim(v_heal_dice), 1) <> '-'
    )
    or nullif(trim(coalesce(v_heal_attribute, '')), '') is not null;

  -- Any Level IX Shape with a positive Other healing profile is a Resurrection Shape.
  if v_level = 9 and v_healing then
    return new;
  end if;

  if not v_healing then
    raise exception
      'Only healing Shapes can target a dead Character during the Essence Window.';
  end if;

  select essence_window_minutes
  into v_window
  from public.character_death_rules
  where singleton = true;

  v_window := coalesce(v_window, 60);

  if coalesce(v_died_at, v_zero_hp_at) is null
     or now() >
       coalesce(v_died_at, v_zero_hp_at) +
       make_interval(mins => v_window) then
    raise exception
      'This Character''s essence has faded. Only a Level IX Resurrection Shape can target them now.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_living_opposed_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_attacker_state text;
  v_target_state text;
begin
  select life_state::text
  into v_attacker_state
  from public.characters
  where id = new.attacker_character_id;

  select life_state::text
  into v_target_state
  from public.characters
  where id = new.target_character_id;

  if v_attacker_state <> 'alive' then
    raise exception
      'Dead or dying Characters cannot perform opposed Actions.';
  end if;

  if v_target_state = 'dead' then
    raise exception
      'Dead Characters cannot be targeted by attacks or opposed Attribute Actions.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_living_shape_caster()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_state text;
begin
  select life_state::text
  into v_state
  from public.characters
  where id = new.caster_character_id;

  if v_state = 'dead' then
    raise exception 'Dead Characters cannot Warp Shapes.';
  elsif v_state = 'death_save_pending' then
    raise exception
      'Characters at Death''s Threshold cannot Warp Shapes.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_private_location_room_message_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_private boolean;
  v_owner uuid;
  v_current_character uuid;
  v_staff boolean;
  v_owner_enabled boolean;
  v_member_active boolean;
begin
  select true, owner_character_id
  into v_private, v_owner
  from public.private_location_rooms
  where room_id = new.room_id;

  if not coalesce(v_private, false) then
    return new;
  end if;

  select id
  into v_current_character
  from public.characters
  where user_id = auth.uid()
  limit 1;

  select exists (
    select 1
    from public.staff_members
    where user_id = auth.uid()
  )
  into v_staff;

  if coalesce(v_staff, false) then
    return new;
  end if;

  if v_current_character is null
     or new.character_id <> v_current_character then
    raise exception 'Private location access denied';
  end if;

  select exists (
    select 1
    from public.character_feature_entitlements
    where character_id = v_owner
      and feature_key = 'private_chat'
      and enabled = true
  )
  into v_owner_enabled;

  select exists (
    select 1
    from public.private_location_members
    where room_id = new.room_id
      and character_id = v_current_character
      and status = 'active'
  )
  into v_member_active;

  if not (
    coalesce(v_owner_enabled, false)
    and coalesce(v_member_active, false)
  ) then
    raise exception 'Private location access denied';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_sanction_direct_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
begin
  select c.user_id
  into v_user_id
  from public.characters c
  where c.id = new.sender_character_id;

  if v_user_id is not null then
    perform public.raise_if_user_sanctioned(
      v_user_id,
      'communication'
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_sanction_forum_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
begin
  v_user_id := coalesce(new.author_user_id, auth.uid());

  if v_user_id is not null then
    perform public.raise_if_user_sanctioned(
      v_user_id,
      'forum'
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_sanction_forum_topic()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
begin
  v_user_id := coalesce(new.author_user_id, auth.uid());

  if v_user_id is not null then
    perform public.raise_if_user_sanctioned(
      v_user_id,
      'forum'
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_sanction_room_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
begin
  if new.character_id is null then
    return new;
  end if;

  select c.user_id
  into v_user_id
  from public.characters c
  where c.id = new.character_id;

  if v_user_id is not null then
    perform public.raise_if_user_sanctioned(
      v_user_id,
      'game_chat'
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_single_order_head()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare new_level integer;
begin
  select level into new_level from public.order_levels
  where id = new.order_level_id and order_id = new.order_id;
  if new_level = 5 and exists (
    select 1 from public.order_memberships om
    join public.order_levels ol on ol.id = om.order_level_id
    where om.order_id = new.order_id and ol.level = 5 and om.id <> new.id
  ) then raise exception 'This Order already has a Level 5 Head.'; end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.enforce_user_portal_skin_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  skin_is_default boolean;
  entitlement_enabled boolean;
begin
  if new.selected_skin_id is null then
    return new;
  end if;

  select s.is_default
  into skin_is_default
  from public.portal_skins s
  where s.id = new.selected_skin_id
    and s.is_active = true;

  if skin_is_default is null then
    raise exception 'Selected portal skin is not active.';
  end if;

  if skin_is_default then
    return new;
  end if;

  select e.enabled
  into entitlement_enabled
  from public.user_portal_skin_entitlements e
  where e.user_id = new.user_id
    and e.skin_id = new.selected_skin_id;

  if coalesce(entitlement_enabled, false) is not true then
    raise exception 'This account does not own the selected portal skin.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_my_daily_mission_day()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
  v_date date := (now() at time zone 'UTC')::date;
  v_day_id uuid;

  v_md public.daily_mission_definitions%rowtype;
  v_mm public.daily_mission_milestone_definitions%rowtype;
  v_pool record;

  v_criteria jsonb;
  v_reward_item_id uuid;
  v_reward_item_name text;
  v_reward_item_quantity integer;
begin
  select c.id
  into v_character_id
  from public.characters c
  where c.user_id = auth.uid()
    and c.status = 'approved'
    and coalesce(c.is_system, false) = false
  limit 1;

  if v_character_id is null then
    raise exception 'No approved character is available for Daily Missions.';
  end if;

  insert into public.daily_mission_days (
    character_id,
    mission_date
  )
  values (
    v_character_id,
    v_date
  )
  on conflict (character_id, mission_date)
  do nothing;

  select d.id
  into v_day_id
  from public.daily_mission_days d
  where d.character_id = v_character_id
    and d.mission_date = v_date;

  for v_md in
    select *
    from public.daily_mission_definitions
    where is_active = true
    order by sort_order, name
  loop
    if exists (
      select 1
      from public.daily_mission_assignments a
      where a.day_id = v_day_id
        and a.mission_definition_id = v_md.id
    ) then
      continue;
    end if;

    v_criteria := coalesce(v_md.criteria, '{}'::jsonb);

    if v_md.objective_type = 'gather_specific_location' then
      v_criteria :=
        v_criteria ||
        coalesce(
          (
            select jsonb_build_object(
              'location_id', gl.id,
              'location_name', gl.name
            )
            from public.gathering_locations gl
            where gl.is_active = true
            order by random()
            limit 1
          ),
          '{}'::jsonb
        );
    end if;

    -- Guaranteed fixed Item remains highest priority.
    v_reward_item_id := v_md.reward_item_id;
    v_reward_item_quantity :=
      case
        when v_md.reward_item_id is not null
          then greatest(v_md.reward_item_quantity, 0)
        else 0
      end;

    -- Otherwise evaluate the curated pool in administrator-defined order.
    if v_reward_item_id is null then
      for v_pool in
        select p.*
        from public.daily_mission_reward_pool_entries p
        join public.items i
          on i.id = p.item_id
        where p.mission_definition_id = v_md.id
          and p.is_active = true
          and i.is_active = true
        order by p.sort_order, p.created_at, p.id
      loop
        if (random() * 100) < v_pool.chance_pct then
          v_reward_item_id := v_pool.item_id;
          v_reward_item_quantity := v_pool.quantity;
          exit;
        end if;
      end loop;
    end if;

    select i.name
    into v_reward_item_name
    from public.items i
    where i.id = v_reward_item_id;

    insert into public.daily_mission_assignments (
      day_id,
      mission_definition_id,
      code_snapshot,
      family_snapshot,
      name_snapshot,
      description_snapshot,
      objective_type_snapshot,
      target_snapshot,
      criteria_snapshot,
      difficulty_snapshot,
      reward_remnants_snapshot,
      reward_item_id_snapshot,
      reward_item_name_snapshot,
      reward_item_quantity_snapshot,
      reward_random_kind_snapshot,
      counts_toward_milestones,
      sort_order
    )
    values (
      v_day_id,
      v_md.id,
      v_md.code,
      v_md.family,
      v_md.name,
      v_md.description,
      v_md.objective_type,
      v_md.target_value,
      v_criteria,
      v_md.difficulty,
      v_md.reward_remnants,
      v_reward_item_id,
      v_reward_item_name,
      v_reward_item_quantity,
      case
        when v_md.reward_item_id is not null then 'fixed'
        when v_reward_item_id is not null then 'curated_pool'
        else 'none'
      end,
      v_md.counts_toward_milestones,
      v_md.sort_order
    );
  end loop;

  for v_mm in
    select *
    from public.daily_mission_milestone_definitions
    where is_active = true
    order by sort_order, name
  loop
    if exists (
      select 1
      from public.daily_mission_milestone_claims mc
      where mc.day_id = v_day_id
        and mc.milestone_key = v_mm.milestone_key
    ) then
      continue;
    end if;

    v_reward_item_id := v_mm.reward_item_id;
    v_reward_item_quantity :=
      case
        when v_mm.reward_item_id is not null
          then greatest(v_mm.reward_item_quantity, 0)
        else 0
      end;

    if v_reward_item_id is null then
      for v_pool in
        select p.*
        from public.daily_mission_reward_pool_entries p
        join public.items i
          on i.id = p.item_id
        where p.milestone_key = v_mm.milestone_key
          and p.is_active = true
          and i.is_active = true
        order by p.sort_order, p.created_at, p.id
      loop
        if (random() * 100) < v_pool.chance_pct then
          v_reward_item_id := v_pool.item_id;
          v_reward_item_quantity := v_pool.quantity;
          exit;
        end if;
      end loop;
    end if;

    select i.name
    into v_reward_item_name
    from public.items i
    where i.id = v_reward_item_id;

    insert into public.daily_mission_milestone_claims (
      day_id,
      milestone_key,
      name_snapshot,
      description_snapshot,
      target_count_snapshot,
      is_all_snapshot,
      reward_remnants_snapshot,
      reward_item_id_snapshot,
      reward_item_name_snapshot,
      reward_item_quantity_snapshot,
      reward_random_kind_snapshot
    )
    values (
      v_day_id,
      v_mm.milestone_key,
      v_mm.name,
      v_mm.description,
      v_mm.target_count,
      v_mm.is_all,
      v_mm.reward_remnants,
      v_reward_item_id,
      v_reward_item_name,
      v_reward_item_quantity,
      case
        when v_mm.reward_item_id is not null then 'fixed'
        when v_reward_item_id is not null then 'curated_pool'
        else 'none'
      end
    );
  end loop;

  return v_day_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enter_breeze_lodging(p_room_id uuid)
 RETURNS TABLE(entered_room_id uuid, room_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_is_staff boolean := false;
  v_rental_id uuid;
  v_owner_character_id uuid;
  v_room_name text;
  v_allowed boolean := false;
begin
  if v_user_id is null then
    raise exception 'You must be signed in.';
  end if;

  perform public.expire_breeze_lodging_rentals();

  select c.id
    into v_character_id
  from public.characters c
  where c.user_id = v_user_id
    and c.status = 'approved'
  limit 1;

  if v_character_id is null then
    raise exception 'Your character must be approved.';
  end if;

  select exists(
    select 1
    from public.staff_members sm
    where sm.user_id = v_user_id
  ) into v_is_staff;

  select rent.id, rent.owner_character_id, r.name
    into v_rental_id, v_owner_character_id, v_room_name
  from public.breeze_lodging_rentals rent
  join public.breeze_lodging_rooms blr
    on blr.room_id = rent.room_id
  join public.rooms r
    on r.id = rent.room_id
  where rent.room_id = p_room_id
    and rent.status = 'active'
    and rent.ends_at > now()
    and r.is_active = true
  limit 1;

  if v_rental_id is null then
    raise exception 'That room is not currently occupied.';
  end if;

  v_allowed :=
    v_is_staff
    or v_owner_character_id = v_character_id
    or exists (
      select 1
      from public.breeze_lodging_guests g
      where g.rental_id = v_rental_id
        and g.character_id = v_character_id
        and g.status = 'active'
    );

  if not v_allowed then
    raise exception 'You do not have access to that room.';
  end if;

  update public.characters
  set current_room_id = p_room_id
  where id = v_character_id;

  insert into public.character_presence (
    character_id,
    room_id,
    status,
    manual_status,
    last_seen_at
  )
  values (
    v_character_id,
    p_room_id,
    'online',
    'online',
    now()
  )
  on conflict (character_id)
  do update set
    room_id = excluded.room_id,
    last_seen_at = excluded.last_seen_at;

  return query
  select p_room_id, v_room_name;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.equip_character_inventory_record(p_record_kind text, p_record_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
  v_item_id uuid;
  v_slot text;
  v_layer text;
  v_hands smallint;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if p_record_kind = 'standard' then
    select ci.character_id, ci.item_id
    into v_character_id, v_item_id
    from public.character_items ci
    join public.characters c
      on c.id = ci.character_id
    where ci.id = p_record_id
      and c.user_id = auth.uid();

  elsif p_record_kind = 'unique' then
    select inst.owner_character_id, inst.item_id
    into v_character_id, v_item_id
    from public.character_item_instances inst
    join public.characters c
      on c.id = inst.owner_character_id
    where inst.id = p_record_id
      and inst.vault_status = 'owned'
      and c.user_id = auth.uid();

  else
    raise exception 'Invalid inventory record type.';
  end if;

  if v_character_id is null or v_item_id is null then
    raise exception 'You do not own this Item.';
  end if;

  select equip_slot, equip_layer, hands_required
  into v_slot, v_layer, v_hands
  from public.items
  where id = v_item_id
    and is_equippable = true
    and is_active = true;

  if v_slot is null or v_layer is null then
    raise exception 'This Item cannot be equipped.';
  end if;

  if not public.character_can_equip_item(v_character_id, v_item_id) then
    raise exception 'This character does not meet the requirements to equip this Item.';
  end if;

  -- Equipping always moves the Item out of a Container.
  if p_record_kind = 'standard' then
    update public.character_items
    set container_instance_id = null,
        updated_at = now()
    where id = p_record_id;
  else
    update public.character_item_instances
    set container_instance_id = null,
        updated_at = now()
    where id = p_record_id;
  end if;

  -- A two-handed item clears both hands.
  if v_hands = 2 then
    delete from public.character_equipment
    where character_id = v_character_id
      and slot_key in ('main_hand', 'off_hand');

  -- A one-handed hand item clears any existing two-hander.
  elsif v_slot in ('main_hand', 'off_hand') then
    delete from public.character_equipment ce
    using public.character_items ci
    join public.items i on i.id = ci.item_id
    where ce.character_id = v_character_id
      and ce.character_item_id = ci.id
      and i.hands_required = 2;

    delete from public.character_equipment ce
    using public.character_item_instances inst
    join public.items i on i.id = inst.item_id
    where ce.character_id = v_character_id
      and ce.item_instance_id = inst.id
      and i.hands_required = 2;
  end if;

  -- One item per slot + layer.
  delete from public.character_equipment
  where character_id = v_character_id
    and slot_key = v_slot
    and layer_key = v_layer;

  if p_record_kind = 'standard' then
    insert into public.character_equipment (
      character_id,
      slot_key,
      layer_key,
      character_item_id
    )
    values (
      v_character_id,
      v_slot,
      v_layer,
      p_record_id
    );
  else
    insert into public.character_equipment (
      character_id,
      slot_key,
      layer_key,
      item_instance_id
    )
    values (
      v_character_id,
      v_slot,
      v_layer,
      p_record_id
    );
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.equip_npc_inventory_record_as_staff(p_character_id uuid, p_record_kind text, p_record_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item_id uuid;
  v_slot text;
  v_layer text;
  v_hands smallint;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not public.is_staff_user() then
    raise exception 'Staff access required.';
  end if;

  if not exists (
    select 1
    from public.characters c
    join public.npcs n on n.character_id = c.id
    where c.id = p_character_id
      and c.is_system = true
  ) then
    raise exception 'NPC Character not found.';
  end if;

  if p_record_kind = 'standard' then
    select ci.item_id
    into v_item_id
    from public.character_items ci
    where ci.id = p_record_id
      and ci.character_id = p_character_id;
  elsif p_record_kind = 'unique' then
    select inst.item_id
    into v_item_id
    from public.character_item_instances inst
    where inst.id = p_record_id
      and inst.owner_character_id = p_character_id
      and inst.vault_status = 'owned';
  else
    raise exception 'Invalid inventory record type.';
  end if;

  if v_item_id is null then
    raise exception 'NPC does not own this Item.';
  end if;

  select equip_slot, equip_layer, hands_required
  into v_slot, v_layer, v_hands
  from public.items
  where id = v_item_id
    and is_equippable = true
    and is_active = true;

  if v_slot is null or v_layer is null then
    raise exception 'This Item cannot be equipped.';
  end if;

  if not public.character_can_equip_item(
    p_character_id,
    v_item_id
  ) then
    raise exception 'This character does not meet the requirements to equip this Item.';
  end if;

  if p_record_kind = 'standard' then
    update public.character_items
    set container_instance_id = null,
        updated_at = now()
    where id = p_record_id
      and character_id = p_character_id;
  else
    update public.character_item_instances
    set container_instance_id = null,
        updated_at = now()
    where id = p_record_id
      and owner_character_id = p_character_id;
  end if;

  if v_hands = 2 then
    delete from public.character_equipment
    where character_id = p_character_id
      and slot_key in ('main_hand', 'off_hand');

  elsif v_slot in ('main_hand', 'off_hand') then
    delete from public.character_equipment ce
    using public.character_items ci
    join public.items i on i.id = ci.item_id
    where ce.character_id = p_character_id
      and ce.character_item_id = ci.id
      and i.hands_required = 2;

    delete from public.character_equipment ce
    using public.character_item_instances inst
    join public.items i on i.id = inst.item_id
    where ce.character_id = p_character_id
      and ce.item_instance_id = inst.id
      and i.hands_required = 2;
  end if;

  delete from public.character_equipment
  where character_id = p_character_id
    and slot_key = v_slot
    and layer_key = v_layer;

  if p_record_kind = 'standard' then
    insert into public.character_equipment(
      character_id,
      slot_key,
      layer_key,
      character_item_id
    )
    values(
      p_character_id,
      v_slot,
      v_layer,
      p_record_id
    );
  else
    insert into public.character_equipment(
      character_id,
      slot_key,
      layer_key,
      item_instance_id
    )
    values(
      p_character_id,
      v_slot,
      v_layer,
      p_record_id
    );
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.evaluate_character_trophies(p_character_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  awarded_count integer := 0;
begin

  if not exists (
    select 1
    from public.characters c
    where c.id = p_character_id
      and c.status = 'approved'
      and coalesce(c.is_system, false) = false
  ) then
    return 0;
  end if;

  with metrics as (
    select *
    from public.get_character_trophy_metrics(
      p_character_id
    )
  ),
  eligible as (
    select
      td.id as trophy_id,
      m.metric_value
    from public.trophy_definitions td
    join metrics m
      on m.metric_key = td.metric_key
    where td.is_active = true
      and m.metric_value >= td.threshold
  ),
  inserted as (
    insert into public.character_trophies (
      character_id,
      trophy_id,
      progress_value,
      earned_at
    )
    select
      p_character_id,
      e.trophy_id,
      e.metric_value,
      now()
    from eligible e
    on conflict (
      character_id,
      trophy_id
    )
    do nothing
    returning id
  )
  select count(*)
  into awarded_count
  from inserted;

  return awarded_count;

end;
$function$
;

CREATE OR REPLACE FUNCTION public.expertise_from_presence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  elapsed numeric;
  total_seconds numeric;
  completed_hours integer;
  remainder numeric;
begin
  if tg_op <> 'UPDATE' or old.last_seen_at is null or new.last_seen_at is null then
    return new;
  end if;

  elapsed := extract(epoch from (new.last_seen_at - old.last_seen_at));

  if elapsed <= 0 or elapsed > 300 then
    return new;
  end if;

  insert into public.character_expertise_progress(character_id, online_seconds)
  values (new.character_id, elapsed)
  on conflict (character_id) do update
  set online_seconds = public.character_expertise_progress.online_seconds + excluded.online_seconds,
      updated_at = now()
  returning online_seconds into total_seconds;

  completed_hours := floor(total_seconds / 3600);

  if completed_hours > 0 then
    remainder := total_seconds - (completed_hours * 3600);

    update public.character_expertise_progress
    set online_seconds = remainder,
        updated_at = now()
    where character_id = new.character_id;

    perform public._grant_expertise(
      new.character_id,
      completed_hours * 0.3,
      'portal_time',
      completed_hours,
      completed_hours || ' portal hour(s)',
      null
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.expertise_from_room_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  added_chars integer;
  total_chars bigint;
  completed_blocks integer;
  remainder bigint;
begin
  if new.character_id is null or new.message_type <> 'action' then
    return new;
  end if;

  added_chars := char_length(coalesce(new.message, ''));
  if added_chars <= 0 then return new; end if;

  insert into public.character_expertise_progress(character_id, action_characters)
  values (new.character_id, added_chars)
  on conflict (character_id) do update
  set action_characters = public.character_expertise_progress.action_characters + excluded.action_characters,
      updated_at = now()
  returning action_characters into total_chars;

  completed_blocks := floor(total_chars / 2000.0);

  if completed_blocks > 0 then
    remainder := total_chars - (completed_blocks * 2000);

    update public.character_expertise_progress
    set action_characters = remainder,
        updated_at = now()
    where character_id = new.character_id;

    perform public._grant_expertise(
      new.character_id,
      completed_blocks * 0.5,
      'roleplay_writing',
      completed_blocks * 2000,
      (completed_blocks * 2000) || ' eligible roleplay characters',
      null
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.expire_breeze_lodging_rentals()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inn_id uuid;
begin
  select id
    into v_inn_id
  from public.rooms
  where slug = 'the-breeze-lodgings'
  limit 1;

  with expired as (
    update public.breeze_lodging_rentals
    set status = 'expired',
        expired_at = coalesce(expired_at, now())
    where status = 'active'
      and ends_at <= now()
    returning id, room_id
  ),
  revoke_guests as (
    update public.breeze_lodging_guests g
    set status = 'revoked',
        updated_at = now()
    where g.rental_id in (
      select id from expired
    )
    returning g.rental_id
  )
  update public.characters c
  set current_room_id = v_inn_id
  where v_inn_id is not null
    and c.current_room_id in (
      select room_id from expired
    );

  if v_inn_id is not null then
    update public.character_presence cp
    set room_id = v_inn_id,
        last_seen_at = now()
    where cp.character_id in (
      select c.id
      from public.characters c
      where c.current_room_id = v_inn_id
    )
      and cp.room_id in (
        select blr.room_id
        from public.breeze_lodging_rooms blr
      );
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finalize_store_discount_redemption(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.store_orders%rowtype;
begin
  select * into v_order from public.store_orders where id=p_order_id;
  if not found or v_order.discount_code_id is null then return; end if;

  insert into public.store_discount_redemptions(discount_code_id,user_id,order_id,redeemed_at)
  values(v_order.discount_code_id,v_order.user_id,v_order.id,coalesce(v_order.paid_at,now()))
  on conflict(order_id) do nothing;

  if v_order.user_discount_code_id is not null then
    update public.store_user_discount_codes
    set used_at=coalesce(used_at,coalesce(v_order.paid_at,now())), used_order_id=coalesce(used_order_id,v_order.id)
    where id=v_order.user_discount_code_id and user_id=v_order.user_id;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fulfil_store_order(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.store_orders%rowtype;
  v_grant public.store_order_grants%rowtype;
  v_note text;
begin
  select * into v_order from public.store_orders where id=p_order_id for update;
  if not found then raise exception 'Store order not found.'; end if;
  if v_order.status not in ('paid','fulfilled') then raise exception 'Store order is not paid.'; end if;
  -- Deleted accounts retain payment history but cannot receive new entitlements.
  if v_order.user_id is null then return; end if;

  v_note := case when v_order.payment_method='remnants'
    then 'Purchased from the Sepulchria Store with Remnants.'
    else 'Purchased from the Sepulchria Store.' end;

  for v_grant in select * from public.store_order_grants where order_id=p_order_id and fulfilled_at is null and revoked_at is null order by created_at asc loop
    if v_grant.grant_type='portal_skin' then
      if not exists (select 1 from public.user_portal_skin_entitlements where user_id=v_order.user_id and skin_id=v_grant.portal_skin_id and enabled=true) then
        insert into public.user_portal_skin_entitlements(user_id,skin_id,enabled,source,note,granted_by,granted_at,updated_at)
        values(v_order.user_id,v_grant.portal_skin_id,true,'paid',v_note,v_order.user_id,now(),now())
        on conflict(user_id,skin_id) do update set enabled=true,source='paid',note=excluded.note,granted_by=v_order.user_id,granted_at=now(),updated_at=now();
      end if;
    elsif v_grant.grant_type='cosmetic' then
      if not exists (select 1 from public.character_cosmetic_entitlements where character_id=v_order.character_id and cosmetic_item_id=v_grant.cosmetic_item_id and enabled=true) then
        insert into public.character_cosmetic_entitlements(character_id,cosmetic_item_id,enabled,source,note,granted_at,granted_by,updated_at)
        values(v_order.character_id,v_grant.cosmetic_item_id,true,'paid',v_note,now(),v_order.user_id,now())
        on conflict(character_id,cosmetic_item_id) do update set enabled=true,source='paid',note=excluded.note,granted_at=now(),granted_by=v_order.user_id,updated_at=now();
      end if;
    elsif v_grant.grant_type='music' then
      if not exists (select 1 from public.character_music_entitlements where character_id=v_order.character_id and music_track_id=v_grant.music_track_id and enabled=true) then
        insert into public.character_music_entitlements(character_id,music_track_id,enabled,source,note,granted_at)
        values(v_order.character_id,v_grant.music_track_id,true,'paid',v_note,now())
        on conflict(character_id,music_track_id) do update set enabled=true,source='paid',note=excluded.note,granted_at=now();
      end if;
    elsif v_grant.grant_type='feature' then
      if not exists (select 1 from public.character_feature_entitlements where character_id=v_order.character_id and feature_key=v_grant.feature_key and enabled=true) then
        insert into public.character_feature_entitlements(character_id,feature_key,enabled,source,note,granted_by,granted_at,updated_at)
        values(v_order.character_id,v_grant.feature_key,true,'paid',v_note,v_order.user_id,now(),now())
        on conflict(character_id,feature_key) do update set enabled=true,source='paid',note=excluded.note,granted_by=v_order.user_id,granted_at=now(),updated_at=now();
      end if;
    else
      raise exception 'Unsupported Store grant type: %',v_grant.grant_type;
    end if;
    update public.store_order_grants set fulfilled_at=coalesce(fulfilled_at,now()) where id=v_grant.id;
  end loop;

  update public.store_orders set status='fulfilled',fulfilled_at=coalesce(fulfilled_at,now()) where id=p_order_id;
  perform public.finalize_store_discount_redemption(p_order_id);
  perform public.issue_store_post_purchase_offers(p_order_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.gather_at_current_location()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_character_id uuid;
  v_room_id uuid;
  v_location public.gathering_locations%rowtype;
  v_daily_limit constant integer := 15;
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_used integer;
  v_remaining integer;
  v_nothing_roll numeric;
  v_total_weight numeric;
  v_pick numeric;
  v_running numeric := 0;
  v_reward public.gathering_rewards%rowtype;
  v_quantity integer;
  v_remnants integer;
  v_item public.items%rowtype;
  v_existing record;
  v_remaining_to_add integer;
  v_add integer;
  v_stack_size integer;
  v_attempt_id uuid;
  v_ledger_id uuid;
  v_new_balance bigint;
  v_action_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'You must be signed in.';
  end if;

  select c.id, c.current_room_id
  into v_character_id, v_room_id
  from public.characters c
  where c.user_id = v_user_id
    and c.status = 'approved'
    and coalesce(c.is_system, false) = false
  limit 1;

  if v_character_id is null then
    raise exception 'No approved character is available for Gathering.';
  end if;

  if v_room_id is null then
    raise exception 'You must be in a location to Gather.';
  end if;

  select gl.*
  into v_location
  from public.gathering_locations gl
  where gl.room_id = v_room_id
    and gl.is_active = true
  limit 1;

  if v_location.id is null then
    raise exception 'Gathering is not available in this location.';
  end if;

  v_day_start :=
    date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  v_day_end := v_day_start + interval '1 day';

  select count(*)::integer
  into v_used
  from public.gathering_attempts ga
  where ga.character_id = v_character_id
    and ga.created_at >= v_day_start
    and ga.created_at < v_day_end;

  if v_used >= v_daily_limit then
    raise exception 'You have used all 15 Gathering attempts for today.';
  end if;

  v_nothing_roll := random() * 100;

  if v_nothing_roll < v_location.nothing_chance then
    v_action_id :=
      public.character_audit_begin_action('gathering', 'gathering');

    insert into public.gathering_attempts (
      character_id, gathering_location_id, room_id, outcome_type,
      reward_id, item_id, quantity, remnants
    )
    values (
      v_character_id, v_location.id, v_room_id, 'nothing',
      null, null, null, null
    )
    returning id into v_attempt_id;

    perform public.character_audit_write_event(
      v_character_id,
      'gathering',
      'gathering',
      v_action_id,
      jsonb_build_object(
        'outcome_type', 'nothing',
        'attempt_id', v_attempt_id,
        'location_id', v_location.id,
        'location_name', v_location.name
      ),
      'gathering',
      v_attempt_id::text
    );

    v_remaining := greatest(v_daily_limit - (v_used + 1), 0);

    return jsonb_build_object(
      'ok', true,
      'attempt_id', v_attempt_id,
      'outcome_type', 'nothing',
      'item_id', null,
      'item_name', null,
      'item_image_url', null,
      'quantity', null,
      'remnants', null,
      'attempts_used', v_used + 1,
      'attempts_remaining', v_remaining,
      'daily_limit', v_daily_limit,
      'location_name', v_location.name,
      'message', 'You search carefully, but find nothing useful this time.'
    );
  end if;

  select coalesce(sum(gr.weight), 0)
  into v_total_weight
  from public.gathering_rewards gr
  where gr.gathering_location_id = v_location.id
    and gr.is_active = true;

  if v_total_weight <= 0 then
    raise exception 'This Gathering location has no active rewards configured.';
  end if;

  v_pick := random() * v_total_weight;

  for v_reward in
    select gr.*
    from public.gathering_rewards gr
    where gr.gathering_location_id = v_location.id
      and gr.is_active = true
    order by gr.sort_order asc, gr.id asc
  loop
    v_running := v_running + v_reward.weight;
    if v_pick < v_running then exit; end if;
  end loop;

  if v_reward.id is null then
    raise exception 'Unable to resolve a Gathering reward.';
  end if;

  if v_reward.reward_type = 'item' then
    v_quantity :=
      floor(random() * (v_reward.quantity_max - v_reward.quantity_min + 1))::integer
      + v_reward.quantity_min;

    select i.*
    into v_item
    from public.items i
    where i.id = v_reward.item_id
      and i.is_active = true
    limit 1;

    if v_item.id is null then
      raise exception 'The selected Gathering Item is unavailable.';
    end if;

    v_action_id :=
      public.character_audit_begin_action('gathering', 'gathering');

    if coalesce(v_item.stackable, false) = false then
      insert into public.character_items (
        character_id, item_id, quantity, container_instance_id,
        acquisition_source, assigned_by
      )
      select v_character_id, v_item.id, 1, null, 'system', null
      from generate_series(1, v_quantity);
    else
      v_remaining_to_add := v_quantity;

      for v_existing in
        select ci.id, ci.quantity
        from public.character_items ci
        where ci.character_id = v_character_id
          and ci.item_id = v_item.id
          and ci.container_instance_id is null
        order by ci.acquired_at asc, ci.id asc
        for update
      loop
        exit when v_remaining_to_add <= 0;

        if v_item.max_stack is null then
          update public.character_items
          set quantity = v_existing.quantity + v_remaining_to_add
          where id = v_existing.id;
          v_remaining_to_add := 0;
          exit;
        end if;

        v_add :=
          least(
            greatest(v_item.max_stack - v_existing.quantity, 0),
            v_remaining_to_add
          );

        if v_add > 0 then
          update public.character_items
          set quantity = v_existing.quantity + v_add
          where id = v_existing.id;
          v_remaining_to_add := v_remaining_to_add - v_add;
        end if;
      end loop;

      while v_remaining_to_add > 0 loop
        v_stack_size :=
          case
            when v_item.max_stack is null then v_remaining_to_add
            else least(v_item.max_stack, v_remaining_to_add)
          end;

        insert into public.character_items (
          character_id, item_id, quantity, container_instance_id,
          acquisition_source, assigned_by
        )
        values (
          v_character_id, v_item.id, v_stack_size, null, 'system', null
        );

        v_remaining_to_add := v_remaining_to_add - v_stack_size;
      end loop;
    end if;

    perform public._normalize_character_inventory_stacks(v_character_id);

    insert into public.gathering_attempts (
      character_id, gathering_location_id, room_id, outcome_type,
      reward_id, item_id, quantity, remnants
    )
    values (
      v_character_id, v_location.id, v_room_id, 'item',
      v_reward.id, v_item.id, v_quantity, null
    )
    returning id into v_attempt_id;

    perform public.character_audit_write_event(
      v_character_id,
      'gathering',
      'gathering',
      v_action_id,
      jsonb_build_object(
        'outcome_type', 'item',
        'item_id', v_item.id,
        'item_name', v_item.name,
        'quantity', v_quantity,
        'location_id', v_location.id,
        'location_name', v_location.name,
        'attempt_id', v_attempt_id
      ),
      'gathering',
      v_attempt_id::text
    );

    v_remaining := greatest(v_daily_limit - (v_used + 1), 0);

    return jsonb_build_object(
      'ok', true,
      'attempt_id', v_attempt_id,
      'outcome_type', 'item',
      'item_id', v_item.id,
      'item_name', v_item.name,
      'item_image_url', v_item.image_url,
      'quantity', v_quantity,
      'remnants', null,
      'attempts_used', v_used + 1,
      'attempts_remaining', v_remaining,
      'daily_limit', v_daily_limit,
      'location_name', v_location.name,
      'message', format('You found %s × %s.', v_item.name, v_quantity)
    );
  end if;

  if v_reward.reward_type = 'remnants' then
    v_remnants :=
      floor(random() * (v_reward.remnants_max - v_reward.remnants_min + 1))::integer
      + v_reward.remnants_min;

    v_action_id :=
      public.character_audit_begin_action('gathering', 'gathering');

    insert into public.gathering_attempts (
      character_id, gathering_location_id, room_id, outcome_type,
      reward_id, item_id, quantity, remnants
    )
    values (
      v_character_id, v_location.id, v_room_id, 'remnants',
      v_reward.id, null, null, v_remnants
    )
    returning id into v_attempt_id;

    select t.ledger_id, t.new_balance
    into v_ledger_id, v_new_balance
    from public._post_remnant_transaction(
      v_character_id,
      v_remnants::bigint,
      'gathering_reward',
      'gathering_attempt',
      v_attempt_id::text,
      'Gathering reward at ' || v_location.name,
      null
    ) t;

    perform public.character_audit_write_event(
      v_character_id,
      'gathering',
      'gathering',
      v_action_id,
      jsonb_build_object(
        'outcome_type', 'remnants',
        'remnants', v_remnants,
        'ledger_id', v_ledger_id,
        'attempt_id', v_attempt_id,
        'location_id', v_location.id,
        'location_name', v_location.name
      ),
      'gathering',
      v_attempt_id::text
    );

    v_remaining := greatest(v_daily_limit - (v_used + 1), 0);

    return jsonb_build_object(
      'ok', true,
      'attempt_id', v_attempt_id,
      'outcome_type', 'remnants',
      'item_id', null,
      'item_name', null,
      'item_image_url', null,
      'quantity', null,
      'remnants', v_remnants,
      'ledger_id', v_ledger_id,
      'attempts_used', v_used + 1,
      'attempts_remaining', v_remaining,
      'daily_limit', v_daily_limit,
      'location_name', v_location.name,
      'message', format('You found %s Remnants.', v_remnants)
    );
  end if;

  raise exception 'Unsupported Gathering reward type.';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_active_item_chat_tags(p_character_ids uuid[])
 RETURNS TABLE(character_id uuid, conditions text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with runtime as (
    select
      active.character_id,
      case
        when cardinality(coalesce(active.conditions, '{}'::text[])) > 0
          then active.conditions
        else coalesce(source.conditions, '{}'::text[])
      end as conditions
    from public.character_active_item_effects active
    left join public.item_effects source
      on source.id = active.source_effect_id
    where active.character_id = any(p_character_ids)
      and active.expires_at > now()
  )
  select
    runtime.character_id,
    coalesce(
      array_agg(
        distinct condition_label
        order by condition_label
      ) filter (
        where condition_label is not null
          and btrim(condition_label) <> ''
      ),
      '{}'::text[]
    ) as conditions
  from runtime
  left join lateral
    unnest(coalesce(runtime.conditions, '{}'::text[]))
      as condition_label
    on true
  group by runtime.character_id;
$function$
;

CREATE OR REPLACE FUNCTION public.get_active_item_chat_tags_v2(p_character_ids uuid[])
 RETURNS TABLE(character_id uuid, conditions jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with runtime as (
    select
      active.character_id,
      case
        when cardinality(
          coalesce(
            active.conditions,
            '{}'::text[]
          )
        ) > 0
          then active.conditions
        else coalesce(
          source.conditions,
          '{}'::text[]
        )
      end as conditions
    from public.character_active_item_effects active
    left join public.item_effects source
      on source.id =
        active.source_effect_id
    where
      active.character_id =
        any(p_character_ids)
      and active.expires_at > now()
  ),
  flattened as (
    select
      runtime.character_id,
      condition_label
    from runtime
    cross join lateral
      unnest(runtime.conditions)
        as condition_label
    where
      btrim(condition_label) <> ''
  )
  select
    ids.character_id,
    to_jsonb(
      coalesce(
        (
          select array_agg(
            distinct f.condition_label
            order by f.condition_label
          )
          from flattened f
          where
            f.character_id =
              ids.character_id
        ),
        '{}'::text[]
      )
    ) as conditions
  from (
    select distinct
      unnest(p_character_ids)
        as character_id
  ) ids;
$function$
;

CREATE OR REPLACE FUNCTION public.get_active_price_chat_tags(p_character_ids uuid[])
 RETURNS TABLE(character_id uuid, prices jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    ids.id,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'label',
          coalesce(wp.name,p.price_key)
          || ' (Stage '
          || case p.stage
               when 1 then 'I'
               when 2 then 'II'
               when 3 then 'III'
               else p.stage::text
             end
          || ')',
          'price_key',p.price_key,
          'expires_at',p.expires_at
        )
        order by p.expires_at
      ) filter (where p.character_id is not null),
      '[]'::jsonb
    ) as prices
  from unnest(p_character_ids) ids(id)
  left join public.character_price_effects p
    on p.character_id=ids.id
   and p.expires_at>now()
  left join public.warping_prices wp
    on wp.key=p.price_key
  group by ids.id;
$function$
;

CREATE OR REPLACE FUNCTION public.get_active_shape_chat_tags(p_character_ids uuid[])
 RETURNS TABLE(character_id uuid, buffs text[], debuffs text[], conditions text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with active as (
  select target_character_id,conditions,muscles_modifier,reflexes_modifier,vigour_modifier,
         brains_modifier,shrewd_modifier,presence_modifier,max_hp_modifier
  from public.character_shape_effects
  where target_character_id=any(p_character_ids)
    and dispelled_at is null
    and (expires_at is null or expires_at>now())
),
expanded as (
  select target_character_id,'buff'::text kind,
         unnest(array_remove(array[
           case when muscles_modifier>0 then 'Muscles +'||muscles_modifier end,
           case when reflexes_modifier>0 then 'Reflexes +'||reflexes_modifier end,
           case when vigour_modifier>0 then 'Vigour +'||vigour_modifier end,
           case when brains_modifier>0 then 'Brains +'||brains_modifier end,
           case when shrewd_modifier>0 then 'Shrewd +'||shrewd_modifier end,
           case when presence_modifier>0 then 'Presence +'||presence_modifier end,
           case when max_hp_modifier>0 then 'Max HP +'||max_hp_modifier end
         ],null)) value
  from active
  union all
  select target_character_id,'debuff',
         unnest(array_remove(array[
           case when muscles_modifier<0 then 'Muscles '||muscles_modifier end,
           case when reflexes_modifier<0 then 'Reflexes '||reflexes_modifier end,
           case when vigour_modifier<0 then 'Vigour '||vigour_modifier end,
           case when brains_modifier<0 then 'Brains '||brains_modifier end,
           case when shrewd_modifier<0 then 'Shrewd '||shrewd_modifier end,
           case when presence_modifier<0 then 'Presence '||presence_modifier end,
           case when max_hp_modifier<0 then 'Max HP '||max_hp_modifier end
         ],null))
  from active
),
chars as (
  select target_character_id,unnest(conditions) value from active
)
select ids.id,
       coalesce(array_agg(distinct e.value) filter(where e.kind='buff' and e.value is not null),'{}'::text[]),
       coalesce(array_agg(distinct e.value) filter(where e.kind='debuff' and e.value is not null),'{}'::text[]),
       coalesce((select array_agg(distinct c.value) from chars c where c.target_character_id=ids.id),'{}'::text[])
from unnest(p_character_ids) ids(id)
left join expanded e on e.target_character_id=ids.id
group by ids.id
$function$
;

CREATE OR REPLACE FUNCTION public.get_character_active_item_effects(p_character_id uuid)
 RETURNS TABLE(id uuid, item_id uuid, source_name text, conditions text[], muscles_modifier integer, reflexes_modifier integer, vigour_modifier integer, brains_modifier integer, shrewd_modifier integer, presence_modifier integer, max_health_modifier integer, warping_affinity_modifier integer, warps_per_day_modifier integer, activated_at timestamp with time zone, expires_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    active.id,
    active.item_id,
    active.source_name,
    case
      when cardinality(coalesce(active.conditions, '{}'::text[])) > 0
        then active.conditions
      else coalesce(source.conditions, '{}'::text[])
    end as conditions,
    active.muscles_modifier,
    active.reflexes_modifier,
    active.vigour_modifier,
    active.brains_modifier,
    active.shrewd_modifier,
    active.presence_modifier,
    active.max_health_modifier,
    active.warping_affinity_modifier,
    active.warps_per_day_modifier,
    active.activated_at,
    active.expires_at
  from public.character_active_item_effects active
  left join public.item_effects source
    on source.id = active.source_effect_id
  where active.character_id = p_character_id
    and active.expires_at > now()
  order by
    active.expires_at asc,
    active.activated_at asc,
    active.id asc;
$function$
;

