 RETURNS TABLE(id uuid, item_id uuid, source_name text, conditions jsonb, muscles_modifier integer, reflexes_modifier integer, vigour_modifier integer, brains_modifier integer, shrewd_modifier integer, presence_modifier integer, max_health_modifier integer, warping_affinity_modifier integer, warps_per_day_modifier integer, activated_at timestamp with time zone, expires_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    active.id,
    active.item_id,
    active.source_name,
    to_jsonb(
      case
        when cardinality(
          coalesce(
            active.conditions,
            '{}'::text[]
          )
        ) > 0
          then active.conditions
        else coalesce(
          source.conditions,
          '{}'::text[]
        )
      end
    ) as conditions,
    active.muscles_modifier,
    active.reflexes_modifier,
    active.vigour_modifier,
    active.brains_modifier,
    active.shrewd_modifier,
    active.presence_modifier,
    active.max_health_modifier,
    active.warping_affinity_modifier,
    active.warps_per_day_modifier,
    active.activated_at,
    active.expires_at
  from public.character_active_item_effects active
  left join public.item_effects source
    on source.id = active.source_effect_id
  where
    active.character_id =
      p_character_id
    and active.expires_at > now()
  order by
    active.expires_at asc,
    active.activated_at asc,
    active.id asc;
$function$
;

CREATE OR REPLACE FUNCTION public.get_character_active_item_modifiers(p_character_id uuid)
 RETURNS TABLE(muscles_modifier integer, reflexes_modifier integer, vigour_modifier integer, shrewd_modifier integer, brains_modifier integer, presence_modifier integer, max_health_modifier integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allowed boolean;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  select exists (
    select 1
    from public.characters c
    where c.id = p_character_id
      and (
        c.status = 'approved'
        or c.user_id = auth.uid()
        or public.is_staff_user()
      )
  )
  into v_allowed;

  if not v_allowed then
    raise exception 'Character mechanics are not available.';
  end if;

  return query
  select
    coalesce(sum(a.muscles_modifier), 0)::integer,
    coalesce(sum(a.reflexes_modifier), 0)::integer,
    coalesce(sum(a.vigour_modifier), 0)::integer,
    coalesce(sum(a.shrewd_modifier), 0)::integer,
    coalesce(sum(a.brains_modifier), 0)::integer,
    coalesce(sum(a.presence_modifier), 0)::integer,
    coalesce(sum(a.max_health_modifier), 0)::integer
  from public.character_active_item_effects a
  where a.character_id = p_character_id
    and a.expires_at > now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_character_active_shape_effects(p_character_id uuid)
 RETURNS TABLE(id uuid, shape_id uuid, shape_name text, shape_level integer, effect_nature text, conditions text[], muscles_modifier integer, reflexes_modifier integer, vigour_modifier integer, brains_modifier integer, shrewd_modifier integer, presence_modifier integer, max_hp_modifier integer, starts_at timestamp with time zone, expires_at timestamp with time zone, source_character_id uuid, source_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select e.id,e.shape_id,s.name,e.shape_level,e.effect_nature,e.conditions,e.muscles_modifier,
e.reflexes_modifier,e.vigour_modifier,e.brains_modifier,e.shrewd_modifier,e.presence_modifier,
e.max_hp_modifier,e.starts_at,e.expires_at,e.source_character_id,c.display_name
from character_shape_effects e join shapes s on s.id=e.shape_id join characters c on c.id=e.source_character_id
where e.target_character_id=p_character_id and e.dispelled_at is null and(e.expires_at is null or e.expires_at>now())
order by e.starts_at desc $function$
;

CREATE OR REPLACE FUNCTION public.get_character_current_max_health(p_character_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_base_vigour integer := 0;
  v_ancestry_vigour integer := 0;
  v_order_vigour integer := 0;
  v_gift_vigour integer := 0;
  v_item_vigour integer := 0;
  v_item_max_health integer := 0;
  v_active_vigour integer := 0;
  v_active_max_health integer := 0;
  v_effect_vigour integer := 0;
  v_effect_max_health integer := 0;
begin
  select
    coalesce(c.vigor, 0),
    coalesce(r.vigour_modifier, 0)
  into
    v_base_vigour,
    v_ancestry_vigour
  from public.characters c
  left join public.races r
    on r.id = c.race_id
  where c.id = p_character_id;

  if not found then
    return 0;
  end if;

  select
    coalesce(oj.vigour_modifier, 0)
  into
    v_order_vigour
  from public.order_memberships om
  join public.order_jobs oj
    on oj.id = om.order_job_id
  where om.character_id = p_character_id
  limit 1;

  v_order_vigour :=
    coalesce(
      v_order_vigour,
      0
    );

  select
    coalesce(
      sum(g.vigour_modifier),
      0
    )::integer
  into
    v_gift_vigour
  from public.character_gifts cg
  join public.gifts g
    on g.id = cg.gift_id
  where cg.character_id = p_character_id
    and g.is_active = true
    and (
      g.effect_mode = 'passive'
      or (
        g.effect_mode = 'temporary'
        and exists (
          select 1
          from public.gift_activations ga
          where ga.character_gift_id = cg.id
            and ga.ended_at is null
            and ga.health_reverted_at is null
            and ga.activated_at <= now()
            and ga.expires_at > now()
        )
      )
    );

  select
    m.vigour_modifier,
    m.max_health_modifier
  into
    v_item_vigour,
    v_item_max_health
  from public.get_character_item_passive_modifiers(
    p_character_id
  ) m;

  v_item_vigour :=
    coalesce(
      v_item_vigour,
      0
    );

  v_item_max_health :=
    coalesce(
      v_item_max_health,
      0
    );

  select
    coalesce(
      sum(a.vigour_modifier),
      0
    )::integer,
    coalesce(
      sum(a.max_health_modifier),
      0
    )::integer
  into
    v_active_vigour,
    v_active_max_health
  from public.character_active_item_effects a
  where a.character_id = p_character_id
    and a.expires_at > now();

  -- NEW: include currently active Shape / persistent Character effects.
  select
    coalesce(
      sum(e.vigour_modifier),
      0
    )::integer,
    coalesce(
      sum(e.max_health_modifier),
      0
    )::integer
  into
    v_effect_vigour,
    v_effect_max_health
  from public.character_effects e
  where e.target_character_id = p_character_id
    and e.ended_at is null
    and e.dispelled_at is null
    and (
      e.starts_at is null
      or e.starts_at <= now()
    )
    and (
      e.expires_at is null
      or e.expires_at > now()
    );

  return greatest(
    0,
    (
      v_base_vigour
      + v_gift_vigour
      + v_item_vigour
      + v_active_vigour
      + v_effect_vigour
      + v_ancestry_vigour
      + v_order_vigour
    ) * 10
    + v_item_max_health
    + v_active_max_health
    + v_effect_max_health
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_character_item_passive_modifiers(p_character_id uuid)
 RETURNS TABLE(muscles_modifier integer, reflexes_modifier integer, vigour_modifier integer, shrewd_modifier integer, brains_modifier integer, presence_modifier integer, max_health_modifier integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allowed boolean;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  select exists (
    select 1
    from public.characters c
    where c.id = p_character_id
      and (
        c.status = 'approved'
        or c.user_id = auth.uid()
        or public.is_staff_user()
      )
  )
  into v_allowed;

  if not v_allowed then
    raise exception 'Character mechanics are not available.';
  end if;

  return query

  with standard_owned as (
    select
      ci.item_id,
      sum(ci.quantity)::integer as copies
    from public.character_items ci
    where ci.character_id = p_character_id
    group by ci.item_id
  ),

  unique_owned as (
    select
      inst.id as instance_id,
      inst.item_id,
      exists (
        select 1
        from public.item_instance_effects ie
        where ie.item_instance_id = inst.id
          and ie.replaces_master_effects = true
      ) as replaces_master
    from public.character_item_instances inst
    where inst.owner_character_id = p_character_id
      and inst.vault_status = 'owned'
  ),

  owned_master_counts as (
    select
      owned.item_id,
      sum(owned.copies)::integer as copies
    from (
      select
        so.item_id,
        so.copies
      from standard_owned so

      union all

      select
        uo.item_id,
        count(*)::integer as copies
      from unique_owned uo
      where uo.replaces_master = false
      group by uo.item_id
    ) owned
    group by owned.item_id
  ),

  equipped_standard as (
    select
      ci.item_id,
      count(*)::integer as copies
    from public.character_equipment ce
    join public.character_items ci
      on ci.id = ce.character_item_id
    where ce.character_id = p_character_id
    group by ci.item_id
  ),

  equipped_unique as (
    select
      inst.item_id,
      count(*)::integer as copies
    from public.character_equipment ce
    join public.character_item_instances inst
      on inst.id = ce.item_instance_id
    where ce.character_id = p_character_id
      and not exists (
        select 1
        from public.item_instance_effects ie
        where ie.item_instance_id = inst.id
          and ie.replaces_master_effects = true
      )
    group by inst.item_id
  ),

  equipped_master_counts as (
    select
      equipped.item_id,
      sum(equipped.copies)::integer as copies
    from (
      select
        es.item_id,
        es.copies
      from equipped_standard es

      union all

      select
        eu.item_id,
        eu.copies
      from equipped_unique eu
    ) equipped
    group by equipped.item_id
  ),

  master_effect_rows as (
    select
      e.muscles_modifier,
      e.reflexes_modifier,
      e.vigour_modifier,
      e.shrewd_modifier,
      e.brains_modifier,
      e.presence_modifier,
      e.max_health_modifier,
      e.allow_duplicate_stacking,
      omc.copies
    from public.item_effects e
    join owned_master_counts omc
      on omc.item_id = e.item_id
    where e.trigger_type = 'owned'
      and e.effect_mode = 'passive'

    union all

    select
      e.muscles_modifier,
      e.reflexes_modifier,
      e.vigour_modifier,
      e.shrewd_modifier,
      e.brains_modifier,
      e.presence_modifier,
      e.max_health_modifier,
      e.allow_duplicate_stacking,
      emc.copies
    from public.item_effects e
    join equipped_master_counts emc
      on emc.item_id = e.item_id
    where e.trigger_type = 'equipped'
      and e.effect_mode = 'passive'
  ),

  master_totals as (
    select
      coalesce(
        sum(
          mer.muscles_modifier *
          case
            when mer.allow_duplicate_stacking then mer.copies
            else 1
          end
        ),
        0
      )::integer as muscles,

      coalesce(
        sum(
          mer.reflexes_modifier *
          case
            when mer.allow_duplicate_stacking then mer.copies
            else 1
          end
        ),
        0
      )::integer as reflexes,

      coalesce(
        sum(
          mer.vigour_modifier *
          case
            when mer.allow_duplicate_stacking then mer.copies
            else 1
          end
        ),
        0
      )::integer as vigour,

      coalesce(
        sum(
          mer.shrewd_modifier *
          case
            when mer.allow_duplicate_stacking then mer.copies
            else 1
          end
        ),
        0
      )::integer as shrewd,

      coalesce(
        sum(
          mer.brains_modifier *
          case
            when mer.allow_duplicate_stacking then mer.copies
            else 1
          end
        ),
        0
      )::integer as brains,

      coalesce(
        sum(
          mer.presence_modifier *
          case
            when mer.allow_duplicate_stacking then mer.copies
            else 1
          end
        ),
        0
      )::integer as presence,

      coalesce(
        sum(
          mer.max_health_modifier *
          case
            when mer.allow_duplicate_stacking then mer.copies
            else 1
          end
        ),
        0
      )::integer as max_health

    from master_effect_rows mer
  ),

  unique_effect_rows as (
    select
      ie.muscles_modifier,
      ie.reflexes_modifier,
      ie.vigour_modifier,
      ie.shrewd_modifier,
      ie.brains_modifier,
      ie.presence_modifier,
      ie.max_health_modifier
    from public.item_instance_effects ie
    join public.character_item_instances inst
      on inst.id = ie.item_instance_id
    where inst.owner_character_id = p_character_id
      and inst.vault_status = 'owned'
      and ie.effect_mode = 'passive'
      and (
        ie.trigger_type = 'owned'
        or (
          ie.trigger_type = 'equipped'
          and exists (
            select 1
            from public.character_equipment ce
            where ce.character_id = p_character_id
              and ce.item_instance_id = inst.id
          )
        )
      )
  ),

  unique_totals as (
    select
      coalesce(sum(uer.muscles_modifier), 0)::integer as muscles,
      coalesce(sum(uer.reflexes_modifier), 0)::integer as reflexes,
      coalesce(sum(uer.vigour_modifier), 0)::integer as vigour,
      coalesce(sum(uer.shrewd_modifier), 0)::integer as shrewd,
      coalesce(sum(uer.brains_modifier), 0)::integer as brains,
      coalesce(sum(uer.presence_modifier), 0)::integer as presence,
      coalesce(sum(uer.max_health_modifier), 0)::integer as max_health
    from unique_effect_rows uer
  )

  select
    (mt.muscles + ut.muscles)::integer,
    (mt.reflexes + ut.reflexes)::integer,
    (mt.vigour + ut.vigour)::integer,
    (mt.shrewd + ut.shrewd)::integer,
    (mt.brains + ut.brains)::integer,
    (mt.presence + ut.presence)::integer,
    (mt.max_health + ut.max_health)::integer
  from master_totals mt
  cross join unique_totals ut;

end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_character_item_warping_modifiers(p_character_id uuid)
 RETURNS TABLE(affinity_modifier integer, warps_per_day_modifier integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allowed boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required.'; end if;

  select exists (
    select 1 from public.characters c
    where c.id=p_character_id
      and (c.status='approved' or c.user_id=auth.uid() or public.is_staff_user())
  ) into v_allowed;

  if not v_allowed then raise exception 'Character mechanics are not available.'; end if;

  return query
  with standard_owned as (
    select ci.item_id,sum(ci.quantity)::integer copies
    from public.character_items ci
    where ci.character_id=p_character_id group by ci.item_id
  ),
  unique_owned as (
    select inst.id instance_id,inst.item_id,
      exists(select 1 from public.item_instance_effects ie
             where ie.item_instance_id=inst.id and ie.replaces_master_effects=true) replaces_master
    from public.character_item_instances inst
    where inst.owner_character_id=p_character_id and inst.vault_status='owned'
  ),
  owned_master_counts as (
    select x.item_id,sum(x.copies)::integer copies from (
      select item_id,copies from standard_owned
      union all
      select item_id,count(*)::integer from unique_owned
      where replaces_master=false group by item_id
    ) x group by x.item_id
  ),
  equipped_standard as (
    select ci.item_id,count(*)::integer copies
    from public.character_equipment ce
    join public.character_items ci on ci.id=ce.character_item_id
    where ce.character_id=p_character_id group by ci.item_id
  ),
  equipped_unique as (
    select inst.item_id,count(*)::integer copies
    from public.character_equipment ce
    join public.character_item_instances inst on inst.id=ce.item_instance_id
    where ce.character_id=p_character_id
      and not exists(select 1 from public.item_instance_effects ie
                     where ie.item_instance_id=inst.id and ie.replaces_master_effects=true)
    group by inst.item_id
  ),
  equipped_master_counts as (
    select x.item_id,sum(x.copies)::integer copies from (
      select item_id,copies from equipped_standard
      union all select item_id,copies from equipped_unique
    ) x group by x.item_id
  ),
  master_rows as (
    select e.warping_affinity_modifier affinity,e.warps_per_day_modifier warps,
           e.allow_duplicate_stacking,omc.copies
    from public.item_effects e join owned_master_counts omc on omc.item_id=e.item_id
    where e.trigger_type='owned' and e.effect_mode='passive'
    union all
    select e.warping_affinity_modifier,e.warps_per_day_modifier,
           e.allow_duplicate_stacking,emc.copies
    from public.item_effects e join equipped_master_counts emc on emc.item_id=e.item_id
    where e.trigger_type='equipped' and e.effect_mode='passive'
  ),
  master_totals as (
    select
      coalesce(sum(affinity * case when allow_duplicate_stacking then copies else 1 end),0)::integer affinity,
      coalesce(sum(warps * case when allow_duplicate_stacking then copies else 1 end),0)::integer warps
    from master_rows
  ),
  unique_totals as (
    select
      coalesce(sum(ie.warping_affinity_modifier),0)::integer affinity,
      coalesce(sum(ie.warps_per_day_modifier),0)::integer warps
    from public.item_instance_effects ie
    join public.character_item_instances inst on inst.id=ie.item_instance_id
    where inst.owner_character_id=p_character_id and inst.vault_status='owned'
      and ie.effect_mode='passive'
      and (
        ie.trigger_type='owned'
        or (ie.trigger_type='equipped' and exists(
          select 1 from public.character_equipment ce
          where ce.character_id=p_character_id and ce.item_instance_id=inst.id
        ))
      )
  ),
  active_totals as (
    select
      coalesce(sum(a.warping_affinity_modifier),0)::integer affinity,
      coalesce(sum(a.warps_per_day_modifier),0)::integer warps
    from public.character_active_item_effects a
    where a.character_id=p_character_id and a.expires_at>now()
  )
  select (m.affinity+u.affinity+a.affinity)::integer,
         (m.warps+u.warps+a.warps)::integer
  from master_totals m cross join unique_totals u cross join active_totals a;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_character_trophy_metrics(p_character_id uuid)
 RETURNS TABLE(metric_key text, metric_value numeric)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$

  select 'character_approved'::text,
    case when c.status = 'approved' then 1::numeric else 0::numeric end
  from public.characters c
  where c.id = p_character_id

  union all
  select 'expertise_total', coalesce(c.expertise, 0)::numeric
  from public.characters c
  where c.id = p_character_id

  union all
  select 'membership_days',
    greatest(
      floor(extract(epoch from (now() - u.created_at)) / 86400),
      0
    )::numeric
  from public.characters c
  join auth.users u on u.id = c.user_id
  where c.id = p_character_id

  union all
  select 'recipes_known', count(distinct cr.recipe_id)::numeric
  from public.character_recipes cr
  where cr.character_id = p_character_id

  union all
  select 'items_crafted_total', coalesce(cls.items_crafted_total, 0)::numeric
  from public.character_lifetime_stats cls
  where cls.character_id = p_character_id

  union all
  select 'gathering_attempts_total', count(ga.id)::numeric
  from public.gathering_attempts ga
  where ga.character_id = p_character_id

  union all
  select 'active_portal_seconds', coalesce(cls.active_portal_seconds, 0)::numeric
  from public.character_lifetime_stats cls
  where cls.character_id = p_character_id

  union all
  select 'item_types_ever_owned', count(distinct inventory.item_id)::numeric
  from (
    select ci.item_id
    from public.character_items ci
    where ci.character_id = p_character_id
      and coalesce(ci.acquisition_source, '') <> 'crafting-test'

    union

    select cii.item_id
    from public.character_item_instances cii
    where cii.owner_character_id = p_character_id
      and coalesce(cii.acquisition_source, '') <> 'crafting-test'

    union

    select (cal.new_values ->> 'item_id')::uuid
    from public.character_audit_log cal
    where cal.entity_type = 'character_items'
      and cal.operation = 'insert'
      and cal.character_id = p_character_id
      and cal.new_values ->> 'item_id' is not null
      and coalesce(cal.new_values ->> 'acquisition_source', '') <> 'crafting-test'

    union

    select (cal.new_values ->> 'item_id')::uuid
    from public.character_audit_log cal
    where cal.entity_type = 'character_item_instances'
      and cal.operation = 'insert'
      and (
        cal.character_id = p_character_id
        or cal.new_values ->> 'owner_character_id' = p_character_id::text
      )
      and cal.new_values ->> 'item_id' is not null
      and coalesce(cal.new_values ->> 'acquisition_source', '') <> 'crafting-test'
  ) inventory

  union all
  select 'shapes_owned', count(distinct cs.shape_id)::numeric
  from public.character_shapes cs
  where cs.character_id = p_character_id

  union all
  select 'feats_owned', count(distinct cg.gift_id)::numeric
  from public.character_gifts cg
  where cg.character_id = p_character_id

  union all
  select 'feat_activations', count(ga.id)::numeric
  from public.gift_activations ga
  join public.character_gifts cg on cg.id = ga.character_gift_id
  where cg.character_id = p_character_id

  union all
  select 'private_messages_sent', count(dm.id)::numeric
  from public.direct_messages dm
  where dm.sender_character_id = p_character_id

  union all
  select 'instant_chat_messages', count(icm.id)::numeric
  from public.instant_chat_messages icm
  where icm.sender_character_id = p_character_id

  union all
  select 'forum_posts', count(fp.id)::numeric
  from public.forum_posts fp
  where fp.author_character_id = p_character_id

  union all
  select 'forum_topics_created', count(ft.id)::numeric
  from public.forum_topics ft
  where ft.author_character_id = p_character_id
    and ft.deleted_at is null

  union all
  select 'odd_jobs_completed', count(ojc.id)::numeric
  from public.odd_job_claims ojc
  where ojc.character_id = p_character_id

  union all
  select 'house_of_chances_plays', count(hcp.id)::numeric
  from public.house_of_chances_plays hcp
  where hcp.character_id = p_character_id

  union all
  select 'house_of_chances_wins', count(hcp.id)::numeric
  from public.house_of_chances_plays hcp
  where hcp.character_id = p_character_id
    and hcp.matched_rule_id is not null

  union all
  select 'breeze_rentals', count(blr.id)::numeric
  from public.breeze_lodging_rentals blr
  where blr.owner_character_id = p_character_id

  union all
  select 'breeze_days', coalesce(sum(blr.days), 0)::numeric
  from public.breeze_lodging_rentals blr
  where blr.owner_character_id = p_character_id

  union all
  select 'order_memberships', count(distinct om.order_id)::numeric
  from public.order_memberships om
  where om.character_id = p_character_id

  union all
  select 'remnants_lifetime_earned',
    coalesce(sum(case when rl.amount > 0 then rl.amount else 0 end), 0)::numeric
  from public.remnant_ledger rl
  where rl.character_id = p_character_id

  union all
  select 'remnants_lifetime_spent',
    coalesce(sum(case when rl.amount < 0 then abs(rl.amount) else 0 end), 0)::numeric
  from public.remnant_ledger rl
  where rl.character_id = p_character_id

  union all
  select 'premium_features_ever',
    (
      (
        select count(distinct cfe.feature_key)
        from public.character_feature_entitlements cfe
        where cfe.character_id = p_character_id
      )
      +
      (
        select count(distinct upse.skin_id)
        from public.user_portal_skin_entitlements upse
        join public.characters c on c.user_id = upse.user_id
        where c.id = p_character_id
      )
    )::numeric;

$function$
;

CREATE OR REPLACE FUNCTION public.get_character_warping_feat_bonuses(p_character_id uuid)
 RETURNS TABLE(affinity_modifier integer, warps_per_day_modifier integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allowed boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required.'; end if;

  select exists (
    select 1 from public.characters c
    where c.id=p_character_id
      and (c.status='approved' or c.user_id=auth.uid() or public.is_staff_user())
  ) into v_allowed;

  if not v_allowed then raise exception 'Character mechanics are not available.'; end if;

  return query
  with passive as (
    select
      coalesce(sum(g.warping_affinity_modifier),0)::integer affinity,
      coalesce(sum(g.warps_per_day_modifier),0)::integer warps
    from public.character_gifts cg
    join public.gifts g on g.id=cg.gift_id
    where cg.character_id=p_character_id
      and (cg.expires_at is null or cg.expires_at>now())
      and g.is_active=true
      and g.effect_mode='passive'
  ),
  temporary as (
    select
      coalesce(sum(g.warping_affinity_modifier),0)::integer affinity,
      coalesce(sum(g.warps_per_day_modifier),0)::integer warps
    from public.gift_activations ga
    join public.character_gifts cg on cg.id=ga.character_gift_id
    join public.gifts g on g.id=cg.gift_id
    where g.is_active=true
      and g.effect_mode='temporary'
      and ga.activated_at<=now()
      and ga.expires_at>now()
      and ga.ended_at is null
      and (
        ga.target_character_id=p_character_id
        or (ga.target_character_id is null and cg.character_id=p_character_id)
      )
  )
  select (p.affinity+t.affinity)::integer,(p.warps+t.warps)::integer
  from passive p cross join temporary t;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_current_sanction_enforcement(p_capability text)
 RETURNS TABLE(blocked boolean, sanction_id uuid, sanction_type text, message text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_row public.sanctions%rowtype;
  v_prefix text;
begin
  if v_user_id is null then
    return query
    select false, null::uuid, null::text, null::text, null::timestamptz;
    return;
  end if;

  if p_capability not in (
    'communication',
    'forum',
    'game_chat',
    'portal'
  ) then
    raise exception 'Invalid sanction capability.';
  end if;

  select s.*
  into v_row
  from public.sanctions s
  where s.target_user_id = v_user_id
    and s.status = 'active'
    and s.starts_at <= now()
    and (
      s.expires_at is null
      or s.expires_at > now()
    )
    and (
      s.sanction_type in (
        'temporary_suspension',
        'permanent_ban'
      )
      or (
        p_capability = 'communication'
        and s.sanction_type = 'communication_restriction'
      )
      or (
        p_capability = 'forum'
        and s.sanction_type = 'forum_restriction'
      )
      or (
        p_capability = 'game_chat'
        and s.sanction_type = 'game_chat_restriction'
      )
    )
  order by
    case s.sanction_type
      when 'permanent_ban' then 1
      when 'temporary_suspension' then 2
      else 3
    end,
    s.issued_at desc
  limit 1;

  if v_row.id is null then
    return query
    select false, null::uuid, null::text, null::text, null::timestamptz;
    return;
  end if;

  v_prefix :=
    case v_row.sanction_type
      when 'permanent_ban'
        then 'This account has been permanently banned.'
      when 'temporary_suspension'
        then 'This account is temporarily suspended.'
      when 'communication_restriction'
        then 'Private communication is currently restricted on this account.'
      when 'forum_restriction'
        then 'Forum posting is currently restricted on this account.'
      when 'game_chat_restriction'
        then 'Game chat is currently restricted on this account.'
      else
        'This action is currently restricted on this account.'
    end;

  return query
  select
    true,
    v_row.id,
    v_row.sanction_type,
    trim(
      v_prefix || ' ' ||
      coalesce(nullif(btrim(v_row.player_reason), '') || ' ', '') ||
      case
        when v_row.expires_at is not null
          then 'Restriction expires ' ||
               to_char(
                 v_row.expires_at at time zone 'UTC',
                 'DD-MM-YYYY HH24:MI'
               ) ||
               ' UTC.'
        else ''
      end
    ),
    v_row.expires_at;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_instant_chat_contacts()
 RETURNS TABLE(character_id uuid, display_name text, portrait_url text, public_slug text, presence_status text, conversation_id uuid, unread_count bigint, last_message_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 with me as (select public.instant_chat_current_character_id() id)
 select
  c.id,
  coalesce(nullif(btrim(c.display_name),''),c.first_name,'Unnamed character'),
  c.portrait_url,
  c.public_slug,
  coalesce(cp.status::text,'offline'),
  conv.id,
  coalesce((
   select count(*) from public.instant_chat_messages m
   left join public.instant_chat_participants p
    on p.conversation_id=conv.id and p.character_id=(select id from me)
   where m.conversation_id=conv.id
    and m.sender_character_id<>(select id from me)
    and m.created_at>coalesce(p.last_read_at,'-infinity'::timestamptz)
  ),0)::bigint,
  (select max(m.created_at) from public.instant_chat_messages m where m.conversation_id=conv.id)
 from public.characters c
 join public.instant_chat_settings s on s.character_id=c.id and s.enabled=true
 left join public.character_presence cp on cp.character_id=c.id
 cross join me
 left join public.instant_chat_conversations conv on
  (conv.character_one_id=me.id and conv.character_two_id=c.id)
  or (conv.character_two_id=me.id and conv.character_one_id=c.id)
 where c.status='approved' and c.id<>me.id
 and not exists (
  select 1 from public.character_blocks b where
   (b.blocker_character_id=me.id and b.blocked_character_id=c.id)
   or (b.blocker_character_id=c.id and b.blocked_character_id=me.id)
 )
 order by
  (
    select max(m.created_at)
    from public.instant_chat_messages m
    where m.conversation_id = conv.id
  ) desc nulls last,
  coalesce(
    nullif(btrim(c.display_name), ''),
    c.first_name,
    'Unnamed character'
  ) asc;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_breeze_lodgings_state()
 RETURNS TABLE(room_id uuid, room_name text, room_number integer, tier text, daily_rate integer, is_available boolean, rented_by_me boolean, can_enter boolean, rental_ends_at timestamp with time zone, my_wallet_balance integer, viewer_is_staff boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_balance integer := 0;
  v_is_staff boolean := false;
begin
  if v_user_id is null then
    raise exception 'You must be signed in.';
  end if;

  perform public.expire_breeze_lodging_rentals();

  select c.id
    into v_character_id
  from public.characters c
  where c.user_id = v_user_id
    and c.status = 'approved'
  limit 1;

  if v_character_id is null then
    raise exception 'Your character must be approved.';
  end if;

  select exists(
    select 1
    from public.staff_members sm
    where sm.user_id = v_user_id
  ) into v_is_staff;

  select coalesce(w.balance, 0)
    into v_balance
  from public.character_wallets w
  where w.character_id = v_character_id;

  return query
  select
    blr.room_id,
    r.name::text,
    blr.room_number,
    blr.tier,
    blr.daily_rate,
    (rent.id is null) as is_available,
    (rent.owner_character_id = v_character_id) as rented_by_me,
    (
      rent.id is not null
      and (
        rent.owner_character_id = v_character_id
        or v_is_staff
        or exists (
          select 1
          from public.breeze_lodging_guests g
          where g.rental_id = rent.id
            and g.character_id = v_character_id
            and g.status = 'active'
        )
      )
    ) as can_enter,
    case
      when rent.owner_character_id = v_character_id
        then rent.ends_at
      else null
    end as rental_ends_at,
    v_balance as my_wallet_balance,
    v_is_staff as viewer_is_staff
  from public.breeze_lodging_rooms blr
  join public.rooms r on r.id = blr.room_id
  left join public.breeze_lodging_rentals rent
    on rent.room_id = blr.room_id
   and rent.status = 'active'
  where r.is_active = true
  order by blr.room_number;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_gathering_history_today()
 RETURNS TABLE(attempt_id uuid, created_at timestamp with time zone, location_name text, outcome_type text, item_id uuid, item_name text, quantity integer, remnants integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    ga.id,
    ga.created_at,
    gl.name,
    ga.outcome_type,
    ga.item_id,
    i.name,
    ga.quantity,
    ga.remnants
  from public.gathering_attempts ga
  join public.characters c
    on c.id = ga.character_id
  join public.gathering_locations gl
    on gl.id = ga.gathering_location_id
  left join public.items i
    on i.id = ga.item_id
  where c.user_id = auth.uid()
    and ga.created_at >=
      date_trunc('day', now() at time zone 'UTC')
      at time zone 'UTC'
    and ga.created_at <
      (
        date_trunc('day', now() at time zone 'UTC')
        + interval '1 day'
      ) at time zone 'UTC'
  order by ga.created_at desc;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_gathering_state()
 RETURNS TABLE(gathering_location_id uuid, room_id uuid, location_name text, location_description text, nothing_chance numeric, daily_limit integer, attempts_used integer, attempts_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_character_id uuid;
  v_room_id uuid;
  v_location public.gathering_locations%rowtype;
  v_used integer;
  v_daily_limit constant integer := 15;
  v_day_start timestamptz;
  v_day_end timestamptz;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'You must be signed in.';
  end if;

  select c.id, c.current_room_id
  into v_character_id, v_room_id
  from public.characters c
  where c.user_id = v_user_id
    and c.status = 'approved'
    and coalesce(c.is_system, false) = false
  limit 1;

  if v_character_id is null or v_room_id is null then
    return;
  end if;

  select gl.*
  into v_location
  from public.gathering_locations gl
  where gl.room_id = v_room_id
    and gl.is_active = true
  limit 1;

  if v_location.id is null then
    return;
  end if;

  v_day_start :=
    date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  v_day_end := v_day_start + interval '1 day';

  select count(*)::integer
  into v_used
  from public.gathering_attempts ga
  where ga.character_id = v_character_id
    and ga.created_at >= v_day_start
    and ga.created_at < v_day_end;

  return query
  select
    v_location.id,
    v_location.room_id,
    v_location.name,
    v_location.description,
    v_location.nothing_chance,
    v_daily_limit,
    least(v_used, v_daily_limit),
    greatest(v_daily_limit - v_used, 0);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_house_of_chances_state()
 RETURNS TABLE(is_open boolean, play_cost integer, daily_play_limit integer, plays_used integer, plays_remaining integer, wallet_balance integer, room_slug text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_character_id uuid;
  v_settings public.house_of_chances_settings%rowtype;
  v_used integer := 0;
  v_balance integer := 0;
  v_today date := (now() at time zone 'UTC')::date;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'You must be signed in.';
  end if;

  select c.id
  into v_character_id
  from public.characters c
  where c.user_id = v_user_id
    and coalesce(c.is_system, false) = false
  limit 1;

  if v_character_id is null then
    raise exception 'No playable character was found.';
  end if;

  select *
  into v_settings
  from public.house_of_chances_settings
  where id = 1;

  if not found then
    raise exception 'House of Chances settings are missing.';
  end if;

  select count(*)::integer
  into v_used
  from public.house_of_chances_plays p
  where p.character_id = v_character_id
    and p.played_on = v_today;

  select coalesce(w.balance, 0)
  into v_balance
  from public.character_wallets w
  where w.character_id = v_character_id;

  return query
  select
    v_settings.is_open,
    v_settings.play_cost,
    v_settings.daily_play_limit,
    v_used,
    greatest(v_settings.daily_play_limit - v_used, 0),
    coalesce(v_balance, 0),
    v_settings.room_slug;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_notification_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_muted boolean;
  v_rows jsonb;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Authentication required.';
  end if;

  select coalesce(p.muted, false)
  into v_muted
  from public.notification_preferences p
  where p.user_id = v_uid;

  v_muted := coalesce(v_muted, false);

  if v_muted then
    return jsonb_build_object(
      'muted', true,
      'notifications', '[]'::jsonb
    );
  end if;

  select coalesce(
    jsonb_agg(to_jsonb(n)),
    '[]'::jsonb
  )
  into v_rows
  from public.get_my_notifications() n;

  return jsonb_build_object(
    'muted', false,
    'notifications', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_notifications()
 RETURNS TABLE(id uuid, type text, title text, body text, href text, starts_at timestamp with time zone, expires_at timestamp with time zone, expires_game_at timestamp with time zone, source_type text, source_trigger text, is_automatic boolean, created_at timestamp with time zone, is_unread boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_game_now timestamptz;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Authentication required.';
  end if;

  perform public.materialize_due_event_notifications();
  v_game_now := public.current_aureth_game_datetime();

  return query
  select distinct
    n.id,
    n.type,
    n.title,
    n.body,
    n.href,
    n.starts_at,
    n.expires_at,
    n.expires_game_at,
    n.source_type,
    n.source_trigger,
    n.is_automatic,
    n.created_at,
    (r.notification_id is null) as is_unread
  from public.notifications n
  join public.notification_targets t
    on t.notification_id = n.id
  left join public.notification_reads r
    on r.notification_id = n.id
   and r.user_id = v_uid
  where n.is_active = true
    and n.starts_at <= now()
    and (
      n.expires_game_at is null
      or v_game_now is null
      or n.expires_game_at > v_game_now
    )
    and (
      t.target_type = 'global'
      or (
        t.target_type = 'staff'
        and exists (
          select 1
          from public.staff_members sm
          where sm.user_id = v_uid
        )
      )
      or (
        t.target_type = 'user'
        and t.target_id = v_uid
      )
      or (
        t.target_type = 'character'
        and exists (
          select 1
          from public.characters c
          where c.id = t.target_id
            and c.user_id = v_uid
        )
      )
      or (
        t.target_type = 'ancestry'
        and exists (
          select 1
          from public.characters c
          where c.user_id = v_uid
            and c.race_id = t.target_id
        )
      )
      or (
        t.target_type = 'association'
        and exists (
          select 1
          from public.characters c
          where c.user_id = v_uid
            and c.association_id = t.target_id
        )
      )
      or (
        t.target_type = 'order'
        and exists (
          select 1
          from public.characters c
          join public.order_memberships om
            on om.character_id = c.id
          where c.user_id = v_uid
            and om.order_id = t.target_id
        )
      )
    )
    and (
      case
        -- Mutual friend entered/left: read = gone; unread = one-hour expiry.
        when n.source_type = 'friend_presence' then
          r.notification_id is null
          and (
            n.expires_at is null
            or n.expires_at > now()
          )

        -- Private Location invitation: remains while pending, read or unread.
        when n.source_type = 'private_location_invite' then
          exists (
            select 1
            from public.private_location_invitations pli
            where pli.id::text = n.source_id
              and pli.status = 'pending'
          )

        -- Breeze invitation: pending + rental still active/unexpired.
        when n.source_type = 'breeze_lodging_invite' then
          exists (
            select 1
            from public.breeze_lodging_invitations bli
            join public.breeze_lodging_rentals blr
              on blr.id = bli.rental_id
            where bli.id::text = n.source_id
              and bli.status = 'pending'
              and blr.status = 'active'
              and blr.ends_at > now()
          )

        -- Order HQ invitation: remains only while pending.
        when n.source_type = 'order_headquarters_invite' then
          exists (
            select 1
            from public.order_headquarters_invitations ohi
            where ohi.id::text = n.source_id
              and ohi.status = 'pending'
          )

        -- Item Exchange: open and both characters still in the same Location.
        when n.source_type = 'item_trade' then
          exists (
            select 1
            from public.item_trades it
            join public.characters c1
              on c1.id = it.character_one_id
            join public.characters c2
              on c2.id = it.character_two_id
            where it.id::text = n.source_id
              and it.status = 'open'
              and c1.current_room_id is not null
              and c1.current_room_id = c2.current_room_id
          )

        -- Daily reward notices: normal daily-reset expiry; read state irrelevant.
        when n.source_type in ('daily_mission', 'daily_milestone') then
          n.expires_at is null or n.expires_at > now()

        -- Open Poll: follows Poll close/expiry regardless of read state.
        when n.source_type = 'poll'
         and n.source_trigger = 'opened' then
          n.expires_at is null or n.expires_at > now()

        -- Closed Poll: acknowledgement retention.
        when n.source_type = 'poll'
         and n.source_trigger = 'closed' then
          r.notification_id is null
          or r.viewed_at > now() - interval '3 days'

        -- Event notices/reminders: follow event expiry regardless of read state.
        when n.source_type = 'event' then
          n.expires_at is null or n.expires_at > now()

        -- Issued sanction: lifecycle expiry plus 3-day read cap.
        when n.source_type = 'sanction'
         and n.source_trigger = 'issued' then
          (n.expires_at is null or n.expires_at > now())
          and (
            r.notification_id is null
            or r.viewed_at > now() - interval '3 days'
          )

        -- Revoked sanction: acknowledgement retention.
        when n.source_type = 'sanction'
         and n.source_trigger = 'revoked' then
          r.notification_id is null
          or r.viewed_at > now() - interval '3 days'

        -- Ordinary acknowledgement categories.
        when n.source_type in (
          'friend_list',
          'character_application',
          'order_membership',
          'order_submission',
          'trophy',
          'ticket',
          'forum_reply',
          'premium_feature'
        ) then
          r.notification_id is null
          or r.viewed_at > now() - interval '3 days'

        -- Backward compatibility for old premium/reward rows with no source.
        when n.is_automatic = true
         and n.source_type is null
         and n.type = 'reward' then
          r.notification_id is null
          or r.viewed_at > now() - interval '3 days'

        -- Manual staff notifications and unknown future categories.
        else
          (n.expires_at is null or n.expires_at > now())
          and (
            r.notification_id is null
            or r.viewed_at > now() - interval '3 days'
          )
      end
    )
  order by n.starts_at desc, n.created_at desc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_odd_jobs_state()
 RETURNS TABLE(job_id uuid, job_name text, job_description text, pay integer, starting_pay integer, claims_used integer, claims_remaining integer, max_claims integer, sort_order integer, claimed boolean, claimed_job_id uuid, claimed_job_name text, claimed_pay integer, wallet_balance bigint, work_date date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_work_date date := (now() at time zone 'Europe/London')::date;
begin
  if v_user_id is null then
    raise exception 'Authentication required.';
  end if;

  select c.id
  into v_character_id
  from public.characters as c
  where c.user_id = v_user_id
  limit 1;

  if v_character_id is null then
    raise exception 'Character not found.';
  end if;

  perform public._ensure_odd_job_rates(v_work_date);

  return query
  select
    j.id as job_id,
    j.name as job_name,
    j.description as job_description,
    public._odd_job_current_pay(r.starting_pay, r.claims_used) as pay,
    r.starting_pay,
    r.claims_used,
    greatest(r.max_claims - r.claims_used, 0) as claims_remaining,
    r.max_claims,
    j.sort_order,
    (cl.id is not null) as claimed,
    cl.job_id as claimed_job_id,
    cj.name as claimed_job_name,
    cl.pay as claimed_pay,
    w.balance as wallet_balance,
    v_work_date as work_date
  from public.odd_jobs as j
  join public.odd_job_daily_rates as r
    on r.job_id = j.id
   and r.work_date = v_work_date
  join public.character_wallets as w
    on w.character_id = v_character_id
  left join public.odd_job_claims as cl
    on cl.character_id = v_character_id
   and cl.work_date = v_work_date
  left join public.odd_jobs as cj
    on cj.id = cl.job_id
  where j.is_active = true
  order by j.sort_order, j.name;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_warping_runtime()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.characters%rowtype;
  b timestamptz := public.warping_reset_boundary(now());
  used int := 0;
  ss jsonb := '[]';
  ee jsonb := '[]';
  pp jsonb := '[]';
begin
  select *
    into c
  from public.characters
  where user_id = auth.uid()
  limit 1;

  if c.id is null then
    raise exception 'Character not found';
  end if;

  select count(*)
    into used
  from public.shape_casts
  where caster_character_id = c.id
    and resource_type = 'character'
    and status <> 'failed'
    and created_at >= b;

  select coalesce(
    jsonb_agg(to_jsonb(q) order by q.level, q.name),
    '[]'
  )
  into ss
  from (
    select
      s.*,
      bool_or(cs.level_override) level_override,
      bool_or(cs.acquisition_source = 'order') order_granted,
      string_agg(distinct cs.acquisition_source, ',') acquisition_source,
      (
        bool_or(cs.level_override)
        or bool_or(cs.acquisition_source = 'order')
        or s.level <= c.warping_affinity
      ) level_available
    from public.character_shapes cs
    join public.shapes s
      on s.id = cs.shape_id
    where cs.character_id = c.id
      and s.is_active = true
    group by s.id
  ) q;

  select coalesce(
    jsonb_agg(to_jsonb(q) order by q.starts_at desc),
    '[]'
  )
  into ee
  from (
    select
      e.*,
      s.name shape_name,
      s.word_of_power
    from public.character_shape_effects e
    join public.shapes s
      on s.id = e.shape_id
    where e.target_character_id = c.id
      and e.dispelled_at is null
      and (
        e.expires_at is null
        or e.expires_at > now()
      )
  ) q;

  select coalesce(
    jsonb_agg(to_jsonb(q) order by q.expires_at desc),
    '[]'
  )
  into pp
  from (
    select *
    from public.character_price_effects
    where character_id = c.id
      and expires_at > now()
  ) q;

  return jsonb_build_object(
    'character_id', c.id,
    'affinity', c.warping_affinity,
    'warps_per_day', c.warps_per_day,
    'warps_used', used,
    'warps_remaining', greatest(0, c.warps_per_day - used),
    'reset_boundary', b,
    'next_reset', b + interval '1 day',
    'shapes', ss,
    'active_effects', ee,
    'active_prices', pp
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.get_npc_visual_order(p_character_id uuid)
 RETURNS TABLE(id uuid, name text, slug text, icon_url text, colour text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    o.id,
    o.name,
    o.slug,
    o.icon_url,
    o.colour
  from public.npcs n
  join public.orders o
    on o.id = n.order_id
  where n.character_id = p_character_id
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_public_character_inventory(p_character_id uuid)
 RETURNS TABLE(record_kind text, record_id uuid, item_id uuid, parent_container_id uuid, name text, description text, image_url text, category_name text, subcategory_name text, quality text, quantity integer, is_unique boolean, is_quest_item boolean, transfer_policy text, container_capacity integer, is_usable boolean, is_equippable boolean, is_equipped boolean, equipped_slot text, equipped_layer text, hands_required smallint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  allowed boolean;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  select exists (
    select 1
    from public.characters c
    where c.id = p_character_id
      and (
        c.status = 'approved'
        or c.user_id = auth.uid()
        or public.is_staff_user()
      )
  )
  into allowed;

  if not allowed then
    raise exception 'Character inventory is not available.';
  end if;

  return query
  select
    'standard'::text,
    ci.id,
    i.id,
    ci.container_instance_id,
    i.name,
    i.description,
    i.image_url,
    cat.name,
    sub.name,
    i.quality,
    ci.quantity,
    false,
    i.is_quest_item,
    i.transfer_policy,
    i.container_capacity,
    i.is_usable,
    i.is_equippable,
    ce.id is not null,
    ce.slot_key,
    ce.layer_key,
    i.hands_required
  from public.character_items ci
  join public.items i
    on i.id = ci.item_id
  join public.item_categories cat
    on cat.id = i.category_id
  left join public.item_subcategories sub
    on sub.id = i.subcategory_id
  left join public.character_equipment ce
    on ce.character_item_id = ci.id
   and ce.character_id = p_character_id
  where ci.character_id = p_character_id

  union all

  select
    'unique'::text,
    inst.id,
    i.id,
    inst.container_instance_id,
    coalesce(inst.custom_name, i.name),
    coalesce(inst.custom_description, i.description),
    coalesce(inst.custom_image_url, i.image_url),
    cat.name,
    sub.name,
    coalesce(inst.quality_override, i.quality),
    1,
    true,
    coalesce(inst.is_quest_item_override, i.is_quest_item),
    coalesce(inst.transfer_policy_override, i.transfer_policy),
    i.container_capacity,
    i.is_usable,
    i.is_equippable,
    ce.id is not null,
    ce.slot_key,
    ce.layer_key,
    i.hands_required
  from public.character_item_instances inst
  join public.items i
    on i.id = inst.item_id
  join public.item_categories cat
    on cat.id = i.category_id
  left join public.item_subcategories sub
    on sub.id = i.subcategory_id
  left join public.character_equipment ce
    on ce.item_instance_id = inst.id
   and ce.character_id = p_character_id
  where inst.owner_character_id = p_character_id
    and inst.vault_status = 'owned';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_room_message_effect_conditions(p_message_ids uuid[])
 RETURNS TABLE(message_id uuid, conditions jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with selected_messages as (
    select
      m.id,
      case
        when coalesce(m.speaker_type, 'character') = 'npc'
          then n.character_id
        else m.character_id
      end as subject_character_id,
      m.created_at
    from public.room_messages m
    left join public.npcs n
      on n.id = m.npc_id
    where m.id = any(p_message_ids)
  ),
  effect_conditions as (
    select
      m.id as message_id,
      btrim(item_condition.value) as label
    from selected_messages m
    join public.character_active_item_effects e
      on e.character_id = m.subject_character_id
     and e.activated_at <= m.created_at
     and e.expires_at > m.created_at
    cross join lateral
      jsonb_array_elements_text(
        coalesce(to_jsonb(e)->'conditions', '[]'::jsonb)
      ) as item_condition(value)
    where m.subject_character_id is not null
      and btrim(item_condition.value) <> ''

    union

    select
      m.id as message_id,
      btrim(shape_condition.value) as label
    from selected_messages m
    join public.character_shape_effects e
      on coalesce(
           nullif(to_jsonb(e)->>'target_character_id',''),
           nullif(to_jsonb(e)->>'character_id','')
         )::uuid = m.subject_character_id
     and coalesce(
           nullif(to_jsonb(e)->>'starts_at','')::timestamptz,
           nullif(to_jsonb(e)->>'created_at','')::timestamptz,
           nullif(to_jsonb(e)->>'activated_at','')::timestamptz
         ) <= m.created_at
     and (
       nullif(to_jsonb(e)->>'expires_at','') is null
       or nullif(to_jsonb(e)->>'expires_at','')::timestamptz > m.created_at
     )
     and (
       nullif(to_jsonb(e)->>'dispelled_at','') is null
       or nullif(to_jsonb(e)->>'dispelled_at','')::timestamptz > m.created_at
     )
    cross join lateral
      jsonb_array_elements_text(
        coalesce(to_jsonb(e)->'conditions', '[]'::jsonb)
      ) as shape_condition(value)
    where m.subject_character_id is not null
      and btrim(shape_condition.value) <> ''
  )
  select
    m.id as message_id,
    to_jsonb(
      coalesce(
        array_agg(distinct ec.label order by ec.label)
          filter (where ec.label is not null and ec.label <> ''),
        '{}'::text[]
      )
    ) as conditions
  from selected_messages m
  left join effect_conditions ec
    on ec.message_id = m.id
  group by m.id;
$function$
;

CREATE OR REPLACE FUNCTION public.get_targeted_gift_modifiers(p_character_id uuid)
 RETURNS TABLE(muscles bigint, reflexes bigint, vigor bigint, brains bigint, shrewd bigint, presence_score bigint, max_health bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    coalesce(sum(g.muscles_modifier), 0)::bigint,
    coalesce(sum(g.reflexes_modifier), 0)::bigint,
    coalesce(sum(g.vigour_modifier), 0)::bigint,
    coalesce(sum(g.brains_modifier), 0)::bigint,
    coalesce(sum(g.shrewd_modifier), 0)::bigint,
    coalesce(sum(g.presence_modifier), 0)::bigint,
    coalesce(sum(g.max_health_modifier), 0)::bigint
  from public.gift_activations ga
  join public.character_gifts cg
    on cg.id = ga.character_gift_id
  join public.gifts g
    on g.id = cg.gift_id
  where ga.target_character_id = p_character_id
    and cg.character_id <> p_character_id
    and g.is_active = true
    and g.effect_mode = 'temporary'
    and ga.ended_at is null
    and ga.activated_at <= now()
    and ga.expires_at > now();
$function$
;

CREATE OR REPLACE FUNCTION public.get_unread_direct_message_count()
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select count(*)::bigint
  from public.characters c
  join public.direct_conversation_participants p
    on p.character_id = c.id
  join public.direct_messages m
    on m.conversation_id = p.conversation_id
  where c.user_id = auth.uid()
    and p.archived_at is null
    and p.deleted_at is null
    and m.sender_character_id <> c.id
    and (
      p.last_read_at is null
      or m.created_at > p.last_read_at
    );
$function$
;

CREATE OR REPLACE FUNCTION public.get_unread_forum_topic_count()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with current_user_character as (
    select
      c.id,
      c.association_id
    from public.characters c
    where
      c.user_id = auth.uid()
      and c.status = 'approved'
    limit 1
  ),

  current_user_staff as (
    select exists (
      select 1
      from public.staff_members sm
      where sm.user_id = auth.uid()
    ) as is_staff
  ),

  visible_sections as (
    select fs.id
    from public.forum_sections fs
    cross join current_user_staff cus
    left join current_user_character cuc
      on true
    where
      fs.is_active = true
      and (
        /* Public sections */
        fs.visibility = 'public'

        /* Staff-only sections */
        or (
          fs.visibility = 'staff'
          and cus.is_staff = true
        )

        /* Association/member sections */
        or (
          fs.visibility = 'members'
          and cuc.id is not null
          and (
            fs.association_id is null
            or fs.association_id = cuc.association_id
          )
        )

        /*
         * Association-linked sections are never
         * visible to a character from another
         * association, even if configured oddly.
         */
        or (
          fs.association_id is not null
          and cuc.association_id = fs.association_id
        )
      )
  )

  select count(*)::bigint
  from public.forum_topics ft
  join visible_sections vs
    on vs.id = ft.section_id

  left join public.forum_topic_reads ftr
    on
      ftr.topic_id = ft.id
      and ftr.user_id = auth.uid()

  where
    ft.deleted_at is null

    and (
      ftr.last_read_at is null

      or ft.last_post_at >
        ftr.last_read_at
    );
$function$
;

