CREATE OR REPLACE FUNCTION public.give_npc_inventory_record_as_staff(p_source_character_id uuid, p_record_kind text, p_record_id uuid, p_target_character_id uuid, p_quantity integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source_room uuid;
  v_target_room uuid;
  v_item_id uuid;
  v_have integer;
  v_policy text;
  v_quest boolean;
  v_instance public.character_item_instances%rowtype;
  v_action_id uuid;
  v_item_name text;
  v_giver_name text;
  v_target_name text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not public.is_staff_user() then
    raise exception 'Staff access required.';
  end if;

  if p_quantity is null or p_quantity < 1 then
    raise exception 'Invalid transfer quantity.';
  end if;

  if not exists (
    select 1
    from public.characters c
    join public.npcs n on n.character_id = c.id
    where c.id = p_source_character_id
      and c.is_system = true
      and c.status = 'approved'
      and n.is_active = true
      and n.is_location_active = true
  ) then
    raise exception 'Active NPC Character not found.';
  end if;

  if not exists (
    select 1
    from public.characters c
    where c.id = p_target_character_id
      and c.status = 'approved'
      and c.is_system = false
  ) then
    raise exception 'Choose an ordinary Character.';
  end if;

  if p_target_character_id = p_source_character_id then
    raise exception 'You cannot give an Item to yourself.';
  end if;

  select current_room_id,
         coalesce(nullif(display_name,''), btrim(coalesce(first_name,'')||' '||coalesce(surname,'')), id::text)
  into v_source_room, v_giver_name
  from public.characters
  where id = p_source_character_id;

  select current_room_id,
         coalesce(nullif(display_name,''), btrim(coalesce(first_name,'')||' '||coalesce(surname,'')), id::text)
  into v_target_room, v_target_name
  from public.characters
  where id = p_target_character_id;

  if v_source_room is null
     or v_target_room is distinct from v_source_room then
    raise exception 'Both characters must be in the same Location.';
  end if;

  if public.item_record_is_equipped(
       p_record_kind,
       p_record_id,
       p_source_character_id
     ) then
    raise exception 'Unequip this Item first.';
  end if;

  if p_record_kind = 'standard' then
    select ci.item_id, ci.quantity, i.transfer_policy, i.is_quest_item
    into v_item_id, v_have, v_policy, v_quest
    from public.character_items ci
    join public.items i on i.id = ci.item_id
    where ci.id = p_record_id
      and ci.character_id = p_source_character_id
      and ci.container_instance_id is null
    for update of ci;

    if not found then
      raise exception 'Item not found in Loose Inventory.';
    end if;

    if v_policy <> 'free' or v_quest then
      raise exception 'This Item cannot be transferred.';
    end if;

    if p_quantity > v_have then
      raise exception 'Not enough quantity.';
    end if;

    select name into v_item_name
    from public.items
    where id = v_item_id;

    v_action_id :=
      public.character_audit_begin_action(
        'item_gift',
        'gift'
      );

    if p_quantity = v_have then
      update public.character_items
      set character_id = p_target_character_id,
          acquisition_source = 'gift',
          assigned_by = null,
          updated_at = now()
      where id = p_record_id;
    else
      update public.character_items
      set quantity = quantity - p_quantity,
          updated_at = now()
      where id = p_record_id;

      insert into public.character_items(
        character_id,
        item_id,
        quantity,
        acquisition_source,
        acquired_at
      )
      values(
        p_target_character_id,
        v_item_id,
        p_quantity,
        'gift',
        now()
      );
    end if;

  elsif p_record_kind = 'unique' then
    if p_quantity <> 1 then
      raise exception 'Unique Items have quantity 1.';
    end if;

    select *
    into v_instance
    from public.character_item_instances
    where id = p_record_id
      and owner_character_id = p_source_character_id
      and container_instance_id is null
      and vault_status = 'owned'
    for update;

    if not found then
      raise exception 'Unique Item not found in Loose Inventory.';
    end if;

    select
      coalesce(v_instance.transfer_policy_override, i.transfer_policy),
      coalesce(v_instance.is_quest_item_override, i.is_quest_item)
    into v_policy, v_quest
    from public.items i
    where i.id = v_instance.item_id;

    if v_policy <> 'free' or v_quest then
      raise exception 'This Item cannot be transferred.';
    end if;

    v_item_id := v_instance.item_id;

    select name into v_item_name
    from public.items
    where id = v_item_id;

    v_action_id :=
      public.character_audit_begin_action(
        'item_gift',
        'gift'
      );

    update public.character_item_instances
    set owner_character_id = p_target_character_id,
        acquisition_source = 'gift',
        acquired_at = now(),
        updated_at = now()
    where id = p_record_id;

    insert into public.item_instance_history(
      item_instance_id,
      event_type,
      from_character_id,
      to_character_id,
      actor_user_id,
      details
    )
    values(
      p_record_id,
      'gift',
      p_source_character_id,
      p_target_character_id,
      auth.uid(),
      'Given directly by staff-controlled NPC.'
    );

  else
    raise exception 'Invalid Item type.';
  end if;

  perform public.character_audit_write_event(
    p_source_character_id,
    'item_given',
    'gift',
    v_action_id,
    jsonb_build_object(
      'item_id', v_item_id,
      'item_name', v_item_name,
      'quantity', p_quantity,
      'other_character_id', p_target_character_id,
      'other_character_name', v_target_name,
      'direction', 'given'
    ),
    'item_gift',
    v_action_id::text
  );

  perform public.character_audit_write_event(
    p_target_character_id,
    'item_received',
    'gift',
    v_action_id,
    jsonb_build_object(
      'item_id', v_item_id,
      'item_name', v_item_name,
      'quantity', p_quantity,
      'other_character_id', p_source_character_id,
      'other_character_name', v_giver_name,
      'direction', 'received'
    ),
    'item_gift',
    v_action_id::text
  );

  perform public._normalize_character_inventory_stacks(
    p_source_character_id
  );
  perform public._normalize_character_inventory_stacks(
    p_target_character_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.give_own_inventory_record(k text, r uuid, target uuid, q integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 me uuid:=public.my_character_id();
 room uuid;
 targetroom uuid;
 iid uuid;
 have int;
 pol text;
 quest bool;
 inst public.character_item_instances%rowtype;
 v_action_id uuid;
 v_item_name text;
 v_giver_name text;
 v_target_name text;
begin
 if me is null or q<1 then raise exception 'Invalid transfer.'; end if;
 if target=me then raise exception 'You cannot give an Item to yourself.'; end if;
 select current_room_id into room from characters where id=me;
 select current_room_id into targetroom from characters where id=target and status='approved';
 if room is null or targetroom is distinct from room then raise exception 'Both characters must be in the same Location.'; end if;
 if public.item_record_is_equipped(k,r,me) then raise exception 'Unequip this Item first.'; end if;
 select coalesce(nullif(display_name,''), btrim(coalesce(first_name,'')||' '||coalesce(surname,'')), id::text)
   into v_giver_name from characters where id=me;
 select coalesce(nullif(display_name,''), btrim(coalesce(first_name,'')||' '||coalesce(surname,'')), id::text)
   into v_target_name from characters where id=target;
 if k='standard' then
  select ci.item_id,ci.quantity,i.transfer_policy,i.is_quest_item into iid,have,pol,quest
  from character_items ci join items i on i.id=ci.item_id
  where ci.id=r and ci.character_id=me and ci.container_instance_id is null for update of ci;
  if not found then raise exception 'Item not found in Loose Inventory.'; end if;
  if pol<>'free' or quest then raise exception 'This Item cannot be transferred.'; end if;
  if q>have then raise exception 'Not enough quantity.'; end if;
  select name into v_item_name from items where id=iid;
  v_action_id := public.character_audit_begin_action('item_gift','gift');
  if q=have then update character_items set character_id=target,acquisition_source='gift',assigned_by=null,updated_at=now() where id=r;
  else
   update character_items set quantity=quantity-q,updated_at=now() where id=r;
   insert into character_items(character_id,item_id,quantity,acquisition_source,acquired_at) values(target,iid,q,'gift',now());
  end if;
 elsif k='unique' then
  if q<>1 then raise exception 'Unique Items have quantity 1.'; end if;
  select * into inst from character_item_instances where id=r and owner_character_id=me and container_instance_id is null and vault_status='owned' for update;
  if not found then raise exception 'Unique Item not found in Loose Inventory.'; end if;
  select coalesce(inst.transfer_policy_override,i.transfer_policy),coalesce(inst.is_quest_item_override,i.is_quest_item) into pol,quest from items i where i.id=inst.item_id;
  if pol<>'free' or quest then raise exception 'This Item cannot be transferred.'; end if;
  iid := inst.item_id;
  select name into v_item_name from items where id=iid;
  v_action_id := public.character_audit_begin_action('item_gift','gift');
  update character_item_instances set owner_character_id=target,acquisition_source='gift',acquired_at=now(),updated_at=now() where id=r;
  insert into item_instance_history(item_instance_id,event_type,from_character_id,to_character_id,actor_user_id,details)
  values(r,'gift',me,target,auth.uid(),'Given directly by owner.');
 else raise exception 'Invalid Item type.'; end if;

 perform public.character_audit_write_event(
   me,
   'item_given',
   'gift',
   v_action_id,
   jsonb_build_object(
     'item_id', iid,
     'item_name', v_item_name,
     'quantity', q,
     'other_character_id', target,
     'other_character_name', v_target_name,
     'direction', 'given'
   ),
   'item_gift',
   v_action_id::text
 );

 perform public.character_audit_write_event(
   target,
   'item_received',
   'gift',
   v_action_id,
   jsonb_build_object(
     'item_id', iid,
     'item_name', v_item_name,
     'quantity', q,
     'other_character_id', me,
     'other_character_name', v_giver_name,
     'direction', 'received'
   ),
   'item_gift',
   v_action_id::text
 );
end $function$
;

CREATE OR REPLACE FUNCTION public.give_own_inventory_record_normalized(k text, r uuid, target uuid, q integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := public.my_character_id();
begin
  if me is null then
    raise exception 'Unable to identify your character.';
  end if;

  perform public.give_own_inventory_record(k, r, target, q);
  perform public._normalize_character_inventory_stacks(me);
  perform public._normalize_character_inventory_stacks(target);
end
$function$
;

CREATE OR REPLACE FUNCTION public.give_remnants_same_location(p_target_character_id uuid, p_amount bigint)
 RETURNS TABLE(sender_balance bigint, recipient_balance bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sender_id uuid;
  v_sender_name text;
  v_sender_room_id uuid;
  v_target_name text;
  v_target_room_id uuid;
  v_sender_balance bigint;
  v_recipient_balance bigint;
begin
  if auth.uid() is null then raise exception 'You must be signed in.'; end if;
  if p_target_character_id is null then raise exception 'Choose a character.'; end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'Enter a positive whole Remnant amount.';
  end if;

  select c.id, c.display_name, c.current_room_id
  into v_sender_id, v_sender_name, v_sender_room_id
  from public.characters c
  where c.user_id = auth.uid()
    and c.status = 'approved'
  limit 1;

  if v_sender_id is null then
    raise exception 'Unable to identify your approved character.';
  end if;

  if p_target_character_id = v_sender_id then
    raise exception 'You cannot give Remnants to yourself.';
  end if;

  select c.display_name, c.current_room_id
  into v_target_name, v_target_room_id
  from public.characters c
  where c.id = p_target_character_id
    and c.status = 'approved';

  if v_target_name is null then
    raise exception 'The selected character could not be found.';
  end if;

  if v_sender_room_id is null
     or v_target_room_id is null
     or v_sender_room_id <> v_target_room_id then
    raise exception 'You can only give Remnants to a character in the same location.';
  end if;

  insert into public.character_wallets(character_id, balance)
  values(v_sender_id, 0), (p_target_character_id, 0)
  on conflict(character_id) do nothing;

  perform 1
  from public.character_wallets w
  where w.character_id in (v_sender_id, p_target_character_id)
  order by w.character_id
  for update;

  select w.balance into v_sender_balance
  from public.character_wallets w
  where w.character_id = v_sender_id;

  if coalesce(v_sender_balance, 0) < p_amount then
    raise exception 'You do not have enough Remnants.';
  end if;

  update public.character_wallets
  set balance = balance - p_amount
  where character_id = v_sender_id
  returning balance into v_sender_balance;

  update public.character_wallets
  set balance = balance + p_amount
  where character_id = p_target_character_id
  returning balance into v_recipient_balance;

  insert into public.remnant_ledger(
    character_id, amount, balance_after, transaction_type,
    source_type, source_id, reason, actor_user_id
  )
  values
    (
      v_sender_id,
      -p_amount,
      v_sender_balance,
      'transfer_out',
      'character_transfer',
      p_target_character_id::text,
      'Given to ' || v_target_name,
      auth.uid()
    ),
    (
      p_target_character_id,
      p_amount,
      v_recipient_balance,
      'transfer_in',
      'character_transfer',
      v_sender_id::text,
      'Received from ' || coalesce(v_sender_name, 'another character'),
      auth.uid()
    );

  return query
  select v_sender_balance, v_recipient_balance;
end
$function$
;

CREATE OR REPLACE FUNCTION public.grant_first_50_pioneer_rewards()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_position smallint;

  v_lantern_id uuid;
  v_tarot_id uuid;

  v_portrait_frame_id uuid;
  v_name_frame_id uuid;
  v_crest_id uuid;

  v_music_id uuid;
  v_skin_id uuid;
  v_trophy_id uuid;

  v_reward_note constant text :=
    'Automatic First 50 Pioneer reward';
begin
  -- Trigger WHEN clause already enforces the status transition,
  -- but keep defensive guards inside the function as well.
  if new.status <> 'approved'
     or old.status is not distinct from new.status
  then
    return new;
  end if;

  -- NPC/system Characters never qualify.
  if coalesce(new.is_system, false) = true then
    return new;
  end if;

  -- Pioneer rewards belong to an actual player account.
  if new.user_id is null then
    return new;
  end if;

  -- A previous claim can never claim again.
  if exists (
    select 1
    from public.pioneer_reward_claims prc
    where prc.character_id = new.id
  ) then
    return new;
  end if;

  /*
   * Do not reward a re-approval.
   *
   * The admin action records status history after the Character UPDATE.
   * Therefore on a genuine first approval there is no historical row
   * involving an earlier approved state yet.
   *
   * Checking both old_status and new_status also protects older
   * Characters whose original approval predates complete history but
   * who were subsequently moved away from approved.
   */
  if exists (
    select 1
    from public.character_status_history csh
    where csh.character_id = new.id
      and (
        csh.old_status = 'approved'
        or csh.new_status = 'approved'
      )
  ) then
    return new;
  end if;

  /*
   * Serialize the "who gets position 1..50?" decision.
   * This prevents two simultaneous approvals from both claiming
   * the same final slot.
   */
  perform pg_catalog.pg_advisory_xact_lock(53150, 50);

  -- Re-check after acquiring the lock.
  if exists (
    select 1
    from public.pioneer_reward_claims prc
    where prc.character_id = new.id
  ) then
    return new;
  end if;

  select
    (coalesce(max(prc.position), 0) + 1)::smallint
  into v_position
  from public.pioneer_reward_claims prc;

  if v_position > 50 then
    return new;
  end if;


  -- ----------------------------------------------------------
  -- Resolve every reward through stable unique catalogue keys.
  -- Do not hardcode generated UUIDs.
  -- ----------------------------------------------------------

  select i.id
  into v_lantern_id
  from public.items i
  where i.slug = 'the-first-lantern-item'
    and i.is_active = true;

  if v_lantern_id is null then
    raise exception
      'Pioneer reward setup error: The First Lantern is missing or inactive.';
  end if;


  select i.id
  into v_tarot_id
  from public.items i
  where i.slug = 'tarot-of-the-first'
    and i.is_active = true;

  if v_tarot_id is null then
    raise exception
      'Pioneer reward setup error: Tarot of the First is missing or inactive.';
  end if;


  select c.id
  into v_portrait_frame_id
  from public.cosmetic_items c
  where c.slug = 'pioneer-portrait-frame'
    and c.is_active = true;

  if v_portrait_frame_id is null then
    raise exception
      'Pioneer reward setup error: Pioneer Portrait Frame is missing or inactive.';
  end if;


  -- These are the catalogue's CURRENT unique slugs.
  -- "pionner" is intentionally preserved because that is how the
  -- records currently exist in Supabase.
  select c.id
  into v_name_frame_id
  from public.cosmetic_items c
  where c.slug = 'pionner-name-frame'
    and c.is_active = true;

  if v_name_frame_id is null then
    raise exception
      'Pioneer reward setup error: Pioneer Name Frame is missing or inactive.';
  end if;


  select c.id
  into v_crest_id
  from public.cosmetic_items c
  where c.slug = 'pionner-crest'
    and c.is_active = true;

  if v_crest_id is null then
    raise exception
      'Pioneer reward setup error: Pioneer Crest is missing or inactive.';
  end if;


  select m.id
  into v_music_id
  from public.music_tracks m
  where m.track_key = 'exclusivepioneer'
    and m.is_active = true;

  if v_music_id is null then
    raise exception
      'Pioneer reward setup error: Pioneer of Sepulchria music is missing or inactive.';
  end if;


  select s.id
  into v_skin_id
  from public.portal_skins s
  where s.slug = 'pioneers-land';

  if v_skin_id is null then
    raise exception
      'Pioneer reward setup error: Pioneers'' Land skin is missing.';
  end if;


  select t.id
  into v_trophy_id
  from public.trophy_definitions t
  where t.trophy_key = 'first_fifty_50'
    and t.is_active = true;

  if v_trophy_id is null then
    raise exception
      'Pioneer reward setup error: Pioneer of Sepulchria Trophy is missing or inactive.';
  end if;


  -- ----------------------------------------------------------
  -- Claim the numbered slot.
  -- If anything below fails, the whole approval transaction,
  -- including this claim, rolls back.
  -- ----------------------------------------------------------

  insert into public.pioneer_reward_claims (
    character_id,
    user_id,
    position,
    claimed_at
  )
  values (
    new.id,
    new.user_id,
    v_position,
    now()
  );


  -- ----------------------------------------------------------
  -- 1) The First Lantern
  -- 2) Tarot of the First
  --
  -- The campaign-specific note makes these inserts idempotent
  -- without preventing a player who already owned another copy
  -- from receiving the actual Pioneer reward copy.
  -- ----------------------------------------------------------

  insert into public.character_items (
    character_id,
    item_id,
    quantity,
    acquisition_source,
    acquired_at,
    assigned_by,
    notes
  )
  select
    new.id,
    v_lantern_id,
    1,
    'reward',
    now(),
    null,
    v_reward_note
  where not exists (
    select 1
    from public.character_items ci
    where ci.character_id = new.id
      and ci.item_id = v_lantern_id
      and ci.acquisition_source = 'reward'
      and ci.notes = v_reward_note
  );


  insert into public.character_items (
    character_id,
    item_id,
    quantity,
    acquisition_source,
    acquired_at,
    assigned_by,
    notes
  )
  select
    new.id,
    v_tarot_id,
    1,
    'reward',
    now(),
    null,
    v_reward_note
  where not exists (
    select 1
    from public.character_items ci
    where ci.character_id = new.id
      and ci.item_id = v_tarot_id
      and ci.acquisition_source = 'reward'
      and ci.notes = v_reward_note
  );


  -- ----------------------------------------------------------
  -- 3) Title
  --
  -- BEFORE UPDATE trigger: changing NEW directly means we do not
  -- need a second UPDATE of the Character row.
  -- ----------------------------------------------------------

  new.title := 'Pioneer of Sepulchria';


  -- ----------------------------------------------------------
  -- 4-6) Cosmetics
  -- Existing ownership is preserved, but disabled ownership is
  -- re-enabled.
  -- ----------------------------------------------------------

  insert into public.character_cosmetic_entitlements (
    character_id,
    cosmetic_item_id,
    enabled,
    source,
    note,
    granted_at,
    granted_by,
    created_at,
    updated_at
  )
  values
    (
      new.id,
      v_portrait_frame_id,
      true,
      'reward',
      v_reward_note,
      now(),
      null,
      now(),
      now()
    ),
    (
      new.id,
      v_name_frame_id,
      true,
      'reward',
      v_reward_note,
      now(),
      null,
      now(),
      now()
    ),
    (
      new.id,
      v_crest_id,
      true,
      'reward',
      v_reward_note,
      now(),
      null,
      now(),
      now()
    )
  on conflict (character_id, cosmetic_item_id)
  do update
  set
    enabled = true,
    updated_at = now();


  -- ----------------------------------------------------------
  -- 7) Music
  -- ----------------------------------------------------------

  insert into public.character_music_entitlements (
    character_id,
    music_track_id,
    enabled,
    source,
    note,
    granted_at,
    updated_at
  )
  values (
    new.id,
    v_music_id,
    true,
    'reward',
    v_reward_note,
    now(),
    now()
  )
  on conflict (character_id, music_track_id)
  do update
  set
    enabled = true,
    updated_at = now();


  -- ----------------------------------------------------------
  -- 8) Pioneers' Land skin
  --
  -- The existing schema permits skin sources 'paid' or 'staff'.
  -- Keep that contract unchanged and explain the automatic reward
  -- in the note.
  -- ----------------------------------------------------------

  insert into public.user_portal_skin_entitlements (
    user_id,
    skin_id,
    enabled,
    source,
    note,
    granted_by,
    granted_at,
    updated_at
  )
  values (
    new.user_id,
    v_skin_id,
    true,
    'staff',
    v_reward_note,
    null,
    now(),
    now()
  )
  on conflict (user_id, skin_id)
  do update
  set
    enabled = true,
    updated_at = now();


  -- ----------------------------------------------------------
  -- Individual reward notifications.
  --
  -- Each source_trigger is unique, so create_automatic_notification
  -- remains idempotent. These intentionally mirror the normal
  -- destination pages used by the portal.
  -- ----------------------------------------------------------

  perform public.create_automatic_notification(
    'system',
    'Item received: The First Lantern',
    'The First Lantern has been added to your Inventory as part of your Pioneer rewards.',
    '/character?tab=inventory',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'item_first_lantern',
    now() + interval '30 days'
  );

  perform public.create_automatic_notification(
    'system',
    'Item received: Tarot of the First',
    'Tarot of the First has been added to your Inventory as part of your Pioneer rewards.',
    '/character?tab=inventory',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'item_tarot_of_the_first',
    now() + interval '30 days'
  );

  perform public.create_automatic_notification(
    'system',
    'Title granted: Pioneer of Sepulchria',
    'Your Character has been granted the title Pioneer of Sepulchria.',
    '/character',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'title_pioneer_of_sepulchria',
    now() + interval '30 days'
  );

  perform public.create_automatic_notification(
    'system',
    'Premium cosmetic unlocked: Pioneer Portrait Frame',
    'You have unlocked Pioneer Portrait Frame (Portrait Frame). Equip it from your Cosmetics collection.',
    '/cosmetics',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'cosmetic_pioneer_portrait_frame',
    now() + interval '30 days'
  );

  perform public.create_automatic_notification(
    'system',
    'Premium cosmetic unlocked: Pioneer Name Frame',
    'You have unlocked Pioneer Name Frame (Nameplate). Equip it from your Cosmetics collection.',
    '/cosmetics',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'cosmetic_pioneer_name_frame',
    now() + interval '30 days'
  );

  perform public.create_automatic_notification(
    'system',
    'Premium cosmetic unlocked: Pioneer Crest',
    'You have unlocked Pioneer Crest (Profile Crest). Equip it from your Cosmetics collection.',
    '/cosmetics',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'cosmetic_pioneer_crest',
    now() + interval '30 days'
  );

  perform public.create_automatic_notification(
    'system',
    'Premium feature unlocked: Pioneer of Sepulchria',
    'You have unlocked the music track Pioneer of Sepulchria. You can select it from the music controls while in a location.',
    '/cosmetics',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'music_pioneer_of_sepulchria',
    now() + interval '30 days'
  );

  perform public.create_automatic_notification(
    'system',
    'Premium feature unlocked: Pioneers'' Land',
    'You have unlocked the Pioneers'' Land portal skin. You can select it from Appearance.',
    '/appearance',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'skin_pioneers_land',
    now() + interval '30 days'
  );


  -- ----------------------------------------------------------
  -- 9) Trophy
  --
  -- Your existing notify_trophy_award_trigger will create the
  -- normal "Trophy Earned" notification when this INSERT is new.
  -- ----------------------------------------------------------

  insert into public.character_trophies (
    character_id,
    trophy_id,
    progress_value,
    earned_at
  )
  values (
    new.id,
    v_trophy_id,
    1,
    now()
  )
  on conflict (character_id, trophy_id)
  do nothing;


  -- ----------------------------------------------------------
  -- 10) Special Pioneer notification.
  --
  -- PIONEER20 is now public, active, 20%, and currently permits
  -- up to five redemptions per user. Nothing is inserted into
  -- store_user_discount_codes.
  --
  -- Clicking the notification opens the Store.
  -- ----------------------------------------------------------

  perform public.create_automatic_notification(
    'system',
    'You are a Pioneer of Sepulchria',
    'Your Character is among the first 50 Pioneers of Sepulchria. Your exclusive Pioneer rewards have been added to your Character and account. You have also received the Store discount code PIONEER20, granting 20% off up to five purchases. Select this notification to visit the Sepulchria Store.',
    '/store',
    'character',
    new.id,
    'pioneer_reward',
    new.id::text,
    'granted',
    now() + interval '365 days'
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.gtrgm_compress(internal)
 RETURNS internal
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
AS '$libdir/pg_trgm', $function$gtrgm_compress$function$
;

CREATE OR REPLACE FUNCTION public.gtrgm_consistent(internal, text, smallint, oid, internal)
 RETURNS boolean
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
