CREATE OR REPLACE FUNCTION public.handle_character_health_life_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.current_health = 0 and coalesce(old.current_health, 1) > 0 then
    update public.characters
    set life_state = 'death_save_pending',
        zero_hp_at = now(),
        dead_until = null
    where id = new.id;

    insert into public.character_death_events(character_id, triggered_at, status)
    values (new.id, now(), 'pending')
    on conflict do nothing;

  elsif new.current_health > 0 and coalesce(old.current_health, 0) = 0 then
    update public.characters
    set life_state = 'alive',
        zero_hp_at = null,
        dead_until = null
    where id = new.id;

    update public.character_death_events
    set status = 'rescued',
        resolved_at = coalesce(resolved_at, now())
    where character_id = new.id
      and status = 'pending';
  end if;

  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.house_of_chances_grant_item(p_character_id uuid, p_item_id uuid, p_quantity integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item record;
  v_category_slug text;
  v_remaining integer;
  v_stack record;
  v_add integer;
  v_stack_size integer;
  v_action_id uuid;
begin
  if p_quantity is null or p_quantity < 1 or p_quantity > 9999 then
    raise exception 'Invalid House of Chances Item reward quantity.';
  end if;

  select
    i.id,
    i.name,
    i.stackable,
    i.max_stack,
    i.use_behaviour,
    i.max_charges,
    c.slug as category_slug
  into v_item
  from public.items i
  left join public.item_categories c
    on c.id = i.category_id
  where i.id = p_item_id;

  if not found then
    raise exception 'House of Chances reward Item no longer exists.';
  end if;

  v_action_id := public.character_audit_begin_action('house_of_chances','house_of_chances');

  v_category_slug := v_item.category_slug;

  -- Containers and limited-charge Items use proper instances.
  if v_category_slug = 'container'
     or v_item.use_behaviour = 'limited_charges'
  then
    for v_remaining in 1..p_quantity loop
      insert into public.character_item_instances (
        item_id,
        owner_character_id,
        charges_remaining,
        vault_status,
        acquisition_source
      )
      values (
        p_item_id,
        p_character_id,
        case
          when v_item.use_behaviour = 'limited_charges'
            then v_item.max_charges
          else null
        end,
        'owned',
        'house_of_chances'
      );
    end loop;

    perform public.character_audit_write_event(
      p_character_id,'house_of_chances','house_of_chances',v_action_id,
      jsonb_build_object('item_id',p_item_id,'item_name',v_item.name,'quantity',p_quantity),
      'house_of_chances',p_item_id::text
    );

    return;
  end if;

  -- Ordinary non-stackable Items follow the existing standard
  -- inventory representation: one row per awarded copy.
  if coalesce(v_item.stackable, false) = false then
    for v_remaining in 1..p_quantity loop
      insert into public.character_items (
        character_id,
        item_id,
        quantity,
        acquisition_source
      )
      values (
        p_character_id,
        p_item_id,
        1,
        'house_of_chances'
      );
    end loop;

    perform public.character_audit_write_event(
      p_character_id,'house_of_chances','house_of_chances',v_action_id,
      jsonb_build_object('item_id',p_item_id,'item_name',v_item.name,'quantity',p_quantity),
      'house_of_chances',p_item_id::text
    );

    return;
  end if;

  -- Stackable Items: fill existing root-level stacks first.
  v_remaining := p_quantity;

  for v_stack in
    select ci.id, ci.quantity
    from public.character_items ci
    where ci.character_id = p_character_id
      and ci.item_id = p_item_id
      and ci.container_instance_id is null
    order by ci.acquired_at asc
    for update
  loop
    exit when v_remaining <= 0;

    if v_item.max_stack is null then
      update public.character_items
      set quantity = v_stack.quantity + v_remaining
      where id = v_stack.id;

      v_remaining := 0;
      exit;
    end if;

    v_add := least(
      greatest(v_item.max_stack - v_stack.quantity, 0),
      v_remaining
    );

    if v_add > 0 then
      update public.character_items
      set quantity = v_stack.quantity + v_add
      where id = v_stack.id;

      v_remaining := v_remaining - v_add;
    end if;
  end loop;

  while v_remaining > 0 loop
    v_stack_size :=
      case
        when v_item.max_stack is null then v_remaining
        else least(v_item.max_stack, v_remaining)
      end;

    insert into public.character_items (
      character_id,
      item_id,
      quantity,
      acquisition_source
    )
    values (
      p_character_id,
      p_item_id,
      v_stack_size,
      'house_of_chances'
    );

    v_remaining := v_remaining - v_stack_size;
  end loop;

  perform public.character_audit_write_event(
    p_character_id,'house_of_chances','house_of_chances',v_action_id,
    jsonb_build_object('item_id',p_item_id,'item_name',v_item.name,'quantity',p_quantity),
    'house_of_chances',p_item_id::text
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.house_of_chances_rule_matches(p_match_type text, p_roll_1 integer, p_roll_2 integer, p_roll_3 integer, p_roll_1_min integer, p_roll_1_max integer, p_roll_2_min integer, p_roll_2_max integer, p_roll_3_min integer, p_roll_3_max integer, p_total_min integer, p_total_max integer)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_total integer := p_roll_1 + p_roll_2 + p_roll_3;
begin
  case p_match_type
    when 'exact' then
      return p_roll_1_min is not null
        and p_roll_2_min is not null
        and p_roll_3_min is not null
        and p_roll_1 = p_roll_1_min
        and p_roll_2 = p_roll_2_min
        and p_roll_3 = p_roll_3_min;

    when 'all_equal' then
      return p_roll_1 = p_roll_2
        and p_roll_2 = p_roll_3
        and (p_roll_1_min is null or p_roll_1 >= p_roll_1_min)
        and (p_roll_1_max is null or p_roll_1 <= p_roll_1_max);

    when 'all_in_range' then
      return p_roll_1_min is not null
        and p_roll_1_max is not null
        and p_roll_1 between p_roll_1_min and p_roll_1_max
        and p_roll_2 between p_roll_1_min and p_roll_1_max
        and p_roll_3 between p_roll_1_min and p_roll_1_max;

    when 'total_range' then
      return p_total_min is not null
        and p_total_max is not null
        and v_total between p_total_min and p_total_max;

    when 'ordered_ranges' then
      return p_roll_1_min is not null
        and p_roll_1_max is not null
        and p_roll_2_min is not null
        and p_roll_2_max is not null
        and p_roll_3_min is not null
        and p_roll_3_max is not null
        and p_roll_1 between p_roll_1_min and p_roll_1_max
        and p_roll_2 between p_roll_2_min and p_roll_2_max
        and p_roll_3 between p_roll_3_min and p_roll_3_max;

    else
      return false;
  end case;
end;
$function$
;

