CREATE OR REPLACE FUNCTION public.issue_store_post_purchase_offers(p_order_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.store_orders%rowtype;
  v_offer public.store_post_purchase_offers%rowtype;
  v_template public.store_discount_codes%rowtype;
  v_code text;
  v_expires timestamptz;
  v_issued integer := 0;
begin
  select * into v_order from public.store_orders where id=p_order_id;
  if not found or v_order.status <> 'fulfilled' then return 0; end if;

  for v_offer in
    select o.* from public.store_post_purchase_offers o
    where o.is_active=true
      and (o.starts_at is null or o.starts_at<=now())
      and (o.ends_at is null or o.ends_at>now())
      and exists (
        select 1 from public.store_order_items oi
        where oi.order_id=p_order_id
          and ((o.trigger_product_id is not null and oi.product_id=o.trigger_product_id)
            or (o.trigger_category is not null and oi.category_snapshot=o.trigger_category))
      )
  loop
    if exists (select 1 from public.store_user_discount_codes where post_purchase_offer_id=v_offer.id and source_order_id=p_order_id) then
      continue;
    end if;

    select * into v_template from public.store_discount_codes where id=v_offer.discount_code_template_id and is_active=true;
    if not found then continue; end if;
    if v_template.ends_at is not null and v_template.ends_at<=now() then continue; end if;

    v_expires := now() + make_interval(days=>v_offer.valid_for_days);
    if v_template.ends_at is not null then v_expires := least(v_expires,v_template.ends_at); end if;

    loop
      v_code := 'OFFER-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
      exit when not exists (select 1 from public.store_user_discount_codes where code=v_code);
    end loop;

    insert into public.store_user_discount_codes(user_id,discount_code_id,post_purchase_offer_id,source_order_id,code,expires_at)
    values(v_order.user_id,v_template.id,v_offer.id,p_order_id,v_code,v_expires);
    v_issued := v_issued + 1;
  end loop;
  return v_issued;
end;
$function$
;

