CREATE OR REPLACE FUNCTION public.learn_recipe_from_item(p_character_id uuid, p_record_kind text, p_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_item_id uuid;
    v_quantity integer;
    v_item_name text;
    v_recipe_id uuid;
    v_recipe_name text;
    v_item_active boolean;
    v_item_usable boolean;
    v_use_behaviour text;
    v_action_id uuid;
begin
    -- Only the logged-in owner may learn for this character.
    if not exists (
        select 1
        from public.characters c
        where c.id = p_character_id
          and c.user_id = auth.uid()
    ) then
        raise exception 'You cannot use items for this character.';
    end if;

    -- Lock and resolve the actual owned inventory record.
    if p_record_kind = 'standard' then
        select ci.item_id, ci.quantity
        into v_item_id, v_quantity
        from public.character_items ci
        where ci.id = p_record_id
          and ci.character_id = p_character_id
          and ci.quantity > 0
        for update;

        if not found then
            raise exception 'That Item is not in your Inventory.';
        end if;

    elsif p_record_kind = 'unique' then
        select cii.item_id
        into v_item_id
        from public.character_item_instances cii
        where cii.id = p_record_id
          and cii.owner_character_id = p_character_id
          and cii.vault_status = 'owned'
        for update;

        if not found then
            raise exception 'That Item is not in your Inventory.';
        end if;

    else
        raise exception 'Invalid Item record kind.';
    end if;

    -- Load the Item definition and linked recipe.
    select
        i.name,
        i.teaches_recipe_id,
        i.is_active,
        i.is_usable,
        i.use_behaviour
    into
        v_item_name,
        v_recipe_id,
        v_item_active,
        v_item_usable,
        v_use_behaviour
    from public.items i
    where i.id = v_item_id;

    if not found then
        raise exception 'The Item definition could not be loaded.';
    end if;

    if not v_item_active then
        raise exception 'This Item is inactive.';
    end if;

    if not v_item_usable then
        raise exception 'This Item cannot be used.';
    end if;

    if v_recipe_id is null then
        raise exception 'This Item does not teach a crafting recipe.';
    end if;

    -- Recipe items use the existing consumable behaviour.
    if v_use_behaviour is distinct from 'consumable' then
        raise exception 'Recipe Items must use consumable behaviour.';
    end if;

    select cr.name
    into v_recipe_name
    from public.crafting_recipes cr
    where cr.id = v_recipe_id
      and cr.is_active = true;

    if not found then
        raise exception 'The recipe taught by this Item is unavailable.';
    end if;

    -- Do NOT consume duplicate recipe books.
    if exists (
        select 1
        from public.character_recipes known
        where known.character_id = p_character_id
          and known.recipe_id = v_recipe_id
    ) then
        return jsonb_build_object(
            'success', false,
            'already_known', true,
            'recipe_id', v_recipe_id,
            'recipe_name', v_recipe_name,
            'message', 'This character already knows ' || v_recipe_name || '.'
        );
    end if;

    v_action_id := public.character_audit_begin_action('recipe_learned','recipe_learning');

    insert into public.character_recipes (
        character_id,
        recipe_id
    )
    values (
        p_character_id,
        v_recipe_id
    );

    -- Consume exactly one physical recipe Item.
    if p_record_kind = 'standard' then
        if v_quantity <= 1 then
            delete from public.character_items
            where id = p_record_id
              and character_id = p_character_id;
        else
            update public.character_items
            set
                quantity = quantity - 1,
                updated_at = now()
            where id = p_record_id
              and character_id = p_character_id;
        end if;
    else
        delete from public.character_item_instances
        where id = p_record_id
          and owner_character_id = p_character_id
          and vault_status = 'owned';
    end if;

    perform public.character_audit_write_event(
        p_character_id,'recipe_learned','recipe_learning',v_action_id,
        jsonb_build_object(
          'recipe_id',v_recipe_id,'recipe_name',v_recipe_name,
          'item_id',v_item_id,'item_name',v_item_name,'quantity_consumed',1
        ),
        'recipe_learning',v_recipe_id::text
    );

    return jsonb_build_object(
        'success', true,
        'already_known', false,
        'recipe_id', v_recipe_id,
        'recipe_name', v_recipe_name,
        'item_name', v_item_name,
        'message', 'Learned recipe: ' || v_recipe_name || '.'
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.leave_group_conversation(target_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor_user uuid := auth.uid();
  actor_character uuid;
  target_is_group boolean;
  active_member_count integer;
begin
  if actor_user is null then
    raise exception 'Authentication required.';
  end if;

  select c.id
  into actor_character
  from public.characters c
  where c.user_id = actor_user
  limit 1;

  if actor_character is null then
    raise exception 'Character required.';
  end if;

  select dc.is_group
  into target_is_group
  from public.direct_conversations dc
  where dc.id = target_conversation_id;

  if target_is_group is distinct from true then
    raise exception 'This conversation is not a group conversation.';
  end if;

  -- The important change:
  -- REMOVE the membership. Do not merely set deleted_at.
  delete from public.direct_conversation_participants dcp
  where dcp.conversation_id = target_conversation_id
    and dcp.character_id = actor_character;

  if not found then
    raise exception 'Group membership not found.';
  end if;

  -- Keep the group itself for everyone else.
  select count(*)
  into active_member_count
  from public.direct_conversation_participants dcp
  where dcp.conversation_id = target_conversation_id;

  -- If somehow nobody remains, clean up the empty shell.
  if active_member_count = 0 then
    delete from public.direct_conversations dc
    where dc.id = target_conversation_id;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.list_admin_users()
 RETURNS TABLE(user_id uuid, email text, created_at timestamp with time zone, last_sign_in_at timestamp with time zone, staff_role text, character_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.current_user_is_admin() then
    raise exception
      'Only owners and administrators can view users.';
  end if;

  return query
  select
    auth_user.id as user_id,
    auth_user.email::text as email,
    auth_user.created_at,
    auth_user.last_sign_in_at,
    staff_member.role as staff_role,
    count(character.id)::bigint as character_count
  from auth.users as auth_user
  left join public.staff_members as staff_member
    on staff_member.user_id = auth_user.id
  left join public.characters as character
    on character.user_id = auth_user.id
  group by
    auth_user.id,
    auth_user.email,
    auth_user.created_at,
    auth_user.last_sign_in_at,
    staff_member.role
  order by
    auth_user.created_at asc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.list_user_storage_objects(target_user_id uuid)
 RETURNS TABLE(bucket_id text, name text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'storage', 'public', 'pg_temp'
AS $function$
  select
    objects.bucket_id::text,
    objects.name::text
  from storage.objects as objects
  where objects.owner_id =
    target_user_id::text
  order by
    objects.bucket_id,
    objects.name;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_all_forum_topics_read()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'You must be authenticated';
  end if;

  insert into public.forum_topic_reads (
    user_id,
    topic_id,
    last_read_at
  )
  select
    auth.uid(),
    forum_topics.id,
    now()
  from public.forum_topics
  inner join public.forum_sections
    on forum_sections.id = forum_topics.section_id
  where forum_topics.deleted_at is null
    and forum_sections.is_active = true
  on conflict (user_id, topic_id)
  do update set
    last_read_at = excluded.last_read_at;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_forum_section_read(target_section_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'You must be authenticated';
  end if;

  insert into public.forum_topic_reads (
    user_id,
    topic_id,
    last_read_at
  )
  select
    auth.uid(),
    forum_topics.id,
    now()
  from public.forum_topics
  inner join public.forum_sections
    on forum_sections.id = forum_topics.section_id
  where forum_topics.section_id = target_section_id
    and forum_topics.deleted_at is null
    and forum_sections.is_active = true
  on conflict (user_id, topic_id)
  do update set
    last_read_at = excluded.last_read_at;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_forum_topic_read(target_topic_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid;
  current_last_post_at timestamptz;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'Authentication required';
  end if;

  select
    coalesce(last_post_at, updated_at, created_at)
  into current_last_post_at
  from public.forum_topics
  where id = target_topic_id
    and deleted_at is null;

  if current_last_post_at is null then
    raise exception 'Forum topic not found';
  end if;

  insert into public.forum_topic_reads (
    user_id,
    topic_id,
    last_read_at,
    created_at,
    updated_at
  )
  values (
    current_user_id,
    target_topic_id,
    current_last_post_at,
    now(),
    now()
  )
  on conflict (user_id, topic_id)
  do update set
    last_read_at = excluded.last_read_at,
    updated_at = now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_instant_chat_read(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 update public.instant_chat_participants set last_read_at=now()
 where conversation_id=p_conversation_id
 and character_id=public.instant_chat_current_character_id();
end $function$
;

CREATE OR REPLACE FUNCTION public.mark_my_notifications_viewed()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_game_now timestamptz;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Authentication required.';
  end if;

  perform public.materialize_due_event_notifications();
  v_game_now := public.current_aureth_game_datetime();

  insert into public.notification_reads (
    notification_id,
    user_id,
    viewed_at
  )
  select distinct
    n.id,
    v_uid,
    now()
  from public.notifications n
  join public.notification_targets t
    on t.notification_id = n.id
  where n.is_active = true
    and n.starts_at <= now()
    and (
      n.expires_at is null
      or n.expires_at > now()
    )
    and (
      n.expires_game_at is null
      or v_game_now is null
      or n.expires_game_at > v_game_now
    )
    and (
      t.target_type = 'global'
      or (
        t.target_type = 'staff'
        and exists (
          select 1
          from public.staff_members sm
          where sm.user_id = v_uid
        )
      )
      or (
        t.target_type = 'user'
        and t.target_id = v_uid
      )
      or (
        t.target_type = 'character'
        and exists (
          select 1
          from public.characters c
          where c.id = t.target_id
            and c.user_id = v_uid
        )
      )
      or (
        t.target_type = 'ancestry'
        and exists (
          select 1
          from public.characters c
          where c.user_id = v_uid
            and c.race_id = t.target_id
        )
      )
      or (
        t.target_type = 'association'
        and exists (
          select 1
          from public.characters c
          where c.user_id = v_uid
            and c.association_id = t.target_id
        )
      )
      or (
        t.target_type = 'order'
        and exists (
          select 1
          from public.characters c
          join public.order_memberships om
            on om.character_id = c.id
          where c.user_id = v_uid
            and om.order_id = t.target_id
        )
      )
    )
  on conflict (notification_id, user_id)
  do update set
    viewed_at = excluded.viewed_at;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.market_buy_listing(p_listing_id uuid, p_quantity integer DEFAULT 1)
 RETURNS TABLE(item_name text, quantity integer, total_paid bigint, new_balance bigint, stock_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_character_status text;

  v_shop_id uuid;
  v_shop_name text;
  v_shop_active boolean;

  v_item_id uuid;
  v_item_name text;
  v_item_active boolean;
  v_stackable boolean;
  v_max_stack integer;
  v_use_behaviour text;
  v_max_charges integer;
  v_category_slug text;

  v_listing_active boolean;
  v_buy_price bigint;
  v_stock_mode text;
  v_stock_quantity integer;

  v_total bigint;
  v_remaining integer;
  v_free integer;
  v_add integer;
  v_stack_size integer;

  v_ledger_id uuid;
  v_balance bigint;
  v_instance_id uuid;

  r record;
  v_action_id uuid;
begin
  perform public.enforce_db_user_rate_limit('db_market_action_user', auth.uid(), 30, 60);
  if v_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if p_listing_id is null then
    raise exception 'Market listing is required.';
  end if;

  if p_quantity is null
     or p_quantity < 1
     or p_quantity > 99 then
    raise exception 'Purchase quantity must be between 1 and 99.';
  end if;

  select
    c.id,
    c.status::text
  into
    v_character_id,
    v_character_status
  from public.characters c
  where c.user_id = v_user_id
  limit 1;

  if v_character_id is null then
    raise exception 'Character not found.';
  end if;

  if v_character_status <> 'approved' then
    raise exception 'Only approved characters can use the Market.';
  end if;

  select
    l.shop_id,
    s.name,
    s.is_active,
    l.is_active,
    l.buy_price,
    l.stock_mode,
    l.stock_quantity,
    i.id,
    i.name,
    i.is_active,
    i.stackable,
    i.max_stack,
    i.use_behaviour,
    i.max_charges,
    cat.slug
  into
    v_shop_id,
    v_shop_name,
    v_shop_active,
    v_listing_active,
    v_buy_price,
    v_stock_mode,
    v_stock_quantity,
    v_item_id,
    v_item_name,
    v_item_active,
    v_stackable,
    v_max_stack,
    v_use_behaviour,
    v_max_charges,
    v_category_slug
  from public.market_listings l
  join public.market_shops s
    on s.id = l.shop_id
  join public.items i
    on i.id = l.item_id
  join public.item_categories cat
    on cat.id = i.category_id
  where l.id = p_listing_id
  for update of l;

  if v_item_id is null then
    raise exception 'Market listing not found.';
  end if;

  if not v_shop_active then
    raise exception 'This shop is currently closed.';
  end if;

  if not v_listing_active then
    raise exception 'This Item is not currently for sale.';
  end if;

  if not v_item_active then
    raise exception 'This Item is currently inactive.';
  end if;

  if v_stock_mode = 'finite' then
    if coalesce(v_stock_quantity, 0) < p_quantity then
      raise exception 'There is not enough stock remaining.';
    end if;
  end if;

  v_total := v_buy_price * p_quantity::bigint;

  v_action_id := public.character_audit_begin_action('market_purchase','market');

  select
    t.ledger_id,
    t.new_balance
  into
    v_ledger_id,
    v_balance
  from public._post_remnant_transaction(
    v_character_id,
    -v_total,
    'market_purchase',
    'market',
    p_listing_id::text,
    'Market purchase — ' || v_shop_name || ' — ' ||
      v_item_name || ' ×' || p_quantity,
    v_user_id
  ) t;

  -- Containers require an individual instance so they can hold Items.
  if v_category_slug = 'container' then
    for r in
      select generate_series(1, p_quantity)
    loop
      insert into public.character_item_instances (
        item_id,
        owner_character_id,
        charges_remaining,
        vault_status,
        acquisition_source
      )
      values (
        v_item_id,
        v_character_id,
        case
          when v_use_behaviour = 'limited_charges'
            then v_max_charges
          else null
        end,
        'owned',
        'market'
      )
      returning id into v_instance_id;

      insert into public.item_instance_history (
        item_instance_id,
        to_character_id,
        actor_user_id,
        event_type,
        details
      )
      values (
        v_instance_id,
        v_character_id,
        v_user_id,
        'market_purchase',
        'Purchased from ' || v_shop_name || '.'
      );
    end loop;

  elsif not v_stackable then
    insert into public.character_items (
      character_id,
      item_id,
      quantity,
      container_instance_id,
      acquisition_source
    )
    select
      v_character_id,
      v_item_id,
      1,
      null,
      'market'
    from generate_series(1, p_quantity);

  else
    v_remaining := p_quantity;

    for r in
      select
        ci.id,
        ci.quantity
      from public.character_items ci
      where ci.character_id = v_character_id
        and ci.item_id = v_item_id
        and ci.container_instance_id is null
      order by ci.acquired_at asc
      for update
    loop
      exit when v_remaining <= 0;

      if v_max_stack is null then
        update public.character_items
        set quantity =
          r.quantity + v_remaining
        where id = r.id;

        v_remaining := 0;
        exit;
      end if;

      v_free :=
        greatest(
          0,
          v_max_stack -
          r.quantity
        );

      if v_free = 0 then
        continue;
      end if;

      v_add :=
        least(
          v_free,
          v_remaining
        );

      update public.character_items
      set quantity =
        r.quantity + v_add
      where id = r.id;

      v_remaining :=
        v_remaining - v_add;
    end loop;

    while v_remaining > 0 loop
      v_stack_size :=
        case
          when v_max_stack is null
            then v_remaining
          else least(
            v_max_stack,
            v_remaining
          )
        end;

      insert into public.character_items (
        character_id,
        item_id,
        quantity,
        container_instance_id,
        acquisition_source
      )
      values (
        v_character_id,
        v_item_id,
        v_stack_size,
        null,
        'market'
      );

      v_remaining :=
        v_remaining -
        v_stack_size;
    end loop;
  end if;

  if v_stock_mode = 'finite' then
    update public.market_listings
    set
      stock_quantity =
        stock_quantity -
        p_quantity,
      updated_at = now()
    where id = p_listing_id;

    v_stock_quantity :=
      v_stock_quantity -
      p_quantity;
  else
    v_stock_quantity := null;
  end if;

  insert into public.market_transactions (
    character_id,
    shop_id,
    listing_id,
    item_id,
    direction,
    quantity,
    unit_price,
    total_amount,
    ledger_id
  )
  values (
    v_character_id,
    v_shop_id,
    p_listing_id,
    v_item_id,
    'buy',
    p_quantity,
    v_buy_price,
    v_total,
    v_ledger_id
  );

  perform public.character_audit_write_event(
    v_character_id,'market_purchase','market',v_action_id,
    jsonb_build_object(
      'item_id',v_item_id,'item_name',v_item_name,'quantity',p_quantity,
      'shop_id',v_shop_id,'shop_name',v_shop_name,'remnants_spent',v_total
    ),
    'market_purchase',p_listing_id::text
  );

  return query
  select
    v_item_name,
    p_quantity,
    v_total,
    v_balance,
    v_stock_quantity;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.market_sell_listing(p_listing_id uuid, p_quantity integer DEFAULT 1)
 RETURNS TABLE(item_name text, quantity integer, total_received bigint, new_balance bigint, stock_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_character_status text;
  v_shop_id uuid;
  v_shop_name text;
  v_shop_active boolean;
  v_item_id uuid;
  v_item_name text;
  v_item_active boolean;
  v_category_slug text;
  v_listing_active boolean;
  v_sell_price bigint;
  v_stock_mode text;
  v_stock_quantity integer;
  v_standard_available integer := 0;
  v_container_available integer := 0;
  v_available integer := 0;
  v_remaining integer;
  v_take integer;
  v_total bigint;
  v_ledger_id uuid;
  v_balance bigint;
  r record;
  v_action_id uuid;
begin
  perform public.enforce_db_user_rate_limit('db_market_action_user', auth.uid(), 30, 60);
  if v_user_id is null then raise exception 'Authentication required.'; end if;
  if p_listing_id is null then raise exception 'Market listing is required.'; end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 99 then
    raise exception 'Sale quantity must be between 1 and 99.';
  end if;

  select c.id, c.status::text
  into v_character_id, v_character_status
  from public.characters c
  where c.user_id = v_user_id
  limit 1;

  if v_character_id is null then raise exception 'Character not found.'; end if;
  if v_character_status <> 'approved' then
    raise exception 'Only approved characters can use the Market.';
  end if;

  select
    l.shop_id, s.name, s.is_active,
    l.is_active, l.sell_price, l.stock_mode, l.stock_quantity,
    i.id, i.name, i.is_active, cat.slug
  into
    v_shop_id, v_shop_name, v_shop_active,
    v_listing_active, v_sell_price, v_stock_mode, v_stock_quantity,
    v_item_id, v_item_name, v_item_active, v_category_slug
  from public.market_listings l
  join public.market_shops s on s.id = l.shop_id
  join public.items i on i.id = l.item_id
  join public.item_categories cat on cat.id = i.category_id
  where l.id = p_listing_id
  for update of l;

  if v_item_id is null then raise exception 'Market listing not found.'; end if;
  if not v_shop_active then raise exception 'This shop is currently closed.'; end if;
  if not v_listing_active then raise exception 'This Item is not currently traded by this shop.'; end if;
  if not v_item_active then raise exception 'This Item is currently inactive.'; end if;
  if v_sell_price is null or v_sell_price <= 0 then
    raise exception 'This shop is not buying this Item.';
  end if;

  select coalesce(sum(inv.quantity), 0)::integer
  into v_standard_available
  from public.get_public_character_inventory(v_character_id) inv
  where inv.record_kind = 'standard'
    and inv.item_id = v_item_id
    and inv.parent_container_id is null
    and inv.is_equipped = false
    and inv.transfer_policy = 'free'
    and inv.is_quest_item = false;

  if v_category_slug = 'container' then
    select count(*)::integer
    into v_container_available
    from public.get_public_character_inventory(v_character_id) inv
    where inv.record_kind = 'unique'
      and inv.item_id = v_item_id
      and inv.container_capacity is not null
      and inv.parent_container_id is null
      and inv.is_equipped = false
      and inv.transfer_policy = 'free'
      and inv.is_quest_item = false
      and not exists (
        select 1 from public.character_items ci
        where ci.container_instance_id = inv.record_id
      )
      and not exists (
        select 1 from public.character_item_instances child
        where child.container_instance_id = inv.record_id
          and child.id <> inv.record_id
      );
  end if;

  v_available := v_standard_available + v_container_available;

  if v_available < p_quantity then
    if v_category_slug = 'container' then
      raise exception 'You do not have enough empty, eligible copies of this Container to sell.';
    end if;
    raise exception 'You do not have enough eligible copies of this Item to sell.';
  end if;

  v_action_id := public.character_audit_begin_action('market_sale','market');

  v_remaining := p_quantity;

  for r in
    select inv.record_id, inv.quantity
    from public.get_public_character_inventory(v_character_id) inv
    where inv.record_kind = 'standard'
      and inv.item_id = v_item_id
      and inv.parent_container_id is null
      and inv.is_equipped = false
      and inv.transfer_policy = 'free'
      and inv.is_quest_item = false
    order by inv.record_id
  loop
    exit when v_remaining <= 0;
    v_take := least(r.quantity, v_remaining);

    if v_take >= r.quantity then
      delete from public.character_items ci
      where ci.id = r.record_id
        and ci.character_id = v_character_id;
    else
      update public.character_items ci
      set quantity = ci.quantity - v_take
      where ci.id = r.record_id
        and ci.character_id = v_character_id;
    end if;

    v_remaining := v_remaining - v_take;
  end loop;

  if v_remaining > 0 and v_category_slug = 'container' then
    for r in
      select inv.record_id
      from public.get_public_character_inventory(v_character_id) inv
      where inv.record_kind = 'unique'
        and inv.item_id = v_item_id
        and inv.container_capacity is not null
        and inv.parent_container_id is null
        and inv.is_equipped = false
        and inv.transfer_policy = 'free'
        and inv.is_quest_item = false
        and not exists (
          select 1 from public.character_items ci
          where ci.container_instance_id = inv.record_id
        )
        and not exists (
          select 1 from public.character_item_instances child
          where child.container_instance_id = inv.record_id
            and child.id <> inv.record_id
        )
      order by inv.record_id
    loop
      exit when v_remaining <= 0;

      delete from public.item_instance_history h
      where h.item_instance_id = r.record_id;

      delete from public.character_item_instances inst
      where inst.id = r.record_id
        and inst.owner_character_id = v_character_id;

      if found then
        v_remaining := v_remaining - 1;
      end if;
    end loop;
  end if;

  if v_remaining <> 0 then
    raise exception 'Inventory changed while the sale was being processed.';
  end if;

  v_total := v_sell_price * p_quantity::bigint;

  select t.ledger_id, t.new_balance
  into v_ledger_id, v_balance
  from public._post_remnant_transaction(
    v_character_id,
    v_total,
    'market_sale',
    'market',
    p_listing_id::text,
    'Market sale — ' || v_shop_name || ' — ' || v_item_name || ' ×' || p_quantity,
    v_user_id
  ) t;

  if v_stock_mode = 'finite' then
    update public.market_listings
    set stock_quantity = coalesce(stock_quantity, 0) + p_quantity,
        updated_at = now()
    where id = p_listing_id;

    v_stock_quantity := coalesce(v_stock_quantity, 0) + p_quantity;
  else
    v_stock_quantity := null;
  end if;

  insert into public.market_transactions (
    character_id, shop_id, listing_id, item_id,
    direction, quantity, unit_price, total_amount, ledger_id
  )
  values (
    v_character_id, v_shop_id, p_listing_id, v_item_id,
    'sell', p_quantity, v_sell_price, v_total, v_ledger_id
  );

  perform public.character_audit_write_event(
    v_character_id,'market_sale','market',v_action_id,
    jsonb_build_object(
      'item_id',v_item_id,'item_name',v_item_name,'quantity',p_quantity,
      'shop_id',v_shop_id,'shop_name',v_shop_name,'remnants_received',v_total
    ),
    'market_sale',p_listing_id::text
  );

  return query
  select v_item_name, p_quantity, v_total, v_balance, v_stock_quantity;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.materialize_due_event_notifications()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_game timestamptz;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  v_now_game := public.current_aureth_game_datetime();

  if v_now_game is null then
    return;
  end if;

  -- -------------------------------------------------------------------------
  -- 24 Aureth hour reminders
  --
  -- We only need to inspect today and tomorrow because a 24-hour reminder
  -- cannot become due for any occurrence further away than that.
  -- -------------------------------------------------------------------------

  with candidate_dates as (
    select
      (
        (v_now_game at time zone 'Europe/London')::date
        + offset_days
      )::date as occurrence_date
    from generate_series(0, 1) as g(offset_days)
  ),
  occurrences as (
    select
      e.*,
      d.occurrence_date,
      public.calendar_event_start_datetime(
        d.occurrence_date,
        e.start_time
      ) as occurrence_start,
      public.calendar_event_expiry_datetime(
        d.occurrence_date,
        e.start_time,
        e.end_time
      ) as occurrence_end
    from public.calendar_events e
    cross join candidate_dates d
    where e.is_active = true
      and e.notify_24h = true
      and e.start_time is not null
      and d.occurrence_date >= e.event_date
      and (
        (
          e.recurrence_type = 'once'
          and d.occurrence_date = e.event_date
        )
        or e.recurrence_type = 'daily'
        or (
          e.recurrence_type = 'weekly'
          and (
            (d.occurrence_date - e.event_date) % 7
          ) = 0
        )
        or (
          e.recurrence_type = 'monthly'
          and extract(day from d.occurrence_date)::int =
            least(
              extract(day from e.event_date)::int,
              extract(
                day from (
                  date_trunc(
                    'month',
                    d.occurrence_date::timestamp
                  )
                  + interval '1 month'
                  - interval '1 day'
                )
              )::int
            )
        )
        or (
          e.recurrence_type = 'yearly'
          and extract(month from d.occurrence_date)::int =
            extract(month from e.event_date)::int
          and extract(day from d.occurrence_date)::int =
            least(
              extract(day from e.event_date)::int,
              extract(
                day from (
                  date_trunc(
                    'month',
                    d.occurrence_date::timestamp
                  )
                  + interval '1 month'
                  - interval '1 day'
                )
              )::int
            )
        )
      )
  )
  insert into public.notifications (
    type,
    title,
    body,
    starts_at,
    expires_game_at,
    source_type,
    source_id,
    source_trigger,
    created_by,
    is_automatic,
    is_active
  )
  select
    'event',
    o.title || ' — 24 Aureth hours',
    o.title || ' begins in 24 Aureth hours.',
    now(),
    o.occurrence_end,
    'event',
    o.id::text,
    '24h:' || o.occurrence_date::text,
    o.created_by,
    true,
    true
  from occurrences o
  where v_now_game >= o.occurrence_start - interval '24 hours'
    and v_now_game < o.occurrence_start - interval '1 hour'
    and not exists (
      select 1
      from public.notification_suppressions s
      where s.source_type = 'event'
        and s.source_id = o.id::text
        and (
          s.source_trigger = '24h'
          or s.source_trigger =
            '24h:' || o.occurrence_date::text
        )
    )
  on conflict (
    source_type,
    source_id,
    source_trigger
  )
  where is_automatic = true
  do nothing;


  -- -------------------------------------------------------------------------
  -- 1 Aureth hour reminders
  -- -------------------------------------------------------------------------

  with candidate_dates as (
    select
      (
        (v_now_game at time zone 'Europe/London')::date
        + offset_days
      )::date as occurrence_date
    from generate_series(0, 1) as g(offset_days)
  ),
  occurrences as (
    select
      e.*,
      d.occurrence_date,
      public.calendar_event_start_datetime(
        d.occurrence_date,
        e.start_time
      ) as occurrence_start,
      public.calendar_event_expiry_datetime(
        d.occurrence_date,
        e.start_time,
        e.end_time
      ) as occurrence_end
    from public.calendar_events e
    cross join candidate_dates d
    where e.is_active = true
      and e.notify_1h = true
      and e.start_time is not null
      and d.occurrence_date >= e.event_date
      and (
        (
          e.recurrence_type = 'once'
          and d.occurrence_date = e.event_date
        )
        or e.recurrence_type = 'daily'
        or (
          e.recurrence_type = 'weekly'
          and (
            (d.occurrence_date - e.event_date) % 7
          ) = 0
        )
        or (
          e.recurrence_type = 'monthly'
          and extract(day from d.occurrence_date)::int =
            least(
              extract(day from e.event_date)::int,
              extract(
                day from (
                  date_trunc(
                    'month',
                    d.occurrence_date::timestamp
                  )
                  + interval '1 month'
                  - interval '1 day'
                )
              )::int
            )
        )
        or (
          e.recurrence_type = 'yearly'
          and extract(month from d.occurrence_date)::int =
            extract(month from e.event_date)::int
          and extract(day from d.occurrence_date)::int =
            least(
              extract(day from e.event_date)::int,
              extract(
                day from (
                  date_trunc(
                    'month',
                    d.occurrence_date::timestamp
                  )
                  + interval '1 month'
                  - interval '1 day'
                )
              )::int
            )
        )
      )
  )
  insert into public.notifications (
    type,
    title,
    body,
    starts_at,
    expires_game_at,
    source_type,
    source_id,
    source_trigger,
    created_by,
    is_automatic,
    is_active
  )
  select
    'event',
    o.title || ' — 1 Aureth hour',
    o.title || ' begins in 1 Aureth hour.',
    now(),
    o.occurrence_end,
    'event',
    o.id::text,
    '1h:' || o.occurrence_date::text,
    o.created_by,
    true,
    true
  from occurrences o
  where v_now_game >= o.occurrence_start - interval '1 hour'
    and v_now_game < o.occurrence_end
    and not exists (
      select 1
      from public.notification_suppressions s
      where s.source_type = 'event'
        and s.source_id = o.id::text
        and (
          s.source_trigger = '1h'
          or s.source_trigger =
            '1h:' || o.occurrence_date::text
        )
    )
  on conflict (
    source_type,
    source_id,
    source_trigger
  )
  where is_automatic = true
  do nothing;


  -- Every automatic Event notification is global.
  insert into public.notification_targets (
    notification_id,
    target_type,
    target_id
  )
  select
    n.id,
    'global',
    null
  from public.notifications n
  where n.is_automatic = true
    and n.source_type = 'event'
    and not exists (
      select 1
      from public.notification_targets t
      where t.notification_id = n.id
        and t.target_type = 'global'
        and t.target_id is null
    )
  on conflict do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.move_own_inventory_record(p_record_kind text, p_record_id uuid, p_target_container_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
  v_item_id uuid;
  v_current_container_id uuid;
  v_target_owner_id uuid;
  v_target_capacity integer;
  v_used_slots integer;
  v_is_container boolean;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if p_record_kind = 'standard' then
    select
      ci.character_id,
      ci.item_id,
      ci.container_instance_id
    into
      v_character_id,
      v_item_id,
      v_current_container_id
    from public.character_items ci
    join public.characters c
      on c.id = ci.character_id
    where ci.id = p_record_id
      and c.user_id = auth.uid();

  elsif p_record_kind = 'unique' then
    select
      inst.owner_character_id,
      inst.item_id,
      inst.container_instance_id
    into
      v_character_id,
      v_item_id,
      v_current_container_id
    from public.character_item_instances inst
    join public.characters c
      on c.id = inst.owner_character_id
    where inst.id = p_record_id
      and inst.vault_status = 'owned'
      and c.user_id = auth.uid();

  else
    raise exception 'Invalid inventory record type.';
  end if;

  if v_character_id is null or v_item_id is null then
    raise exception 'You do not own this Item.';
  end if;

  if v_current_container_id is not distinct from p_target_container_id then
    return;
  end if;

  select (i.container_capacity is not null)
  into v_is_container
  from public.items i
  where i.id = v_item_id;

  if coalesce(v_is_container, false)
     and p_target_container_id is not null then
    raise exception 'Containers cannot be placed inside other Containers.';
  end if;

  if p_target_container_id is not null then

    if p_record_kind = 'unique'
       and p_record_id = p_target_container_id then
      raise exception 'A Container cannot contain itself.';
    end if;

    select
      target.owner_character_id,
      master.container_capacity
    into
      v_target_owner_id,
      v_target_capacity
    from public.character_item_instances target
    join public.items master
      on master.id = target.item_id
    where target.id = p_target_container_id
      and target.vault_status = 'owned';

    if v_target_owner_id is null then
      raise exception 'Target Container not found.';
    end if;

    if v_target_owner_id <> v_character_id then
      raise exception 'You can only use your own Containers.';
    end if;

    if v_target_capacity is null then
      raise exception 'The selected Item is not a Container.';
    end if;

    select
      (
        select count(*)::integer
        from public.character_items ci
        where ci.container_instance_id = p_target_container_id
      )
      +
      (
        select count(*)::integer
        from public.character_item_instances inst
        where inst.container_instance_id = p_target_container_id
      )
    into v_used_slots;

    if coalesce(v_used_slots, 0) >= v_target_capacity then
      raise exception 'That Container is full.';
    end if;

  end if;

  if p_record_kind = 'standard' then

    update public.character_items
    set
      container_instance_id = p_target_container_id,
      updated_at = now()
    where id = p_record_id;

  else

    update public.character_item_instances
    set
      container_instance_id = p_target_container_id,
      updated_at = now()
    where id = p_record_id;

  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.my_character_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 select id from public.characters where user_id=auth.uid() limit 1
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_character_inventory_stacks_staff(p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if not exists (
    select 1
    from public.staff_members s
    where s.user_id = v_user_id
  ) then
    raise exception 'Staff access required.';
  end if;

  if p_character_id is null then
    raise exception 'Character is required.';
  end if;

  if not exists (
    select 1
    from public.characters c
    where c.id = p_character_id
  ) then
    raise exception 'Character not found.';
  end if;

  perform public._normalize_character_inventory_stacks(
    p_character_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_inventory_after_change(p_other_character_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_room_id uuid;
  v_other_room_id uuid;
begin
  if v_user_id is null then
    raise exception 'Authentication required.';
  end if;

  select c.id, c.current_room_id
  into v_character_id, v_room_id
  from public.characters c
  where c.user_id = v_user_id
  limit 1;

  if v_character_id is null then
    raise exception 'Character not found.';
  end if;

  perform public._normalize_character_inventory_stacks(v_character_id);

  if p_other_character_id is not null
     and p_other_character_id <> v_character_id then

    select c.current_room_id
    into v_other_room_id
    from public.characters c
    where c.id = p_other_character_id;

    if not found then
      raise exception 'Other character not found.';
    end if;

    if v_room_id is distinct from v_other_room_id then
      raise exception 'Characters must be in the same Location.';
    end if;

    perform public._normalize_character_inventory_stacks(p_other_character_id);
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_npc_mechanics_room_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_npc public.npcs%rowtype;
  v_staff_character_id uuid;
  v_staff_role text;
  v_race jsonb;
begin
  select n.*
  into v_npc
  from public.npcs n
  join public.characters c on c.id = n.character_id
  where c.id = new.character_id
    and c.is_system = true
    and n.is_active = true
    and n.is_location_active = true
  limit 1;

  if not found then
    return new;
  end if;

  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  select sm.role
  into v_staff_role
  from public.staff_members sm
  where sm.user_id = auth.uid();

  if v_staff_role is null
     or v_staff_role not in ('owner','admin','master') then
    raise exception 'NPC mechanics require Master/Admin/Owner access.';
  end if;

  if v_npc.current_room_id is distinct from new.room_id then
    raise exception 'NPC is not in this Location.';
  end if;

  select c.id
  into v_staff_character_id
  from public.characters c
  where c.user_id = auth.uid()
    and c.is_system = false
    and c.status = 'approved'
    and c.current_room_id = new.room_id
  limit 1;

  if v_staff_character_id is null then
    raise exception 'Your staff Character must be in this Location to control an NPC.';
  end if;

  select case
    when r.id is null then null
    else jsonb_build_object(
      'id', r.id,
      'name', r.name,
      'icon_url', r.icon_url
    )
  end
  into v_race
  from public.characters c
  left join public.races r on r.id = c.race_id
  where c.id = v_npc.character_id;

  new.character_id := v_staff_character_id;
  new.speaker_type := 'npc';
  new.npc_id := v_npc.id;
  new.sent_by_user_id := auth.uid();
  new.npc_snapshot := jsonb_build_object(
    'id', v_npc.id,
    'character_id', v_npc.character_id,
    'name', v_npc.name,
    'pronouns', v_npc.pronouns,
    'portrait_url', v_npc.portrait_url,
    'description', v_npc.description,
    'race', v_race
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_own_inventory_stacks()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
begin
  select c.id
  into v_character_id
  from public.characters c
  where c.user_id = auth.uid()
  limit 1;

  if v_character_id is null then
    raise exception 'Character not found.';
  end if;

  perform public._normalize_character_inventory_stacks(v_character_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_character_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name text;
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  if new.status not in ('approved', 'rejected') then
    return new;
  end if;

  v_name := coalesce(
    nullif(trim(new.display_name), ''),
    trim(coalesce(new.first_name, '') || ' ' || coalesce(new.surname, '')),
    'Your character'
  );

  perform public.create_automatic_notification(
    'character',
    case
      when new.status = 'approved'
      then 'Character Approved'
      else 'Character Application Updated'
    end,
    case
      when new.status = 'approved'
      then v_name || ' has been approved.'
      else v_name || ' has been returned as rejected. Open your Character page for details.'
    end,
    '/character',
    'user',
    new.user_id,
    'character_application',
    new.id::text,
    'status_' || new.status,
    now() + interval '30 days'
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_friend_list_add()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name text;
  v_slug text;
  v_scope text;
  v_relationship text;
begin
  select
    coalesce(
      nullif(trim(c.display_name), ''),
      trim(coalesce(c.first_name, '') || ' ' || coalesce(c.surname, '')),
      'A character'
    ),
    c.public_slug
  into
    v_name,
    v_slug
  from public.characters c
  where c.id = new.owner_character_id;

  v_scope :=
    case new.list_scope
      when 'ingame' then 'In-Game'
      when 'offgame' then 'Off-Game'
      else initcap(replace(new.list_scope, '_', ' '))
    end;

  v_relationship :=
    initcap(replace(new.relationship_type, '_', ' '));

  perform public.create_automatic_notification(
    'friend',
    'Added to a Friend List',
    v_name || ' added you to their ' || v_scope ||
      ' Friend List as ' || v_relationship || '.',
    case
      when v_slug is not null and v_slug <> ''
      then '/characters/' || v_slug
      else null
    end,
    'character',
    new.target_character_id,
    'friend_list',
    new.owner_character_id::text || ':' || new.target_character_id::text,
    'added',
    now() + interval '30 days'
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_my_mutual_friends_entered()
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select public.notify_my_mutual_friends_presence('entered');
$function$
;

