 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select public.notify_my_mutual_friends_presence('left');
$function$
;

CREATE OR REPLACE FUNCTION public.notify_my_mutual_friends_presence(p_action text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_uid uuid;
    v_character_id uuid;
      v_first_name text;
        v_display_name text;
          v_public_slug text;
            v_session_id text;
              v_source_trigger text;
                v_title text;
                  v_body text;
                    v_recipient record;
                      v_notification_id uuid;
                        v_created integer := 0;
                        begin
                          if p_action not in ('entered', 'left') then
                              raise exception 'Invalid presence notification action.';
                                end if;

                                  v_uid := auth.uid();

                                    if v_uid is null then
                                        raise exception 'Authentication required.';
                                          end if;

                                            v_session_id :=
                                                coalesce(
                                                      nullif(auth.jwt() ->> 'session_id', ''),
                                                            nullif(auth.jwt() ->> 'session', ''),
                                                                  v_uid::text
                                                                      );

                                                                        select
                                                                            c.id,
                                                                                coalesce(
                                                                                      nullif(trim(c.first_name), ''),
                                                                                            'Someone'
                                                                                                ),
                                                                                                    coalesce(
                                                                                                          nullif(trim(c.display_name), ''),
                                                                                                                trim(
                                                                                                                        coalesce(c.first_name, '')
                                                                                                                                || ' '
                                                                                                                                        || coalesce(c.surname, '')
                                                                                                                                              )
                                                                                                                                                  ),
                                                                                                                                                      c.public_slug
                                                                                                                                                        into
                                                                                                                                                            v_character_id,
                                                                                                                                                                v_first_name,
                                                                                                                                                                    v_display_name,
                                                                                                                                                                        v_public_slug
                                                                                                                                                                          from public.characters c
                                                                                                                                                                            where c.user_id = v_uid
                                                                                                                                                                                and c.status = 'approved'
                                                                                                                                                                                    and coalesce(c.is_system, false) = false
                                                                                                                                                                                      limit 1;

                                                                                                                                                                                        if v_character_id is null then
                                                                                                                                                                                            return 0;
                                                                                                                                                                                              end if;

                                                                                                                                                                                                if p_action = 'entered' then
                                                                                                                                                                                                    v_title :=
                                                                                                                                                                                                          v_display_name || ' has entered Sepulchria';

                                                                                                                                                                                                              v_body :=
                                                                                                                                                                                                                    v_display_name || ' has entered Sepulchria.';
                                                                                                                                                                                                                      else
                                                                                                                                                                                                                          v_title :=
                                                                                                                                                                                                                                v_display_name || ' has left Sepulchria';

                                                                                                                                                                                                                                    v_body :=
                                                                                                                                                                                                                                          v_display_name || ' has left Sepulchria.';
                                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                                              v_source_trigger :=
                                                                                                                                                                                                                                                  p_action || ':' || v_session_id;

                                                                                                                                                                                                                                                    insert into public.portal_presence_events (
                                                                                                                                                                                                                                                        character_id,
                                                                                                                                                                                                                                                            first_name,
                                                                                                                                                                                                                                                                event_type,
                                                                                                                                                                                                                                                                    session_key,
                                                                                                                                                                                                                                                                        occurred_at
                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                            values (
                                                                                                                                                                                                                                                                                v_character_id,
                                                                                                                                                                                                                                                                                    v_first_name,
                                                                                                                                                                                                                                                                                        p_action,
                                                                                                                                                                                                                                                                                            v_session_id,
                                                                                                                                                                                                                                                                                                now()
                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                    on conflict (
                                                                                                                                                                                                                                                                                                        character_id,
                                                                                                                                                                                                                                                                                                            event_type,
                                                                                                                                                                                                                                                                                                                session_key
                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                    do nothing;

                                                                                                                                                                                                                                                                                                                      delete from public.portal_presence_events
                                                                                                                                                                                                                                                                                                                        where occurred_at <
                                                                                                                                                                                                                                                                                                                            now() - interval '1 day';

                                                                                                                                                                                                                                                                                                                              for v_recipient in
                                                                                                                                                                                                                                                                                                                                  select distinct
                                                                                                                                                                                                                                                                                                                                        mine.owner_character_id
                                                                                                                                                                                                                                                                                                                                                as recipient_character_id

                                                                                                                                                                                                                                                                                                                                                    from public.character_friend_entries mine

                                                                                                                                                                                                                                                                                                                                                        where mine.target_character_id =
                                                                                                                                                                                                                                                                                                                                                              v_character_id

                                                                                                                                                                                                                                                                                                                                                                    and exists (
                                                                                                                                                                                                                                                                                                                                                                            select 1
                                                                                                                                                                                                                                                                                                                                                                                    from public.character_friend_entries reciprocal
                                                                                                                                                                                                                                                                                                                                                                                            where
                                                                                                                                                                                                                                                                                                                                                                                                      reciprocal.owner_character_id =
                                                                                                                                                                                                                                                                                                                                                                                                                  v_character_id
                                                                                                                                                                                                                                                                                                                                                                                                                            and reciprocal.target_character_id =
                                                                                                                                                                                                                                                                                                                                                                                                                                        mine.owner_character_id
                                                                                                                                                                                                                                                                                                                                                                                                                                              )

                                                                                                                                                                                                                                                                                                                                                                                                                                                    and not exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                            select 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    from public.character_blocks b
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            where
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  b.blocker_character_id =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mine.owner_character_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            and b.blocked_character_id =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_character_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              or
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    b.blocker_character_id =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_character_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              and b.blocked_character_id =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mine.owner_character_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  and exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          select 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  from public.characters recipient
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          where
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    recipient.id =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mine.owner_character_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          and recipient.status = 'approved'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    and coalesce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                recipient.is_system,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  and exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          select 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  from public.character_presence presence
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          where
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    presence.character_id =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mine.owner_character_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          and presence.last_seen_at >=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      now() - interval '5 minutes'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              loop
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  select public.create_automatic_notification(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_type => 'system',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              p_title => v_title,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p_body => v_body,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p_href =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            when
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_public_slug is null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    or trim(v_public_slug) = ''
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              then '/friends'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '/characters/' || v_public_slug
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_target_type => 'character',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_target_id =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_recipient.recipient_character_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      p_source_type => 'friend_presence',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p_source_id => v_character_id::text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_source_trigger => v_source_trigger,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_expires_at =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                now() + interval '1 hour'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        into v_notification_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if v_notification_id is not null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_created := v_created + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end loop;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return v_created;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $function$
;

CREATE OR REPLACE FUNCTION public.notify_order_membership_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_name text;
  v_level integer;
  v_job_name text;
  v_character_id uuid;
  v_source_id text;
  v_trigger text;
begin
  if tg_op = 'DELETE' then
    v_character_id := old.character_id;
    v_source_id := old.id::text;

    select o.name
    into v_order_name
    from public.orders o
    where o.id = old.order_id;

    perform public.create_automatic_notification(
      'order',
      'Order Membership Ended',
      'You are no longer a member of ' || coalesce(v_order_name, 'that Order') || '.',
      '/orders',
      'character',
      v_character_id,
      'order_membership',
      v_source_id,
      'removed',
      now() + interval '30 days'
    );

    return old;
  end if;

  v_character_id := new.character_id;
  v_source_id := new.id::text;

  select o.name
  into v_order_name
  from public.orders o
  where o.id = new.order_id;

  select l.level
  into v_level
  from public.order_levels l
  where l.id = new.order_level_id;

  select j.name
  into v_job_name
  from public.order_jobs j
  where j.id = new.order_job_id;

  if tg_op = 'INSERT' then
    perform public.create_automatic_notification(
      'order',
      'Joined an Order',
      'You joined ' || coalesce(v_order_name, 'an Order') ||
        coalesce(
          ' · Level ' || v_level::text || ' · ' || nullif(v_job_name, ''),
          ''
        ) || '.',
      '/orders',
      'character',
      v_character_id,
      'order_membership',
      v_source_id,
      'joined',
      now() + interval '30 days'
    );

    return new;
  end if;

  if
    new.order_level_id is distinct from old.order_level_id
    or new.order_job_id is distinct from old.order_job_id
  then
    v_trigger :=
      'changed:' ||
      coalesce(new.order_level_id::text, '') ||
      ':' ||
      coalesce(new.order_job_id::text, '');

    perform public.create_automatic_notification(
      'order',
      'Order Standing Updated',
      'Your standing in ' || coalesce(v_order_name, 'your Order') ||
        ' is now' ||
        coalesce(' Level ' || v_level::text, '') ||
        coalesce(' · ' || nullif(v_job_name, ''), '') ||
        '.',
      '/orders',
      'character',
      v_character_id,
      'order_membership',
      v_source_id,
      v_trigger,
      now() + interval '30 days'
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_order_submission_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_transition_key text;
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  if new.status not in ('accepted', 'rejected') then
    return new;
  end if;

  v_transition_key :=
    'status_' || new.status || ':' ||
    coalesce(
      extract(
        epoch from
        coalesce(new.updated_at, now())
      )::bigint::text,
      txid_current()::text
    );

  perform public.create_automatic_notification(
    'order',
    case
      when new.status = 'accepted'
      then 'Order Proposal Accepted'
      else 'Order Proposal Rejected'
    end,
    'Your Order proposal "' ||
      coalesce(new.order_name, 'Untitled Order') ||
      '" has been ' || new.status || '.',
    '/orders',
    'character',
    new.submitted_by_character_id,
    'order_submission',
    new.id::text,
    v_transition_key,
    now() + interval '30 days'
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_sanction_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expiry timestamptz;
begin
  if tg_op = 'INSERT' then
    v_expiry := coalesce(
      new.expires_at,
      now() + interval '30 days'
    );

    perform public.create_automatic_notification(
      'sanction',
      'Account Notice',
      'A ' || replace(new.sanction_type, '_', ' ') ||
        ' sanction has been issued: ' || coalesce(new.player_reason, 'See your Sanctions page for details.'),
      '/sanctions',
      'user',
      new.target_user_id,
      'sanction',
      new.id::text,
      'issued',
      v_expiry
    );

    return new;
  end if;

  if
    new.status is distinct from old.status
    and new.status = 'revoked'
  then
    perform public.create_automatic_notification(
      'sanction',
      'Sanction Revoked',
      'A sanction on your account has been revoked.',
      '/sanctions',
      'user',
      new.target_user_id,
      'sanction',
      new.id::text,
      'revoked',
      now() + interval '30 days'
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_ticket_state_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_reference text;
  v_status text;
begin
  if new.event_type <> 'ticket_state_changed' then
    return new;
  end if;

  select
    t.opened_by_user_id,
    t.public_reference
  into
    v_user_id,
    v_reference
  from public.tickets t
  where t.id = new.ticket_id;

  if v_user_id is null then
    return new;
  end if;

  v_status :=
    nullif(new.details ->> 'status', '');

  perform public.create_automatic_notification(
    'ticket',
    'Ticket Updated',
    'Ticket ' ||
      coalesce(v_reference, '') ||
      case
        when v_status is not null
        then
          ' is now ' ||
          replace(
            v_status,
            '_',
            ' '
          ) ||
          '.'
        else
          ' was updated.'
      end,
    case
      when v_reference is not null
       and v_reference <> ''
      then
        '/support/' || v_reference
      else
        '/support'
    end,
    'user',
    v_user_id,
    'ticket',
    new.id::text,
    'state_changed',
    now() + interval '30 days'
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_trophy_award()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name text;
begin
  select t.name
  into v_name
  from public.trophy_definitions t
  where t.id = new.trophy_id;

  perform public.create_automatic_notification(
    'trophy',
    'Trophy Earned',
    'You earned the Trophy "' ||
      coalesce(v_name, 'Unknown Trophy') ||
      '".',

    -- Open Character Sheet -> Trophies -> exact Trophy
    '/character?tab=trophies#trophy-' ||
      new.trophy_id::text,

    'character',
    new.character_id,
    'trophy',
    new.character_id::text ||
      ':' ||
      new.trophy_id::text,
    'earned',
    now() + interval '30 days'
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.permanently_delete_forum_post(target_post_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  post_record record;
  deleted_image_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to permanently delete forum content.';
  end if;

  if not public.current_user_can_purge_forum() then
    raise exception 'Only owners, administrators and moderators may permanently delete forum content.';
  end if;

  select
    post.id,
    post.topic_id,
    post.is_initial,
    post.deleted_at,
    topic.title as topic_title,
    topic.slug as topic_slug,
    topic.section_id,
    section.slug as section_slug
  into post_record
  from public.forum_posts as post
  join public.forum_topics as topic
    on topic.id = post.topic_id
  left join public.forum_sections as section
    on section.id = topic.section_id
  where post.id = target_post_id
  for update of post;

  if not found then
    raise exception 'The selected reply no longer exists.';
  end if;

  if post_record.is_initial then
    raise exception 'The opening post can only be erased by permanently deleting its entire discussion.';
  end if;

  if post_record.deleted_at is null then
    raise exception 'The reply must be soft-deleted before it can be permanently erased.';
  end if;

  select count(*)::integer
  into deleted_image_count
  from public.forum_post_images
  where post_id = target_post_id;

  update public.forum_moderation_log
  set post_id = null
  where post_id = target_post_id;

  /* Existing quotations remain readable as posts, but no longer reference a
     record that is about to disappear. */
  update public.forum_posts
  set quoted_post_id = null
  where quoted_post_id = target_post_id;

  delete from public.forum_post_images
  where post_id = target_post_id;

  delete from public.forum_posts
  where id = target_post_id;

  return jsonb_build_object(
    'post_id', target_post_id,
    'topic_id', post_record.topic_id,
    'topic_title', post_record.topic_title,
    'topic_slug', post_record.topic_slug,
    'section_slug', post_record.section_slug,
    'deleted_images', deleted_image_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.permanently_delete_forum_topic(target_topic_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  topic_record record;
  deleted_post_count integer := 0;
  deleted_image_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to permanently delete forum content.';
  end if;

  if not public.current_user_can_purge_forum() then
    raise exception 'Only owners, administrators and moderators may permanently delete forum content.';
  end if;

  select
    topic.id,
    topic.title,
    topic.slug,
    topic.section_id,
    topic.deleted_at,
    section.slug as section_slug
  into topic_record
  from public.forum_topics as topic
  left join public.forum_sections as section
    on section.id = topic.section_id
  where topic.id = target_topic_id
  for update of topic;

  if not found then
    raise exception 'The selected discussion no longer exists.';
  end if;

  if topic_record.deleted_at is null then
    raise exception 'The discussion must be soft-deleted before it can be permanently erased.';
  end if;

  select count(*)::integer
  into deleted_post_count
  from public.forum_posts
  where topic_id = target_topic_id;

  select count(*)::integer
  into deleted_image_count
  from public.forum_post_images
  where post_id in (
    select id
    from public.forum_posts
    where topic_id = target_topic_id
  );

  /* Preserve old audit rows, but remove references to records being erased. */
  update public.forum_moderation_log
  set
    topic_id = null,
    post_id = null
  where topic_id = target_topic_id
     or post_id in (
       select id
       from public.forum_posts
       where topic_id = target_topic_id
     );

  /* Clear any legacy quote that points into this discussion. */
  update public.forum_posts
  set quoted_post_id = null
  where quoted_post_id in (
    select id
    from public.forum_posts
    where topic_id = target_topic_id
  );

  delete from public.forum_post_images
  where post_id in (
    select id
    from public.forum_posts
    where topic_id = target_topic_id
  );

  delete from public.forum_topic_reads
  where topic_id = target_topic_id;

  delete from public.forum_posts
  where topic_id = target_topic_id;

  delete from public.forum_topics
  where id = target_topic_id;

  return jsonb_build_object(
    'topic_id', target_topic_id,
    'topic_title', topic_record.title,
    'topic_slug', topic_record.slug,
    'section_slug', topic_record.section_slug,
    'deleted_posts', deleted_post_count,
    'deleted_images', deleted_image_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.play_house_of_chances()
 RETURNS TABLE(play_id uuid, roll_1 integer, roll_2 integer, roll_3 integer, roll_total integer, cost_paid integer, matched_rule_id uuid, matched_rule_name text, reward_snapshot jsonb, wallet_balance integer, plays_used integer, plays_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_character record;
  v_settings public.house_of_chances_settings%rowtype;
  v_room_slug text;

  v_today date := (now() at time zone 'UTC')::date;
  v_used integer := 0;

  v_balance bigint;
  v_new_balance bigint;

  v_roll_1 integer;
  v_roll_2 integer;
  v_roll_3 integer;
  v_total integer;

  v_rule public.house_of_chances_prize_rules%rowtype;
  v_reward record;
  v_item_name text;

  v_remnant_win bigint := 0;
  v_snapshot jsonb := '[]'::jsonb;

  -- Generate the permanent play ID before any ledger writes so
  -- every financial movement can reference this exact play.
  v_play_id uuid := gen_random_uuid();
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'You must be signed in to play.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('house-of-chances:' || v_user_id::text, 0)
  );

  select
    c.id,
    c.display_name,
    c.current_room_id,
    c.status
  into v_character
  from public.characters c
  where c.user_id = v_user_id
    and coalesce(c.is_system, false) = false
  limit 1;

  if not found then
    raise exception 'No playable character was found.';
  end if;

  if v_character.status <> 'approved' then
    raise exception 'Your character must be approved before playing.';
  end if;

  select *
  into v_settings
  from public.house_of_chances_settings
  where id = 1
  for update;

  if not found then
    raise exception 'House of Chances settings are missing.';
  end if;

  if not v_settings.is_open then
    raise exception 'The House of Chances is presently closed.';
  end if;

  select r.slug
  into v_room_slug
  from public.rooms r
  where r.id = v_character.current_room_id;

  if v_room_slug is distinct from v_settings.room_slug then
    raise exception 'You must be at the House of Chances to play.';
  end if;

  select count(*)::integer
  into v_used
  from public.house_of_chances_plays p
  where p.character_id = v_character.id
    and p.played_on = v_today;

  if v_used >= v_settings.daily_play_limit then
    raise exception 'You have already used all of your plays for today.';
  end if;

  select w.balance
  into v_balance
  from public.character_wallets w
  where w.character_id = v_character.id
  for update;

  if not found then
    raise exception 'Your Remnant wallet could not be found.';
  end if;

  if v_balance < v_settings.play_cost then
    raise exception 'You do not have enough Remnants to play.';
  end if;

  -- ----------------------------------------------------------
  -- CHARGE STAKE
  -- ----------------------------------------------------------

  v_new_balance := v_balance - v_settings.play_cost;

  update public.character_wallets
  set balance = v_new_balance
  where character_id = v_character.id;

  insert into public.remnant_ledger (
    character_id,
    amount,
    balance_after,
    transaction_type,
    source_type,
    source_id,
    reason,
    actor_user_id
  )
  values (
    v_character.id,
    -v_settings.play_cost,
    v_new_balance,
    'expense',
    'house_of_chances',
    v_play_id::text,
    'House of Chances - play',
    v_user_id
  );

  -- ----------------------------------------------------------
  -- SERVER-SIDE 3d100
  -- ----------------------------------------------------------

  v_roll_1 := floor(random() * 100)::integer + 1;
  v_roll_2 := floor(random() * 100)::integer + 1;
  v_roll_3 := floor(random() * 100)::integer + 1;
  v_total := v_roll_1 + v_roll_2 + v_roll_3;

  -- Highest-priority matching rule wins.
  select r.*
  into v_rule
  from public.house_of_chances_prize_rules r
  where r.is_active = true
    and public.house_of_chances_rule_matches(
      r.match_type,
      v_roll_1,
      v_roll_2,
      v_roll_3,
      r.roll_1_min,
      r.roll_1_max,
      r.roll_2_min,
      r.roll_2_max,
      r.roll_3_min,
      r.roll_3_max,
      r.total_min,
      r.total_max
    )
  order by
    r.priority desc,
    r.sort_order asc,
    r.created_at asc
  limit 1;

  -- ----------------------------------------------------------
  -- AWARD MATCHED RULE REWARDS
  -- ----------------------------------------------------------

  if v_rule.id is not null then
    for v_reward in
      select rr.*
      from public.house_of_chances_rule_rewards rr
      where rr.rule_id = v_rule.id
      order by rr.sort_order asc, rr.created_at asc
    loop
      if v_reward.reward_type = 'remnants' then
        v_remnant_win :=
          v_remnant_win + v_reward.remnants_amount;

        v_snapshot :=
          v_snapshot ||
          jsonb_build_array(
            jsonb_build_object(
              'type', 'remnants',
              'amount', v_reward.remnants_amount
            )
          );

      elsif v_reward.reward_type = 'item' then
        select i.name
        into v_item_name
        from public.items i
        where i.id = v_reward.item_id;

        if v_item_name is null then
          raise exception
            'A configured House of Chances prize Item no longer exists.';
        end if;

        perform public.house_of_chances_grant_item(
          v_character.id,
          v_reward.item_id,
          v_reward.quantity
        );

        v_snapshot :=
          v_snapshot ||
          jsonb_build_array(
            jsonb_build_object(
              'type', 'item',
              'item_id', v_reward.item_id,
              'name', v_item_name,
              'quantity', v_reward.quantity
            )
          );
      end if;
    end loop;
  end if;

  -- ----------------------------------------------------------
  -- PAY REMNANT WINNINGS
  -- ----------------------------------------------------------

  if v_remnant_win > 0 then
    v_new_balance := v_new_balance + v_remnant_win;

    update public.character_wallets
    set balance = v_new_balance
    where character_id = v_character.id;

    insert into public.remnant_ledger (
      character_id,
      amount,
      balance_after,
      transaction_type,
      source_type,
      source_id,
      reason,
      actor_user_id
    )
    values (
      v_character.id,
      v_remnant_win,
      v_new_balance,
      'income',
      'house_of_chances',
      v_play_id::text,
      case
        when v_rule.id is not null
          then 'House of Chances - ' || v_rule.name
        else 'House of Chances - winnings'
      end,
      v_user_id
    );
  end if;

  -- ----------------------------------------------------------
  -- PERMANENT PLAY HISTORY
  -- ----------------------------------------------------------

  insert into public.house_of_chances_plays (
    id,
    character_id,
    played_on,
    roll_1,
    roll_2,
    roll_3,
    cost_paid,
    matched_rule_id,
    matched_rule_name,
    reward_snapshot
  )
  values (
    v_play_id,
    v_character.id,
    v_today,
    v_roll_1,
    v_roll_2,
    v_roll_3,
    v_settings.play_cost,
    v_rule.id,
    v_rule.name,
    v_snapshot
  );

  return query
  select
    v_play_id,
    v_roll_1,
    v_roll_2,
    v_roll_3,
    v_total,
    v_settings.play_cost,
    v_rule.id,
    v_rule.name,
    v_snapshot,
    v_new_balance::integer,
    v_used + 1,
    greatest(v_settings.daily_play_limit - (v_used + 1), 0);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.prepare_gift_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  mode text;
  mins integer;
begin
  select g.effect_mode, g.duration_minutes
  into mode, mins
  from public.character_gifts cg
  join public.gifts g on g.id = cg.gift_id
  where cg.id = new.character_gift_id;

  if mode is null then
    raise exception 'Gift ownership record does not exist.';
  end if;

  if mode <> 'temporary' then
    raise exception 'Only temporary Gifts can create activation records.';
  end if;

  if mins is null or mins < 0 then
    raise exception 'Temporary Gift has no valid duration.';
  end if;

  new.activated_at := coalesce(new.activated_at, now());

  if mins = 0 then
    -- Instantaneous Feat:
    -- it begins and ends at exactly the same DB timestamp.
    new.expires_at := new.activated_at;
    new.ended_at := new.activated_at;
  else
    -- Timed Feat.
    new.expires_at :=
      new.activated_at + make_interval(mins => mins);
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.preserve_deleted_character_forum_author()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  preserved_name text;
  forum_topic_triggers_disabled boolean := false;
begin
  preserved_name :=
    'Deleted character (' ||
    coalesce(
      nullif(trim(old.display_name), ''),
      nullif(trim(concat_ws(' ', old.first_name, old.surname)), ''),
      'Unnamed character'
    ) ||
    ')';

  update public.forum_posts
  set
    deleted_author_name = preserved_name,
    author_character_id = null,
    author_user_id = null
  where author_character_id = old.id;

  alter table public.forum_topics disable trigger user;
  forum_topic_triggers_disabled := true;

  update public.forum_topics
  set
    deleted_author_name = preserved_name,
    author_character_id = null,
    author_user_id = null
  where author_character_id = old.id;

  alter table public.forum_topics enable trigger user;
  forum_topic_triggers_disabled := false;

  return old;

exception
  when others then
    if forum_topic_triggers_disabled then
      alter table public.forum_topics enable trigger user;
    end if;
    raise;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_character_audit_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE'
     and old.character_id is not null
     and new.character_id is null
     and old.id = new.id
  then
    return new;
  end if;

  raise exception
    'Character audit history is append-only and cannot be edited or deleted.';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_character_heritage_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if
    old.race_id is distinct from new.race_id
    or old.association_id is distinct from new.association_id
  then
    if
      coalesce(auth.role(), '') <> 'service_role'
      and not public.current_user_is_staff()
    then
      raise exception
        'Race and Association can only be changed by staff.';
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_duplicate_active_gift_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare duplicate_exists boolean;
begin
  select exists(
    select 1
    from public.gift_activations ga
    where ga.character_gift_id=new.character_gift_id
      and ga.ended_at is null
      and ga.expires_at > now()
  ) into duplicate_exists;

  if duplicate_exists then
    raise exception 'This Gift is already active for this character.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_duplicate_active_shape_effect()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if exists (
    select 1
    from public.character_shape_effects e
    where e.target_character_id = new.target_character_id
      and e.shape_id = new.shape_id
      and e.dispelled_at is null
      and (e.expires_at is null or e.expires_at > now())
  ) then
    return null;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_market_transaction_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 -- Permit only FK detachment after the parent has actually been deleted.
 IF TG_OP='UPDATE' AND OLD.character_id IS NOT NULL AND NEW.character_id IS NULL
    AND (to_jsonb(OLD)-'character_id')=(to_jsonb(NEW)-'character_id')
    AND NOT EXISTS(SELECT 1 FROM public.characters c WHERE c.id=OLD.character_id) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Historical financial records are immutable.';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_moderation_history_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION
        'Moderation history records are append-only and cannot be edited or deleted.';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_remnant_ledger_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 -- Permit only FK detachment after the parent has actually been deleted.
 IF TG_OP='UPDATE' AND OLD.character_id IS NOT NULL AND NEW.character_id IS NULL
    AND (to_jsonb(OLD)-'character_id')=(to_jsonb(NEW)-'character_id')
    AND NOT EXISTS(SELECT 1 FROM public.characters c WHERE c.id=OLD.character_id) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Historical financial records are immutable.';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.private_location_can_access(p_room_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    public.private_location_is_staff()
    or (
      public.private_location_owner_enabled(p_room_id)
      and exists (
        select 1
        from public.private_location_members plm
        where plm.room_id = p_room_id
          and plm.character_id = public.private_location_current_character_id()
          and plm.status = 'active'
      )
    );
$function$
;

CREATE OR REPLACE FUNCTION public.private_location_current_character_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select id
  from public.characters
  where user_id = auth.uid()
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.private_location_is_staff()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.staff_members
    where user_id = auth.uid()
  );
$function$
;

CREATE OR REPLACE FUNCTION public.private_location_owner_enabled(p_room_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.private_location_rooms plr
    join public.character_feature_entitlements cfe
      on cfe.character_id = plr.owner_character_id
     and cfe.feature_key = 'private_chat'
     and cfe.enabled = true
    where plr.room_id = p_room_id
  );
$function$
;

CREATE OR REPLACE FUNCTION public.protect_character_attributes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.current_user_is_staff(), false) then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and (
       new.muscles is distinct from old.muscles
       or new.reflexes is distinct from old.reflexes
       or new.vigor is distinct from old.vigor
       or new.brains is distinct from old.brains
       or new.shrewd is distinct from old.shrewd
       or new.presence_score is distinct from old.presence_score
     )
  then
    raise exception
      'Character attributes cannot be changed after creation.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.protect_character_sensitive_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_staff_role text;
begin

  -- Trusted internal/database operations.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  v_staff_role := public.current_staff_role();


  -- ==========================================================
  -- MASTERS' NOTES
  -- Publicly visible, but only Owner/Admin/Master may edit.
  -- ==========================================================

  if new.master_notes is distinct from old.master_notes
     or new.master_notes_expires_at is distinct from old.master_notes_expires_at
  then
    if v_staff_role is null
       or v_staff_role not in ('owner', 'admin', 'master')
    then
      raise exception
        'Only Owners, Admins and Masters can change Masters'' Notes.';
    end if;
  end if;


  -- ==========================================================
  -- STAFF NOTES
  -- Internal notes. Moderator may read them, but only
  -- Owner/Admin/Master may edit them.
  -- ==========================================================

  if new.staff_notes is distinct from old.staff_notes then
    if v_staff_role is null
       or v_staff_role not in ('owner', 'admin', 'master')
    then
      raise exception
        'Only Owners, Admins and Masters can change Staff Notes.';
    end if;
  end if;


  -- Other staff Character editing permissions.
  if coalesce(public.current_user_is_staff(), false) then
    return new;
  end if;


  -- Normal players cannot alter protected identity/system data.
  if new.id is distinct from old.id
     or new.user_id is distinct from old.user_id
     or new.is_system is distinct from old.is_system
     or new.created_at is distinct from old.created_at
  then
    raise exception 'Protected Character field cannot be changed.';
  end if;


  -- Normal players cannot alter mechanics directly.
  if new.expertise is distinct from old.expertise
     or new.current_health is distinct from old.current_health
     or new.life_state is distinct from old.life_state
     or new.zero_hp_at is distinct from old.zero_hp_at
     or new.dead_until is distinct from old.dead_until
     or new.died_at is distinct from old.died_at
     or new.warps_per_day is distinct from old.warps_per_day
     or new.warping_affinity is distinct from old.warping_affinity
  then
    raise exception 'Character mechanics cannot be changed directly.';
  end if;


  if new.approved_at is distinct from old.approved_at
     or new.approved_by is distinct from old.approved_by
     or new.rejection_reason is distinct from old.rejection_reason
     or new.title is distinct from old.title
  then
    raise exception 'Staff-only Character field cannot be changed.';
  end if;


  -- Players may submit their Character.
  if new.status is distinct from old.status then
    if not (
      old.status in ('draft', 'rejected')
      and new.status = 'submitted'
    ) then
      raise exception 'Character status cannot be changed directly.';
    end if;
  end if;


  if new.submitted_at is distinct from old.submitted_at
     and not (
       old.status in ('draft', 'rejected')
       and new.status = 'submitted'
     )
  then
    raise exception 'Submission timestamp cannot be changed directly.';
  end if;


  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.protect_forum_post_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  user_is_staff boolean;
  user_is_deleting_own_post boolean;
  is_anonymising_author boolean;
begin
  user_is_staff :=
    coalesce(
      public.current_user_is_staff(),
      false
    );

  is_anonymising_author :=
    old.author_user_id is not null
    and new.author_user_id is null
    and new.author_character_id is null
    and new.topic_id is not distinct from old.topic_id
    and new.is_initial is not distinct from old.is_initial
    and new.body is not distinct from old.body
    and new.deleted_at is not distinct from old.deleted_at
    and new.deleted_by is not distinct from old.deleted_by;

  if is_anonymising_author then
    return new;
  end if;

  if user_is_staff then
    if new.body is distinct from old.body then
      new.edited_at := now();
    end if;

    /*
     * IMPORTANT:
     * Soft deletion must NOT erase the post body.
     * deleted_at controls visibility; the original
     * content must remain available for restoration.
     */
    return new;
  end if;

  if old.author_user_id <> auth.uid() then
    raise exception
      'You cannot edit this reply.';
  end if;

  if old.deleted_at is not null then
    raise exception
      'A deleted reply cannot be edited.';
  end if;

  user_is_deleting_own_post :=
    old.deleted_at is null
    and new.deleted_at is not null
    and new.deleted_by = auth.uid();

  if new.topic_id is distinct from old.topic_id
     or new.author_user_id is distinct from old.author_user_id
     or new.author_character_id is distinct from old.author_character_id
     or new.is_initial is distinct from old.is_initial
  then
    raise exception
      'You cannot modify protected reply fields.';
  end if;

  if new.deleted_at is distinct from old.deleted_at
     or new.deleted_by is distinct from old.deleted_by
  then
    if not user_is_deleting_own_post then
      raise exception
        'You cannot restore or moderate this reply.';
    end if;
  end if;

  if new.body is distinct from old.body
     and not user_is_deleting_own_post
  then
    new.edited_at := now();
  end if;

  /*
   * Do NOT blank body when deleting.
   * The frontend hides soft-deleted content.
   */
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.protect_forum_topic_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  user_is_staff boolean;
  user_is_deleting_own_topic boolean;
  is_anonymising_author boolean;
  is_statistics_refresh boolean;
begin
  user_is_staff :=
    coalesce(
      public.current_user_is_staff(),
      false
    );

  /*
   * Internal forum statistics refresh.
   *
   * refresh_forum_topic_statistics() updates only:
   *   replies_count
   *   last_post_at
   *   updated_at
   *
   * A normal user replying to somebody else's topic must therefore
   * be allowed to cause this specific update without gaining the
   * ability to edit that discussion themselves.
   */
  is_statistics_refresh :=
    new.author_user_id is not distinct from old.author_user_id
    and new.author_character_id is not distinct from old.author_character_id
    and new.section_id is not distinct from old.section_id
    and new.title is not distinct from old.title
    and new.is_pinned is not distinct from old.is_pinned
    and new.is_locked is not distinct from old.is_locked
    and new.views_count is not distinct from old.views_count
    and new.moved_at is not distinct from old.moved_at
    and new.moved_by is not distinct from old.moved_by
    and new.locked_at is not distinct from old.locked_at
    and new.locked_by is not distinct from old.locked_by
    and new.pinned_at is not distinct from old.pinned_at
    and new.pinned_by is not distinct from old.pinned_by
    and new.deleted_at is not distinct from old.deleted_at
    and new.deleted_by is not distinct from old.deleted_by
    and new.edited_at is not distinct from old.edited_at
    and (
      new.replies_count is distinct from old.replies_count
      or new.last_post_at is distinct from old.last_post_at
      or new.updated_at is distinct from old.updated_at
    );

  if is_statistics_refresh then
    return new;
  end if;

  is_anonymising_author :=
    old.author_user_id is not null
    and new.author_user_id is null
    and new.author_character_id is null
    and new.section_id is not distinct from old.section_id
    and new.title is not distinct from old.title
    and new.is_pinned is not distinct from old.is_pinned
    and new.is_locked is not distinct from old.is_locked
    and new.views_count is not distinct from old.views_count
    and new.replies_count is not distinct from old.replies_count
    and new.last_post_at is not distinct from old.last_post_at
    and new.moved_at is not distinct from old.moved_at
    and new.moved_by is not distinct from old.moved_by
    and new.locked_at is not distinct from old.locked_at
    and new.locked_by is not distinct from old.locked_by
    and new.pinned_at is not distinct from old.pinned_at
    and new.pinned_by is not distinct from old.pinned_by
    and new.deleted_at is not distinct from old.deleted_at
    and new.deleted_by is not distinct from old.deleted_by;

  if is_anonymising_author then
    return new;
  end if;

  if user_is_staff then
    if new.title is distinct from old.title then
      new.edited_at := now();
    end if;

    return new;
  end if;

  if old.author_user_id <> auth.uid() then
    raise exception
      'You cannot edit this discussion.';
  end if;

  if old.deleted_at is not null then
    raise exception
      'A deleted discussion cannot be edited.';
  end if;

  user_is_deleting_own_topic :=
    old.deleted_at is null
    and new.deleted_at is not null
    and new.deleted_by = auth.uid();

  if new.author_user_id is distinct from old.author_user_id
    or new.author_character_id is distinct from old.author_character_id
    or new.section_id is distinct from old.section_id
    or new.is_pinned is distinct from old.is_pinned
    or new.is_locked is distinct from old.is_locked
    or new.views_count is distinct from old.views_count
    or new.replies_count is distinct from old.replies_count
    or new.last_post_at is distinct from old.last_post_at
    or new.moved_at is distinct from old.moved_at
    or new.moved_by is distinct from old.moved_by
    or new.locked_at is distinct from old.locked_at
    or new.locked_by is distinct from old.locked_by
    or new.pinned_at is distinct from old.pinned_at
    or new.pinned_by is distinct from old.pinned_by
  then
    raise exception
      'You cannot modify administrative discussion fields.';
  end if;

  if new.deleted_at is distinct from old.deleted_at
    or new.deleted_by is distinct from old.deleted_by
  then
    if not user_is_deleting_own_topic then
      raise exception
        'You cannot restore or moderate this discussion.';
    end if;
  end if;

  if new.title is distinct from old.title then
    new.edited_at := now();
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.purchase_store_product_with_remnants(p_product_id uuid, p_discount_code text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_product public.store_products%rowtype;
  v_price public.store_product_prices%rowtype;
  v_balance bigint;
  v_new_balance bigint;
  v_order_id uuid;
  v_order_item_id uuid;
  v_grant public.store_product_grants%rowtype;
  v_discount record;
  v_discount_id uuid := null;
  v_user_discount_id uuid := null;
  v_discount_remnants bigint := 0;
  v_total_remnants bigint;
begin
  if v_user_id is null then raise exception 'You must be signed in.'; end if;
  select id into v_character_id from public.characters where user_id=v_user_id limit 1;
  if v_character_id is null then raise exception 'No character is attached to this account.'; end if;

  select * into v_product from public.store_products where id=p_product_id and is_active=true and (available_from is null or available_from<=now()) and (available_until is null or available_until>now());
  if not found then raise exception 'This Store product is not available.'; end if;

  select * into v_price from public.store_product_prices where product_id=p_product_id and is_active=true and remnants_amount is not null order by created_at asc limit 1;
  if not found then raise exception 'This Store product does not have a Remnant price.'; end if;
  if not exists(select 1 from public.store_product_grants where product_id=p_product_id) then raise exception 'This Store product has no fulfilment grants.'; end if;
  if public.store_product_all_owned(v_user_id,v_character_id,p_product_id) then raise exception 'You already own everything included in this product.'; end if;

  if trim(coalesce(p_discount_code,''))<>'' then
    select * into v_discount from public.resolve_store_discount(v_user_id,p_product_id,p_discount_code,'remnants',0,v_price.remnants_amount,null);
    if not found then raise exception 'Discount code is invalid or expired.'; end if;
    v_discount_id := v_discount.discount_code_id;
    v_user_discount_id := v_discount.user_discount_code_id;
    v_discount_remnants := coalesce(v_discount.discount_remnants,0);
  end if;

  v_total_remnants := greatest(0,v_price.remnants_amount-v_discount_remnants);
  select balance into v_balance from public.character_wallets where character_id=v_character_id for update;
  if not found then raise exception 'Character wallet not found.'; end if;
  if v_balance<v_total_remnants then raise exception 'Not enough Remnants.'; end if;
  v_new_balance := v_balance-v_total_remnants;
  update public.character_wallets set balance=v_new_balance where character_id=v_character_id;

  insert into public.store_orders(user_id,character_id,status,payment_method,currency,subtotal_money_minor,discount_money_minor,total_money_minor,subtotal_remnants,discount_remnants,total_remnants,discount_code_id,user_discount_code_id,paid_at)
  values(v_user_id,v_character_id,'paid','remnants',null,0,0,0,v_price.remnants_amount,v_discount_remnants,v_total_remnants,v_discount_id,v_user_discount_id,now()) returning id into v_order_id;

  insert into public.store_order_items(order_id,product_id,product_slug_snapshot,product_name_snapshot,product_type_snapshot,category_snapshot,quantity,unit_money_minor_snapshot,total_money_minor_snapshot,unit_remnants_snapshot,total_remnants_snapshot)
  values(v_order_id,v_product.id,v_product.slug,v_product.name,v_product.product_type,v_product.category,1,null,null,v_price.remnants_amount,v_price.remnants_amount) returning id into v_order_item_id;

  for v_grant in select * from public.store_product_grants where product_id=p_product_id order by created_at asc loop
    insert into public.store_order_grants(order_id,order_item_id,grant_type,portal_skin_id,cosmetic_item_id,music_track_id,feature_key,quantity)
    values(v_order_id,v_order_item_id,v_grant.grant_type,v_grant.portal_skin_id,v_grant.cosmetic_item_id,v_grant.music_track_id,v_grant.feature_key,v_grant.quantity);
  end loop;

  if v_total_remnants<>0 then
    insert into public.remnant_ledger(character_id,amount,balance_after,reason,transaction_type,source_type,source_id)
    values(v_character_id,-v_total_remnants,v_new_balance,'Sepulchria Store purchase: '||v_product.name||case when v_discount_remnants>0 then ' (discount '||v_discount_remnants::text||' Remnants)' else '' end,'store_purchase','store_order',v_order_id);
  end if;

  perform public.fulfil_store_order(v_order_id);
  return v_order_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.raise_if_user_sanctioned(p_user_id uuid, p_capability text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.sanctions%rowtype;
  v_message text;
begin
  select s.*
  into v_row
  from public.sanctions s
  where s.target_user_id = p_user_id
    and s.status = 'active'
    and s.starts_at <= now()
    and (
      s.expires_at is null
      or s.expires_at > now()
    )
    and (
      s.sanction_type in (
        'temporary_suspension',
        'permanent_ban'
      )
      or (
        p_capability = 'communication'
        and s.sanction_type = 'communication_restriction'
      )
      or (
        p_capability = 'forum'
        and s.sanction_type = 'forum_restriction'
      )
      or (
        p_capability = 'game_chat'
        and s.sanction_type = 'game_chat_restriction'
      )
    )
  order by
    case s.sanction_type
      when 'permanent_ban' then 1
      when 'temporary_suspension' then 2
      else 3
    end,
    s.issued_at desc
  limit 1;

  if v_row.id is null then
    return;
  end if;

  v_message :=
    case v_row.sanction_type
      when 'permanent_ban'
        then 'This account has been permanently banned.'
      when 'temporary_suspension'
        then 'This account is temporarily suspended.'
      when 'communication_restriction'
        then 'Private communication is currently restricted on this account.'
      when 'forum_restriction'
        then 'Forum posting is currently restricted on this account.'
      when 'game_chat_restriction'
        then 'Game chat is currently restricted on this account.'
      else
        'This action is currently restricted on this account.'
    end;

  if nullif(btrim(v_row.player_reason), '') is not null then
    v_message := v_message || ' ' || btrim(v_row.player_reason);
  end if;

  if v_row.expires_at is not null then
    v_message :=
      v_message ||
      ' Restriction expires ' ||
      to_char(
        v_row.expires_at at time zone 'UTC',
        'DD-MM-YYYY HH24:MI'
      ) ||
      ' UTC.';
  end if;

  raise exception using
    message = v_message,
    errcode = 'P0001';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rate_limit_direct_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
begin
  select c.user_id
  into v_user_id
  from public.characters c
  where c.id = new.sender_character_id;

  if v_user_id is null then
    return new;
  end if;

  perform public.enforce_db_user_rate_limit(
    'db_private_message_user',
    v_user_id,
    30,
    60
  );

  if exists (
    select 1
    from public.direct_messages dm
    where dm.sender_character_id = new.sender_character_id
      and dm.created_at >= now() - interval '2 seconds'
  ) then
    raise exception
      'Please wait 2 seconds before sending another message.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rate_limit_forum_reply()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
begin
  if coalesce(new.is_initial, false) then
    return new;
  end if;

  v_user_id := new.author_user_id;

  if v_user_id is null
     and new.author_character_id is not null
  then
    select c.user_id
    into v_user_id
    from public.characters c
    where c.id = new.author_character_id;
  end if;

  if v_user_id is not null then
    perform public.enforce_db_user_rate_limit(
      'db_forum_reply_user',
      v_user_id,
      20,
      600
    );
  end if;

  return new;
end;
$function$
;

