CREATE OR REPLACE FUNCTION public.rate_limit_room_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
begin
  -- NPC mechanics are staff-controlled and are not player chat spam.
  if coalesce(new.speaker_type, 'character') = 'npc' then
