;

CREATE OR REPLACE FUNCTION public.rate_limit_support_reply()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ticket_owner uuid;
  v_existing_message boolean;
begin
  select t.opened_by_user_id
  into v_ticket_owner
  from public.tickets t
  where t.id = new.ticket_id;

  if v_ticket_owner is null
     or new.author_user_id is distinct from v_ticket_owner
  then
    return new;
  end if;

  select exists (
    select 1
    from public.ticket_messages tm
    where tm.ticket_id = new.ticket_id
  )
  into v_existing_message;

  -- First message is ticket creation, not a reply.
  if not v_existing_message then
    return new;
  end if;

  perform public.enforce_db_user_rate_limit(
    'db_support_reply_user',
    new.author_user_id,
    20,
    600
  );

  return new;
end;
$function$
;

