    perform public.enforce_db_user_rate_limit(
      'db_support_ticket_user',
      new.opened_by_user_id,
      5,
      3600
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_character_equipment(p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from public.character_equipment ce
  using public.character_items ci,
        public.items i
  where ce.character_id = p_character_id
    and ce.character_item_id = ci.id
    and i.id = ci.item_id
    and (
      ci.character_id <> p_character_id
      or ci.container_instance_id is not null
      or ce.slot_key is distinct from i.equip_slot
      or ce.layer_key is distinct from i.equip_layer
      or not public.character_can_equip_item(p_character_id, ci.item_id)
    );

  delete from public.character_equipment ce
  using public.character_item_instances inst,
        public.items i
  where ce.character_id = p_character_id
    and ce.item_instance_id = inst.id
    and i.id = inst.item_id
    and (
      inst.owner_character_id is distinct from p_character_id
      or inst.vault_status <> 'owned'
      or inst.container_instance_id is not null
      or ce.slot_key is distinct from i.equip_slot
      or ce.layer_key is distinct from i.equip_layer
      or not public.character_can_equip_item(p_character_id, inst.item_id)
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_equipment_after_character_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.reconcile_character_equipment(new.id);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_equipment_after_item_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.reconcile_equipment_for_item(new.id);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_equipment_after_membership_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    perform public.reconcile_character_equipment(old.character_id);
    return old;
  end if;

  perform public.reconcile_character_equipment(new.character_id);

  if tg_op = 'UPDATE'
     and old.character_id is distinct from new.character_id then
    perform public.reconcile_character_equipment(old.character_id);
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_equipment_after_requirement_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item_id uuid;
begin
  if tg_op = 'DELETE' then
    v_item_id := old.item_id;
  else
    v_item_id := new.item_id;
  end if;

  perform public.reconcile_equipment_for_item(v_item_id);

  if tg_op = 'UPDATE'
     and old.item_id is distinct from new.item_id then
    perform public.reconcile_equipment_for_item(old.item_id);
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_equipment_for_item(p_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
begin
  for r in
    select distinct ce.character_id
    from public.character_equipment ce
    left join public.character_items ci
      on ci.id = ce.character_item_id
    left join public.character_item_instances inst
      on inst.id = ce.item_instance_id
    where ci.item_id = p_item_id
       or inst.item_id = p_item_id
  loop
    perform public.reconcile_character_equipment(r.character_id);
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_expired_gift_health(p_character_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  delta_to_reverse integer := 0;
  current_value integer;
  activation_ids uuid[];
begin
  select
    coalesce(sum(ga.health_delta_applied), 0),
    array_agg(ga.id)
  into
    delta_to_reverse,
    activation_ids
  from public.gift_activations ga
  join public.character_gifts cg
    on cg.id = ga.character_gift_id
  where cg.character_id = p_character_id
    and ga.health_reverted_at is null
    and ga.expires_at <= now()
    and ga.health_delta_applied <> 0;

  if delta_to_reverse = 0
     or activation_ids is null
  then
    return 0;
  end if;

  select current_health
  into current_value
  from public.characters
  where id = p_character_id
  for update;

  update public.characters
  set current_health =
    greatest(
      0,
      coalesce(current_value, 0)
      - delta_to_reverse
    )
  where id = p_character_id;

  update public.gift_activations
  set health_reverted_at = now()
  where id = any(activation_ids)
    and health_reverted_at is null;

  return delta_to_reverse;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_expired_item_effects(p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_max_health integer;
begin
  delete from public.character_active_item_effects
  where character_id = p_character_id
    and expires_at <= now();

  v_max_health := public.get_character_current_max_health(p_character_id);

  update public.characters
  set
    current_health = greatest(
      0,
      least(
        coalesce(current_health, v_max_health),
        v_max_health
      )
    ),
    updated_at = now()
  where id = p_character_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reconcile_expired_staff_gifts(p_character_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  assignment_row record;
  activation_health_delta integer;
  passive_health_delta integer;
  total_health_delta integer;
  removed_count integer := 0;
begin
  for assignment_row in
    select cg.id, cg.character_id, g.effect_mode,
           coalesce(g.vigour_modifier,0) as vigour_modifier
    from public.character_gifts cg
    join public.gifts g on g.id = cg.gift_id
    where cg.character_id = p_character_id
      and cg.acquisition_source = 'staff'
      and cg.expires_at is not null
      and cg.expires_at <= now()
    for update of cg
  loop
    select coalesce(sum(ga.health_delta_applied),0)
    into activation_health_delta
    from public.gift_activations ga
    where ga.character_gift_id = assignment_row.id
      and ga.health_reverted_at is null
      and coalesce(ga.health_delta_applied,0) <> 0;

    passive_health_delta :=
      case when assignment_row.effect_mode = 'passive'
        then assignment_row.vigour_modifier * 10 else 0 end;

    total_health_delta := passive_health_delta + activation_health_delta;

    if total_health_delta <> 0 then
      update public.characters
      set current_health = greatest(0, coalesce(current_health,0) - total_health_delta)
      where id = assignment_row.character_id;
    end if;

    update public.gift_activations
    set health_reverted_at = coalesce(health_reverted_at, now()),
        ended_at = coalesce(ended_at, now())
    where character_gift_id = assignment_row.id
      and health_reverted_at is null;

    delete from public.character_gifts where id = assignment_row.id;
    removed_count := removed_count + 1;
  end loop;
  return removed_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.record_account_legal_acceptance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  accepted boolean;
  terms_ver text;
  privacy_ver text;
begin
  accepted :=
    coalesce(
      new.raw_user_meta_data ->> 'legal_terms_accepted',
      'false'
    ) = 'true';

  terms_ver :=
    nullif(
      trim(new.raw_user_meta_data ->> 'terms_version'),
      ''
    );

  privacy_ver :=
    nullif(
      trim(new.raw_user_meta_data ->> 'privacy_version'),
      ''
    );

  if accepted
     and terms_ver is not null
     and privacy_ver is not null then
    insert into public.account_legal_acceptances (
      user_id,
      terms_version,
      privacy_version
    )
    values (
      new.id,
      terms_ver,
      privacy_ver
    )
    on conflict (
      user_id,
      terms_version,
      privacy_version
    ) do nothing;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_character_warping_pool(p_character_id uuid)
 RETURNS character_warping
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.character_warping%rowtype;
  v_boundary timestamptz := public.current_warping_reset_boundary();
begin
  insert into public.character_warping(character_id)
  values (p_character_id)
  on conflict (character_id) do nothing;

  select * into v_row
  from public.character_warping
  where character_id = p_character_id
  for update;

  if v_row.last_daily_reset_at is null or v_row.last_daily_reset_at < v_boundary then
    update public.character_warping
       set remaining_warps = base_warps_per_day,
           last_daily_reset_at = v_boundary,
           updated_at = now()
     where character_id = p_character_id
     returning * into v_row;
  end if;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_forum_topic_statistics()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  affected_topic_id uuid;
begin
  affected_topic_id :=
    case
      when tg_op = 'DELETE'
        then old.topic_id
      else new.topic_id
    end;

  if affected_topic_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  if not exists (
    select 1
    from public.forum_topics
    where id = affected_topic_id
      and deleted_at is null
  ) then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  update public.forum_topics
  set
    replies_count = (
      select greatest(count(*) - 1, 0)::integer
      from public.forum_posts
      where topic_id = affected_topic_id
        and deleted_at is null
    ),
    last_post_at = coalesce(
      (
        select max(created_at)
        from public.forum_posts
        where topic_id = affected_topic_id
          and deleted_at is null
      ),
      forum_topics.created_at
    ),
    updated_at = now()
  where id = affected_topic_id
    and deleted_at is null;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_my_daily_mission_progress()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_day_id uuid;
  v_character_id uuid;
  v_date date;

  r record;

  v_progress integer;
  v_before_progress integer;
  v_before_completed_at timestamptz;

  v_completed integer;
  v_total integer;
  v_required integer;
  v_milestone record;
begin
  v_day_id := public.ensure_my_daily_mission_day();

  select d.character_id, d.mission_date
  into v_character_id, v_date
  from public.daily_mission_days d
  where d.id = v_day_id;

  for r in
    select *
    from public.daily_mission_assignments a
    where a.day_id = v_day_id
    order by a.sort_order, a.id
  loop
    v_progress := 0;
    v_before_progress := coalesce(r.progress, 0);
    v_before_completed_at := r.completed_at;

    if r.objective_type_snapshot = 'gather_attempts' then
      select count(*)::integer
      into v_progress
      from public.daily_mission_events e
      where e.character_id = v_character_id
        and e.mission_date = v_date
        and e.event_type = 'gather_attempt';

    elsif r.objective_type_snapshot = 'gather_specific_location' then
      select count(*)::integer
      into v_progress
      from public.daily_mission_events e
      where e.character_id = v_character_id
        and e.mission_date = v_date
        and e.event_type = 'gather_attempt'
        and e.subject_id =
          r.criteria_snapshot->>'location_id';

    elsif r.objective_type_snapshot = 'gather_distinct_locations' then
      select count(distinct e.subject_id)::integer
      into v_progress
      from public.daily_mission_events e
      where e.character_id = v_character_id
        and e.mission_date = v_date
        and e.event_type = 'gather_attempt'
        and e.subject_id is not null;

    elsif r.objective_type_snapshot = 'gather_ingredients' then
      select coalesce(sum(e.event_value), 0)::integer
      into v_progress
      from public.daily_mission_events e
      where e.character_id = v_character_id
        and e.mission_date = v_date
        and e.event_type = 'gather_ingredient';

    elsif r.objective_type_snapshot = 'instant_chat_distinct_players' then
      select count(distinct e.subject_id)::integer
      into v_progress
      from public.daily_mission_events e
      where e.character_id = v_character_id
        and e.mission_date = v_date
        and e.event_type = 'instant_chat_message'
        and e.subject_id is not null;

    else
      select coalesce(sum(e.event_value), 0)::integer
      into v_progress
      from public.daily_mission_events e
      where e.character_id = v_character_id
        and e.mission_date = v_date
        and e.event_type =
          case r.objective_type_snapshot
            when 'craft_item' then 'craft_item'
            when 'odd_job' then 'odd_job'
            when 'chance_play' then 'chance_play'
            when 'chance_win' then 'chance_win'
            when 'market_buy' then 'market_buy'
            when 'market_sell' then 'market_sell'
            when 'private_message' then 'private_message'
            when 'instant_chat_messages' then 'instant_chat_message'
            when 'location_chat_actions' then 'location_chat_action'
            when 'remnants_earned' then 'remnants_earned'
            when 'remnants_spent' then 'remnants_spent'
            else '__unknown__'
          end;
    end if;

    v_progress :=
      least(
        greatest(coalesce(v_progress, 0), 0),
        r.target_snapshot
      );

    if v_progress <> v_before_progress then
      perform public.daily_mission_audit_event(
        v_character_id,
        'daily_mission_progress',
        'daily_mission_assignment',
        r.id,
        jsonb_build_object(
          'mission_date', v_date,
          'mission_code', r.code_snapshot,
          'mission_name', r.name_snapshot,
          'family', r.family_snapshot,
          'progress_before', v_before_progress,
          'progress_after', v_progress,
          'progress_delta', v_progress - v_before_progress,
          'target', r.target_snapshot
        ),
        jsonb_build_object(
          'objective_type', r.objective_type_snapshot,
          'criteria', r.criteria_snapshot
        )
      );
    end if;

    update public.daily_mission_assignments
    set
      progress = v_progress,
      completed_at =
        case
          when v_progress >= target_snapshot
            then coalesce(completed_at, now())
          else completed_at
        end
    where id = r.id;

    if v_before_completed_at is null
       and v_progress >= r.target_snapshot
    then
      perform public.daily_mission_audit_event(
        v_character_id,
        'daily_mission_completed',
        'daily_mission_assignment',
        r.id,
        jsonb_build_object(
          'mission_date', v_date,
          'mission_code', r.code_snapshot,
          'mission_name', r.name_snapshot,
          'family', r.family_snapshot,
          'progress', v_progress,
          'target', r.target_snapshot
        ),
        jsonb_build_object(
          'objective_type', r.objective_type_snapshot,
          'criteria', r.criteria_snapshot
        )
      );
    end if;
  end loop;

  -- Milestone completion is calculated ONLY from normal missions currently
  -- eligible to count toward milestones.
  select
    count(*) filter (
      where a.completed_at is not null
    )::integer,
    count(*)::integer
  into v_completed, v_total
  from public.daily_mission_assignments a
  where a.day_id = v_day_id
    and a.counts_toward_milestones = true;

  for v_milestone in
    select *
    from public.daily_mission_milestone_claims mc
    where mc.day_id = v_day_id
    order by mc.created_at, mc.id
  loop
    v_required :=
      case
        when v_milestone.is_all_snapshot
          then v_total
        else coalesce(v_milestone.target_count_snapshot, 0)
      end;

    if v_milestone.completed_at is null
       and v_required > 0
       and v_completed >= v_required
    then
      update public.daily_mission_milestone_claims
      set completed_at = now()
      where id = v_milestone.id;

      perform public.daily_mission_audit_event(
        v_character_id,
        'daily_milestone_completed',
        'daily_mission_milestone',
        v_milestone.id,
        jsonb_build_object(
          'mission_date', v_date,
          'milestone_key', v_milestone.milestone_key,
          'milestone_name', v_milestone.name_snapshot,
          'completed_missions', v_completed,
          'required_missions', v_required
        ),
        jsonb_build_object(
          'countable_missions', v_total
        )
      );
    end if;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.remove_friends_after_block()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from public.character_friend_entries
  where (owner_character_id=new.blocker_character_id and target_character_id=new.blocked_character_id)
     or (owner_character_id=new.blocked_character_id and target_character_id=new.blocker_character_id);
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.remove_item_trade_offer(tid uuid, oid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid:=public.my_character_id();
begin
  perform public.enforce_db_user_rate_limit('db_item_trade_mutation_user', auth.uid(), 60, 60);
 delete from item_trade_offers where id=oid and trade_id=tid and character_id=me;
 if not found then raise exception 'Offer not found.'; end if;
 update item_trades set character_one_confirmed=false,character_two_confirmed=false,updated_at=now() where id=tid and status='open';
end $function$
;

CREATE OR REPLACE FUNCTION public.rent_breeze_lodging(p_room_id uuid, p_days integer)
 RETURNS TABLE(rented_room_id uuid, room_name text, days integer, daily_rate integer, total_paid integer, balance_after integer, ends_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_character_id uuid;
  v_room_name text;
  v_daily_rate integer;
  v_balance integer;
  v_total integer;
  v_ends_at timestamptz;
begin
  if v_user_id is null then
    raise exception 'You must be signed in.';
  end if;

  if p_days is null or p_days < 1 or p_days > 7 then
    raise exception 'Choose between 1 and 7 days.';
  end if;

  if exists (
    select 1
    from public.staff_members sm
    where sm.user_id = v_user_id
  ) then
    raise exception 'Staff accounts have free access and cannot own a Breeze Lodgings rental.';
  end if;

  select c.id
  into v_character_id
  from public.characters c
  where c.user_id = v_user_id
    and c.status = 'approved'
  limit 1;

  if v_character_id is null then
    raise exception 'Your character must be approved.';
  end if;

  perform public.expire_breeze_lodging_rentals();

  perform 1
  from public.breeze_lodging_rooms lock_row
  where lock_row.room_id = p_room_id
  for update;

  select r.name, blr.daily_rate
  into v_room_name, v_daily_rate
  from public.breeze_lodging_rooms blr
  join public.rooms r
    on r.id = blr.room_id
  where blr.room_id = p_room_id
    and r.is_active = true;

  if v_daily_rate is null then
    raise exception 'That room is not available for rental.';
  end if;

  if exists (
    select 1
    from public.breeze_lodging_rentals rent
    where rent.room_id = p_room_id
      and rent.status = 'active'
  ) then
    raise exception 'That room has already been rented.';
  end if;

  if exists (
    select 1
    from public.breeze_lodging_rentals rent
    where rent.owner_character_id = v_character_id
      and rent.status = 'active'
  ) then
    raise exception 'You may rent only one room at a time.';
  end if;

  select w.balance
  into v_balance
  from public.character_wallets w
  where w.character_id = v_character_id
  for update;

  if v_balance is null then
    raise exception 'Your Remnant wallet could not be found.';
  end if;

  v_total := v_daily_rate * p_days;

  if v_balance < v_total then
    raise exception 'You do not have enough Remnants.';
  end if;

  v_balance := v_balance - v_total;
  v_ends_at := now() + make_interval(days => p_days);

  update public.character_wallets
  set
    balance = v_balance,
    updated_at = now()
  where character_id = v_character_id;

  insert into public.remnant_ledger (
    character_id,
    amount,
    balance_after,
    transaction_type,
    source_type,
    source_id,
    reason,
    actor_user_id
  )
  values (
    v_character_id,
    -v_total,
    v_balance,
    'expense',
    'breeze_lodgings',
    p_room_id::text,
    format(
      'The Breeze Lodgings — %s, %s day%s at %s Remnants/day',
      v_room_name,
      p_days,
      case when p_days = 1 then '' else 's' end,
      v_daily_rate
    ),
    v_user_id
  );

  insert into public.breeze_lodging_rentals (
    room_id,
    owner_character_id,
    days,
    daily_rate,
    total_paid,
    starts_at,
    ends_at,
    status
  )
  values (
    p_room_id,
    v_character_id,
    p_days,
    v_daily_rate,
    v_total,
    now(),
    v_ends_at,
    'active'
  );

  return query
  select
    p_room_id,
    v_room_name,
    p_days,
    v_daily_rate,
    v_total,
    v_balance,
    v_ends_at;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_opposed_item_use(p_action_id uuid, p_apply_effects boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_action public.opposed_actions%rowtype;
  v_item public.items%rowtype;
  v_my_character uuid;
  v_attacker_user uuid;
  v_attacker_is_npc boolean := false;
  v_source_key text;
  v_quantity integer;
  v_charges integer;
  v_rpc jsonb;
  v_audit_action_id uuid;
begin
  select *
  into v_action
  from public.opposed_actions
  where id = p_action_id
  for update;

  if v_action.id is null then
    raise exception 'Opposed Action not found.';
  end if;

  if v_action.status <> 'pending' then
    raise exception 'That Action is no longer pending.';
  end if;

  v_my_character := public.my_character_id();

  if v_my_character = v_action.target_character_id then
    null;
  elsif public.is_staff_user() and exists (
    select 1
    from public.characters c
    join public.npcs n on n.character_id = c.id
    where c.id = v_action.target_character_id
      and c.is_system = true
      and n.is_active = true
      and n.is_location_active = true
      and n.current_room_id = v_action.room_id
  ) then
    null;
  else
    raise exception 'You cannot resolve that Action.';
  end if;

  if v_action.action_kind <> 'item' then
    return jsonb_build_object('ok', true, 'handled', false);
  end if;

  if v_action.source_item_id is null
     or v_action.source_record_kind is null
     or v_action.source_record_id is null then
    raise exception 'This opposed Item is missing its source Inventory record.';
  end if;

  select *
  into v_item
  from public.items
  where id = v_action.source_item_id;

  if v_item.id is null then
    raise exception 'The source Item no longer exists.';
  end if;

  v_source_key :=
    case
      when v_action.source_record_kind = 'unique'
        then 'unique:' || v_action.source_record_id::text
      else 'standard:' || v_action.source_item_id::text
    end;

  if exists (
    select 1
    from public.character_item_use_cooldowns c
    where c.character_id = v_action.attacker_character_id
      and c.source_key = v_source_key
      and c.ready_at > now()
  ) then
    raise exception 'This Item is still on cooldown.';
  end if;

  if not p_apply_effects then
    v_audit_action_id :=
      public.character_audit_begin_action(
        'item_used',
        'item_use'
      );

    if v_item.use_behaviour = 'consumable' then
      if v_action.source_record_kind = 'standard' then
        select quantity
        into v_quantity
        from public.character_items
        where id = v_action.source_record_id
          and character_id = v_action.attacker_character_id
        for update;

        if coalesce(v_quantity, 0) <= 0 then
          raise exception 'This Item has no uses remaining.';
        end if;

        if v_quantity = 1 then
          delete from public.character_items
          where id = v_action.source_record_id
            and character_id = v_action.attacker_character_id;
        else
          update public.character_items
          set quantity = quantity - 1
          where id = v_action.source_record_id
            and character_id = v_action.attacker_character_id;
        end if;
      else
        delete from public.character_item_instances
        where id = v_action.source_record_id
          and owner_character_id = v_action.attacker_character_id
          and vault_status = 'owned';

        if not found then
          raise exception 'That Item is no longer in the attacker''s Inventory.';
        end if;
      end if;

    elsif v_item.use_behaviour = 'limited_charges' then
      if v_action.source_record_kind <> 'unique' then
        raise exception 'Limited-charge Items require an individual Item instance.';
      end if;

      select charges_remaining
      into v_charges
      from public.character_item_instances
      where id = v_action.source_record_id
        and owner_character_id = v_action.attacker_character_id
        and vault_status = 'owned'
      for update;

      if coalesce(v_charges, 0) <= 0 then
        raise exception 'This Item has no charges remaining.';
      end if;

      update public.character_item_instances
      set charges_remaining = v_charges - 1
      where id = v_action.source_record_id
        and owner_character_id = v_action.attacker_character_id
        and vault_status = 'owned';
    end if;

    perform public.character_audit_write_event(
      v_action.attacker_character_id,
      'item_used',
      'item_use',
      v_audit_action_id,
      jsonb_build_object(
        'item_id', v_item.id,
        'item_name', v_item.name,
        'record_kind', v_action.source_record_kind,
        'target_character_id', v_action.target_character_id,
        'opposed_action_id', p_action_id,
        'effects_applied', false,
        'countered', true
      ),
      'item_use',
      v_action.source_record_id::text
    );

    return jsonb_build_object(
      'ok', true,
      'handled', true,
      'effects_applied', false,
      'cooldown_started', false
    );
  end if;

  select exists (
    select 1
    from public.characters c
    join public.npcs n on n.character_id = c.id
    where c.id = v_action.attacker_character_id
      and c.is_system = true
      and n.is_active = true
      and n.is_location_active = true
      and n.current_room_id = v_action.room_id
  )
  into v_attacker_is_npc;

  if v_attacker_is_npc then
    select private.use_character_inventory_record_targeted_internal(
      v_action.attacker_character_id,
      v_action.source_record_kind,
      v_action.source_record_id,
      v_action.target_character_id
    )::jsonb
    into v_rpc;

    return coalesce(v_rpc, '{}'::jsonb);
  end if;

  select user_id
  into v_attacker_user
  from public.characters
  where id = v_action.attacker_character_id;

  if v_attacker_user is null then
    raise exception 'Attacker account could not be resolved.';
  end if;

  perform set_config(
    'request.jwt.claim.sub',
    v_attacker_user::text,
    true
  );

  begin
    select public.use_own_inventory_record_targeted(
      v_action.source_record_kind,
      v_action.source_record_id,
      v_action.target_character_id
    )::jsonb
    into v_rpc;
  exception
    when others then
      if sqlerrm not ilike '%no configured Use effect%' then
        raise;
      end if;

      if v_item.use_behaviour = 'consumable' then
        if v_action.source_record_kind = 'standard' then
          select quantity
          into v_quantity
          from public.character_items
          where id = v_action.source_record_id
            and character_id = v_action.attacker_character_id
          for update;

          if coalesce(v_quantity, 0) <= 0 then
            raise exception 'This Item has no uses remaining.';
          end if;

          if v_quantity = 1 then
            delete from public.character_items
            where id = v_action.source_record_id
              and character_id = v_action.attacker_character_id;
          else
            update public.character_items
            set quantity = quantity - 1
            where id = v_action.source_record_id
              and character_id = v_action.attacker_character_id;
          end if;
        else
          delete from public.character_item_instances
          where id = v_action.source_record_id
            and owner_character_id = v_action.attacker_character_id
            and vault_status = 'owned';
        end if;

      elsif v_item.use_behaviour = 'limited_charges' then
        select charges_remaining
        into v_charges
        from public.character_item_instances
        where id = v_action.source_record_id
          and owner_character_id = v_action.attacker_character_id
          and vault_status = 'owned'
        for update;

        if coalesce(v_charges, 0) <= 0 then
          raise exception 'This Item has no charges remaining.';
        end if;

        update public.character_item_instances
        set charges_remaining = v_charges - 1
        where id = v_action.source_record_id
          and owner_character_id = v_action.attacker_character_id
          and vault_status = 'owned';
      end if;

      if coalesce(v_item.cooldown_minutes, 0) > 0 then
        insert into public.character_item_use_cooldowns(
          character_id,
          source_key,
          ready_at
        )
        values(
          v_action.attacker_character_id,
          v_source_key,
          now() + make_interval(mins => v_item.cooldown_minutes)
        )
        on conflict (character_id, source_key)
        do update set ready_at = excluded.ready_at;
      end if;

      v_rpc := jsonb_build_object(
        'ok', true,
        'blocked', false,
        'damage_only_fallback', true
      );
  end;

  return coalesce(v_rpc, '{}'::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_store_discount(p_user_id uuid, p_product_id uuid, p_code text, p_payment_method text, p_subtotal_money_minor integer DEFAULT 0, p_subtotal_remnants bigint DEFAULT 0, p_currency text DEFAULT NULL::text)
 RETURNS TABLE(discount_code_id uuid, user_discount_code_id uuid, discount_type text, discount_value integer, discount_money_minor integer, discount_remnants bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text := upper(trim(coalesce(p_code, '')));
  v_product public.store_products%rowtype;
  v_discount public.store_discount_codes%rowtype;
  v_user_code public.store_user_discount_codes%rowtype;
  v_total_count integer;
  v_user_count integer;
  v_money integer := 0;
  v_remnants bigint := 0;
begin
  if v_code = '' then return; end if;

  select * into v_product
  from public.store_products
  where id = p_product_id
    and is_active = true
    and (available_from is null or available_from <= now())
    and (available_until is null or available_until > now());

  if not found then
    raise exception 'This Store product is not available.';
  end if;

  select udc.* into v_user_code
  from public.store_user_discount_codes udc
  where udc.user_id = p_user_id
    and upper(udc.code) = v_code
    and udc.used_at is null
    and udc.expires_at > now()
  limit 1;

  if found then
    select * into v_discount
    from public.store_discount_codes
    where id = v_user_code.discount_code_id
      and is_active = true
      and (starts_at is null or starts_at <= now())
      and (ends_at is null or ends_at > now());

    if not found then
      raise exception 'This discount code is no longer active.';
    end if;
  else
    select * into v_discount
    from public.store_discount_codes
    where upper(code) = v_code
      and is_public = true
      and is_active = true
      and (starts_at is null or starts_at <= now())
      and (ends_at is null or ends_at > now())
    limit 1;

    if not found then
      raise exception 'Discount code is invalid or expired.';
    end if;
  end if;

  if v_discount.scope_type = 'category'
     and v_discount.scope_category is distinct from v_product.category then
    raise exception 'This discount does not apply to this product.';
  end if;

  if v_discount.scope_type = 'products'
     and not exists (
       select 1
       from public.store_discount_code_products dcp
       where dcp.discount_code_id = v_discount.id
         and dcp.product_id = p_product_id
     ) then
    raise exception 'This discount does not apply to this product.';
  end if;

  select count(*) into v_total_count
  from public.store_discount_redemptions
  where store_discount_redemptions.discount_code_id = v_discount.id;

  if v_discount.max_redemptions is not null
     and v_total_count >= v_discount.max_redemptions then
    raise exception 'This discount has reached its usage limit.';
  end if;

  select count(*) into v_user_count
  from public.store_discount_redemptions
  where store_discount_redemptions.discount_code_id = v_discount.id
    and store_discount_redemptions.user_id = p_user_id;

  if v_user_count >= v_discount.max_redemptions_per_user then
    raise exception 'You have already used this discount the maximum number of times.';
  end if;

  if p_payment_method = 'stripe' then
    if v_discount.discount_type = 'fixed_remnants' then
      raise exception 'This discount can only be used with Remnants.';
    end if;

    if v_discount.minimum_money_minor is not null
       and p_subtotal_money_minor < v_discount.minimum_money_minor then
      raise exception 'This order does not meet the discount minimum.';
    end if;

    if v_discount.discount_type = 'percentage' then
      v_money :=
        floor(
          (p_subtotal_money_minor::numeric * v_discount.discount_value) / 100
        )::integer;
    else
      if upper(coalesce(v_discount.currency, ''))
         <> upper(coalesce(p_currency, '')) then
        raise exception 'This discount is for a different currency.';
      end if;

      v_money :=
        least(v_discount.discount_value, p_subtotal_money_minor);
    end if;

    if v_money <= 0 then
      raise exception 'This discount does not reduce this order.';
    end if;

  elsif p_payment_method = 'remnants' then
    if v_discount.discount_type = 'fixed_money' then
      raise exception 'This discount can only be used with real money.';
    end if;

    if v_discount.minimum_remnants is not null
       and p_subtotal_remnants < v_discount.minimum_remnants then
      raise exception 'This order does not meet the discount minimum.';
    end if;

    if v_discount.discount_type = 'percentage' then
      v_remnants :=
        floor(
          (p_subtotal_remnants::numeric * v_discount.discount_value) / 100
        )::bigint;
    else
      v_remnants :=
        least(
          v_discount.discount_value::bigint,
          p_subtotal_remnants
        );
    end if;

    if v_remnants <= 0 then
      raise exception 'This discount does not reduce this order.';
    end if;

  else
    raise exception 'Unsupported Store payment method.';
  end if;

  return query
  select
    v_discount.id,
    case
      when v_user_code.id is not null then v_user_code.id
      else null
    end,
    v_discount.discount_type,
    v_discount.discount_value,
    v_money,
    v_remnants;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.revive_direct_conversation_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.direct_conversation_participants
  set deleted_at = null, archived_at = null
  where conversation_id = new.conversation_id;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_store_order_entitlements(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.store_orders%rowtype;
  v_grant public.store_order_grants%rowtype;

  v_default_skin_id uuid;
  v_cosmetic_category text;
begin
  select *
  into v_order
  from public.store_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Store order not found.';
  end if;

  for v_grant in
    select *
    from public.store_order_grants
    where order_id = p_order_id
      and fulfilled_at is not null
      and revoked_at is null
  loop

    update public.store_order_grants
    set revoked_at = now()
    where id = v_grant.id;

    ----------------------------------------------------------------
    -- PORTAL SKIN
    ----------------------------------------------------------------
    if v_grant.grant_type = 'portal_skin' then

      if not exists (
        select 1
        from public.store_order_grants g
        join public.store_orders o
          on o.id = g.order_id
        where g.id <> v_grant.id
          and g.grant_type = 'portal_skin'
          and g.portal_skin_id = v_grant.portal_skin_id
          and g.fulfilled_at is not null
          and g.revoked_at is null
          and o.user_id = v_order.user_id
          and o.status not in ('refunded', 'cancelled', 'failed')
      ) then

        update public.user_portal_skin_entitlements
        set
          enabled = false,
          updated_at = now()
        where user_id = v_order.user_id
          and skin_id = v_grant.portal_skin_id
          and source = 'paid';

      end if;

      /*
       * If that skin is no longer owned from ANY source,
       * stop using it immediately and return to the default skin.
       */
      if not exists (
        select 1
        from public.user_portal_skin_entitlements
        where user_id = v_order.user_id
          and skin_id = v_grant.portal_skin_id
          and enabled = true
      ) then

        select id
        into v_default_skin_id
        from public.portal_skins
        where is_default = true
          and is_active = true
        limit 1;

        if v_default_skin_id is not null then
          update public.user_portal_preferences
          set
            selected_skin_id = v_default_skin_id,
            updated_at = now()
          where user_id = v_order.user_id
            and selected_skin_id = v_grant.portal_skin_id;
        else
          update public.user_portal_preferences
          set
            selected_skin_id = null,
            updated_at = now()
          where user_id = v_order.user_id
            and selected_skin_id = v_grant.portal_skin_id;
        end if;

      end if;


    ----------------------------------------------------------------
    -- COSMETIC
    ----------------------------------------------------------------
    elsif v_grant.grant_type = 'cosmetic' then

      if not exists (
        select 1
        from public.store_order_grants g
        join public.store_orders o
          on o.id = g.order_id
        where g.id <> v_grant.id
          and g.grant_type = 'cosmetic'
          and g.cosmetic_item_id = v_grant.cosmetic_item_id
          and g.fulfilled_at is not null
          and g.revoked_at is null
          and o.character_id = v_order.character_id
          and o.status not in ('refunded', 'cancelled', 'failed')
      ) then

        update public.character_cosmetic_entitlements
        set
          enabled = false,
          updated_at = now()
        where character_id = v_order.character_id
          and cosmetic_item_id = v_grant.cosmetic_item_id
          and source = 'paid';

      end if;

      /*
       * Only unequip it if no enabled entitlement remains
       * from any source.
       */
      if not exists (
        select 1
        from public.character_cosmetic_entitlements
        where character_id = v_order.character_id
          and cosmetic_item_id = v_grant.cosmetic_item_id
          and enabled = true
      ) then

        select category
        into v_cosmetic_category
        from public.cosmetic_items
        where id = v_grant.cosmetic_item_id;

        case v_cosmetic_category

          when 'sheet_frame' then
            update public.character_cosmetic_preferences
            set equipped_sheet_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_sheet_frame_id = v_grant.cosmetic_item_id;

          when 'chat_frame' then
            update public.character_cosmetic_preferences
            set equipped_chat_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_chat_frame_id = v_grant.cosmetic_item_id;

          when 'portrait_frame' then
            update public.character_cosmetic_preferences
            set equipped_portrait_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_portrait_frame_id = v_grant.cosmetic_item_id;

          when 'profile_background' then
            update public.character_cosmetic_preferences
            set equipped_profile_background_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_profile_background_id = v_grant.cosmetic_item_id;

          when 'pm_frame' then
            update public.character_cosmetic_preferences
            set equipped_pm_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_pm_frame_id = v_grant.cosmetic_item_id;

          when 'instant_chat_frame' then
            update public.character_cosmetic_preferences
            set equipped_instant_chat_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_instant_chat_frame_id = v_grant.cosmetic_item_id;

          when 'forum_frame' then
            update public.character_cosmetic_preferences
            set equipped_forum_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_forum_frame_id = v_grant.cosmetic_item_id;

          when 'action_style' then
            update public.character_cosmetic_preferences
            set equipped_action_style_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_action_style_id = v_grant.cosmetic_item_id;

          when 'nameplate' then
            update public.character_cosmetic_preferences
            set equipped_nameplate_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_nameplate_id = v_grant.cosmetic_item_id;

          when 'profile_crest' then
            update public.character_cosmetic_preferences
            set equipped_profile_crest_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_profile_crest_id = v_grant.cosmetic_item_id;

          when 'action_flourish' then
            update public.character_cosmetic_preferences
            set equipped_action_flourish_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_action_flourish_id = v_grant.cosmetic_item_id;

          when 'whisper_style' then
            update public.character_cosmetic_preferences
            set equipped_whisper_style_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_whisper_style_id = v_grant.cosmetic_item_id;

          when 'off_character_message_frame' then
            update public.character_cosmetic_preferences
            set equipped_off_character_message_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_off_character_message_frame_id = v_grant.cosmetic_item_id;

          when 'header_control_frame' then
            update public.character_cosmetic_preferences
            set equipped_header_control_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_header_control_frame_id = v_grant.cosmetic_item_id;

          when 'left_panel_frame' then
            update public.character_cosmetic_preferences
            set equipped_left_panel_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_left_panel_frame_id = v_grant.cosmetic_item_id;

          when 'right_panel_frame' then
            update public.character_cosmetic_preferences
            set equipped_right_panel_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_right_panel_frame_id = v_grant.cosmetic_item_id;

          when 'centre_panel_frame' then
            update public.character_cosmetic_preferences
            set equipped_centre_panel_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_centre_panel_frame_id = v_grant.cosmetic_item_id;

          when 'location_frame' then
            update public.character_cosmetic_preferences
            set equipped_location_frame_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_location_frame_id = v_grant.cosmetic_item_id;

          when 'location_atmosphere' then
            update public.character_cosmetic_preferences
            set equipped_location_atmosphere_id = null, updated_at = now()
            where character_id = v_order.character_id
              and equipped_location_atmosphere_id = v_grant.cosmetic_item_id;

          else
            null;

        end case;

      end if;


    ----------------------------------------------------------------
    -- MUSIC
    ----------------------------------------------------------------
    elsif v_grant.grant_type = 'music' then

      if not exists (
        select 1
        from public.store_order_grants g
        join public.store_orders o
          on o.id = g.order_id
        where g.id <> v_grant.id
          and g.grant_type = 'music'
          and g.music_track_id = v_grant.music_track_id
          and g.fulfilled_at is not null
          and g.revoked_at is null
          and o.character_id = v_order.character_id
          and o.status not in ('refunded', 'cancelled', 'failed')
      ) then

        update public.character_music_entitlements
        set enabled = false
        where character_id = v_order.character_id
          and music_track_id = v_grant.music_track_id
          and source = 'paid';

      end if;

      /*
       * If the refunded track is no longer owned,
       * remove it from the active music preference too.
       */
      if not exists (
        select 1
        from public.character_music_entitlements
        where character_id = v_order.character_id
          and music_track_id = v_grant.music_track_id
          and enabled = true
      ) then

        update public.character_music_preferences
        set
          selected_track_id = null,
          use_personal_music = false
        where character_id = v_order.character_id
          and selected_track_id = v_grant.music_track_id;

      end if;


    ----------------------------------------------------------------
    -- FEATURES: FRIEND LIST / PRIVATE LOCATION
    ----------------------------------------------------------------
    elsif v_grant.grant_type = 'feature' then

      if not exists (
        select 1
        from public.store_order_grants g
        join public.store_orders o
          on o.id = g.order_id
        where g.id <> v_grant.id
          and g.grant_type = 'feature'
          and g.feature_key = v_grant.feature_key
          and g.fulfilled_at is not null
          and g.revoked_at is null
          and o.character_id = v_order.character_id
          and o.status not in ('refunded', 'cancelled', 'failed')
      ) then

        update public.character_feature_entitlements
        set
          enabled = false,
          updated_at = now()
        where character_id = v_order.character_id
          and feature_key = v_grant.feature_key
          and source = 'paid';

      end if;

      /*
       * No destructive cleanup here.
       *
       * Friend List:
       *   keep friendships/data; access disappears while entitlement is off.
       *
       * Private Location:
       *   keep room/members/settings; visibility/access disappears while
       *   entitlement is off.
       */

    end if;

  end loop;


  update public.store_orders
  set
    status = 'refunded',
    refunded_at = coalesce(refunded_at, now())
  where id = p_order_id;

end;
$function$
;

CREATE OR REPLACE FUNCTION public.rollback_failed_shape_cast(p_cast_id uuid, p_character_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cast public.shape_casts%rowtype;
  v_price_key text;
  v_price_days integer;
  v_price record;
  v_restored_expiry timestamptz;
  v_reset_date date;
  v_used integer;
begin
  select sc.*
    into v_cast
  from public.shape_casts sc
  where sc.id = p_cast_id
    and sc.caster_character_id = p_character_id
    and sc.status = 'resolving'
  for update;

  if v_cast.id is null then
    return jsonb_build_object(
      'rolled_back', false,
      'reason', 'That Warp is no longer eligible for rollback.'
    );
  end if;

  -- Never refund a cast whose target mechanics have already been resolved.
  if exists (
    select 1
    from public.shape_cast_targets t
    where t.cast_id = p_cast_id
      and (
        t.resolved_at is not null
        or t.outcome not in ('pending', 'manual')
      )
  ) then
    return jsonb_build_object(
      'rolled_back', false,
      'reason', 'The Warp already resolved one or more targets.'
    );
  end if;

  -- Persistent Shape/Feat effects created from this cast prove mechanics ran.
  if exists (
    select 1
    from public.character_effects e
    where e.source_instance_id = p_cast_id
  ) then
    return jsonb_build_object(
      'rolled_back', false,
      'reason', 'The Warp already created a persistent effect.'
    );
  end if;

  /*
   * create_price_for_shape_cast either creates a new Price row or extends an
   * existing active row by exactly duration_days. Restore that duration before
   * marking the cast failed.
   */
  select
    s.price_key,
    wp.duration_days
  into
    v_price_key,
    v_price_days
  from public.shapes s
  left join public.warping_prices wp
    on wp.key = s.price_key
  where s.id = v_cast.shape_id;

  if v_price_key is not null and v_price_days is not null then
    for v_price in
      select
        cpe.id,
        cpe.expires_at
      from public.character_price_effects cpe
      where cpe.cast_id = p_cast_id
        and cpe.character_id = p_character_id
        and cpe.price_key = v_price_key
      for update
    loop
      v_restored_expiry :=
        v_price.expires_at -
        make_interval(days => v_price_days);

      /*
       * If subtracting this cast's duration takes the row back to/before the
       * cast time, this cast created the Price row rather than extending one.
       */
      if v_restored_expiry <= v_cast.created_at then
        delete from public.character_price_effects
        where id = v_price.id;
      else
        update public.character_price_effects
        set expires_at = v_restored_expiry
        where id = v_price.id;
      end if;
    end loop;
  end if;

  -- Refund an Item-Shape reservation/charge from the UTC day of the cast.
  if v_cast.resource_type = 'item'
     and v_cast.item_shape_id is not null
     and v_cast.item_record_kind is not null
     and v_cast.item_record_id is not null then

    v_reset_date :=
      (v_cast.created_at at time zone 'utc')::date;

    update public.character_item_shape_usage
    set
      charges_used = greatest(0, charges_used - 1),
      updated_at = now()
    where character_id = p_character_id
      and item_shape_id = v_cast.item_shape_id
      and item_record_kind = v_cast.item_record_kind
      and item_record_id = v_cast.item_record_id
      and reset_date = v_reset_date
      and charges_used > 0
    returning charges_used
    into v_used;

    if v_used = 0 then
      delete from public.character_item_shape_usage
      where character_id = p_character_id
        and item_shape_id = v_cast.item_shape_id
        and item_record_kind = v_cast.item_record_kind
        and item_record_id = v_cast.item_record_id
        and reset_date = v_reset_date
        and charges_used = 0;
    end if;
  end if;

  -- Pending/manual target rows must disappear so no Save popup survives.
  delete from public.shape_cast_targets
  where cast_id = p_cast_id;

  update public.shape_casts
  set
    status = 'failed',
    dispel_target_character_id = null,
    dispel_effect_id = null
  where id = p_cast_id;

  return jsonb_build_object(
    'rolled_back', true,
    'resource_type', v_cast.resource_type
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.run_order_monthly_payroll(p_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_month date := date_trunc('month', p_month)::date;
  v_row record;
  v_balance bigint;
  v_paid integer := 0;
begin
  for v_row in
    select
      m.character_id,
      m.order_id,
      m.order_level_id,
      l.level,
      l.monthly_pay,
      o.name as order_name
    from public.order_memberships m
    join public.order_levels l
      on l.id = m.order_level_id
     and l.order_id = m.order_id
    join public.orders o
      on o.id = m.order_id
    where l.monthly_pay > 0
      and o.is_active = true
    order by m.character_id, m.order_id
  loop
    insert into public.order_payroll_runs (
      pay_month, order_id, order_level_id, character_id, amount
    )
    values (
      v_month, v_row.order_id, v_row.order_level_id, v_row.character_id, v_row.monthly_pay
    )
    on conflict (pay_month, order_id, character_id) do nothing;

    if not found then
      continue;
    end if;

    insert into public.character_wallets (character_id, balance)
    values (v_row.character_id, 0)
    on conflict (character_id) do nothing;

    perform 1
    from public.character_wallets
    where character_id = v_row.character_id
    for update;

    update public.character_wallets
    set balance = balance + v_row.monthly_pay
    where character_id = v_row.character_id
    returning balance into v_balance;

    insert into public.remnant_ledger (
      character_id,
      amount,
      balance_after,
      transaction_type,
      source_type,
      source_id,
      reason,
      actor_user_id
    )
    values (
      v_row.character_id,
      v_row.monthly_pay,
      v_balance,
      'income',
      'order_pay',
      v_row.order_id::text || ':' || v_month::text,
      v_row.order_name || ' — Level ' || v_row.level || ' monthly pay',
      null
    );

    v_paid := v_paid + 1;
  end loop;

  return v_paid;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.safe_evaluate_character_trophies(p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_character_id is null then
    return;
  end if;

  begin
    perform public.evaluate_character_trophies(
      p_character_id
    );
  exception
    when others then
      raise warning
        'Trophy evaluation failed for character %: %',
        p_character_id,
        sqlerrm;
  end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.send_direct_message_fast(p_conversation_id uuid, p_body text, p_client_nonce uuid, p_message_mode text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user_id uuid:=auth.uid(); v_character_id uuid; v_other_ids uuid[]; v_new_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required.'; end if;
  perform public.raise_if_user_sanctioned(v_user_id,'communication');
  if p_message_mode not in ('ongame','offgame') then raise exception 'The selected message type is invalid.'; end if;
  select id into v_character_id from public.characters where user_id=v_user_id and status='approved' limit 1;
  if v_character_id is null then raise exception 'Your character must be approved before sending private messages.'; end if;
  if not exists(select 1 from public.direct_conversation_participants where conversation_id=p_conversation_id and character_id=v_character_id and deleted_at is null) then raise exception 'Conversation not found.'; end if;
  select array_agg(character_id) into v_other_ids from public.direct_conversation_participants where conversation_id=p_conversation_id and character_id<>v_character_id and deleted_at is null;
  if coalesce(array_length(v_other_ids,1),0)=0 then raise exception 'Recipient not found.'; end if;
  if exists(select 1 from public.characters where id=any(v_other_ids) and is_system=true) then raise exception 'Automated system conversations cannot receive replies.'; end if;
  if exists(select 1 from public.character_blocks b where (b.blocker_character_id=v_character_id and b.blocked_character_id=any(v_other_ids)) or (b.blocked_character_id=v_character_id and b.blocker_character_id=any(v_other_ids))) then raise exception 'This conversation is unavailable.'; end if;
  if exists(select 1 from public.direct_messages where conversation_id=p_conversation_id and sender_character_id=v_character_id and created_at>=now()-interval '2 seconds') then raise exception 'Please wait 2 seconds before sending another message.'; end if;
  insert into public.direct_messages(conversation_id,sender_character_id,body,client_nonce,message_mode) values(p_conversation_id,v_character_id,p_body,p_client_nonce,p_message_mode) returning id into v_new_id;
  update public.direct_conversations set updated_at=now() where id=p_conversation_id;
  update public.direct_conversation_participants set archived_at=null where conversation_id=p_conversation_id and deleted_at is null;
  return v_new_id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.send_instant_chat_message(p_conversation_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := public.instant_chat_current_character_id();
  other_id uuid;
  new_id uuid;
  recent_message_count integer;
begin
  perform public.raise_if_user_sanctioned(
    auth.uid(),
    'communication'
  );

  p_body := btrim(coalesce(p_body,''));

  if me is null then
    raise exception 'Approved character required.';
  end if;

  if char_length(p_body) < 1
     or char_length(p_body) > 1200 then
    raise exception 'Message must contain 1–1200 characters.';
  end if;

  /*
   * SECURITY:
   * Maximum 30 Instant Chat messages per minute
   * for each character.
   */
  select count(*)
  into recent_message_count
  from public.instant_chat_messages
  where sender_character_id = me
    and created_at >= now() - interval '1 minute';

  if recent_message_count >= 30 then
    raise exception
      'You are sending Instant Chat messages too quickly. Please wait a moment before trying again.';
  end if;

  select case
    when character_one_id = me
      then character_two_id
    when character_two_id = me
      then character_one_id
  end
  into other_id
  from public.instant_chat_conversations
  where id = p_conversation_id;

  if other_id is null then
    raise exception 'Conversation not found.';
  end if;

  if not coalesce(
    (
      select enabled
      from public.instant_chat_settings
      where character_id = me
    ),
    true
  ) then
    raise exception
      'Enable instant chat before sending messages.';
  end if;

  if not coalesce(
    (
      select enabled
      from public.instant_chat_settings
      where character_id = other_id
    ),
    false
  ) then
    raise exception
      'That character has disabled instant chat.';
  end if;

  if exists (
    select 1
    from public.character_blocks b
    where
      (
        b.blocker_character_id = me
        and
        b.blocked_character_id = other_id
      )
      or
      (
        b.blocker_character_id = other_id
        and
        b.blocked_character_id = me
      )
  ) then
    raise exception
      'Instant chat is unavailable between these characters.';
  end if;

  insert into public.instant_chat_messages(
    conversation_id,
    sender_character_id,
    body
  )
  values(
    p_conversation_id,
    me,
    p_body
  )
  returning id into new_id;

  update public.instant_chat_conversations
  set updated_at = now()
  where id = p_conversation_id;

  update public.instant_chat_participants
  set last_read_at = now()
  where conversation_id = p_conversation_id
    and character_id = me;

  return new_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_codex_published_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'published'
