CREATE OR REPLACE FUNCTION public.set_item_trade_remnants(tid uuid, p_amount bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid;
  v_trade public.item_trades%rowtype;
  v_balance bigint;
begin
  perform public.enforce_db_user_rate_limit('db_item_trade_mutation_user', auth.uid(), 60, 60);
  if auth.uid() is null then raise exception 'You must be signed in.'; end if;
  if p_amount is null or p_amount < 0 then raise exception 'Remnants offered cannot be negative.'; end if;

  select c.id into v_me
  from public.characters c
  where c.user_id = auth.uid()
  limit 1;

  if v_me is null then raise exception 'Unable to identify your character.'; end if;

  select * into v_trade
  from public.item_trades
  where id = tid
  for update;

  if not found then raise exception 'Exchange not found.'; end if;
  if v_trade.status <> 'open' then raise exception 'This exchange is no longer open.'; end if;

  if v_me <> v_trade.character_one_id and v_me <> v_trade.character_two_id then
    raise exception 'You are not part of this exchange.';
  end if;

  insert into public.character_wallets (character_id, balance)
  values (v_me, 0)
  on conflict (character_id) do nothing;

  select balance into v_balance
  from public.character_wallets
  where character_id = v_me;

  if coalesce(v_balance, 0) < p_amount then
    raise exception 'You do not have enough Remnants for this offer.';
  end if;

  if v_me = v_trade.character_one_id then
    update public.item_trades
    set character_one_remnants = p_amount,
        character_one_confirmed = false,
        character_two_confirmed = false
    where id = tid;
  else
    update public.item_trades
    set character_two_remnants = p_amount,
        character_one_confirmed = false,
        character_two_confirmed = false
    where id = tid;
  end if;
end;
$function$
;

