CREATE OR REPLACE FUNCTION public.set_staff_role(target_user_id uuid, new_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  acting_role text;
  target_current_role text;
  owner_count integer;
begin
  acting_role :=
    public.current_staff_role();

  if acting_role not in ('owner', 'admin') then
    raise exception
      'Only owners and administrators can manage staff.';
  end if;

  if not exists (
    select 1
    from auth.users
    where id = target_user_id
  ) then
    raise exception
      'The selected user does not exist.';
  end if;

  select role
  into target_current_role
  from public.staff_members
  where user_id = target_user_id;

  if new_role is not null
    and new_role not in (
      'owner',
      'admin',
      'moderator',
      'master'
    )
  then
    raise exception
      'The selected staff role is invalid.';
  end if;

  -- Only an Owner may create,
  -- modify or revoke Owner roles.
  if acting_role <> 'owner'
    and (
      target_current_role = 'owner'
      or new_role = 'owner'
    )
  then
    raise exception
      'Only an owner can manage owner roles.';
  end if;

  -- Only an Owner may create,
  -- modify or revoke Admin roles.
  if acting_role <> 'owner'
    and (
      target_current_role = 'admin'
      or new_role = 'admin'
    )
  then
    raise exception
      'Only an owner can manage administrator roles.';
  end if;

  -- Protect the final Owner.
  if target_current_role = 'owner'
    and new_role is distinct from 'owner'
  then
    select count(*)
    into owner_count
    from public.staff_members
    where role = 'owner';

    if owner_count <= 1 then
      raise exception
        'The final owner cannot be removed or demoted.';
    end if;
  end if;

  if new_role is null then
    delete from public.staff_members
    where user_id = target_user_id;

    return;
  end if;

  insert into public.staff_members (
    user_id,
    role
  )
  values (
    target_user_id,
    new_role
  )
  on conflict (user_id)
  do update set
    role = excluded.role,
    updated_at = now();
end;
$function$
;

