CREATE OR REPLACE FUNCTION public.settle_portal_session_expertise(p_user_id uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  character_uuid uuid;
  session_claimed_at timestamptz;
  session_last_seen_at timestamptz;
  checkpoint timestamptz;
  eligible_end timestamptz;
  account_from timestamptz;
  elapsed_seconds numeric;
  total_seconds numeric;
  completed_hours integer;
  remainder numeric;
  awarded numeric := 0;
begin
  if p_user_id is null then
    return 0;
  end if;

  select c.id
  into character_uuid
  from public.characters c
  where c.user_id = p_user_id
    and c.status = 'approved'
    and coalesce(c.is_system, false) = false
  limit 1;

  if character_uuid is null then
    return 0;
  end if;

  select
    s.claimed_at,
    s.last_seen_at
  into
    session_claimed_at,
    session_last_seen_at
  from public.portal_active_sessions s
  where s.user_id = p_user_id
  for update;

  if not found then
    return 0;
  end if;

  eligible_end :=
    least(
      p_now,
      session_last_seen_at + interval '60 minutes'
    );

  if eligible_end <= session_claimed_at then
    return 0;
  end if;

  insert into public.character_expertise_progress(
    character_id,
    presence_checkpoint_at
  )
  values (
    character_uuid,
    session_claimed_at
  )
  on conflict (character_id) do nothing;

  select p.presence_checkpoint_at
  into checkpoint
  from public.character_expertise_progress p
  where p.character_id = character_uuid
  for update;

  account_from :=
    greatest(
      session_claimed_at,
      coalesce(
        checkpoint,
        session_claimed_at
      )
    );

  if eligible_end <= account_from then
    return 0;
  end if;

  elapsed_seconds :=
    extract(
      epoch from (
        eligible_end - account_from
      )
    );

  update public.character_expertise_progress
  set
    online_seconds =
      coalesce(online_seconds, 0)
      + elapsed_seconds,
    presence_checkpoint_at =
      eligible_end,
    updated_at = now()
  where character_id =
    character_uuid
  returning online_seconds
  into total_seconds;

  completed_hours :=
    floor(total_seconds / 3600);

  if completed_hours > 0 then
    remainder :=
      total_seconds
      - (completed_hours * 3600);

    update public.character_expertise_progress
    set
      online_seconds = remainder,
      updated_at = now()
    where character_id =
      character_uuid;

    awarded :=
      completed_hours * 0.3;

    perform public._grant_expertise(
      character_uuid,
      awarded,
      'portal_time',
      completed_hours,
      completed_hours
        || ' portal hour(s)',
      null
    );
  end if;

  return awarded;
end;
$function$
;

