CREATE OR REPLACE FUNCTION public.snapshot_market_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.shop_name_snapshot is null
     or new.shop_slug_snapshot is null
     or new.item_name_snapshot is null
     or new.item_slug_snapshot is null then
    select s.name, s.slug, i.name, i.slug
    into new.shop_name_snapshot, new.shop_slug_snapshot,
         new.item_name_snapshot, new.item_slug_snapshot
    from public.market_shops s, public.items i
    where s.id = new.shop_id
      and i.id = new.item_id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.snapshot_room_message_conditions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_subject_character_id uuid;
begin
  if new.character_id is null and new.npc_id is null then
    new.condition_snapshot := '[]'::jsonb;
    return new;
  end if;

  if coalesce(new.speaker_type, 'character') = 'npc' then
    select n.character_id
    into v_subject_character_id
    from public.npcs n
    where n.id = new.npc_id
    limit 1;
  else
    v_subject_character_id := new.character_id;
  end if;

  if v_subject_character_id is null then
    new.condition_snapshot := '[]'::jsonb;
    return new;
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object('label', c.label)
        order by c.created_at asc, c.id asc
      ),
      '[]'::jsonb
    )
  into new.condition_snapshot
  from public.character_conditions c
  where c.character_id = v_subject_character_id;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_adjust_remnants(p_character_id uuid, p_amount bigint, p_reason text)
 RETURNS TABLE(ledger_id uuid, new_balance bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then raise exception 'Authentication required.'; end if;
  if not exists (select 1 from public.staff_members where user_id = v_user_id) then
    raise exception 'Staff access required.';
  end if;
  if p_amount = 0 then raise exception 'Adjustment amount cannot be zero.'; end if;
  if length(trim(coalesce(p_reason,''))) < 3 then raise exception 'A staff adjustment reason is required.'; end if;

  return query
  select * from public._post_remnant_transaction(
    p_character_id, p_amount, 'staff_adjustment', 'staff',
    v_user_id::text, trim(p_reason), v_user_id
  );
end;
$function$
;

