CREATE OR REPLACE FUNCTION public.staff_award_expertise(p_character_id uuid, p_amount numeric, p_note text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller uuid := auth.uid();
  caller_role text;
  new_total numeric;
begin
  if caller is null then
    raise exception 'Not authenticated';
  end if;

  select role
  into caller_role
  from public.staff_members
  where user_id = caller;

  if caller_role not in ('owner','admin','master') then
    raise exception 'Owner, Admin or Master access required';
  end if;

  if p_amount is null
     or p_amount = 0
     or abs(p_amount) > 10000
  then
    raise exception 'Enter a non-zero Expertise amount up to 10,000';
  end if;

  if p_amount < 0 then
    select expertise
    into new_total
    from public.characters
    where id = p_character_id;

    if new_total is null then
      raise exception 'Character not found';
    end if;

    if new_total + p_amount < 0 then
      raise exception 'Expertise cannot fall below zero';
    end if;
  end if;

  perform public._grant_expertise(
    p_character_id,
    p_amount,
    case
      when p_amount > 0 then 'staff_award'
      else 'staff_adjustment'
    end,
    null,
    nullif(trim(p_note),''),
    caller
  );

  select expertise
  into new_total
  from public.characters
  where id = p_character_id;

  return new_total;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_award_expertise_with_character_audit(p_character_id uuid, p_amount numeric, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  staff_role text;
  staff_email text;
  character_name text;
  old_expertise numeric;
  new_expertise numeric;
begin
  select sm.role::text
  into staff_role
  from public.staff_members sm
  where sm.user_id = auth.uid()
  limit 1;

  if staff_role is null
     or staff_role not in ('owner', 'admin', 'master') then
    raise exception 'You do not have permission to award Expertise.';
  end if;

  select
    coalesce(c.expertise, 0),
    coalesce(
      nullif(c.display_name, ''),
      nullif(
        btrim(
          coalesce(c.first_name, '')
          || ' '
          || coalesce(c.surname, '')
        ),
        ''
      ),
      c.id::text
    )
  into
    old_expertise,
    character_name
  from public.characters c
  where c.id = p_character_id
  for update;

  if not found then
    raise exception 'Character not found.';
  end if;

  perform public.staff_award_expertise(
    p_character_id,
    p_amount,
    p_note
  );

  select coalesce(c.expertise, 0)
  into new_expertise
  from public.characters c
  where c.id = p_character_id;

  select u.email
  into staff_email
  from auth.users u
  where u.id = auth.uid();

  insert into public.character_audit_log (
    character_id,
    character_name_snapshot,
    event_type,
    entity_type,
    entity_id,
    operation,
    actor_user_id,
    actor_type,
    actor_staff_role,
    actor_label,
    source,
    changed_fields,
    old_values,
    new_values,
    metadata
  )
  values (
    p_character_id,
    character_name,
    'expertise_manually_adjusted',
    'characters',
    p_character_id::text,
    'event',
    auth.uid(),
    'staff',
    staff_role,
    case
      when staff_email is not null
        then staff_role || ' · ' || staff_email
      else staff_role
    end,
    'admin_expertise',
    array['expertise']::text[],
    jsonb_build_object(
      'expertise',
      old_expertise
    ),
    jsonb_build_object(
      'expertise',
      new_expertise
    ),
    jsonb_build_object(
      'amount',
      p_amount,
      'note',
      p_note,
      'manual_staff_award',
      true
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_create_unique_item_for_character(p_character_id uuid, p_item_id uuid, p_container_instance_id uuid DEFAULT NULL::uuid, p_custom_name text DEFAULT NULL::text, p_custom_description text DEFAULT NULL::text, p_custom_image_url text DEFAULT NULL::text, p_quality_override text DEFAULT NULL::text, p_transfer_policy_override text DEFAULT NULL::text, p_is_quest_item_override boolean DEFAULT NULL::boolean, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_item public.items%rowtype;
  v_instance_id uuid;
  v_action_id uuid;
begin
  if v_actor is null or not exists (
    select 1 from public.staff_members where user_id=v_actor
  ) then raise exception 'Staff access required.'; end if;

  if not exists (
    select 1 from public.characters
    where id=p_character_id and (coalesce(is_system,false)=false or exists (select 1 from public.npcs n where n.character_id=public.characters.id))
  ) then raise exception 'Character not found.'; end if;

  select * into v_item from public.items where id=p_item_id;
  if not found then raise exception 'Item not found.'; end if;

  v_action_id:=public.character_audit_begin_action('staff_item_grant','staff_inventory');

  insert into public.character_item_instances(
    item_id,owner_character_id,custom_name,custom_description,custom_image_url,
    quality_override,transfer_policy_override,is_quest_item_override,notes,
    charges_remaining,container_instance_id,vault_status,acquisition_source,assigned_by
  ) values (
    p_item_id,p_character_id,p_custom_name,p_custom_description,p_custom_image_url,
    p_quality_override,p_transfer_policy_override,p_is_quest_item_override,p_notes,
    case when v_item.use_behaviour='limited_charges' then v_item.max_charges else null end,
    p_container_instance_id,'owned','staff',v_actor
  ) returning id into v_instance_id;

  insert into public.item_instance_history(
    item_instance_id,to_character_id,actor_user_id,event_type,details
  ) values (
    v_instance_id,p_character_id,v_actor,'created_and_granted',
    'Created as an individual Item instance and granted by staff.'
  );

  perform public.character_audit_write_event(
    p_character_id,'staff_item_grant','staff_inventory',v_action_id,
    jsonb_build_object('item_id',p_item_id,'item_name',coalesce(p_custom_name,v_item.name),'quantity',1,'record_kind','unique','instance_id',v_instance_id),
    'staff_item_grant',v_instance_id::text
  );

  return v_instance_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_expertise_history(p_character_id uuid)
 RETURNS TABLE(id bigint, amount numeric, source text, source_units numeric, note text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_role text;
begin
  select role
  into caller_role
  from public.staff_members
  where user_id = auth.uid();

  if caller_role not in ('owner','admin','master') then
    raise exception 'Owner, Admin or Master access required';
  end if;

  return query
  select
    l.id,
    l.amount,
    l.source,
    l.source_units,
    l.note,
    l.created_at
  from public.character_expertise_ledger l
  where l.character_id = p_character_id
  order by l.created_at desc
  limit 100;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_expertise_overview()
 RETURNS TABLE(character_id uuid, display_name text, expertise numeric, online_seconds_progress numeric, action_characters_progress bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_role text;
begin
  select role
  into caller_role
  from public.staff_members
  where user_id = auth.uid();

  if caller_role not in ('owner','admin','master') then
    raise exception 'Owner, Admin or Master access required';
  end if;

  return query
  select
    c.id,
    c.display_name,
    c.expertise,
    coalesce(p.online_seconds,0),
    coalesce(p.action_characters,0)
  from public.characters c
  left join public.character_expertise_progress p
    on p.character_id = c.id
  where c.status = 'approved'
  order by c.display_name;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_grant_inventory_item(p_character_id uuid, p_item_id uuid, p_quantity integer DEFAULT 1, p_container_instance_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_item public.items%rowtype;
  v_category_slug text;
  v_remaining integer;
  v_stack record;
  v_add integer;
  v_stack_size integer;
  v_action_id uuid;
begin
  perform public.assert_character_economy_staff();

  if not exists (
    select 1
    from public.characters
    where id = p_character_id
      and (
        coalesce(is_system,false) = false
        or exists (
          select 1
          from public.npcs n
          where n.character_id = public.characters.id
        )
      )
  ) then
    raise exception 'Character not found.';
  end if;

  if p_quantity is null
     or p_quantity < 1
     or p_quantity > 9999
  then
    raise exception 'Quantity must be between 1 and 9999.';
  end if;

  select i.*
  into v_item
  from public.items i
  where i.id = p_item_id;

  if not found then
    raise exception 'Item not found.';
  end if;

  select c.slug
  into v_category_slug
  from public.item_categories c
  where c.id = v_item.category_id;

  v_action_id :=
    public.character_audit_begin_action(
      'staff_item_grant',
      'staff_inventory'
    );

  if v_category_slug = 'container'
     or v_item.use_behaviour = 'limited_charges'
  then

    if p_container_instance_id is not null then
      raise exception
        'Containers and limited-charge Items must be granted as top-level individual Items.';
    end if;

    for v_remaining in 1..p_quantity loop
      insert into public.character_item_instances(
        item_id,
        owner_character_id,
        charges_remaining,
        vault_status,
        acquisition_source,
        assigned_by
      )
      values (
        p_item_id,
        p_character_id,
        case
          when v_item.use_behaviour='limited_charges'
          then v_item.max_charges
          else null
        end,
        'owned',
        'staff',
        v_actor
      );
    end loop;

  elsif coalesce(v_item.stackable,false)=false then

    for v_remaining in 1..p_quantity loop
      insert into public.character_items(
        character_id,
        item_id,
        quantity,
        container_instance_id,
        acquisition_source,
        assigned_by
      )
      values (
        p_character_id,
        p_item_id,
        1,
        p_container_instance_id,
        'staff',
        v_actor
      );
    end loop;

  else

    v_remaining := p_quantity;

    for v_stack in
      select id, quantity
      from public.character_items
      where character_id = p_character_id
        and item_id = p_item_id
        and container_instance_id
            is not distinct from p_container_instance_id
      order by acquired_at,id
      for update
    loop

      exit when v_remaining <= 0;

      if v_item.max_stack is null then

        update public.character_items
        set
          quantity = v_stack.quantity + v_remaining,
          acquisition_source = 'staff',
          assigned_by = v_actor,
          updated_at = now()
        where id = v_stack.id;

        v_remaining := 0;
        exit;
      end if;

      v_add :=
        least(
          greatest(
            v_item.max_stack - v_stack.quantity,
            0
          ),
          v_remaining
        );

      if v_add > 0 then
        update public.character_items
        set
          quantity = v_stack.quantity + v_add,
          acquisition_source = 'staff',
          assigned_by = v_actor,
          updated_at = now()
        where id = v_stack.id;

        v_remaining :=
          v_remaining - v_add;
      end if;

    end loop;

    while v_remaining > 0 loop

      v_stack_size :=
        case
          when v_item.max_stack is null
            then v_remaining
          else least(v_item.max_stack,v_remaining)
        end;

      insert into public.character_items(
        character_id,
        item_id,
        quantity,
        container_instance_id,
        acquisition_source,
        assigned_by
      )
      values (
        p_character_id,
        p_item_id,
        v_stack_size,
        p_container_instance_id,
        'staff',
        v_actor
      );

      v_remaining :=
        v_remaining - v_stack_size;

    end loop;

  end if;

  perform public.character_audit_write_event(
    p_character_id,
    'staff_item_grant',
    'staff_inventory',
    v_action_id,
    jsonb_build_object(
      'item_id',p_item_id,
      'item_name',v_item.name,
      'quantity',p_quantity,
      'container_instance_id',p_container_instance_id
    ),
    'staff_item_grant',
    p_item_id::text
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_link_shape_to_order_level(p_shape_id uuid, p_order_level_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.current_staff_role() <> 'owner' then
    raise exception 'Owner access required';
  end if;

  insert into public.order_level_shapes(
    shape_id,
    order_level_id
  )
  values(
    p_shape_id,
    p_order_level_id
  )
  on conflict(order_level_id,shape_id)
  do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_obscure_communication(p_source_type text, p_source_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  actor uuid := auth.uid();
  actor_role text;
  actor_label text := 'Staff';
  original_text text;
  original_forwarded text;
  clean_reason text := trim(coalesce(p_reason, ''));
begin
  if actor is null then
    raise exception 'You must be signed in.';
  end if;

  select role
  into actor_role
  from public.staff_members
  where user_id = actor
  limit 1;

  if actor_role is null then
    raise exception 'Staff access required.';
  end if;

  if p_source_type not in (
    'direct_message',
    'instant_chat_message',
    'room_message'
  ) then
    raise exception 'Unsupported communication type.';
  end if;

  if clean_reason = '' then
    raise exception 'A moderation reason is required.';
  end if;

  if length(clean_reason) > 500 then
    raise exception 'Moderation reason is too long.';
  end if;

  select coalesce(
    nullif(trim(display_name), ''),
    nullif(trim(concat_ws(' ', first_name, surname)), ''),
    'Staff'
  )
  into actor_label
  from public.characters
  where user_id = actor
  limit 1;

  actor_label := coalesce(actor_label, 'Staff');

  if exists (
    select 1
    from public.communication_moderation_actions
    where source_type = p_source_type
      and source_id = p_source_id
  ) then
    raise exception 'This message has already been obscured by staff.';
  end if;

  if p_source_type = 'direct_message' then
    select body, forwarded_body
    into original_text, original_forwarded
    from public.direct_messages
    where id = p_source_id
    for update;

    if not found then
      raise exception 'Private Message not found.';
    end if;

  elsif p_source_type = 'instant_chat_message' then
    select body
    into original_text
    from public.instant_chat_messages
    where id = p_source_id
    for update;

    if not found then
      raise exception 'Instant Chat message not found.';
    end if;

  elsif p_source_type = 'room_message' then
    select message
    into original_text
    from public.room_messages
    where id = p_source_id
    for update;

    if not found then
      raise exception 'Location message not found.';
    end if;
  end if;

  insert into public.communication_moderation_actions (
    source_type,
    source_id,
    original_content,
    original_forwarded_body,
    reason,
    moderated_by_user_id,
    moderated_by_label
  )
  values (
    p_source_type,
    p_source_id,
    coalesce(original_text, ''),
    original_forwarded,
    clean_reason,
    actor,
    actor_label
  );

  if p_source_type = 'direct_message' then
    update public.direct_messages
    set
      body = 'This message has been removed by staff.',
      forwarded_body = null
    where id = p_source_id;

    -- Prevent already-forwarded copies from continuing to expose the content.
    update public.direct_messages
    set forwarded_body = 'This message has been removed by staff.'
    where forwarded_from_message_id = p_source_id;

  elsif p_source_type = 'instant_chat_message' then
    update public.instant_chat_messages
    set body = 'This message has been removed by staff.'
    where id = p_source_id;

  elsif p_source_type = 'room_message' then
    update public.room_messages
    set message = 'This message has been removed by staff.'
    where id = p_source_id;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_remove_standard_inventory_item(p_record_id uuid, p_quantity integer DEFAULT 1)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_character_id uuid;
  v_item_id uuid;
  v_item_name text;
  v_have integer;
  v_remove integer;
  v_action_id uuid;
begin
  perform public.assert_character_economy_staff();

  if p_quantity is null or p_quantity < 1 then
    raise exception 'Removal quantity must be at least 1.';
  end if;

  select
    ci.character_id,
    ci.item_id,
    i.name,
    ci.quantity
  into
    v_character_id,
    v_item_id,
    v_item_name,
    v_have
  from public.character_items ci
  join public.items i
    on i.id = ci.item_id
  where ci.id = p_record_id
  for update;

  if not found then
    raise exception 'Inventory record not found.';
  end if;

  v_remove := least(p_quantity,v_have);

  v_action_id :=
    public.character_audit_begin_action(
      'staff_item_removal',
      'staff_inventory'
    );

  if v_remove >= v_have then
    delete from public.character_items
    where id = p_record_id;
  else
    update public.character_items
    set
      quantity = quantity - v_remove,
      updated_at = now()
    where id = p_record_id;
  end if;

  perform public.character_audit_write_event(
    v_character_id,
    'staff_item_removal',
    'staff_inventory',
    v_action_id,
    jsonb_build_object(
      'item_id',v_item_id,
      'item_name',v_item_name,
      'quantity',v_remove,
      'record_kind','standard'
    ),
    'staff_item_removal',
    p_record_id::text
  );

  return v_character_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_unlink_shape_from_order_level(p_shape_id uuid, p_order_level_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.current_staff_role() <> 'owner' then
    raise exception 'Owner access required';
  end if;

  delete from public.order_level_shapes
  where shape_id = p_shape_id
    and order_level_id = p_order_level_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_direct_conversation(recipient_character_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sender_character_id uuid;
  sender_user_id uuid;
  generated_pair_key text;
  target_conversation_id uuid;
begin
  sender_user_id := auth.uid();

  if sender_user_id is null then
    raise exception 'Authentication required.';
  end if;

  perform public.raise_if_user_sanctioned(
    sender_user_id,
    'communication'
  );

  select c.id
  into sender_character_id
  from public.characters c
  where c.user_id = sender_user_id
    and c.status = 'approved'
    and coalesce(c.is_system, false) = false
  limit 1;

  if sender_character_id is null then
    raise exception 'An approved character is required.';
  end if;

  if recipient_character_id is null then
    raise exception 'Missing recipient.';
  end if;

  if recipient_character_id = sender_character_id then
    raise exception 'You cannot message yourself.';
  end if;

  if not exists (
    select 1
    from public.characters c
    where c.id = recipient_character_id
      and c.status = 'approved'
      and coalesce(c.is_system, false) = false
  ) then
    raise exception 'Recipient not found.';
  end if;

  if exists (
    select 1
    from public.npcs n
    where n.character_id = recipient_character_id
  ) then
    raise exception 'NPCs cannot receive private messages.';
  end if;

  if exists (
    select 1
    from public.character_blocks cb
    where
      (
        cb.blocker_character_id = sender_character_id
        and cb.blocked_character_id = recipient_character_id
      )
      or
      (
        cb.blocker_character_id = recipient_character_id
        and cb.blocked_character_id = sender_character_id
      )
  ) then
    raise exception 'This conversation is unavailable.';
  end if;

  generated_pair_key :=
    case
      when sender_character_id::text < recipient_character_id::text
        then sender_character_id::text || ':' || recipient_character_id::text
      else recipient_character_id::text || ':' || sender_character_id::text
    end;

  insert into public.direct_conversations(pair_key)
  values (generated_pair_key)
  on conflict (pair_key)
  do update
  set pair_key = excluded.pair_key
  returning id into target_conversation_id;

  insert into public.direct_conversation_participants(
    conversation_id,
    character_id
  )
  values
    (target_conversation_id, sender_character_id),
    (target_conversation_id, recipient_character_id)
  on conflict (conversation_id, character_id)
  do nothing;

  return target_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_group_conversation(recipient_character_ids uuid[], group_title text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor_user uuid := auth.uid();
  actor_character uuid;
  clean_recipients uuid[];
  conversation_id uuid := gen_random_uuid();
  synthetic_pair_key text := 'group:' || conversation_id::text;
begin
  if actor_user is null then
    raise exception 'Authentication required.';
  end if;

  select c.id
    into actor_character
  from public.characters c
  where c.user_id = actor_user
    and c.status = 'approved'
  limit 1;

  if actor_character is null then
    raise exception 'Approved character required.';
  end if;

  select coalesce(array_agg(distinct x), '{}'::uuid[])
    into clean_recipients
  from unnest(coalesce(recipient_character_ids, '{}'::uuid[])) as x
  where x <> actor_character;

  if cardinality(clean_recipients) < 2 then
    raise exception 'A group conversation requires at least two other characters.';
  end if;

  if cardinality(clean_recipients) > 19 then
    raise exception 'A group conversation may contain at most 20 characters including you.';
  end if;

  if exists (
    select 1
    from unnest(clean_recipients) x
    left join public.characters c on c.id = x
    where c.id is null or c.status <> 'approved'
  ) then
    raise exception 'One or more selected characters are unavailable.';
  end if;

  if exists (
    select 1
    from unnest(clean_recipients) x
    join public.character_blocks b
      on (
        b.blocker_character_id = actor_character
        and b.blocked_character_id = x
      ) or (
        b.blocker_character_id = x
        and b.blocked_character_id = actor_character
      )
  ) then
    raise exception 'One or more selected characters are unavailable for private messages.';
  end if;

  insert into public.direct_conversations (
    id,
    pair_key,
    is_group,
    title,
    created_by_character_id,
    updated_at
  )
  values (
    conversation_id,
    synthetic_pair_key,
    true,
    nullif(trim(group_title), ''),
    actor_character,
    now()
  );

  insert into public.direct_conversation_participants (
    conversation_id,
    character_id
  )
  values (
    conversation_id,
    actor_character
  );

  insert into public.direct_conversation_participants (
    conversation_id,
    character_id
  )
  select conversation_id, x
  from unnest(clean_recipients) x;

  return conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_instant_chat(p_target_character_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := public.instant_chat_current_character_id();
  cid uuid;
begin
  perform public.raise_if_user_sanctioned(
    auth.uid(),
    'communication'
  );

  if me is null then raise exception 'Approved character required.'; end if;
  if p_target_character_id = me then raise exception 'You cannot chat with yourself.'; end if;

  if not exists (
    select 1
    from public.characters c
    join public.instant_chat_settings s
      on s.character_id = c.id
    where c.id = p_target_character_id
      and c.status = 'approved'
      and s.enabled = true
  ) then
    raise exception 'That character is not available for instant chat.';
  end if;

  if exists (
    select 1
    from public.character_blocks b
    where
      (b.blocker_character_id = me and b.blocked_character_id = p_target_character_id)
      or
      (b.blocker_character_id = p_target_character_id and b.blocked_character_id = me)
  ) then
    raise exception 'Instant chat is unavailable between these characters.';
  end if;

  select id into cid
  from public.instant_chat_conversations
  where
    (character_one_id = me and character_two_id = p_target_character_id)
    or
    (character_one_id = p_target_character_id and character_two_id = me)
  limit 1;

  if cid is null then
    insert into public.instant_chat_conversations (
      character_one_id,
      character_two_id
    )
    values (me, p_target_character_id)
    returning id into cid;

    insert into public.instant_chat_participants (
      conversation_id,
      character_id
    )
    values
      (cid, me),
      (cid, p_target_character_id)
    on conflict do nothing;
  end if;

  return cid;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.store_product_all_owned(p_user_id uuid, p_character_id uuid, p_product_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_grant public.store_product_grants%rowtype;
  v_any boolean := false;
begin
  for v_grant in select * from public.store_product_grants where product_id = p_product_id loop
    v_any := true;
    if v_grant.grant_type = 'portal_skin' then
      if not exists (select 1 from public.user_portal_skin_entitlements where user_id=p_user_id and skin_id=v_grant.portal_skin_id and enabled=true) then return false; end if;
    elsif v_grant.grant_type = 'cosmetic' then
      if not exists (select 1 from public.character_cosmetic_entitlements where character_id=p_character_id and cosmetic_item_id=v_grant.cosmetic_item_id and enabled=true) then return false; end if;
    elsif v_grant.grant_type = 'music' then
      if not exists (select 1 from public.character_music_entitlements where character_id=p_character_id and music_track_id=v_grant.music_track_id and enabled=true) then return false; end if;
    elsif v_grant.grant_type = 'feature' then
      if not exists (select 1 from public.character_feature_entitlements where character_id=p_character_id and feature_key=v_grant.feature_key and enabled=true) then return false; end if;
    else
      return false;
    end if;
  end loop;
  return v_any;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.store_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at = now(); return new; end;
$function$
;

CREATE OR REPLACE FUNCTION public.store_validate_order_character()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  character_user_id uuid;
begin
  if new.user_id is null then
    if TG_OP='UPDATE' and old.user_id is not null
       and (to_jsonb(old)-'user_id')=(to_jsonb(new)-'user_id')
       and not exists(select 1 from auth.users u where u.id=old.user_id) then
      return new;
    end if;
    if TG_OP='UPDATE' and old.user_id is null and old.character_id is not null and new.character_id is null
       and (to_jsonb(old)-'character_id')=(to_jsonb(new)-'character_id')
       and not exists(select 1 from public.characters c where c.id=old.character_id) then return new; end if;
    raise exception 'A live account is required for a Store order.';
  end if;
  if new.character_id is null then
    return new;
  end if;

  select c.user_id
  into character_user_id
  from public.characters c
  where c.id = new.character_id;

  if character_user_id is null then
    raise exception 'Store order character does not exist.';
  end if;

  if character_user_id <> new.user_id then
    raise exception 'Store order character does not belong to this user.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.strict_word_similarity(text, text)
 RETURNS real
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
AS '$libdir/pg_trgm', $function$strict_word_similarity$function$
;

CREATE OR REPLACE FUNCTION public.strict_word_similarity_commutator_op(text, text)
 RETURNS boolean
 LANGUAGE c
 STABLE PARALLEL SAFE STRICT
