CREATE OR REPLACE FUNCTION public.sync_active_item_effect_conditions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.source_effect_id is not null then
    select coalesce(e.conditions, '{}'::text[])
    into new.conditions
    from public.item_effects e
    where e.id = new.source_effect_id;

    new.conditions := coalesce(new.conditions, '{}'::text[]);
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_active_item_effect_to_character_effect()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  j jsonb;
  v_conditions text[];
  v_id uuid;
begin
  if tg_op='DELETE' then
    j := to_jsonb(old);
    v_id := (j->>'id')::uuid;

    update public.character_effects
       set ended_at=coalesce(ended_at,now())
     where source_type='item'
       and source_instance_id=v_id;

    return old;
  end if;

  j := to_jsonb(new);
  v_id := (j->>'id')::uuid;

  select coalesce(array_agg(value), '{}'::text[])
    into v_conditions
  from jsonb_array_elements_text(
    case
      when jsonb_typeof(j->'conditions')='array'
        then j->'conditions'
      else '[]'::jsonb
    end
  ) value;

  insert into public.character_effects (
    target_character_id,
    source_type,
    source_definition_id,
    source_instance_id,
    source_name,
    source_level,
    effect_nature,
    conditions,
    muscles_modifier,
    reflexes_modifier,
    vigour_modifier,
    brains_modifier,
    shrewd_modifier,
    presence_modifier,
    max_health_modifier,
    warping_affinity_modifier,
    warps_per_day_modifier,
    starts_at,
    expires_at,
    ended_at,
    dispellable
  )
  values (
    (j->>'character_id')::uuid,
    'item',
    nullif(j->>'item_id','')::uuid,
    v_id,
    coalesce(nullif(j->>'source_name',''),'Item effect'),
    1,
    'mixed',
    v_conditions,
    coalesce((j->>'muscles_modifier')::integer,0),
    coalesce((j->>'reflexes_modifier')::integer,0),
    coalesce((j->>'vigour_modifier')::integer,0),
    coalesce((j->>'brains_modifier')::integer,0),
    coalesce((j->>'shrewd_modifier')::integer,0),
    coalesce((j->>'presence_modifier')::integer,0),
    coalesce((j->>'max_health_modifier')::integer,0),
    coalesce((j->>'warping_affinity_modifier')::integer,0),
    coalesce((j->>'warps_per_day_modifier')::integer,0),
    coalesce((j->>'activated_at')::timestamptz,now()),
    nullif(j->>'expires_at','')::timestamptz,
    case
      when coalesce((j->>'expires_at')::timestamptz, now()+interval '1 minute') <= now()
        then now()
      else null
    end,
    true
  )
  on conflict (source_type,source_instance_id)
  where source_instance_id is not null and source_type in ('item','manual')
  do update set
    target_character_id=excluded.target_character_id,
    source_definition_id=excluded.source_definition_id,
    source_name=excluded.source_name,
    conditions=excluded.conditions,
    muscles_modifier=excluded.muscles_modifier,
    reflexes_modifier=excluded.reflexes_modifier,
    vigour_modifier=excluded.vigour_modifier,
    brains_modifier=excluded.brains_modifier,
    shrewd_modifier=excluded.shrewd_modifier,
    presence_modifier=excluded.presence_modifier,
    max_health_modifier=excluded.max_health_modifier,
    warping_affinity_modifier=excluded.warping_affinity_modifier,
    warps_per_day_modifier=excluded.warps_per_day_modifier,
    starts_at=excluded.starts_at,
    expires_at=excluded.expires_at,
    ended_at=excluded.ended_at,
    dispelled_at=null,
    dispelled_by_source_type=null,
    dispelled_by_source_id=null;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.sync_calendar_event_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_notification_id uuid;
  v_expiry timestamptz;
begin
  if tg_op = 'DELETE' then
    delete from public.notifications
    where is_automatic = true
      and source_type = 'event'
      and source_id = old.id::text;

    return old;
  end if;

  v_expiry := public.calendar_event_expiry_datetime(
    new.event_date,
    new.start_time,
    new.end_time
  );

  /*
   * Occurrence reminders are derived data.
   *
   * If staff changes the Event, remove any non-overridden generated
   * occurrence reminder. The next bell refresh will rematerialize the
   * currently-due occurrence with the new date/time/settings.
   */
  if tg_op = 'UPDATE' then
    delete from public.notifications
    where is_automatic = true
      and source_type = 'event'
      and source_id = new.id::text
      and staff_overridden = false
      and (
        source_trigger = '24h'
        or source_trigger = '1h'
        or source_trigger like '24h:%'
        or source_trigger like '1h:%'
      );
  end if;

  -- Keep the publication notice aligned with Event edits unless overridden.
  update public.notifications
  set
    title =
      'New Event: ' || new.title,
    body =
      new.title || ' has been added to the calendar.',
    expires_game_at =
      v_expiry,
    updated_at =
      now(),
    is_active =
      case
        when not new.notify_on_publish then false
        when not new.is_active then false
        else true
      end
  where is_automatic = true
    and source_type = 'event'
    and source_id = new.id::text
    and source_trigger = 'published'
    and staff_overridden = false;

  -- "Notify when published" means visible/active Calendar publication.
  if new.is_active
     and new.notify_on_publish
     and not exists (
       select 1
       from public.notification_suppressions s
       where s.source_type = 'event'
         and s.source_id = new.id::text
         and s.source_trigger = 'published'
     )
  then
    insert into public.notifications (
      type,
      title,
      body,
      href,
      starts_at,
      expires_game_at,
      source_type,
      source_id,
      source_trigger,
      created_by,
      is_automatic,
      is_active
    )
    values (
      'event',
      'New Event: ' || new.title,
      new.title || ' has been added to the calendar.',
      null,
      now(),
      v_expiry,
      'event',
      new.id::text,
      'published',
      new.created_by,
      true,
      true
    )
    on conflict (
      source_type,
      source_id,
      source_trigger
    )
    where is_automatic = true
    do nothing
    returning id into v_notification_id;

    if v_notification_id is null then
      select n.id
      into v_notification_id
      from public.notifications n
      where n.is_automatic = true
        and n.source_type = 'event'
        and n.source_id = new.id::text
        and n.source_trigger = 'published'
      limit 1;
    end if;

    if v_notification_id is not null then
      insert into public.notification_targets (
        notification_id,
        target_type,
        target_id
      )
      values (
        v_notification_id,
        'global',
        null
      )
      on conflict do nothing;
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_character_condition_to_effect()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    update public.character_effects
       set ended_at = coalesce(ended_at, now())
     where source_type='manual'
       and source_instance_id=old.id;
    return old;
  end if;

  insert into public.character_effects (
    target_character_id,
    source_type,
    source_instance_id,
    source_name,
    source_level,
    effect_nature,
    conditions,
    starts_at,
    dispellable,
    created_by_user_id,
    created_by_role
  )
  values (
    new.character_id,
    'manual',
    new.id,
    new.label,
    1,
    'mixed',
    array[new.label],
    new.created_at,
    false,
    new.created_by_user_id,
    new.created_by_role
  )
  on conflict (source_type,source_instance_id)
  where source_instance_id is not null and source_type in ('item','manual')
  do update set
    target_character_id=excluded.target_character_id,
    source_name=excluded.source_name,
    conditions=excluded.conditions,
    ended_at=null,
    created_by_user_id=excluded.created_by_user_id,
    created_by_role=excluded.created_by_role;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.sync_character_order_shapes(p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order uuid;v_level integer;
begin
 select om.order_id,ol.level into v_order,v_level from order_memberships om
 join order_levels ol on ol.id=om.order_level_id where om.character_id=p_character_id limit 1;
 delete from character_shapes where character_id=p_character_id and acquisition_source='order';
 if v_order is null then return; end if;
 insert into character_shapes(character_id,shape_id,acquisition_source,level_override)
 select distinct p_character_id,ols.shape_id,'order',true from order_level_shapes ols
 join order_levels gl on gl.id=ols.order_level_id
 where gl.order_id=v_order and gl.level<=v_level
 on conflict(character_id,shape_id,acquisition_source) do update set level_override=true;
end $function$
;

CREATE OR REPLACE FUNCTION public.sync_character_presence_room()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.current_room_id is distinct from old.current_room_id then
    update public.character_presence
    set
      room_id = new.current_room_id,
      last_seen_at = now(),
      updated_at = now()
    where character_id = new.id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_gift_activation_to_character_effect()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ownership record;
  v_gift record;
  v_target uuid;
begin
  if tg_op='DELETE' then
    update public.character_effects
       set ended_at=coalesce(ended_at,now())
     where source_type='feat'
       and mechanics_definition_id is null
       and source_instance_id=old.id;
    return old;
  end if;

  select cg.character_id,cg.gift_id
    into v_ownership
    from public.character_gifts cg
   where cg.id=new.character_gift_id;

  if not found then
    return new;
  end if;

  -- New-style Feats resolve through their hidden mechanics definition and are
  -- inserted directly by the shared Shape/Feat runtime instead.
  if exists (
    select 1 from public.shapes s
    where s.feat_id=v_ownership.gift_id
      and s.is_feat_backing=true
  ) then
    update public.character_effects
       set ended_at=coalesce(ended_at,now())
     where source_type='feat'
       and mechanics_definition_id is null
       and source_instance_id=new.id;
    return new;
  end if;

  select * into v_gift
    from public.gifts g
   where g.id=v_ownership.gift_id;

  if not found or v_gift.effect_mode<>'temporary' then
    return new;
  end if;

  v_target:=coalesce(new.target_character_id,v_ownership.character_id);

  insert into public.character_effects (
    target_character_id,source_type,source_definition_id,mechanics_definition_id,
    source_instance_id,source_character_id,source_name,source_level,effect_nature,
    conditions,muscles_modifier,reflexes_modifier,vigour_modifier,brains_modifier,
    shrewd_modifier,presence_modifier,max_health_modifier,warping_affinity_modifier,
    warps_per_day_modifier,starts_at,expires_at,ended_at,dispellable
  ) values (
    v_target,'feat',v_ownership.gift_id,null,new.id,v_ownership.character_id,
    v_gift.name,1,'mixed','{}'::text[],
    coalesce(v_gift.muscles_modifier,0),coalesce(v_gift.reflexes_modifier,0),
    coalesce(v_gift.vigour_modifier,0),coalesce(v_gift.brains_modifier,0),
    coalesce(v_gift.shrewd_modifier,0),coalesce(v_gift.presence_modifier,0),
    coalesce(v_gift.max_health_modifier,0),coalesce(v_gift.warping_affinity_modifier,0),
    coalesce(v_gift.warps_per_day_modifier,0),coalesce(new.activated_at,now()),
    new.expires_at,new.ended_at,true
  )
  on conflict (source_instance_id)
  where source_type='feat' and mechanics_definition_id is null and source_instance_id is not null
  do update set
    target_character_id=excluded.target_character_id,
    source_definition_id=excluded.source_definition_id,
    source_character_id=excluded.source_character_id,
    source_name=excluded.source_name,
    muscles_modifier=excluded.muscles_modifier,
    reflexes_modifier=excluded.reflexes_modifier,
    vigour_modifier=excluded.vigour_modifier,
    brains_modifier=excluded.brains_modifier,
    shrewd_modifier=excluded.shrewd_modifier,
    presence_modifier=excluded.presence_modifier,
    max_health_modifier=excluded.max_health_modifier,
    warping_affinity_modifier=excluded.warping_affinity_modifier,
    warps_per_day_modifier=excluded.warps_per_day_modifier,
    starts_at=excluded.starts_at,
    expires_at=excluded.expires_at,
    ended_at=excluded.ended_at;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.sync_npc_location_presence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.character_id is not null then
    update public.characters
    set current_room_id = new.current_room_id,
        updated_at = now()
    where id = new.character_id
      and is_system = true;
  end if;

  if new.is_active = true
     and new.is_location_active = true
     and new.character_id is not null
     and new.current_room_id is not null then

    insert into public.character_presence(
      character_id, room_id, status, manual_status, last_seen_at,
      appear_offline, appeared_offline_at, updated_at
    )
    values(
      new.character_id,
      new.current_room_id,
      'online',
      'online',
      '9999-12-31 23:59:59+00'::timestamptz,
      false,
      null,
      now()
    )
    on conflict(character_id)
    do update set
      room_id = excluded.room_id,
      status = 'online',
      manual_status = 'online',
      last_seen_at = '9999-12-31 23:59:59+00'::timestamptz,
      appear_offline = false,
      appeared_offline_at = null,
      updated_at = now();
  elsif new.character_id is not null then
    delete from public.character_presence
    where character_id = new.character_id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_order_shapes_after_membership_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='DELETE' then
    perform public.sync_character_order_shapes(old.character_id);
    return old;
  end if;
  perform public.sync_character_order_shapes(new.character_id);
  if tg_op='UPDATE' and old.character_id is distinct from new.character_id then
    perform public.sync_character_order_shapes(old.character_id);
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.sync_order_shapes_for_character(p_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from public.character_shapes cs
   where cs.character_id = p_character_id
     and cs.acquisition_source = 'order'
     and not exists (
       select 1
       from public.order_job_shapes ojs
       join public.order_memberships om on om.order_job_id = ojs.order_job_id
       where om.character_id = p_character_id
         and ojs.shape_id = cs.shape_id
         and ojs.order_job_id = cs.source_order_job_id
     );

  insert into public.character_shapes(
    character_id, shape_id, acquisition_source, source_order_job_id, level_override
  )
  select p_character_id, ojs.shape_id, 'order', ojs.order_job_id, true
  from public.order_job_shapes ojs
  join public.order_memberships om on om.order_job_id = ojs.order_job_id
  where om.character_id = p_character_id
  on conflict do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_passive_feat_effect_for_assignment(p_assignment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
begin
  -- Remove the previous synthetic passive row first. Active/cast Feat effects
  -- use their cast/activation id as source_instance_id and are dispellable.
  delete from public.character_effects
  where source_type = 'feat'
    and source_instance_id = p_assignment_id
    and dispellable = false;

  insert into public.character_effects (
    target_character_id,
    source_type,
    source_definition_id,
    mechanics_definition_id,
    source_instance_id,
    source_character_id,
    source_name,
    source_level,
    effect_nature,
    conditions,
    muscles_modifier,
    reflexes_modifier,
    vigour_modifier,
    brains_modifier,
    shrewd_modifier,
    presence_modifier,
    max_health_modifier,
    warping_affinity_modifier,
    warps_per_day_modifier,
    starts_at,
    expires_at,
    dispellable
  )
  select
    cg.character_id,
    'feat',
    g.id,
    s.id,
    cg.id,
    cg.character_id,
    g.name,
    1,
    coalesce(s.effect_nature, 'beneficial'),
    coalesce(s.self_conditions, '{}'::text[]),
    coalesce(s.self_muscles_modifier, 0),
    coalesce(s.self_reflexes_modifier, 0),
    coalesce(s.self_vigour_modifier, 0),
    coalesce(s.self_brains_modifier, 0),
    coalesce(s.self_shrewd_modifier, 0),
    coalesce(s.self_presence_modifier, 0),
    case
      when btrim(coalesce(s.self_max_hp_change, '')) ~ '^[+-]?[0-9]+$'
        then btrim(s.self_max_hp_change)::integer
      else 0
    end,
    0,
    0,
    v_now,
    cg.expires_at,
    false
  from public.character_gifts cg
  join public.gifts g
    on g.id = cg.gift_id
  join public.shapes s
    on s.feat_id = g.id
   and s.is_feat_backing = true
  where cg.id = p_assignment_id
    and g.is_active = true
    and g.effect_mode = 'passive'
    and s.is_active = true
    and (
      cg.expires_at is null
      or cg.expires_at > v_now
    )
    and (
      cardinality(coalesce(s.self_conditions, '{}'::text[])) > 0
      or coalesce(s.self_muscles_modifier, 0) <> 0
      or coalesce(s.self_reflexes_modifier, 0) <> 0
      or coalesce(s.self_vigour_modifier, 0) <> 0
      or coalesce(s.self_brains_modifier, 0) <> 0
      or coalesce(s.self_shrewd_modifier, 0) <> 0
      or coalesce(s.self_presence_modifier, 0) <> 0
      or (
        btrim(coalesce(s.self_max_hp_change, '')) ~ '^[+-]?[0-9]+$'
        and btrim(s.self_max_hp_change)::integer <> 0
      )
    );
end
$function$
;

