CREATE OR REPLACE FUNCTION public.trg_sync_passive_feat_from_gift()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
begin
  for r in
    select id
    from public.character_gifts
    where gift_id = new.id
  loop
    perform public.sync_passive_feat_effect_for_assignment(r.id);
  end loop;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.trg_sync_passive_feat_from_shape()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_feat_id uuid;
begin
  v_feat_id := coalesce(new.feat_id, old.feat_id);

  if v_feat_id is null then
    return coalesce(new, old);
  end if;

  for r in
    select id
    from public.character_gifts
    where gift_id = v_feat_id
  loop
    perform public.sync_passive_feat_effect_for_assignment(r.id);
  end loop;

  return coalesce(new, old);
end
$function$
;

CREATE OR REPLACE FUNCTION public.unequip_character_inventory_record(p_record_kind text, p_record_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if p_record_kind = 'standard' then
    select ci.character_id
    into v_character_id
    from public.character_items ci
    join public.characters c
      on c.id = ci.character_id
    where ci.id = p_record_id
      and c.user_id = auth.uid();

    if v_character_id is null then
      raise exception 'You do not own this Item.';
    end if;

    delete from public.character_equipment
    where character_id = v_character_id
      and character_item_id = p_record_id;

  elsif p_record_kind = 'unique' then
    select inst.owner_character_id
    into v_character_id
    from public.character_item_instances inst
    join public.characters c
      on c.id = inst.owner_character_id
    where inst.id = p_record_id
      and c.user_id = auth.uid();

    if v_character_id is null then
      raise exception 'You do not own this Item.';
    end if;

    delete from public.character_equipment
    where character_id = v_character_id
      and item_instance_id = p_record_id;

  else
    raise exception 'Invalid inventory record type.';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.unequip_npc_inventory_record_as_staff(p_character_id uuid, p_record_kind text, p_record_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not public.is_staff_user() then
    raise exception 'Staff access required.';
  end if;

  if not exists (
    select 1
    from public.characters c
    join public.npcs n on n.character_id = c.id
    where c.id = p_character_id
      and c.is_system = true
  ) then
    raise exception 'NPC Character not found.';
  end if;

  if p_record_kind = 'standard' then
    if not exists (
      select 1
      from public.character_items
      where id = p_record_id
        and character_id = p_character_id
    ) then
      raise exception 'NPC does not own this Item.';
    end if;

    delete from public.character_equipment
    where character_id = p_character_id
      and character_item_id = p_record_id;

  elsif p_record_kind = 'unique' then
    if not exists (
      select 1
      from public.character_item_instances
      where id = p_record_id
        and owner_character_id = p_character_id
        and vault_status = 'owned'
    ) then
      raise exception 'NPC does not own this Item.';
    end if;

    delete from public.character_equipment
    where character_id = p_character_id
      and item_instance_id = p_record_id;
  else
    raise exception 'Invalid inventory record type.';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.unequip_revoked_cosmetic()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.enabled = true and new.enabled = false then
    update public.character_cosmetic_preferences
    set
      equipped_sheet_frame_id = case
        when equipped_sheet_frame_id = new.cosmetic_item_id then null
        else equipped_sheet_frame_id
      end,
      equipped_chat_frame_id = case
        when equipped_chat_frame_id = new.cosmetic_item_id then null
        else equipped_chat_frame_id
      end,
      updated_at = now()
    where character_id = new.character_id
      and (
        equipped_sheet_frame_id = new.cosmetic_item_id
        or equipped_chat_frame_id = new.cosmetic_item_id
      );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.unequip_revoked_extended_cosmetic()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.enabled = true then
    return new;
  end if;

  update public.character_cosmetic_preferences
  set
    equipped_sheet_frame_id = case when equipped_sheet_frame_id = new.cosmetic_item_id then null else equipped_sheet_frame_id end,
    equipped_chat_frame_id = case when equipped_chat_frame_id = new.cosmetic_item_id then null else equipped_chat_frame_id end,
    equipped_portrait_frame_id = case when equipped_portrait_frame_id = new.cosmetic_item_id then null else equipped_portrait_frame_id end,
    equipped_profile_background_id = case when equipped_profile_background_id = new.cosmetic_item_id then null else equipped_profile_background_id end,
    equipped_pm_frame_id = case when equipped_pm_frame_id = new.cosmetic_item_id then null else equipped_pm_frame_id end,
    equipped_instant_chat_frame_id = case when equipped_instant_chat_frame_id = new.cosmetic_item_id then null else equipped_instant_chat_frame_id end,
    equipped_forum_frame_id = case when equipped_forum_frame_id = new.cosmetic_item_id then null else equipped_forum_frame_id end,
    equipped_action_style_id = case when equipped_action_style_id = new.cosmetic_item_id then null else equipped_action_style_id end,
    equipped_nameplate_id = case when equipped_nameplate_id = new.cosmetic_item_id then null else equipped_nameplate_id end,
    equipped_profile_crest_id = case when equipped_profile_crest_id = new.cosmetic_item_id then null else equipped_profile_crest_id end,
    equipped_action_flourish_id = case when equipped_action_flourish_id = new.cosmetic_item_id then null else equipped_action_flourish_id end,
    equipped_whisper_style_id = case when equipped_whisper_style_id = new.cosmetic_item_id then null else equipped_whisper_style_id end,
    equipped_header_control_frame_id = case when equipped_header_control_frame_id = new.cosmetic_item_id then null else equipped_header_control_frame_id end,
    equipped_left_panel_frame_id = case when equipped_left_panel_frame_id = new.cosmetic_item_id then null else equipped_left_panel_frame_id end,
    equipped_right_panel_frame_id = case when equipped_right_panel_frame_id = new.cosmetic_item_id then null else equipped_right_panel_frame_id end,
    equipped_centre_panel_frame_id = case when equipped_centre_panel_frame_id = new.cosmetic_item_id then null else equipped_centre_panel_frame_id end,
    equipped_location_frame_id = case when equipped_location_frame_id = new.cosmetic_item_id then null else equipped_location_frame_id end,
    equipped_location_atmosphere_id = case when equipped_location_atmosphere_id = new.cosmetic_item_id then null else equipped_location_atmosphere_id end,
    updated_at = now()
  where character_id = new.character_id;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.unequip_standard_item_when_moved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.container_instance_id is not null
     or new.character_id is distinct from old.character_id then
    delete from public.character_equipment
    where character_item_id = new.id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.unequip_unique_item_when_moved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.container_instance_id is not null
     or new.owner_character_id is distinct from old.owner_character_id
     or new.vault_status <> 'owned' then
    delete from public.character_equipment
    where item_instance_id = new.id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.use_character_inventory_record_targeted_as_staff(p_source_character_id uuid, p_record_kind text, p_record_id uuid, p_target_character_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not public.is_staff_user() then
    raise exception 'Staff access required.';
  end if;

  return private.use_character_inventory_record_targeted_internal(
    p_source_character_id,
    p_record_kind,
    p_record_id,
    p_target_character_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.use_own_inventory_record(p_record_kind text, p_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_character_id uuid;
  v_item_id uuid;
  v_item_instance_id uuid;
  v_item_name text;
  v_is_usable boolean;
  v_use_behaviour text;
  v_target_mode text;
  v_cooldown_minutes integer;
  v_max_charges integer;
  v_charges_remaining integer;
  v_quantity integer;
  v_source_key text;
  v_ready_at timestamptz;
  v_health_delta integer := 0;
  v_max_health integer;
  v_temporary_count integer := 0;
  v_effect record;
  v_action_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if p_record_kind = 'standard' then
    select
      ci.character_id,
      ci.item_id,
      null::uuid,
      i.name,
      i.is_usable,
      i.use_behaviour,
      i.target_mode,
      i.cooldown_minutes,
      i.max_charges,
      null::integer,
      ci.quantity
    into
      v_character_id,
      v_item_id,
      v_item_instance_id,
      v_item_name,
      v_is_usable,
      v_use_behaviour,
      v_target_mode,
      v_cooldown_minutes,
      v_max_charges,
      v_charges_remaining,
      v_quantity
    from public.character_items ci
    join public.items i on i.id = ci.item_id
    join public.characters c on c.id = ci.character_id
    where ci.id = p_record_id
      and c.user_id = auth.uid();

  elsif p_record_kind = 'unique' then
    select
      inst.owner_character_id,
      inst.item_id,
      inst.id,
      coalesce(inst.custom_name, i.name),
      i.is_usable,
      i.use_behaviour,
      i.target_mode,
      i.cooldown_minutes,
      i.max_charges,
      coalesce(inst.charges_remaining, i.max_charges),
      1
    into
      v_character_id,
      v_item_id,
      v_item_instance_id,
      v_item_name,
      v_is_usable,
      v_use_behaviour,
      v_target_mode,
      v_cooldown_minutes,
      v_max_charges,
      v_charges_remaining,
      v_quantity
    from public.character_item_instances inst
    join public.items i on i.id = inst.item_id
    join public.characters c on c.id = inst.owner_character_id
    where inst.id = p_record_id
      and inst.vault_status = 'owned'
      and c.user_id = auth.uid();
  else
    raise exception 'Invalid inventory record type.';
  end if;

  if v_character_id is null or v_item_id is null then
    raise exception 'You do not own this Item.';
  end if;

  perform public.reconcile_expired_item_effects(v_character_id);

  if coalesce(v_is_usable, false) = false then
    raise exception 'This Item cannot be used.';
  end if;

  if coalesce(v_target_mode, 'self') <> 'self' then
    raise exception 'This Item requires a target. Targeted Item use is not enabled yet.';
  end if;

  if p_record_kind = 'standard' then
    v_source_key := 'standard:' || v_item_id::text;
  else
    v_source_key := 'unique:' || v_item_instance_id::text;
  end if;

  select c.ready_at
  into v_ready_at
  from public.character_item_use_cooldowns c
  where c.character_id = v_character_id
    and c.source_key = v_source_key;

  if v_ready_at is not null and v_ready_at > now() then
    raise exception 'This Item is still on cooldown.';
  end if;

  if p_record_kind = 'unique'
     and v_max_charges is not null
     and coalesce(v_charges_remaining, 0) <= 0 then
    raise exception 'This Item has no charges remaining.';
  end if;

  if not exists (
    select 1
    from public.item_effects e
    where e.item_id = v_item_id
      and e.trigger_type = 'use'
  ) then
    raise exception 'This Item has no configured Use effect.';
  end if;

  v_action_id := public.character_audit_begin_action('item_used','item_use');

  for v_effect in
    select e.*
    from public.item_effects e
    where e.item_id = v_item_id
      and e.trigger_type = 'use'
    order by e.sort_order, e.id
  loop
    if v_effect.effect_mode = 'instant' then
      v_health_delta :=
        v_health_delta + coalesce(v_effect.health_delta, 0);

    elsif v_effect.effect_mode = 'temporary' then
      if v_effect.duration_minutes is null
         or v_effect.duration_minutes <= 0 then
        raise exception 'Temporary Item effects require a positive duration.';
      end if;

      if coalesce(v_effect.allow_duplicate_stacking, false) = false then
        delete from public.character_active_item_effects
        where character_id = v_character_id
          and source_effect_id = v_effect.id;
      end if;

      insert into public.character_active_item_effects (
        character_id,
        item_id,
        item_instance_id,
        source_effect_id,
        source_name,
        muscles_modifier,
        reflexes_modifier,
        vigour_modifier,
        shrewd_modifier,
        brains_modifier,
        presence_modifier,
        max_health_modifier,
        activated_at,
        expires_at
      )
      values (
        v_character_id,
        v_item_id,
        v_item_instance_id,
        v_effect.id,
        v_item_name,
        coalesce(v_effect.muscles_modifier, 0),
        coalesce(v_effect.reflexes_modifier, 0),
        coalesce(v_effect.vigour_modifier, 0),
        coalesce(v_effect.shrewd_modifier, 0),
        coalesce(v_effect.brains_modifier, 0),
        coalesce(v_effect.presence_modifier, 0),
        coalesce(v_effect.max_health_modifier, 0),
        now(),
        now() + make_interval(mins => v_effect.duration_minutes)
      );

      v_temporary_count := v_temporary_count + 1;
    end if;
  end loop;

  if v_health_delta <> 0 then
    v_max_health := public.get_character_current_max_health(v_character_id);

    update public.characters
    set
      current_health = greatest(
        0,
        least(
          coalesce(current_health, v_max_health) + v_health_delta,
          v_max_health
        )
      ),
      updated_at = now()
    where id = v_character_id;
  end if;

  if p_record_kind = 'standard'
     and v_use_behaviour = 'consumable' then
    if v_quantity <= 1 then
      delete from public.character_items
      where id = p_record_id;
    else
      update public.character_items
      set
        quantity = quantity - 1,
        updated_at = now()
      where id = p_record_id;
    end if;
  end if;

  if p_record_kind = 'unique'
     and v_max_charges is not null then
    update public.character_item_instances
    set
      charges_remaining = greatest(
        0,
        coalesce(charges_remaining, v_max_charges) - 1
      ),
      updated_at = now()
    where id = p_record_id;

    v_charges_remaining := greatest(
      0,
      coalesce(v_charges_remaining, v_max_charges) - 1
    );
  end if;

  if coalesce(v_cooldown_minutes, 0) > 0 then
    v_ready_at := now() + make_interval(mins => v_cooldown_minutes);

    insert into public.character_item_use_cooldowns (
      character_id,
      source_key,
      item_id,
      item_instance_id,
      ready_at,
      updated_at
    )
    values (
      v_character_id,
      v_source_key,
      v_item_id,
      v_item_instance_id,
      v_ready_at,
      now()
    )
    on conflict (character_id, source_key)
    do update
    set
      item_id = excluded.item_id,
      item_instance_id = excluded.item_instance_id,
      ready_at = excluded.ready_at,
      updated_at = now();
  else
    delete from public.character_item_use_cooldowns
    where character_id = v_character_id
      and source_key = v_source_key;

    v_ready_at := null;
  end if;

  perform public.character_audit_write_event(
    v_character_id,'item_used','item_use',v_action_id,
    jsonb_build_object(
      'item_id',v_item_id,'item_name',v_item_name,'record_kind',p_record_kind,
      'target_character_id',v_character_id,'target_name','Self',
      'health_delta',v_health_delta,'temporary_effects',v_temporary_count,
      'charges_remaining',v_charges_remaining
    ),
    'item_use',p_record_id::text
  );

  return jsonb_build_object(
    'ok', true,
    'item_name', v_item_name,
    'health_delta', v_health_delta,
    'temporary_effects', v_temporary_count,
    'charges_remaining', v_charges_remaining,
    'cooldown_ready_at', v_ready_at
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.use_own_inventory_record_targeted(p_record_kind text, p_record_id uuid, p_target_character_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source_character_id uuid;
  v_source_room_id uuid;
  v_item_id uuid;
  v_item_instance_id uuid;
  v_item_name text;
  v_is_usable boolean;
  v_use_behaviour text;
  v_target_mode text;
  v_cooldown_minutes integer;
  v_max_charges integer;
  v_charges_remaining integer;
  v_quantity integer;
  v_target_character_id uuid;
  v_target_name text;
  v_target_room_id uuid;
  v_target_health integer;
  v_target_max_health integer;
  v_source_key text;
  v_ready_at timestamptz;
  v_has_use_effect boolean := false;
  v_has_temporary boolean := false;
  v_has_applicable_instant boolean := false;
  v_has_positive_heal boolean := false;
  v_health_delta integer := 0;
  v_temporary_count integer := 0;
  v_effect record;
  v_action_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required.'; end if;

  if p_record_kind = 'standard' then
    select ci.character_id,c.current_room_id,ci.item_id,null::uuid,i.name,i.is_usable,
      i.use_behaviour,i.target_mode,i.cooldown_minutes,i.max_charges,null::integer,ci.quantity
    into v_source_character_id,v_source_room_id,v_item_id,v_item_instance_id,v_item_name,
      v_is_usable,v_use_behaviour,v_target_mode,v_cooldown_minutes,v_max_charges,
      v_charges_remaining,v_quantity
    from public.character_items ci join public.items i on i.id=ci.item_id
    join public.characters c on c.id=ci.character_id
    where ci.id=p_record_id and c.user_id=auth.uid();
  elsif p_record_kind = 'unique' then
    select inst.owner_character_id,c.current_room_id,inst.item_id,inst.id,
      coalesce(inst.custom_name,i.name),i.is_usable,i.use_behaviour,i.target_mode,
      i.cooldown_minutes,i.max_charges,coalesce(inst.charges_remaining,i.max_charges),1
    into v_source_character_id,v_source_room_id,v_item_id,v_item_instance_id,v_item_name,
      v_is_usable,v_use_behaviour,v_target_mode,v_cooldown_minutes,v_max_charges,
      v_charges_remaining,v_quantity
    from public.character_item_instances inst join public.items i on i.id=inst.item_id
    join public.characters c on c.id=inst.owner_character_id
    where inst.id=p_record_id and inst.vault_status='owned' and c.user_id=auth.uid();
  else raise exception 'Invalid inventory record type.';
  end if;

  if v_source_character_id is null or v_item_id is null then raise exception 'You do not own this Item.'; end if;
  if coalesce(v_is_usable,false)=false then raise exception 'This Item cannot be used.'; end if;

  if coalesce(v_target_mode,'self')='self' then
    v_target_character_id:=v_source_character_id;
    if p_target_character_id is not null and p_target_character_id<>v_source_character_id then
      raise exception 'This Item can only target its owner.';
    end if;
  elsif v_target_mode='other' then
    if p_target_character_id is null then raise exception 'Choose a target.'; end if;
    if p_target_character_id=v_source_character_id then raise exception 'This Item must target another character.'; end if;
    v_target_character_id:=p_target_character_id;
  elsif v_target_mode='either' then
    v_target_character_id:=coalesce(p_target_character_id,v_source_character_id);
  else raise exception 'Invalid Item target mode.';
  end if;

  select c.display_name,c.current_room_id,c.current_health
  into v_target_name,v_target_room_id,v_target_health
  from public.characters c where c.id=v_target_character_id and c.status='approved';
  if v_target_name is null then raise exception 'Target character is not available.'; end if;

  if v_target_character_id<>v_source_character_id then
    if v_source_room_id is null or v_target_room_id is null or v_source_room_id<>v_target_room_id then
      raise exception 'Target character must be in the same location.';
    end if;
  end if;

  v_source_key:=case when p_record_kind='standard' then 'standard:'||v_item_id::text
                     else 'unique:'||v_item_instance_id::text end;
  select c.ready_at into v_ready_at from public.character_item_use_cooldowns c
    where c.character_id=v_source_character_id and c.source_key=v_source_key;
  if v_ready_at is not null and v_ready_at>now() then raise exception 'This Item is still on cooldown.'; end if;
  if p_record_kind='unique' and v_max_charges is not null and coalesce(v_charges_remaining,0)<=0 then
    raise exception 'This Item has no charges remaining.';
  end if;

  v_target_max_health:=public.get_character_current_max_health(v_target_character_id);
  v_target_health:=greatest(0,least(coalesce(v_target_health,v_target_max_health),v_target_max_health));

  select
    exists(select 1 from public.item_effects e where e.item_id=v_item_id and e.trigger_type='use'),
    exists(select 1 from public.item_effects e where e.item_id=v_item_id and e.trigger_type='use' and e.effect_mode='temporary'),
    exists(select 1 from public.item_effects e where e.item_id=v_item_id and e.trigger_type='use' and e.effect_mode='instant' and e.health_delta>0),
    exists(select 1 from public.item_effects e where e.item_id=v_item_id and e.trigger_type='use' and e.effect_mode='instant'
      and ((e.health_delta>0 and v_target_health<v_target_max_health) or (e.health_delta<0 and v_target_health>0)))
  into v_has_use_effect,v_has_temporary,v_has_positive_heal,v_has_applicable_instant;

  if not v_has_use_effect then
    return jsonb_build_object('ok',false,'blocked',true,'block_reason','This Item has no configured Use effect.');
  end if;
  if not v_has_temporary and not v_has_applicable_instant then
    if v_has_positive_heal and v_target_health>=v_target_max_health then
      return jsonb_build_object('ok',false,'blocked',true,'block_reason',
        case when v_target_character_id=v_source_character_id then 'You are already at full Health.'
             else v_target_name||' is already at full Health.' end);
    end if;
    return jsonb_build_object('ok',false,'blocked',true,'block_reason','This Item would have no effect on that target right now.');
  end if;

  v_action_id := public.character_audit_begin_action('item_used','item_use');

  for v_effect in select e.* from public.item_effects e
    where e.item_id=v_item_id and e.trigger_type='use' order by e.sort_order,e.id
  loop
    if v_effect.effect_mode='instant' then
      v_health_delta:=v_health_delta+coalesce(v_effect.health_delta,0);
    elsif v_effect.effect_mode='temporary' then
      if v_effect.duration_minutes is null or v_effect.duration_minutes<=0 then
        raise exception 'Temporary Item effects require a positive duration.';
      end if;
      if coalesce(v_effect.allow_duplicate_stacking,false)=false then
        delete from public.character_active_item_effects
        where character_id=v_target_character_id and source_effect_id=v_effect.id;
      end if;
      insert into public.character_active_item_effects(
        character_id,item_id,item_instance_id,source_effect_id,source_name,
        muscles_modifier,reflexes_modifier,vigour_modifier,shrewd_modifier,
        brains_modifier,presence_modifier,max_health_modifier,
        warping_affinity_modifier,warps_per_day_modifier,activated_at,expires_at
      ) values (
        v_target_character_id,v_item_id,v_item_instance_id,v_effect.id,v_item_name,
        coalesce(v_effect.muscles_modifier,0),coalesce(v_effect.reflexes_modifier,0),
        coalesce(v_effect.vigour_modifier,0),coalesce(v_effect.shrewd_modifier,0),
        coalesce(v_effect.brains_modifier,0),coalesce(v_effect.presence_modifier,0),
        coalesce(v_effect.max_health_modifier,0),
        coalesce(v_effect.warping_affinity_modifier,0),
        coalesce(v_effect.warps_per_day_modifier,0),
        now(),now()+make_interval(mins=>v_effect.duration_minutes)
      );
      v_temporary_count:=v_temporary_count+1;
    end if;
  end loop;

  if v_health_delta<>0 then
    v_target_max_health:=public.get_character_current_max_health(v_target_character_id);
    update public.characters set current_health=greatest(0,least(
      coalesce(current_health,v_target_max_health)+v_health_delta,v_target_max_health)),
      updated_at=now() where id=v_target_character_id;
  elsif v_temporary_count>0 then
    update public.characters set updated_at=now() where id=v_target_character_id;
  end if;

  if p_record_kind='standard' and v_use_behaviour='consumable' then
    if v_quantity<=1 then delete from public.character_items where id=p_record_id;
    else update public.character_items set quantity=quantity-1,updated_at=now() where id=p_record_id;
    end if;
  end if;

  if p_record_kind='unique' and v_max_charges is not null then
    update public.character_item_instances set charges_remaining=greatest(0,coalesce(charges_remaining,v_max_charges)-1),
      updated_at=now() where id=p_record_id;
    v_charges_remaining:=greatest(0,coalesce(v_charges_remaining,v_max_charges)-1);
  end if;

  if coalesce(v_cooldown_minutes,0)>0 then
    v_ready_at:=now()+make_interval(mins=>v_cooldown_minutes);
    insert into public.character_item_use_cooldowns(character_id,source_key,item_id,item_instance_id,ready_at,updated_at)
    values(v_source_character_id,v_source_key,v_item_id,v_item_instance_id,v_ready_at,now())
    on conflict(character_id,source_key) do update set item_id=excluded.item_id,
      item_instance_id=excluded.item_instance_id,ready_at=excluded.ready_at,updated_at=now();
  else
    delete from public.character_item_use_cooldowns where character_id=v_source_character_id and source_key=v_source_key;
    v_ready_at:=null;
  end if;

  perform public.character_audit_write_event(
    v_source_character_id,'item_used','item_use',v_action_id,
    jsonb_build_object(
      'item_id',v_item_id,'item_name',v_item_name,'record_kind',p_record_kind,
      'target_character_id',v_target_character_id,'target_name',v_target_name,
      'health_delta',v_health_delta,'temporary_effects',v_temporary_count,
      'charges_remaining',v_charges_remaining
    ),
    'item_use',p_record_id::text
  );

  return jsonb_build_object('ok',true,'item_name',v_item_name,'target_character_id',v_target_character_id,
    'target_name',v_target_name,'health_delta',v_health_delta,'temporary_effects',v_temporary_count,
    'charges_remaining',v_charges_remaining,'cooldown_ready_at',v_ready_at);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_character_ancestry_gift()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare character_race_id uuid; eligible boolean;
begin
  if new.acquisition_source <> 'ancestry' then return new; end if;

  select race_id into character_race_id
  from public.characters
  where id=new.character_id;

  if character_race_id is null then
    raise exception 'Ancestry Gift cannot be assigned before the character has an Ancestry.';
  end if;

  if new.source_race_id is distinct from character_race_id then
    raise exception 'Ancestry Gift source does not match the character current Ancestry.';
  end if;

  select exists(
    select 1 from public.gift_races
    where gift_id=new.gift_id and race_id=character_race_id
  ) into eligible;

  if not eligible then
    raise exception 'This Gift is not available to the character Ancestry.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_character_condition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  active_count integer;
begin
  new.label :=
    regexp_replace(
      trim(new.label),
      '\s+',
      ' ',
      'g'
    );

  if
    char_length(new.label) < 1
    or
    char_length(new.label) > 40
  then
    raise exception
      'Condition must contain between 1 and 40 characters.';
  end if;

  if tg_op = 'INSERT' then
    select count(*)
    into active_count
    from
      public.character_conditions
    where
      character_id =
        new.character_id;

    if
      active_count >= 10
    then
      raise exception
        'A Character may have at most 10 active Conditions.';
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_character_cosmetic_preferences()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  selected_category text;
  selected_active boolean;
  owns_selected boolean;
begin
  if new.equipped_sheet_frame_id is not null then
    select category, is_active
      into selected_category, selected_active
    from public.cosmetic_items
    where id = new.equipped_sheet_frame_id;

    if not found then
      raise exception 'Selected sheet cosmetic does not exist.';
    end if;

    if selected_category <> 'sheet_frame' then
      raise exception 'Only a sheet_frame cosmetic can be equipped in the sheet frame slot.';
    end if;

    if selected_active is not true then
      raise exception 'Inactive cosmetics cannot be equipped.';
    end if;

    select exists (
      select 1
      from public.character_cosmetic_entitlements e
      where e.character_id = new.character_id
        and e.cosmetic_item_id = new.equipped_sheet_frame_id
        and e.enabled = true
    ) into owns_selected;

    if owns_selected is not true then
      raise exception 'Character does not own the selected sheet frame.';
    end if;
  end if;

  if new.equipped_chat_frame_id is not null then
    select category, is_active
      into selected_category, selected_active
    from public.cosmetic_items
    where id = new.equipped_chat_frame_id;

    if not found then
      raise exception 'Selected chat cosmetic does not exist.';
    end if;

    if selected_category <> 'chat_frame' then
      raise exception 'Only a chat_frame cosmetic can be equipped in the chat frame slot.';
    end if;

    if selected_active is not true then
      raise exception 'Inactive cosmetics cannot be equipped.';
    end if;

    select exists (
      select 1
      from public.character_cosmetic_entitlements e
      where e.character_id = new.character_id
        and e.cosmetic_item_id = new.equipped_chat_frame_id
        and e.enabled = true
    ) into owns_selected;

    if owns_selected is not true then
      raise exception 'Character does not own the selected chat frame.';
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_character_item_quantity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  item_is_stackable boolean;
  item_max_stack integer;
begin
  select i.stackable, i.max_stack
    into item_is_stackable, item_max_stack
  from public.items i
  where i.id = new.item_id;

  if item_is_stackable = false and new.quantity <> 1 then
    raise exception
      'Non-stackable items must have quantity 1.';
  end if;

  if item_max_stack is not null
     and new.quantity > item_max_stack then
    raise exception
      'Quantity exceeds this item''s maximum stack size of %.',
      item_max_stack;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_character_order_gift()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare eligible boolean;
begin
  if new.acquisition_source <> 'order' then return new; end if;

  select exists(
    select 1 from public.gift_order_jobs
    where gift_id=new.gift_id
      and order_job_id=new.source_order_job_id
  ) into eligible;

  if not eligible then
    raise exception 'This Gift is not available through the selected Order Role.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_extended_cosmetic_preferences()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  slot record;
  actual_category text;
  owned boolean;
begin
  for slot in
    select *
    from (
      values
        ('sheet_frame', new.equipped_sheet_frame_id),
        ('chat_frame', new.equipped_chat_frame_id),
        ('portrait_frame', new.equipped_portrait_frame_id),
        ('profile_background', new.equipped_profile_background_id),
        ('pm_frame', new.equipped_pm_frame_id),
        ('instant_chat_frame', new.equipped_instant_chat_frame_id),
        ('forum_frame', new.equipped_forum_frame_id),
        ('action_style', new.equipped_action_style_id),
        ('nameplate', new.equipped_nameplate_id),
        ('profile_crest', new.equipped_profile_crest_id),
        ('action_flourish', new.equipped_action_flourish_id),
        ('whisper_style', new.equipped_whisper_style_id),
        ('header_control_frame', new.equipped_header_control_frame_id),
        ('left_panel_frame', new.equipped_left_panel_frame_id),
        ('right_panel_frame', new.equipped_right_panel_frame_id),
        ('centre_panel_frame', new.equipped_centre_panel_frame_id),
        ('location_frame', new.equipped_location_frame_id),
        ('location_atmosphere', new.equipped_location_atmosphere_id)
    ) as slots(expected_category, cosmetic_id)
  loop
    if slot.cosmetic_id is null then
      continue;
    end if;

    select category
    into actual_category
    from public.cosmetic_items
    where id = slot.cosmetic_id
      and is_active = true;

    if actual_category is distinct from slot.expected_category then
      raise exception 'Cosmetic % does not belong in slot %',
        slot.cosmetic_id,
        slot.expected_category;
    end if;

    select exists (
      select 1
      from public.character_cosmetic_entitlements e
      where e.character_id = new.character_id
        and e.cosmetic_item_id = slot.cosmetic_id
        and e.enabled = true
    )
    into owned;

    if not owned then
      raise exception 'Character does not own cosmetic %',
        slot.cosmetic_id;
    end if;
  end loop;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_forum_author()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if new.author_user_id is null then
    new.author_user_id := auth.uid();
  end if;

  if new.author_user_id <> auth.uid()
     and not public.current_user_is_staff()
  then
    raise exception 'You cannot publish content as another user.';
  end if;

  if new.author_character_id is not null
     and not exists (
       select 1
       from public.characters
       where id = new.author_character_id
         and user_id = new.author_user_id
     )
  then
    raise exception 'The selected character does not belong to this user.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_inventory_container()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  parent_owner_id uuid;
  parent_category_slug text;
  parent_parent_id uuid;
  child_category_slug text;
begin
  if new.container_instance_id is null then
    return new;
  end if;

  select
    ci.owner_character_id,
    cat.slug,
    ci.container_instance_id
  into
    parent_owner_id,
    parent_category_slug,
    parent_parent_id
  from public.character_item_instances ci
  join public.items i
    on i.id = ci.item_id
  join public.item_categories cat
    on cat.id = i.category_id
  where ci.id = new.container_instance_id
    and ci.vault_status = 'owned';

  if parent_owner_id is null then
    raise exception
      'Selected container does not exist or is not currently owned.';
  end if;

  if parent_category_slug <> 'container' then
    raise exception
      'Items can only be placed inside Container-category item instances.';
  end if;

  if parent_parent_id is not null then
    raise exception
      'Nested containers are not allowed.';
  end if;

  select cat.slug
    into child_category_slug
  from public.items i
  join public.item_categories cat
    on cat.id = i.category_id
  where i.id = new.item_id;

  if child_category_slug = 'container' then
    raise exception
      'Containers cannot be placed inside other containers.';
  end if;

  if tg_table_name = 'character_items' then
    if parent_owner_id <> new.character_id then
      raise exception
        'Container and item must belong to the same character.';
    end if;
  else
    if parent_owner_id <> new.owner_character_id then
      raise exception
        'Container and item instance must belong to the same character.';
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_item_subcategory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  subcategory_category_id uuid;
begin
  if new.subcategory_id is null then
    return new;
  end if;

  select s.category_id
    into subcategory_category_id
  from public.item_subcategories s
  where s.id = new.subcategory_id;

  if subcategory_category_id is distinct from new.category_id then
    raise exception
      'Item subcategory must belong to the selected core category.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_order_job_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  from_order_id uuid;
  to_order_id uuid;
  from_level integer;
  to_level integer;
begin
  select l.order_id, l.level
    into from_order_id, from_level
  from public.order_jobs j
  join public.order_levels l on l.id = j.order_level_id
  where j.id = new.from_job_id;

  select l.order_id, l.level
    into to_order_id, to_level
  from public.order_jobs j
  join public.order_levels l on l.id = j.order_level_id
  where j.id = new.to_job_id;

  if from_order_id is null or to_order_id is null then
    raise exception 'Both linked roles must exist.';
  end if;

  if from_order_id <> to_order_id then
    raise exception 'Linked roles must belong to the same Order.';
  end if;

  if to_level <> from_level + 1 then
    raise exception 'Role progression links must connect adjacent Levels upward.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_order_job_link_structure()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  from_level integer;
  to_level integer;
  from_order_id uuid;
  to_order_id uuid;
begin
  select ol.level, ol.order_id
  into from_level, from_order_id
  from public.order_jobs oj
  join public.order_levels ol
    on ol.id = oj.order_level_id
  where oj.id = new.from_job_id;

  select ol.level, ol.order_id
  into to_level, to_order_id
  from public.order_jobs oj
  join public.order_levels ol
    on ol.id = oj.order_level_id
  where oj.id = new.to_job_id;

  if from_level is null or to_level is null then
    raise exception
      'Invalid Role progression link: one or both Roles do not exist.';
  end if;

  if from_order_id is distinct from to_order_id then
    raise exception
      'Invalid Role progression link: Roles must belong to the same Order.';
  end if;

  if to_level <> from_level + 1 then
    raise exception
      'Invalid Role progression link: links must go from a Role to a Role exactly one Level above.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_order_membership_structure()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  selected_level_order_id uuid;
  selected_role_level_id uuid;
begin
  select order_id
  into selected_level_order_id
  from public.order_levels
  where id = new.order_level_id;

  if selected_level_order_id is null then
    raise exception
      'Invalid Order membership: selected Level does not exist.';
  end if;

  if selected_level_order_id is distinct from new.order_id then
    raise exception
      'Invalid Order membership: selected Level does not belong to selected Order.';
  end if;

  select order_level_id
  into selected_role_level_id
  from public.order_jobs
  where id = new.order_job_id;

  if selected_role_level_id is null then
    raise exception
      'Invalid Order membership: selected Role does not exist.';
  end if;

  if selected_role_level_id is distinct from new.order_level_id then
    raise exception
      'Invalid Order membership: selected Role does not belong to selected Level.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_room_message_npc_speaker()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  npc_row public.npcs%rowtype;
begin
  if new.speaker_type='npc' then
    if new.npc_id is null then
      raise exception 'NPC message requires npc_id';
    end if;

    select *
    into npc_row
    from public.npcs
    where id=new.npc_id;

    if not found then
      raise exception 'NPC not found';
    end if;

    if npc_row.is_active is not true then
      raise exception 'NPC is inactive';
    end if;

    if npc_row.is_location_active is not true then
      raise exception 'NPC is not Active in Locations';
    end if;

    if npc_row.current_room_id is distinct from new.room_id then
      raise exception 'NPC is not in this Location';
    end if;
  else
    new.npc_id=null;
    new.npc_snapshot=null;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_special_room_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  sender_user_id uuid;
  sender_room_id uuid;
  staff_role text;
begin
  select
    c.user_id,
    c.current_room_id
  into
    sender_user_id,
    sender_room_id
  from public.characters c
  where c.id = new.character_id;

  /*
   * NPC messages are posted by a trusted server action.
   *
   * character_id remains the controlling staff Character
   * for private audit purposes, while sent_by_user_id records
   * the actual staff account.
   */
  if coalesce(new.speaker_type, 'character') = 'npc' then

    if new.sent_by_user_id is null then
      raise exception
        'NPC messages require an authenticated staff controller.';
    end if;

    if sender_user_id is distinct from new.sent_by_user_id then
      raise exception
        'The NPC controller does not own the auditing character.';
    end if;

    select sm.role
    into staff_role
    from public.staff_members sm
    where sm.user_id = new.sent_by_user_id;

    if
      staff_role is null
      or staff_role not in (
        'owner',
        'admin',
        'master'
      )
    then
      raise exception
        'Only an owner, administrator or master may write as an NPC.';
    end if;

  else

    /*
     * Normal Character messages retain the original security:
     * a user may write only as their own Character.
     */
    if sender_user_id is distinct from auth.uid() then
      raise exception
        'You cannot write as another character.';
    end if;

  end if;

  /*
   * Both Characters and NPC controllers must actually be
   * standing in the Location receiving the message.
   */
  if sender_room_id is distinct from new.room_id then
    raise exception
      'The character is not in this room.';
  end if;

  if new.message_type = 'whisper' then
    if
      new.whisper_recipient_character_id
        is null
    then
      raise exception
        'A whisper recipient is required.';
    end if;

    if
      new.whisper_recipient_character_id =
        new.character_id
    then
      raise exception
        'You cannot whisper to yourself.';
    end if;

    if not exists (
      select 1
      from public.character_presence cp
      where
        cp.character_id =
          new.whisper_recipient_character_id
        and cp.room_id = new.room_id
        and
          cp.last_seen_at >=
            now() - interval '5 minutes'
    ) then
      raise exception
        'The whisper recipient is not currently present in this room.';
    end if;
  end if;

  if new.message_type = 'fate' then

    /*
     * Fate is still controlled using the authenticated account
     * for ordinary messages.
     */
    select sm.role
    into staff_role
    from public.staff_members sm
    where sm.user_id =
      case
        when coalesce(new.speaker_type, 'character') = 'npc'
          then new.sent_by_user_id
        else auth.uid()
      end;

    if
      staff_role is null
      or staff_role not in (
        'owner',
        'admin',
        'master'
      )
    then
      raise exception
        'Only an owner, administrator or master may write Fate actions.';
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.warping_reset_boundary(p_now timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
AS $function$
select case when p_now >= (date_trunc('day',p_now at time zone 'Europe/London')+interval '8 hours') at time zone 'Europe/London'
then (date_trunc('day',p_now at time zone 'Europe/London')+interval '8 hours') at time zone 'Europe/London'
else (date_trunc('day',p_now at time zone 'Europe/London')-interval '1 day'+interval '8 hours') at time zone 'Europe/London' end
$function$
;

