create policy "Warping staff manage active shape effects" on public.active_shape_effects as permissive for all to authenticated
using ((current_staff_role() = ANY (ARRAY['owner'::text, 'admin'::text, 'master'::text])))
with check ((current_staff_role() = ANY (ARRAY['owner'::text, 'admin'::text, 'master'::text])));

create policy "Areas are visible to everyone" on public.areas as permissive for select to public
using ((is_active = true));

create policy "Owner can delete areas" on public.areas as permissive for delete to authenticated
using ((current_staff_role() = 'owner'::text));

create policy "Owner can insert areas" on public.areas as permissive for insert to authenticated
with check ((current_staff_role() = 'owner'::text));

create policy "Owner can update areas" on public.areas as permissive for update to authenticated
using ((current_staff_role() = 'owner'::text))
with check ((current_staff_role() = 'owner'::text));

create policy "Authenticated users can read associations" on public.associations as permissive for select to authenticated
using (true);

create policy "Owner can delete associations" on public.associations as permissive for delete to authenticated
using ((current_staff_role() = 'owner'::text));

create policy "Owner can insert associations" on public.associations as permissive for insert to authenticated
with check ((current_staff_role() = 'owner'::text));

create policy "Owner can update associations" on public.associations as permissive for update to authenticated
using ((current_staff_role() = 'owner'::text))
with check ((current_staff_role() = 'owner'::text));

create policy "Recipients can read Breeze lodging invitations" on public.breeze_lodging_invitations as permissive for select to authenticated
using ((EXISTS ( SELECT 1
   FROM characters c
  WHERE ((c.id = breeze_lodging_invitations.recipient_character_id) AND (c.user_id = auth.uid())))));

create policy "characters can insert own event reads" on public.calendar_event_reads as permissive for insert to authenticated
with check ((EXISTS ( SELECT 1
   FROM characters
  WHERE ((characters.id = calendar_event_reads.character_id) AND (characters.user_id = auth.uid())))));

create policy "characters can read own event reads" on public.calendar_event_reads as permissive for select to authenticated
using ((EXISTS ( SELECT 1
   FROM characters
  WHERE ((characters.id = calendar_event_reads.character_id) AND (characters.user_id = auth.uid())))));

create policy "characters can update own event reads" on public.calendar_event_reads as permissive for update to authenticated
using ((EXISTS ( SELECT 1
   FROM characters
  WHERE ((characters.id = calendar_event_reads.character_id) AND (characters.user_id = auth.uid())))))
with check ((EXISTS ( SELECT 1
   FROM characters
  WHERE ((characters.id = calendar_event_reads.character_id) AND (characters.user_id = auth.uid())))));

create policy "Event staff can delete calendar events" on public.calendar_events as permissive for delete to authenticated
using ((current_staff_role() = ANY (ARRAY['owner'::text, 'admin'::text, 'master'::text])));

create policy "Event staff can insert calendar events" on public.calendar_events as permissive for insert to authenticated
with check ((current_staff_role() = ANY (ARRAY['owner'::text, 'admin'::text, 'master'::text])));

create policy "Event staff can update calendar events" on public.calendar_events as permissive for update to authenticated
using ((current_staff_role() = ANY (ARRAY['owner'::text, 'admin'::text, 'master'::text])))
with check ((current_staff_role() = ANY (ARRAY['owner'::text, 'admin'::text, 'master'::text])));

create policy calendar_events_select on public.calendar_events as permissive for select to authenticated
using (((is_active = true) OR COALESCE(current_user_is_staff(), false)));

create policy character_active_item_effects_read on public.character_active_item_effects as permissive for select to authenticated
using ((EXISTS ( SELECT 1
   FROM characters c
  WHERE ((c.id = character_active_item_effects.character_id) AND ((c.status = 'approved'::text) OR (c.user_id = auth.uid()) OR is_staff_user())))));

create policy "blocks delete self" on public.character_blocks as permissive for delete to authenticated
using ((blocker_character_id = current_character_id()));

create policy "blocks insert self" on public.character_blocks as permissive for insert to authenticated
with check ((blocker_character_id = current_character_id()));

create policy "blocks select involved" on public.character_blocks as permissive for select to authenticated
using (((blocker_character_id = current_character_id()) OR (blocked_character_id = current_character_id())));

