-- ============================================================================
-- TABLE COMMENTS
-- ============================================================================

comment on table public.character_effects is 'Single runtime source of active Conditions and temporary attribute/Max-Health effects from Shapes, Feats, Items and manual Conditions.';

comment on table public.character_item_instances is 'Unique/stateful item instances. No durability/condition. Admin Vault uses owner_character_id NULL and vault_status admin_vault.';

comment on table public.character_items is 'Standard character inventory. One stack occupies one container slot regardless of quantity.';

comment on table public.experience_feedback is 'Logout experience prompts shown at most every 7 days, including optional ratings and comments.';

comment on table public.item_instance_history is 'Append-only provenance/history for unique item instances.';

comment on table public.items is 'Master item catalogue. Ordinary copies reference this row; unique/stateful copies use character_item_instances.';

comment on table public.registration_auth_invitations is 'Staff audit/history for native Supabase Auth closed-alpha invitations.';

-- ============================================================================
-- COLUMN COMMENTS
-- ============================================================================

comment on column public.associations.is_selectable is 'Whether this active Association can be selected during new character creation.';

comment on column public.characters.music_url is 'Optional direct browser-playable audio URL used as the character theme on character sheets.';

comment on column public.characters.show_last_activity is 'When true, Last activity is visible to ordinary players on the public character sheet. Staff can always see it.';

comment on column public.characters.show_inventory is 'Whether non-staff players may view the character''s non-equipped Inventory. Equipped Items remain public.';

comment on column public.characters.master_notes_expires_at is 'Expiry time for Masters Notes. NULL means permanent.';

comment on column public.codex_chapters.read_audio_url is 'Optional direct browser-playable audio URL for the narrated reading of this Codex chapter.';

comment on column public.experience_feedback.prompted_at is 'When the 7-day satisfaction prompt was shown to the player.';

comment on column public.experience_feedback.responded_at is 'When the player answered or skipped the prompt.';

comment on column public.forum_posts.is_anonymous is 'When true, the author identity is hidden from ordinary viewers. The author and staff may still see the real character identity.';

comment on column public.order_memberships.return_room_id is 'Last public room occupied before entering the member''s Order Headquarters; used to return the character when membership/access is removed.';

comment on column public.races.is_selectable is 'Whether this active ancestry can be selected during new character creation.';

comment on column public.registration_invitations.invitation_url is 'Full generated registration URL retained for staff-only invitation history.';

comment on column public.shapes.self_resolution_mode is 'Resolution used by the Self effect profile.';

comment on column public.shapes.other_resolution_mode is 'Resolution used by the normal/Beneficial Other effect profile.';

comment on column public.shapes.other_alt_resolution_mode is 'Resolution used by the Harmful alternative Other effect profile.';

comment on column public.shapes.extended_description is 'Optional sanitised rich-text lore/detail shown on Shape catalogue/profile panels. Not used in Warping chat output.';

comment on column public.world_state.climate_override_snapshot is 'Exact automatic climate state saved immediately before a temporary staff weather/temperature override. Restored on manual reset or when the temporary override expires.';

commit;
